/** Generated by scripts/gen-thirukkural.mjs — do not edit by hand. */
export type Kural = {
  number: number
  line1: string
  line2: string
  meaningTa: string
  meaningEn: string
}

export const KURALS: Kural[] = [
  { number: 1, line1: "அகர முதல எழுத்தெல்லாம் ஆதி", line2: "பகவன் முதற்றே உலகு.", meaningTa: "அ எழுத்து எல்லா எழுத்துகளுக்கும் முதல். அதுபோல கடவுள் உலகத்திற்கு முதல்.", meaningEn: "Just like A comes first in the alphabet, God comes first in the world." },
  { number: 2, line1: "கற்றதனால் ஆய பயனென்கொல் வாலறிவன்", line2: "நற்றாள் தொழாஅர் எனின்.", meaningTa: "கற்ற கல்வி நல்ல வழியில் நடத்த உதவினால் தான் பயன் உண்டு.", meaningEn: "Learning is best when it also teaches us to be thankful and kind." },
  { number: 3, line1: "மலர்மிசை ஏகினான் மாணடி சேர்ந்தார்", line2: "நிலமிசை நீடுவாழ் வார்.", meaningTa: "நல்ல எண்ணங்களை மனத்தில் வைத்து வாழ்பவர் நீண்டகாலம் நலமாக வாழ்வர்.", meaningEn: "People who keep good thoughts in their heart live a long, happy life." },
  { number: 4, line1: "வேண்டுதல் வேண்டாமை இலானடி சேர்ந்தார்க்கு", line2: "யாண்டும் இடும்பை இல.", meaningTa: "அமைதியும் அன்பும் உள்ள வழியில் சென்றால் துன்பம் வராது.", meaningEn: "When you follow a calm and kind way, worry stays away." },
  { number: 5, line1: "இருள்சேர் இருவினையும் சேரா இறைவன்", line2: "பொருள்சேர் புகழ்புரிந்தார் மாட்டு.", meaningTa: "நல்லதை நினைத்து வாழ்ந்தால் தீய செயல்கள் நம்மைச் சேராது.", meaningEn: "Thinking of what is good and true keeps dark mistakes away." },
  { number: 6, line1: "பொறிவாயில் ஐந்தவித்தான் பொய்தீர் ஒழுக்க", line2: "நெறிநின்றார் நீடுவாழ் வார்.", meaningTa: "கண், செவி, வாய் ஆகியவற்றை அடக்கி நல்ல வழியில் நிற்பவர் நலமாக வாழ்வர்.", meaningEn: "People who guide their eyes, ears, and tongue carefully live long and well." },
  { number: 7, line1: "தனக்குவமை இல்லாதான் தாள்சேர்ந்தார்க் கல்லால்", line2: "மனக்கவலை மாற்றல் அரிது.", meaningTa: "ஒப்பில்லா நல்ல வழியைப் பின்பற்றினால் மனக்கவலை நீங்கும்.", meaningEn: "Being close to a one-of-a-kind kind guide helps take worry out of the heart." },
  { number: 8, line1: "அறவாழி அந்தணன் தாள்சேர்ந்தார்க் கல்லால்", line2: "பிறவாழி நீந்தல் அரிது.", meaningTa: "அறம் ஒரு பெரிய கடல் போன்றது. அதைப் பிடித்துக்கொண்டால் வாழ்க்கை எளிதாகும்.", meaningEn: "Goodness is like a big sea. Holding on to it helps you cross hard times." },
  { number: 9, line1: "கோளில் பொறியின் குணமிலவே எண்குணத்தான்", line2: "தாளை வணங்காத் தலை.", meaningTa: "நன்றி சொல்லாத தலை, வேலை செய்யாத கருவி போன்றது.", meaningEn: "A head that never bows in thanks is like a tool that does not work." },
  { number: 10, line1: "பிறவிப் பெருங்கடல் நீந்துவர் நீந்தார்", line2: "இறைவன் அடிசேரா தார்.", meaningTa: "நல்ல வழியில் நிற்பவர் பிறவிக் கடலைக் கடந்து செல்வர்.", meaningEn: "People who stay close to God can cross the big sea of hard births." },
  { number: 11, line1: "வான்நின்று உலகம் வழங்கி வருதலால்", line2: "தான்அமிழ்தம் என்றுணரற் பாற்று.", meaningTa: "மழை இருந்தால்தான் உலகம் வாழும். அதனால் மழை இனிய அமிழ்தம் போன்றது.", meaningEn: "Rain keeps the world alive, so rain is like sweet magic water." },
  { number: 12, line1: "துப்பார்க்குத் துப்பாய துப்பாக்கித் துப்பார்க்குத்", line2: "துப்பாய தூஉம் மழை.", meaningTa: "மழை உணவு தரும். மழையே உலகத்திற்கு உணவு போன்றது.", meaningEn: "Rain helps grow food, and rain itself is like food for the world." },
  { number: 13, line1: "விண்இன்று பொய்ப்பின் விரிநீர் வியனுலகத்து", line2: "உள்நின்று உடற்றும் பசி.", meaningTa: "மழை பொய்த்தால் உலகம் பசியால் வருந்தும்.", meaningEn: "If rain does not come, hunger will hurt the whole wide world." },
  { number: 14, line1: "ஏரின் உழாஅர் உழவர் புயல்என்னும்", line2: "வாரி வளங்குன்றிக் கால்.", meaningTa: "மழை குறைந்தால் உழவர் உழவு செய்ய முடியாது.", meaningEn: "If the helpful rain gets less, farm work has to stop." },
  { number: 15, line1: "கெடுப்பதூஉம் கெட்டார்க்குச் சார்வாய்மற் றாங்கே", line2: "எடுப்பதூஉம் எல்லாம் மழை.", meaningTa: "மழை இல்லாவிட்டால் கெடும்; மழை பெய்தால் மீண்டும் நலம் வரும்.", meaningEn: "No rain can ruin people, and good rain can lift them up again." },
  { number: 16, line1: "விசும்பின் துளிவீழின் அல்லால்மற் றாங்கே", line2: "பசும்புல் தலைகாண்பு அரிது.", meaningTa: "மழைத்துளி விழாவிட்டால் பசும்புல் கூட தெரியாது.", meaningEn: "Without even one raindrop, you will not see tiny green grass." },
  { number: 17, line1: "நெடுங்கடலும் தன்நீர்மை குன்றும் தடிந்தெழிலி", line2: "தான்நல்கா தாகி விடின்.", meaningTa: "மேகம் மழை பெய்யாவிட்டால் கடலும் வற்றிவிடும்.", meaningEn: "Even the big sea needs clouds to give water back as rain." },
  { number: 18, line1: "சிறப்பொடு பூசனை செல்லாது வானம்", line2: "வறக்குமேல் வானோர்க்கும் ஈண்டு.", meaningTa: "மழை பொய்த்தால் திருவிழாவும் வழிபாடும் நடக்காது.", meaningEn: "If the sky stays dry, festivals and daily thanks stop too." },
  { number: 19, line1: "தானம் தவம்இரண்டும் தங்கா வியன்உலகம்", line2: "வானம் வழங்கா தெனின்.", meaningTa: "மழை இல்லாவிட்டால் தானமும் நல்ல முயற்சியும் இருக்காது.", meaningEn: "Without rain, sharing and hard good practice cannot live in the world." },
  { number: 20, line1: "நீர்இன்று அமையாது உலகெனின் யார்யார்க்கும்", line2: "வான்இன்று அமையாது ஒழுக்கு.", meaningTa: "நீர் இல்லாமல் உலகம் இல்லை; மழை இல்லாமல் நீர் இல்லை.", meaningEn: "Just as people need water, good living needs rain." },
  { number: 21, line1: "ஒழுக்கத்து நீத்தார் பெருமை விழுப்பத்து", line2: "வேண்டும் பனுவல் துணிவு.", meaningTa: "ஒழுக்கத்தில் உறுதியான துறவிகளின் பெருமை, சான்றோர் நூலில் விருப்பமுடனும், உயர்வாகவும் இடம் பெறும்.", meaningEn: "The big goal of every wise book is to praise as the very best, the greatness of those who, while living in a good way state, have abandoned all wants." },
  { number: 22, line1: "துறந்தார் பெருமை துணைக்கூறின் வையத்து", line2: "இறந்தாரை எண்ணிக்கொண் டற்று.", meaningTa: "பற்றுக்களைத் துறந்தவர்களின் பெருமையை அளந்து கூறுதல், உலகத்தில் இதுவரை பிறந்து இறந்தவர்களை கணக்கிடுவதைப்போன்றது.", meaningEn: "To describe the measure of the greatness of those who have let go of greedy wants, is like counting every star." },
  { number: 23, line1: "இருமை வகைதெரிந்து ஈண்டுஅறம் பூண்டார்", line2: "பெருமை பிறங்கிற்று உலகு.", meaningTa: "நன்மை எது, தீமை எது என்பதை ஆய்ந்தறிந்து நன்மைகளை மேற்கொள்பவர்களே உலகில் பெருமைக்குரியவர்களாவார்கள்.", meaningEn: "The greatness of those who have discovered the properties of both states of being, and live simply, shines in the world (brightly)." },
  { number: 24, line1: "உரனென்னும் தோட்டியான் ஓரைந்தும் காப்பான்", line2: "வரனென்னும் வைப்பிற்கோர் வித்து.", meaningTa: "அறிவு என்னும் கருவியினால் ஐம்பொறிகளாகிய யானைகளை அடக்கி காக்க வல்லவன், மேலான வீட்டிற்கு விதை போன்றவன்.", meaningEn: "He who uses wisdom to guide feelings will be a bright example." },
  { number: 25, line1: "ஐந்தவித்தான் ஆற்றல் அகல்விசும்பு ளார்கோமான்", line2: "இந்திரனே சாலுங் கரி.", meaningTa: "ஐந்து புலன்களாலாகும் ஆசைகளை ஒழித்தவனுடைய வல்லமைக்கு, வானுலகத்தாரின் தலைவனாகிய இந்திரனே போதுமான சான்று ஆவான்.", meaningEn: "A great sky leader, the leader of the people of the wide sky, is himself, a clear sign of the strength of God who has stays in control of feelings." },
  { number: 26, line1: "செயற்கரிய செய்வார் பெரியர் சிறியர்", line2: "செயற்கரிய செய்கலா தார்.", meaningTa: "பிறர் செய்வதற்கு முடியாத செயல்களைச் செய்பவரே மேன்மக்கள்; செய்ய முடியாதவரோ சிறியவரே.", meaningEn: "The great will do those things that are hard; but the selfish people won't try." },
  { number: 27, line1: "சுவைஒளி ஊறுஓசை நாற்றமென ஐந்தின்", line2: "வகைதெரிவான் கட்டே உலகு.", meaningTa: "ஐம்புலன்களின் இயல்பை உணர்ந்து அவற்றை அடக்கியாளும் திறன் கொண்டவனையே உலகம் போற்றும்.", meaningEn: "The world is within the knowledge of God who knows the five senses." },
  { number: 28, line1: "நிறைமொழி மாந்தர் பெருமை நிலத்து", line2: "மறைமொழி காட்டி விடும்.", meaningTa: "சான்றோர்களின் பெருமையை, இந்த உலகில் அழியாமல் நிலைத்து நிற்கும் அவர்களது அறவழி நூல்களே எடுத்துக் காட்டும்.", meaningEn: "The wise secret words of the people whose words come true, will show their greatness to the world." },
  { number: 29, line1: "குணமென்னும் குன்றேறி நின்றார் வெகுளி", line2: "கணமேயும் காத்தல் அரிது.", meaningTa: "குணக்குன்றுகளான பெரியவர்கள் கோபம் கொண்டால் அந்தக் கோபம் அவர்கள் உள்ளத்தில் ஒரு கணம் கூட நிலைத்து நிற்காது.", meaningEn: "The anger of those who have climbed high in goodness, though it lasts only a moment, is very strong." },
  { number: 30, line1: "அந்தணர் என்போர் அறவோர்மற் றெவ்வுயிர்க்கும்", line2: "செந்தண்மை பூண்டொழுக லான்.", meaningTa: "எல்லா உயிர்களிடத்திலும் இரக்கம் கொண்டு வாழ்பவரே அறவோர்; அவரே அந்தணர்.", meaningEn: "The good are really called kind wise people; because in how they treat every living thing they are wrapped in kindness." },
  { number: 31, line1: "சிறப்புஈனும் செல்வமும் ஈனும் அறத்தினூஉங்கு", line2: "ஆக்கம் எவனோ உயிர்க்கு.", meaningTa: "சிறப்பையும், செழிப்பையும் தரக்கூடிய அறவழி ஒன்றைத்தவிர ஆக்கமளிக்கக் கூடிய வழி வேறென்ன இருக்கிறது?", meaningEn: "Goodness will confer heaven and wealth; what greater source of happiness can man possess ?" },
  { number: 32, line1: "அறத்தினூஉங்கு ஆக்கமும் இல்லை அதனை", line2: "மறத்தலின் ஊங்கில்லை கேடு.", meaningTa: "அறம் செய்வதை விட நன்மையும் இல்லை. அதைச் செய்ய மறப்பதைவிட கெடுதியும் இல்லை.", meaningEn: "There can be no greater source of good than (the practice of) goodness; there can be no greater source of evil than the forgetfulness of it." },
  { number: 33, line1: "ஒல்லும் வகையான் அறவினை ஓவாதே", line2: "செல்லும்வாய் எல்லாஞ் செயல்.", meaningTa: "இடைவிடாமல் இயன்ற மட்டும் எல்லா இடங்களிலும் அறச்செயலைச் செய்க.", meaningEn: "As much as possible, in every way, incessantly practise goodness." },
  { number: 34, line1: "மனத்துக்கண் மாசிலன் ஆதல் அனைத்தறன்", line2: "ஆகுல நீர பிற.", meaningTa: "மனம் தூய்மையாக இருப்பதே அறம்; மற்றவை ஆரவாரத்தைத் தவிர வேறொன்றுமில்லை.", meaningEn: "Let God who does good deeds be of spotless mind; to that extent is goodness; all else is vain show." },
  { number: 35, line1: "அழுக்காறு அவாவெகுளி இன்னாச்சொல் நான்கும்", line2: "இழுக்கா இயன்றது அறம்.", meaningTa: "பொறாமை, பேராசை, பொங்கும் கோபம், புண்படுத்தும் சொல் ஆகிய இந்த நான்கும் அறவழிக்குப் பொருந்தாதவைகளாகும்.", meaningEn: "That conduct is goodness which is free from these four things, that is, malice, wants, anger and bitter speech." },
  { number: 36, line1: "அன்றறிவாம் என்னாது அறஞ்செய்க மற்றது", line2: "பொன்றுங்கால் பொன்றாத் துணை.", meaningTa: "இளைஞராக உள்ளவர், பிற்காலத்தில் பார்த்து கொள்ளலாம் என்று எண்ணாமல் அறம் செய்ய வேண்டும். அதுவே உடல் அழியும் காலத்தில்.", meaningEn: "Defer not goodness to another day; receive her now; and at the dying hour she will be your undying friend." },
  { number: 37, line1: "அறத்தாறு இதுவென வேண்டா சிவிகை", line2: "பொறுத்தானோடு ஊர்ந்தான் இடை.", meaningTa: "பல்லக்கை சுமப்பவனும் அதன்மேலிருந்து ஊர்ந்து செல்லுவோனுமாகிய அவர்களிடையே அறத்தின் பயன் இஃது என்று கூறவேண்டா.", meaningEn: "The fruit of goodness need not be described in books; it may be inferred from seeing the bearer of a palanquin and the rider therein." },
  { number: 38, line1: "வீழ்நாள் படாஅமை நன்றாற்றின் அஃதொருவன்", line2: "வாழ்நாள் வழியடைக்கும் கல்.", meaningTa: "அறத்தை செய்யாது விட்ட நாள் இல்லை என்று சொல்லும்படி ஒருவன் அறம் செய்தால், அச்செயலே, அவன் திரும்பப் பிறக்கும் வழியை.", meaningEn: "If one allows no day to pass without some good being done, his conduct will be a stone to block up the passage to other births." },
  { number: 39, line1: "அறத்தான் வருவதே இன்பம் மற்றெல்லாம்", line2: "புறத்த புகழும் இல.", meaningTa: "அறத்துடன் வருவதே இன்பம்; பிற வழிகளில் வருவன துன்பமே; புகழும் ஆகா.", meaningEn: "Only that pleasure which flows from domestic goodness is pleasure; all else isn't pleasure, and it is without praise." },
  { number: 40, line1: "செயற்பால தோரும் அறனே ஒருவற்கு", line2: "உயற்பால தோரும் பழி.", meaningTa: "ஒருவன் செய்யத் தக்கது அறமே; விட்டுவிடத் தக்கவை தீய செயல்களே.", meaningEn: "That is goodness which each ought to do, and that is wrong which each should shun." },
  { number: 41, line1: "இல்வாழ்வான் என்பான் இயல்புடைய மூவர்க்கும்", line2: "நல்லாற்றின் நின்ற துணை.", meaningTa: "மனைவியோடு வாழ்பவன்தான் பிள்ளைகள், பெற்றோர், உறவினர் என்னும் மூவர்க்கும் நல்ல வழியில் உதவுபவன்.", meaningEn: "He will be called a (true) householder, who is a firm support to the good of the three orders in." },
  { number: 42, line1: "துறந்தார்க்கும் துவ்வாதவர்க்கும் இறந்தார்க்கும்", line2: "இல்வாழ்வான் என்பான் துணை.", meaningTa: "மனைவியோடு வாழ்பவன்தான் துறவியர், வறுமைப்பட்டவர், இறந்து போனவர் என்பவர்க்கும் உதவுபவன்.", meaningEn: "He will be said to do well in domestic goodness who aids the forsaken, the poor, and the dead." },
  { number: 43, line1: "தென்புலத்தார் தெய்வம் விருந்தொக்கல் தானென்றாங்கு", line2: "ஐம்புலத்தாறு ஓம்பல் தலை.", meaningTa: "வாழ்ந்து மறைந்தோரை நினைவுகூர்தல், வாழ்வாங்கு வாழ்வோரைப் போற்றுதல், விருந்தோம்பல், சுற்றம் பேணல் ஆகிய கடமைகளை.", meaningEn: "The chief (duty of the householder) is to preserve the five-fold rule (of conduct) towards the manes, the Gods, his guests, his relations and himself." },
  { number: 44, line1: "பழியஞ்சிப் பாத்தூண் உடைத்தாயின் வாழ்க்கை", line2: "வழியெஞ்சல் எஞ்ஞான்றும் இல்.", meaningTa: "பழிக்கு அஞ்சாமல் சேர்த்த பொருள் கணக்கின்றி இருப்பினும் அதைவிட, பழிக்கு அஞ்சிச் சேர்த்த பொருளைப் பகுத்து உண்ணும்.", meaningEn: "Sin he shuns and food he shares His home is bright and brighter fares." },
  { number: 45, line1: "அன்பும் அறனும் உடைத்தாயின் இல்வாழ்க்கை", line2: "பண்பும் பயனும் அது.", meaningTa: "இல்வாழ்க்கையின் அன்பும் அறமும் உடையதாக விளங்குமானால், அந்த வாழக்கையின் பண்பும் பயனும் அதுவே ஆகும்.", meaningEn: "If the married life possess caring and goodness, these will be both its duty and reward." },
  { number: 46, line1: "அறத்தாற்றின் இல்வாழ்க்கை ஆற்றின் புறத்தாற்றில்", line2: "போஒய்ப் பெறுவ தெவன்?", meaningTa: "ஒருவன் அறநெறியில் இல்வாழ்க்கையைச் செலுத்தி வாழ்வானானால், அத்தகையவன் வேறு நெறியில் சென்று பெறத்தக்கது என்ன?", meaningEn: "What will he who lives goodly in the domestic state gain by going into the other, (people who live simply) state ?" },
  { number: 47, line1: "இயல்பினான் இல்வாழ்க்கை வாழ்பவன் என்பான்", line2: "முயல்வாருள் எல்லாம் தலை.", meaningTa: "அறத்தின் இயல்பொடு இல்வாழ்கை வாழ்கிறவன்- வாழ முயல்கிறவன் பல திறத்தாரிலும் மேம்பட்டு விளங்குகிறவன் ஆவான்.", meaningEn: "Among all those who labour (for future happiness) he is greatest who lives well in the household state." },
  { number: 48, line1: "ஆற்றின் ஒழுக்கி அறனிழுக்கா இல்வாழ்க்கை", line2: "நோற்பாரின் நோன்மை உடைத்து.", meaningTa: "மற்றவர்களை அவர்களின் வழியில் வாழச்செய்து, தானும் அறத்திலிருந்து விலகாமல், மனைவியுடன் வாழும் வாழ்க்கை, துறவறத்தார்.", meaningEn: "The householder who, not swerving from goodness, helps the people who live simply in his way, endures more than those who endure hard good practice." },
  { number: 49, line1: "அறனெனப் பட்டதே இல்வாழ்க்கை அஃதும்", line2: "பிறன்பழிப்ப தில்லாயின் நன்று.", meaningTa: "பழிப்புக்கு இடமில்லாத இல்வாழ்க்கை இல்லறம் எனப் போற்றப்படும்.", meaningEn: "The marriage state is really called goodness The other state is also good, if others don't reproach it." },
  { number: 50, line1: "வையத்துள் வாழ்வாங்கு வாழ்பவன் வான்உறையும்", line2: "தெய்வத்துள் வைக்கப் படும்.", meaningTa: "உலகத்தில் வாழவேண்டிய அறநெறியில் நின்று வாழ்கிறவன், வானுலகத்தில் உள்ள தெய்வ முறையில் வைத்து மதிக்கப்படுவான்.", meaningEn: "He who on earth has lived in the family state as he should live, will be placed among the Gods who dwell in heaven." },
  { number: 51, line1: "மனைக்தக்க மாண்புடையள் ஆகித்தற் கொண்டான்", line2: "வளத்தக்காள் வாழ்க்கைத் துணை.", meaningTa: "பிறந்த, புகுந்த குடும்பங்களுக்கு ஏற்ற நல்ல குணம், நல்ல செயல்களை உடையவளாய்த், தன்னை மணந்தவனின் வருவாய்க்கு ஏற்ப.", meaningEn: "She who has the excellence of home goodnesss, and can expend within the means of her partner, is a help in the domestic state." },
  { number: 52, line1: "மனைமாட்சி இல்லாள்கண் இல்லாயின் வாழ்க்கை", line2: "எனைமாட்சித் தாயினும் இல்.", meaningTa: "நற்பண்புள்ள மனைவி அமையாத இல்வாழ்க்கை எவ்வளவு சிறப்புடையதாக இருந்தாலும் அதற்குத் தனிச்சிறப்புக் கிடையாது.", meaningEn: "If the partner be devoid of domestic excellence, whatever (other) greatness be possessed, the family state, is nothing." },
  { number: 53, line1: "இல்லதென் இல்லவள் மாண்பானால் உள்ளதென்", line2: "இல்லவள் மாணாக் கடை?", meaningTa: "மனைவி நற்பண்பு உடையவளானால் வாழ்க்கையில் இல்லாதது என்ன? அவள் நற்பண்பு இல்லாதவளானால் வாழ்க்கையில் இருப்பது என்ன?", meaningEn: "If his partner be eminent (in goodness), what does (that man) not possess ? If she be without excellence, what does (he) possess ?" },
  { number: 54, line1: "பெண்ணின் பெருந்தக்க யாவுள கற்பென்னும்", line2: "திண்மைஉண் டாகப் பெறின்.", meaningTa: "கற்பு எனப்படும் மன உறுதி மட்டும் பெண்ணிடம் இருக்குமானால் மனைவியைக் காட்டிலும் மேலானவை எவை?", meaningEn: "What is more excellent than a partner, if she possess the stability of chastity ?" },
  { number: 55, line1: "தெய்வம் தொழாஅள் கொழுநன் தொழுதெழுவாள்", line2: "பெய்யெனப் பெய்யும் மழை.", meaningTa: "பிற தெய்வங்களைத் தொழாமல் கணவனையே தெய்வமாகத் தொழுது வாழும் மனைவி, பெய் என்று சொன்னால் மழை பெய்யும்.", meaningEn: "If she, who does not worship God, but who rising worships her partner, say, \"let it rain,\" it will rain." },
  { number: 56, line1: "தற்காத்துத் தற்கொண்டாற் பேணித் தகைசான்ற", line2: "சொற்காத்துச் சோர்விலாள் பெண்.", meaningTa: "கற்பு நெறியில் தன்னையும் காத்துக்கொண்டு, தன்கணவனையும் காப்பாற்றி, தகுதியமைந்த புகழையும் காத்து உறுதி தளராமல்.", meaningEn: "She is a partner who unweariedly guards herself, takes care of her partner, and preserves an unsullied a good name." },
  { number: 57, line1: "சிறைகாக்கும் காப்பெவன் செய்யும் மகளிர்", line2: "நிறைகாக்கும் காப்பே தலை.", meaningTa: "தம்மைத் தாமே காத்துக்கொண்டு சிறந்த பண்புடன் வாழும் மகளிரை அடிமைகளாக நடத்த எண்ணுவது அறியாமையாகும்.", meaningEn: "What avails the guard of a prison ? The chief guard of a woman is her chastity." },
  { number: 58, line1: "பெற்றாற் பெறின்பெறுவர் பெண்டிர் பெருஞ்சிறப்புப்", line2: "புத்தேளிர் வாழும் உலகு.", meaningTa: "கணவனைப் போற்றிக் கடமையைச் செய்யப்பெற்றால் மகளிர் பெரிய சிறப்பை உடைய மேலுலகவாழ்வைப் பெறுவர்.", meaningEn: "If women show reverence to their partners, they will obtain great excellence in the world where the gods do well." },
  { number: 59, line1: "புகழ்புரிந்த இல்லிலோர்க்கு இல்லை இகழ்வார்முன்", line2: "ஏறுபோல் பீடு நடை.", meaningTa: "புகழை விரும்பிய மனைவியைப் பெறாதவர்க்கு அவர்களை ஏளனம் செய்வார் முன்னே ஆண் சிங்கமாய் நடக்கும் பெருமித நடை இல்லை.", meaningEn: "The man whose partner seeks not the praise (of chastity) can't walk with lion-like stately step, before those who revile them." },
  { number: 60, line1: "மங்கலம் என்ப மனைமாட்சி மற்று அதன்", line2: "நன்கலம் நன்மக்கட் பேறு.", meaningTa: "குடும்பத்தின் பண்பாடுதான் இல்வாழ்க்கையின் சிறப்பு; அதற்கு மேலும் சிறப்பு நல்ல பிள்ளைகளைப் பெற்றிருப்பது.", meaningEn: "The excellence of a partner is the good of her partner; and good children are the jewels of that goodness." },
  { number: 61, line1: "பெறுமவற்றுள் யாமறிவது இல்லை அறிவறிந்த", line2: "மக்கட்பேறு அல்ல பிற.", meaningTa: "அறிவில் சிறந்த நல்ல பிள்ளைகளைவிட இல்வாழ்க்கையில் சிறந்த பேறு வேறு எதுவுமில்லை.", meaningEn: "Among all the benefits that may be acquired, we know no greater benefit than the acquisition of intelligent children." },
  { number: 62, line1: "எழுபிறப்பும் தீயவை தீண்டா பழிபிறங்காப்", line2: "பண்புடை மக்கட் பெறின்.", meaningTa: "பழிக்கப்படாத நல்ல குணங்களை உடைய பிள்ளைகளைப் பெற்றால், பெற்றவளை அவனுடைய பிறவிகள்தோறும் துன்பங்கள் தொடமாட்டா.", meaningEn: "No evil comes and no blemish; Noble sons bring all we wish." },
  { number: 63, line1: "தம்பொருள் என்பதம் மக்கள் அவர்பொருள்", line2: "தம்தம் வினையான் வரும்.", meaningTa: "தம் பொருள் என்பது தம்மக்களையேயாம் அம்மக்களின் பொருள்கள் அவரவர் செயல்களின் விளைவாக வரக்கூடியவை.", meaningEn: "People will call their sons their wealth, because it flows to them through the deeds which they (sons) perform on their behalf." },
  { number: 64, line1: "அமிழ்தினும் ஆற்ற இனிதேதம் மக்கள்", line2: "சிறுகை அளாவிய கூழ்.", meaningTa: "தம் பிள்ளைகளின் சிறு கையால் பிசையப்பட்ட கூழ், அமிழ்தைக் காட்டிலும் மிக இனிது.", meaningEn: "The rice in which the little hand of their children has dabbled will be far sweeter (to the parent) than sweet magic water." },
  { number: 65, line1: "மக்கள்மெய் தீண்டல் உடற்கின்பம் மற்றுஅவர்", line2: "சொற்கேட்டல் இன்பம் செவிக்கு.", meaningTa: "பெற்ற பிள்ளைகளின் உடலைத் தழுவுவது உடலுக்கு இன்பம். அவர்களின் பேச்சைக் கேட்பது காதிற்கு இன்பம்.", meaningEn: "The touch of children gives pleasure to the body, and the hearing of their words, pleasure to the ear." },
  { number: 66, line1: "குழல்இனிது யாழ்இனிது என்பதம் மக்கள்", line2: "மழலைச்சொல் கேளா தவர்.", meaningTa: "பெற்ற பிள்ளைகள் பேசும் பொருளற்ற மழலைச் சொல்லைக் கேட்காதவர்தாம், குழலும் யாழும் கேட்க இனியவை என்பர்.", meaningEn: "\"The pipe is sweet, the lute is sweet,\" say those who have not heard the prattle of their own children." },
  { number: 67, line1: "தந்தை மகற்காற்றும் நன்றி அவையத்து", line2: "முந்தி இருப்பச் செயல்.", meaningTa: "தகப்பன் தன் பிள்ளைக்குச் செய்யும் நன்மை, கற்றவர் அவையில் முதன்மைப் பெறச் செய்வதே.", meaningEn: "The benefit which a father should confer on his son is to give him precedence in the assembly of the learned." },
  { number: 68, line1: "தம்மின்தம் மக்கள் அறிவுடைமை மாநிலத்து", line2: "மன்னுயிர்க் கெல்லாம் இனிது.", meaningTa: "தம் மக்களின் அறிவுடைமை தமக்கு இன்பம் பயப்பதை விட உலகத்து உயிர்களுக்கேல்லாம் மிகுந்த இன்பம் பயப்பதாகும்.", meaningEn: "That their children should possess knowledge is more pleasing to all people of this great earth than to themselves." },
  { number: 69, line1: "ஈன்ற பொழுதின் பெரிதுவக்கும் தன்மகனைச்", line2: "சான்றோன் எனக்கேட்ட தாய்.", meaningTa: "நல்ல மகனைப் பெற்றெடுத்தவள் என்று ஊரார் பாராட்டும் பொழுது அவனைப் பெற்றபொழுது அடைந்த மகிழ்ச்சியைவிட அதிக மகிழ்ச்சியை.", meaningEn: "The mother who hears her son called \"a wise man\" will rejoice more than she did at his birth." },
  { number: 70, line1: "மகன்தந்தைக்கு ஆற்றும் உதவி இவன்தந்தை", line2: "என்நோற்றான் கொல் எனும் சொல்.", meaningTa: "``ஆகா! இவனைப் பிள்ளையாகப் பெற்றது இவன் தந்தை பெற்ற பெறும்பேறு'', என்று ஒரு மகன் புகழப்படுவதுதான், அவன் தன்னுடைய.", meaningEn: "That it may be said \"by what great hard good practice did his father beget him,\" is the benefit which a son should render to his father." },
  { number: 71, line1: "அன்பிற்கும் உண்டோ அடைக்குந்தாழ் ஆர்வலர்", line2: "புன்கணீர் பூசல் தரும்.", meaningTa: "அன்புக்கும் அடைத்து வைக்கும் தாழ் உண்டோ? அன்புடையவரின் சிறு கண்ணீரே பலரும் அறிய வெளிப்படுத்திவிடும்.", meaningEn: "Is there any fastening that can shut in caring ? Tears of the affectionate will publish the caring that is within." },
  { number: 72, line1: "அன்பிலார் எல்லாம் தமக்குரியர் அன்புடையார்", line2: "என்பும் உரியர் பிறர்க்கு.", meaningTa: "அன்பு இல்லாதவர் எல்லாப்பொருள்களையும் தமக்கே உரிமையாகக் கொண்டு வாழ்வார்: அன்பு உடையவர் தம் உடமையும் பிறர்க்கு.", meaningEn: "Those who are destitute of caring appropriate all they have to themselves; but those who possess caring consider even their bones to belong to others." },
  { number: 73, line1: "அன்போடு இயைந்த வழக்கென்ப ஆருயிர்க்கு", line2: "என்போடு இயைந்த தொடர்பு.", meaningTa: "உயிரும் உடலும்போல் அன்பும் செயலும் இணைந்திருப்பதே உயர்ந்த பொருத்தமாகும்.", meaningEn: "They say that the union of soul and body in man is the fruit of the union of caring and goodness (in a former birth)." },
  { number: 74, line1: "அன்புஈனும் ஆர்வம் உடைமை அதுஈனும்", line2: "நண்பு என்னும் நாடாச் சிறப்பு.", meaningTa: "அன்பு பிறரிடம் பற்றுள்ளம் கொள்ளச் செய்யும் அந்த உள்ளம், நட்பு எனும் பெருஞ்சிறப்பை உருவாக்கும்.", meaningEn: "Caring begets wants: and that (wants) begets the immeasureable excellence of friendship." },
  { number: 75, line1: "அன்புற்று அமர்ந்த வழக்கென்ப வையகத்து", line2: "இன்புற்றார் எய்தும் சிறப்பு.", meaningTa: "உலகில் இன்புற்று வாழ்கின்றவர்க்கு வாய்க்கும் சிறப்பு, அவர் அன்புள்ளம் கொண்டவராக விளங்குவதன் பயனே என்று கூறலாம்.", meaningEn: "These are the fruits of tranquil life of caring." },
  { number: 76, line1: "அறத்திற்கே அன்புசார் பென்ப அறியார்", line2: "மறத்திற்கும் அஃதே துணை.", meaningTa: "அறத்திற்கு மட்டுமே அன்பு துணையாகும் என்று கூறுவோர் அறியாதவரே; மறத்திற்கும் கூட அதுவே காரணம் ஆகும்.", meaningEn: "The ignorant say that caring is an ally to goodness only, but it is also a help to get out of wrong." },
  { number: 77, line1: "என்பி லதனை வெயில்போலக் காயுமே", line2: "அன்பி லதனை அறம்.", meaningTa: "எலும்பு இல்லாத புழுவை வெயில் காய்ந்து கொள்வது போல அன்பு இல்லாத உயிரை அறக்கடவுள் காய்ந்து கொல்லும்.", meaningEn: "Goodness will burn up the soul which is without caring, even as the sun burns up the creature which is without bone, ie worms." },
  { number: 78, line1: "அன்பகத் தில்லா உயிர்வாழ்க்கை வன்பாற்கண்", line2: "வற்றல் மரந்தளிர்த் தற்று.", meaningTa: "மனத்தில் அன்பு இல்லாதவருடைய வாழ்க்கை, பாலைவனத்தில் பட்டமரம் தளிர்த்தது போன்றது.", meaningEn: "The domestic state of that man whose mind is without caring is like the do welling of a withered tree upon the parched desert." },
  { number: 79, line1: "புறத்துறுப் பெல்லாம் எவன்செய்யும் யாக்கை", line2: "அகத்துறுப்பு அன்பி லவர்க்கு.", meaningTa: "அன்பு எனும் அகத்து உறுப்பு இல்லாதவர்க்குப் புறத்து உறுப்புகள் அழகாக இருந்து என்ன பயன்?", meaningEn: "Of what avail are all the external members (of the body) to those who are destitute of caring, the internal member." },
  { number: 80, line1: "அன்பின் வழியது உயிர்நிலை அஃதிலார்க்கு", line2: "என்புதோல் போர்த்த உடம்பு.", meaningTa: "அன்பின் வழியில் இயங்கும் உடம்பே உயிர்நின்ற உடம்பாகும்: அன்பு இல்லாதவர்க்கு உள்ள உடம்பு எலும்பைத் தோல்போர்த்த.", meaningEn: "That body alone which is inspired with caring contains a living soul: if void of it, (the body) is bone overlaid with skin." },
  { number: 81, line1: "இருந்தோம்பி இல்வாழ்வ தெல்லாம் விருந்தோம்பி", line2: "வேளாண்மை செய்தற் பொருட்டு.", meaningTa: "இல்லறத்தைப் போற்றி வாழ்வது, விருந்தினரை வரவேற்று, அவர்க்கு வேண்டிய உதவிகளைச் செய்வதற்காகவே.", meaningEn: "The whole design of living in the domestic state and laying up (property) is (to be able) to exercise the kindness of hospitality." },
  { number: 82, line1: "விருந்து புறத்ததாத் தானுண்டல் சாவா", line2: "மருந்தெனினும் வேண் டற்பாற் றன்று.", meaningTa: "விருந்தினராக வந்தவரை வெளியே விட்டுவிட்டுச் சாகாத மருந்தாக இருந்தாலும் அதனைத் தான் மட்டும் உண்பது விரும்பத் தக்க.", meaningEn: "It isn't fit that one should wish his guests to be outside (his house) even though he were eating the food of immortality." },
  { number: 83, line1: "வருவிருந்து வைகலும் ஓம்புவான் வாழ்க்கை", line2: "பருவந்து பாழ்படுதல் இன்று.", meaningTa: "நாளும் வரும் விருந்தினரைப் பேணுபவனின் வாழ்க்கை வறுமைப்பட்டுக் கெட்டுப் போவது இல்லை.", meaningEn: "Who tends his guests day in and out His life in want never wears out." },
  { number: 84, line1: "அகனமர்ந்து செய்யாள் உறையும் முகனமர்ந்து", line2: "நல்விருந்து ஓம்புவான் இல்.", meaningTa: "இனிய முகத்தோடு தக்க விருந்தினரைப் பேணுபவரின் வீட்டில் திருமகள் மனம் மகிழ்ந்து குடி இருப்பாள்.", meaningEn: "The goddess of wealth will gladly rest Where smiles welcome the worthy guest." },
  { number: 85, line1: "வித்தும் இடல்வேண்டும் கொல்லோ விருந்தோம்பி", line2: "மிச்சில் மிசைவான் புலம்.", meaningTa: "விருந்தினர் முதலில் உண்ண, மிஞ்சியவற்றையே உண்பவனின் நிலத்தில் விதைக்கவும் வேண்டுமா?", meaningEn: "Is it necessary to sow the field of the man who, having feasted his guests, eats what may remain ?" },
  { number: 86, line1: "செல்விருந்து ஓம்பி வருவிருந்து பார்த்திருப்பான்", line2: "நல்வருந்து வானத் தவர்க்கு.", meaningTa: "வந்த விருந்தினரைப் போற்றி, இனிவரும் விருந்தினரை எதிர் பார்த்திருப்பவன், வானுலகத்தில் உள்ள தேவர்க்கும் நல்ல.", meaningEn: "He who, having entertained the guests that have come, looks out for others who may yet come, will be a welcome guest to the inhabitants of heaven." },
  { number: 87, line1: "இனைத்துணைத் தென்பதொன் றில்லை விருந்தின்", line2: "துணைத்துணை வேள்விப் பயன்.", meaningTa: "விருந்தினராக வந்தவரின் சிறப்பை எண்ணிப் பார்த்து விருந்தோம்பலை ஒரு வேள்வியாகவே கருதலாம்.", meaningEn: "The advantages of kindness can't be measured; the measure (of the goodness) of the guests (entertained) is the only measure." },
  { number: 88, line1: "பரிந்தோம்பிப் பற்றற்றேம் என்பர் விருந்தோம்பி", line2: "வேள்வி தலைப்படா தார்.", meaningTa: "விருந்தினரை ஓம்பி அந்த வேள்வியில் ஈடுபடாதவர் பொருள்களை வருந்திக்காத்துப் பற்றுக்கொடு இழந்தோமே என்று இரங்குவர்.", meaningEn: "Who loathe guest-serwrong one day cry: \\\"We toil and store; but life is dry\\\"." },
  { number: 89, line1: "உடைமையுள் இன்மை விருந்தோம்பல் ஓம்பா", line2: "மடமை மடவார்கண் உண்டு.", meaningTa: "செல்வநிலையில் உள்ள வறுமை என்பது விருந்தோம்புதலைப் போற்றாத அறியாமையாகும்: அஃது அறிவிலிகளிடம் உள்ளதாகும்.", meaningEn: "That stupidity which excercises no hospitality is poverty in the midst of wealth It is the property of the stupid." },
  { number: 90, line1: "மோப்பக் குழையும் அனிச்சம் முகந்திரிந்து", line2: "நோக்கக் குநழ்யும் விருந்து.", meaningTa: "தொட்டு மோந்து பார்த்த அளவில் அனிச்சப்பூ வாடும்; நம் முகம் வேறுபட்டுப் பார்த்த அளவில் விருந்து வாடும்.", meaningEn: "As the Anicham flower fades in smelling, so fades the guest when the face is turned away." },
  { number: 91, line1: "இன்சொலால் ஈரம் அளைஇப் படிறுஇலவாம்", line2: "செம்பொருள் கண்டார்வாய்ச் சொல்.", meaningTa: "அறம் அறிந்தவர் வாயிலிருந்து பிறந்து, அன்பு கலந்து உள்நோக்கம் இல்லாது வருவதே இனிய சொல்.", meaningEn: "Sweet words are those which imbued with caring and free from deceit flow from the mouth of the good." },
  { number: 92, line1: "அகன்அமர்ந்து ஈதலின் நன்றே முகனமர்ந்து", line2: "இன்சொலன் ஆகப் பெறின்.", meaningTa: "முகம் மலர்ந்து இனிமையாகப் பேசுவது, அகம் குளிர்ந்து ஒன்றைக் கொடுப்பதை விட மேலான பண்பாகும்.", meaningEn: "Sweet speech, with a cheerful countenance is better than a gift made with a joyous mind." },
  { number: 93, line1: "முகத்தான் அமர்ந்து இனிதுநோக்கி அகத்தானாம்", line2: "இன்சொ லினதே அறம்.", meaningTa: "முகம் மலர நோக்கி, அகம் மலர இனிய சொற்களைக் கூறுவதே அறவழியில் அமைந்த பண்பாகும்.", meaningEn: "Sweet speech, flowing from the heart (uttered) with a cheerful countenance and a sweet look, is true goodness." },
  { number: 94, line1: "துன்புறூஉம் துவ்வாமை இல்லாகும் யார்மாட்டும்", line2: "இன்புறூஉம் இன்சொ லவர்க்கு.", meaningTa: "எவரிடமும் இன்பம் தரும் இனிய சொற்களைப் பேசுபவர்க்குத் துன்பம் தரும் வறுமை வராது.", meaningEn: "Whose loving words delight each one The woe of want from them is gone." },
  { number: 95, line1: "பணிவுடையன் இன்சொலன் ஆதல் ஒருவற்கு", line2: "அணியல்ல மற்றுப் பிற.", meaningTa: "வணக்கம் உடையவனாகவும் இன்சொல் வழங்குவோனாகவும் ஆதலே ஒருவனுக்கு அணிகலனாகும் மற்றவை அணிகள் அல்ல.", meaningEn: "Humility and sweetness of speech are the ornaments of man; all others aren't (ornaments)." },
  { number: 96, line1: "அல்லவை தேய அறம்பெருகும் நல்லவை", line2: "நாடி இனிய சொலின்", meaningTa: "பிறர்க்கு நன்மையானவற்றை நாடி இனிமை உடையச் சொற்களைச் சொல்லின், பாவங்கள் தேய்ந்து குறைய அறம் வளர்ந்து பெருகும்.", meaningEn: "If a person, while seeleader to speak usefully, speaks also sweetly, his sins will get smaller and his goodness increase." },
  { number: 97, line1: "நயன்ஈன்று நன்றி பயக்கும் பயன்ஈன்று", line2: "பண்பின் தலைப்பிரியாச் சொல்.", meaningTa: "நன்மையான பயனைத் தரக்கூடிய நல்ல பண்பிலிருந்து விலகாத சொற்கள் அவற்றைக் கூறுவோருக்கும் இன்பத்தையும், நன்மையையும்.", meaningEn: "That speech which, while imparting benefits ceases not to please, will yield righteousness (for this world) and merit (for the next world)." },
  { number: 98, line1: "சிறுமையுவு நீங்கிய இன்சொல் மறுமையும்", line2: "இம்மையும் இன்பம் தரும்.", meaningTa: "பிறர்க்கு மனத்துன்பம் தராத இனிய சொல் ஒருவனுக்கு இம்மையிலும் மறுமையிலும் இன்பம் தரும்.", meaningEn: "Sweet speech, free from harm to others, will give pleasure both in this world and in the next." },
  { number: 99, line1: "இன்சொல் இனிதீன்றல் காண்பான் எவன்கொலோ", line2: "வன்சொல் வழங்கு வது?", meaningTa: "இனிய சொற்கள் இன்பம் பயத்தலைக் காண்கின்றவன், அவற்றிற்கு மாறான வன்சொற்களை வழங்குவது என்ன பயன் கருதியோ?", meaningEn: "Why does he use harsh words, who sees the pleasure which sweet speech yields ?" },
  { number: 100, line1: "இனிய உளவாக இன்னாத கூறல்", line2: "கனிஇருப்பக் காய்கவர்ந் தற்று.", meaningTa: "இனிமையான சொற்கள் இருக்கும்போது அவற்றை விடுத்துக் கடுமையாகப் பேசுவது கனிகளை ஒதுக்கி விட்டுக் காய்களைப் பறித்துத்.", meaningEn: "To say disagreeable things when agreeable are at hand is like eating unripe fruit when there is ripe." },
  { number: 101, line1: "செய்யாமல் செய்த உதவிக்கு வையகமும்", line2: "வானகமும் ஆற்றல் அரிது.", meaningTa: "நாம் உதவி செய்யாதபோதும் ஒருவர் நமக்கு உதவினால், அந்த உதவி உலகை விட பெரியது.", meaningEn: "When someone helps you even though you never helped them first, that kindness is bigger than the whole world." },
  { number: 102, line1: "காலத்தி னாற்செய்த நன்றி சிறிதெனினும்", line2: "ஞாலத்தின் மாணப் பெரிது.", meaningTa: "தேவைப்படும் காலத்தில் செய்யப்படும் உதவி சிறிதளவாக இருந்தாலும், அது உலகத்தைவிடப் பெரிதாக மதிக்கப்படும்.", meaningEn: "A favour conferred in the time of need, though it be small (in itself), is (in value) much larger than the world." },
  { number: 103, line1: "பயன்தூக்கார் செய்த உதவி நயன்தூக்கின்", line2: "நன்மை கடலின் பெரிது.", meaningTa: "என்ன பயன் கிடைக்கும் என்று எண்ணிப் பார்க்காமலே, அன்பின் காரணமாக ஒருவர் செய்த உதவியின் சிறப்பு கடலை விடப் பெரிது.", meaningEn: "If we weigh the excellence of a benefit which is conferred without weighing the return, it is larger than the sea." },
  { number: 104, line1: "தினைத்துணை நன்றி செயினும் பனைத்துணையாக்", line2: "கொள்வர் பயன்தெரி வார்.", meaningTa: "ஒருவன் தினையளவாகிய உதவியைச் செய்த போதிலும் அதன் பயனை ஆராய்கின்றவர், அதனையே பனையளவாகக் கொண்டு போற்றுவர்.", meaningEn: "Though the benefit conferred be as small as a millet seed, those who know its advantage will consider it as large as a palmyra fruit." },
  { number: 105, line1: "உதவி வரைத்தன்று உதவி உதவி", line2: "செயப்பட்டார் சால்பின் வரைத்து.", meaningTa: "உதவி என்பது, செய்யப்படும் அளவைப் பொருத்துச் சிறப்படைவதில்லை; அந்த உதவியைப் பெறுபவரின் பண்பைப் பொருத்தே அதன் அளவு.", meaningEn: "The benefit itself isn't the measure of the benefit; the worth of those who have received it is its measure." },
  { number: 106, line1: "மறவற்க மாசற்றார் கேண்மை துறவற்க", line2: "துன்பத்துள் துப்பாயார் நட்பு.", meaningTa: "மாசற்றவர்களின் உறவை மறக்கவும் கூடாது; துன்பத்தில் துணை நின்றவர் நட்பைத் துறக்கவும் கூடாது.", meaningEn: "Forsake not the friendship of those who have been your staff in adversity Forget not be kindness of the blameless." },
  { number: 107, line1: "எழுமை எழுபிறப்பும் உள்ளுவர் தங்கண்", line2: "விழுமந் துடைத்தவர் நட்பு.", meaningTa: "தம் துன்பத்தைப் போக்கியவரின் நட்பை ஏழேழு பிறப்பிலும் நல்லவர் எண்ணுவர்.", meaningEn: "Will remember throughout their seven-fold births the caring of those who have wiped away their hard times." },
  { number: 108, line1: "நன்றி மறப்பது நன்றன்று நன்றல்லது", line2: "அன்றே மறப்பது நன்று.", meaningTa: "ஒருவன் நமக்குச் செய்த உதவியை மறப்பது அறம் அன்று; அவன் செய்த தீமையை அப்போதே மறப்பது அறம்.", meaningEn: "It isn't good to forget a benefit; it is good to forget an injury even in the very moment (in which it is inflicted)." },
  { number: 109, line1: "கொன்றன்ன இன்னா செயினும் அவர்செய்த", line2: "ஒன்றுநன்று உள்ளக் கெடும்.", meaningTa: "ஒருவர் செய்யும் மிகக் கொடுமையான தீமைகூட நமது உள்ளத்தைப் புண்படுத்தாமல் அகன்றுவிட வேண்டுமானால், அந்த ஒருவர் முன்னர்.", meaningEn: "Though one inflict an injury great as murder, it will perish before the thought of one benefit (formerly) conferred." },
  { number: 110, line1: "எந்நன்றி கொன்றார்க்கும் உய்வுண்டாம் உய்வில்லை", line2: "செய்ந்நன்றி கொன்ற மகற்கு.", meaningTa: "எந்த அறத்தை மறந்தார்க்கும் வாழ்வு உண்டு; ஆனால் ஒருவர் செய்த உதவியை மறந்தார்க்கு வாழ்வில்லை.", meaningEn: "He who has killed every goodness may yet escape; there is no escape for God who has killed a benefit." },
  { number: 111, line1: "தகுதி எனவொன்று நன்றே பகுதியால்", line2: "பாற்பட்டு ஒழுகப் பெறின்.", meaningTa: "அந்தந்தப் பகுதிதோறும் முறையோடு பொருந்தி ஒழுகப்பெற்றால், நடுவுநிலைமை என்று கூறப்படும் அறம் நன்மையாகும்.", meaningEn: "That equity which consists in acting with equal regard to each of (the three) divisions of people [people who fight you, strangers and friends] is a." },
  { number: 112, line1: "செப்பம் உடையவன் ஆக்கஞ் சிதைவின்றி", line2: "எச்சத்திற் கேமாப்பு உடைத்து.", meaningTa: "நீதியை உடையவனின் செல்வம் அழியாமல் அவன் வழியினர்க்குப் பாதுகாப்பாக இருக்கும்.", meaningEn: "The wealth of the man of rectitude won't perish, but will bring happiness also to his posterity." },
  { number: 113, line1: "நன்றே தரினும் நடுவிகந்தாம் ஆக்கத்தை", line2: "அன்றே யொழிய விடல்.", meaningTa: "நன்மையே தருவதாக இருந்தாலும் நீதியை விட்டு விலகுவதால் வரும் லாபத்தை, அப்பொழுதே விட்டு விடுக.", meaningEn: "Forsake in the very moment (of acquisition) that gain which, though it should bring advantage, is without equity." },
  { number: 114, line1: "தக்கார் தகவிலர் என்பது அவரவர்", line2: "எச்சத்தாற் காணப்ப படும்.", meaningTa: "நடுவுநிலைமை உடையவர் நடுவுநிலை‌மை இல்லாதவர் என்பது அவரவர்க்குப் பின் எஞ்சி நிற்கும் புகழாலும் பழியாலும் காணப்படும்.", meaningEn: "The worthy and unworthy may be known by the existence or otherwise of good offsprings." },
  { number: 115, line1: "கேடும் பெருக்கமும் இல்லல்ல நெஞ்சத்துக்", line2: "கோடாமை சான்றோர்க் கணி.", meaningTa: "தீமையும் நன்மையும் எல்லார்க்கும் முன்பே குறிக்கப்பட்டு விட்டன; இதை அறிந்து நெஞ்சத்தால் நீதி தவறாது இருப்பது.", meaningEn: "Loss and gain come not without cause; it is the ornament of the wise to preserve evenness of mind (under both)." },
  { number: 116, line1: "கெடுவல்யான் என்பது அறிகதன் நெஞ்சம்", line2: "நடுவொரீஇ அல்ல செயின்.", meaningTa: "தன் நெஞ்சம் நீதியை விட்டுவிட்டு அநீதி செய்ய எண்ணி னால், அதுவே தான் கெடப் போவதற்கு உரிய அறிகுறி.", meaningEn: "Of perdition let him be sure Who leaves justice to sinful lure." },
  { number: 117, line1: "கெடுவாக வையாது உலகம் நடுவாக", line2: "நன்றிக்கண் தங்கியான் தாழ்வு.", meaningTa: "நடுவுநிலைமை நின்று அறநெறியில் நிலைத்து வாழகின்றவன் அடைந்த வறுமை நிலையைக் கேடு என கொள்ளாது உலகு.", meaningEn: "The great won't regard as poverty the low estate of that man who dwells in the goodness of equity." },
  { number: 118, line1: "சமன்செய்து சீர்தூக்குங் கோல்போல் அமைந்தொருபால்", line2: "கோடாமை சான்றோர்க் கணி.", meaningTa: "முன்னே தான் சமமாக இருந்து, பின்பு பொருளைச் சீர்தூக்கும் துலாக்கோல் போல் அமைந்து, ஒரு பக்கமாக சாயாமல் நடுவுநி‌லைமை.", meaningEn: "To incline to neither side, but to rest impartial as the even-fixed scale is the ornament of the wise." },
  { number: 119, line1: "சொற்கோட்டம் இல்லது செப்பம் ஒருதலையா", line2: "உட்கோட்டம் இன்மை பெறின்.", meaningTa: "மனம் ஓரஞ் சாராமல் சமமாக நிற்குமானால் சொல்லிலும் அநீதி பிறக்காது; அதுவே நீதி.", meaningEn: "Freedom from obliquity of speech is rectitude, if there be (corresponding) freedom from bias of mind." },
  { number: 120, line1: "வாணிகம் செய்வார்க்கு வாணிகம் பேணிப்", line2: "பிறவும் தமபோல் செயின்.", meaningTa: "பிறர் பொருளையும் தம் பொருள் போலக் காத்து, வியாபாரம் செய்தால் வியாபாரிகளுக்கு நல்ல வியாபார முறை ஆகும்.", meaningEn: "The true merchandize of merchants is to guard and do by the things of others as they do by their own." },
  { number: 121, line1: "அடக்கம் அமரருள் உய்க்கும் அடங்காமை", line2: "ஆரிருள் உய்த்து விடும்.", meaningTa: "அடக்கம் அழியாத புகழைக் கொடுக்கும் அடங்காமை வாழ்வையே இருளாக்கி விடும்.", meaningEn: "Self-control will place (a person) among the Gods; the want of it will drive (him) into the thickest darkness (of hell)." },
  { number: 122, line1: "காக்க பொருளா அடக்கத்தை ஆக்கம்", line2: "அதனினூஉங் கில்லை உயிர்க்கு.", meaningTa: "அடக்கத்தைச் செல்வமாக எண்ணிக் காக்க; அதைக் காட்டிலும் பெரிய செல்வம் வேறு இல்லை.", meaningEn: "Let self-control be guarded as a treasure; there is no greater source of good for man than that." },
  { number: 123, line1: "செறிவறிந்து சீர்மை பயக்கும் அறிவறிந்து", line2: "ஆற்றின் அடங்கப் பெறின்.", meaningTa: "அறிந்து கொள்ள வேண்டியவற்றை அறிந்து அதற்கேற்ப அடக்கத்துடன் நடந்து கொள்பவரின் பண்பை உணர்ந்து பாராட்டுகள் குவியும்.", meaningEn: "Knowing that self-control is knowledge, if a person should control himself, in the prescribed course, such self-control will bring him distinction." },
  { number: 124, line1: "நிலையின் திரியாது அடங்கியான் தோற்றம்", line2: "மலையினும் மாணப் பெரிது.", meaningTa: "தன் நிலையிலிருந்து மாறுபடாமல் அடங்கி ஒழுகுவோனுடைய உயர்வு, மலையின் உயர்வை விட மிகவும் பெரிதாகும்.", meaningEn: "More lofty than a mountain will be the greatness of that man who without swerving from his domestic state, controls himself." },
  { number: 125, line1: "எல்லார்க்கும் நன்றாம் பணிதல் அவருள்ளும்", line2: "செல்வர்க்கே செல்வம் தகைத்து.", meaningTa: "பணிவு என்னும் பண்பு, எல்லார்க்கும் நலம் பயக்கும் ஏற்கனவே செல்வர்களாக இருப்பவர்களுக்கு அந்தப் பண்பு, மேலும் ஒரு.", meaningEn: "Humility is good in all; but especially in the rich it is (the excellence of) higher riches." },
  { number: 126, line1: "ஒருமையுள் ஆமைபோல் ஐந்தடக்கல் ஆற்றின்", line2: "எழுமையும் ஏமாப் புடைத்து.", meaningTa: "ஆமை தன் நான்கு கால், ஒரு தலை ஆகிய ஐந்து உறுப்புகளையும் ஆபத்து வரும்போது ஓட்டுக்குள் மறைத்துக் கொள்வது போல, ஒருவன் தன்.", meaningEn: "Should one throughout a single birth, like a tortoise keep in his five senses, the fruit of it will prove a safe-guard to him throughout the." },
  { number: 127, line1: "யாகாவா ராயினும் நாகாக்க காவாக்கால்", line2: "சோகாப்பர் சொல்லிழுக்குப் பட்டு.", meaningTa: "ஒருவர் எதைக் காத்திட முடியாவிட்டாலும் நாவையாவது அடக்கிக் காத்திட வேண்டும் இல்லையேல் அவர் சொன்ன சொல்லே அவர்.", meaningEn: "Whatever besides you leave unguarded, guard your tongue; otherwise errors of speech and the consequent misery will ensue." },
  { number: 128, line1: "ஒன்றானுந் தீச்சொல் பொருட்பயன் உண்டாயின்", line2: "நன்றாகா தாகி விடும்.", meaningTa: "தீய சொற்களின் பொருளால் பிறர்க்கு வரும் துன்பம் சிறிதே என்றாலும் அந்தக் குறை ஒருவனிடம் இருந்தால் அவனுக்குப் பிற.", meaningEn: "If a person's speech be productive of a single evil, all the good by him will be turned into evil." },
  { number: 129, line1: "தீயினாற் சுட்டபுண் உள்ளாறும் ஆறாதே", line2: "நாவினாற் சுட்ட வடு.", meaningTa: "நெருப்பு சுட்ட புண்கூட ஆறி விடும்; ஆனால் வெறுப்புக் கொண்டு திட்டிய சொற்கள் விளைத்த துன்பம் ஆறவே ஆறாது.", meaningEn: "The wound which has been burnt in by fire may heal, but a wound burnt in by the tongue will never heal." },
  { number: 130, line1: "கதங்காத்துக் கற்றடங்கல் ஆற்றுவான் செவ்வி", line2: "அறம்பார்க்கும் ஆற்றின் நுழைந்து.", meaningTa: "கற்பவை கற்றுச், சினம் காத்து, அடக்கமெனும் பண்பு கொண்டவரை அடைந்திட அறமானது வழிபார்த்துக் காத்திருக்கும்.", meaningEn: "Goodness, seeleader for an opportunity, will come into the path of that man who, full of learning and self-control, guards himself against anger." },
  { number: 131, line1: "ஒழுக்கம் விழுப்பந் தரலான் ஒழுக்கம்", line2: "உயிரினும் ஓம்பப் படும்.", meaningTa: "ஒழுக்கம், அதை உடையவர்க்குச் சிறப்பைத் தருவதால் உயிரைக் காட்டிலும் மேலானதாக அதைக் காக்க வேண்டும்.", meaningEn: "Propriety of conduct leads to eminence, it should so be preserved more carefully than life." },
  { number: 132, line1: "பரிந்தோம்பிக் காக்க ஒழுக்கம் தெரிந்தோம்பித்", line2: "தேரினும் அஃதே துணை.", meaningTa: "எந்தெந்த வழிகளில் ஆராய்ந்தாலும் வாழ்க்கையில் ஒழுக்கமே சிறந்த துணை என்பதால், எத்தகைய துன்பத்தை ஏற்றாவது அதைக் காக்க.", meaningEn: "Let propriety of conduct be laboriously preserved and guarded; though one know and practise and excel in many goodnesss, that will be an eminent aid." },
  { number: 133, line1: "ஒழுக்கம் உடைமை குடிமை இழுக்கம்", line2: "இழிந்த பிறப்பாய் விடும்.", meaningTa: "தனி மனிதன் தான் வகிக்கும் பாத்திரத்திற்கு ஏற்ற ஒழுக்கம் உடையவனாக வாழ்வதே குடும்பப் பெருமை; அத்தகைய ஒழுக்கம் இல்லாது.", meaningEn: "Propriety of conduct is true greatness of birth, and impropriety will sink into a mean birth." },
  { number: 134, line1: "மறப்பினும் ஓத்துக் கொளலாகும் பார்ப்பான்", line2: "பிறப்பொழுக்கங் குன்றக் கெடும்.", meaningTa: "பார்ப்பான் தான் கற்ற வேதத்தை மறந்து போனாலும் பிறகு கற்றுக் கொள்ளலாம்; ஆனால், அவன் பிறந்த குலத்திற்கு ஏற்ற, மேலான.", meaningEn: "A Brahman though he should forget the Vedas may recover it by reading; but, if he fail in propriety of conduct even his high birth will be destroyed." },
  { number: 135, line1: "அழுக்கா றுடையான்கண் ஆக்கம்போன்று இல்லை", line2: "ஒழுக்க மிலான்கண் உயர்வு.", meaningTa: "பொறாமை உள்ளவனுக்குச் செல்வம் இல்லை என்பது போல், ஒழுக்கம் இல்லாதவனுக்கு உயர்குலம் என்பதும் இல்லை.", meaningEn: "Just as the envious man will be without wealth, so will the man of destitute of propriety of conduct be without greatness." },
  { number: 136, line1: "ஒழுக்கத்தின் ஒல்கார் உரவோர் இழுக்கத்தின்", line2: "ஏதம் படுபாக் கறிந்து.", meaningTa: "ஒழுக்கம் தவறுதலால் குற்றம் உண்டாவதை அறிந்து, மனவலிமை உடைய சான்றோர் ஒழுக்கத்தில் தவறாமல் காத்துக் கொள்வர்.", meaningEn: "Those firm in mind won't slacken in their observance of the proprieties of life, knowing, as they do, the misery that flows from the transgression." },
  { number: 137, line1: "ஒழுக்கத்தின் எய்துவர் மேன்மை இழுக்கத்தின்", line2: "எய்துவர் எய்தாப் பழி.", meaningTa: "நல்ல நடத்தையினால் உயர்வு ஏற்படும்; இல்லையேல் இழிவான பழி வந்து சேரும்.", meaningEn: "From propriety of conduct people obtain greatness; from impropriety comes insufferable disgrace." },
  { number: 138, line1: "நன்றிக்கு வித்தாகும் நல்லொழுக்கம் தீயொழுக்கம்", line2: "என்றும் இடும்பை தரும்.", meaningTa: "நல்லொழுக்கம், வாழ்க்கையில் நன்மைக்கு வித்தாக அமையும் தீயொழுக்கம், தீராத துன்பம் தரும்.", meaningEn: "Propriety of conduct is the seed of goodness; impropriety will ever cause sorrow." },
  { number: 139, line1: "ஒழுக்க முடையவர்க்கு ஒல்லாவே தீய", line2: "வழுக்கியும் வாயாற் சொலல்.", meaningTa: "மறந்தும் தீய சொற்களைத் தம் வாயால் கூறுவது, ஒழுக்கம் உடையவர்க்கு முடியாது.", meaningEn: "Those who study propriety of conduct won't speak evil, even forgetfully." },
  { number: 140, line1: "உலகத்தோடு ஒட்ட ஒழுகல் பலகற்றும்", line2: "கல்லார் அறிவிலா தார்", meaningTa: "உலகத்து உயர்ந்தவரோடு பொருந்த ஒழுகும் முறையைக் கற்காதவர், பல நூல்களைக் கற்றிருந்த போதிலும் அறிவில்லாதவரே ஆவர்.", meaningEn: "Those who know not how to act agreeably to the world, though they have learnt many things, are still ignorant." },
  { number: 141, line1: "பிறன்பொருளாள் பெட்டொழுகும் பேதைமை ஞாலத்து", line2: "அறம்பொருள் கண்டார்கண் இல்.", meaningTa: "பிறனுடைய உரிமையாகிய மனைவியை விரும்பி நடக்கும் அறியாமை, உலகத்தில் அறமும் பொருளும் ஆராய்ந்து கண்டவரிடம் இல்லை.", meaningEn: "The folly of desiring her who is the property of another won't be found in those who know (the attributes of) goodness and (the rights of) property." },
  { number: 142, line1: "அறன்கடை நின்றாருள் எல்லாம் பிறன்கடை", line2: "நின்றாரின் பேதையார் இல்.", meaningTa: "பிறன் மனைவியை அடைவதற்குத் துணிந்தவர்கள் அறவழியை விடுத்துத் தீயவழியில் செல்லும் கடைநிலை மனிதர்களைக் காட்டிலும்.", meaningEn: "Among all those who stand on the outside of goodness, there are no greater fools than those who stand outside their neighbour's door." },
  { number: 143, line1: "விளிந்தாரின் வேறல்லர் மன்ற தெளிந்தாரில்", line2: "தீமை புரிந்து ஒழுகு வார்.", meaningTa: "ஐயமில்லாமல் தெளிந்து நம்பியவருடைய மனைவியிடத்தே விருப்பம் கொண்டு தீமையைச் செய்து நடப்பவர், செத்தவரை விட வேறுபட்டவர்.", meaningEn: "Certainly they are no better than dead people who wants evil towards the partner of those who." },
  { number: 144, line1: "எனைத்துணையர் ஆயினும் என்னாம் தினைத்துணையும்", line2: "தேரான் பிறனில் புகல்.", meaningTa: "பிழை புரிகிறோம் என்பதைத் தினையளவுகூடச் சிந்தித்துப் பாராமல், பிறன் மனைவியிடம் விருப்பம் கொள்வது, எத்துணைப்.", meaningEn: "However great one may be, what does it avail if, without at all considering his guilt, he goes to the partner of another ?" },
  { number: 145, line1: "எளிதென இல்லிறப்பான் எய்துமெஞ் ஞான்றும்", line2: "விளியாது நிற்கும் பழி.", meaningTa: "எளிதாக அடையலாம் என எண்ணிப் பிறனுடைய மனைவியிடம் முறைகேடாக நடப்பவன் என்றும் அழியாத பழிக்கு ஆளாவான்.", meaningEn: "He who thinks lightly of going into the partner of another acquires guilt that will abide with him imperishably and for ever." },
  { number: 146, line1: "பகைபாவம் அச்சம் பழியென நான்கும்", line2: "இகவாவாம் இல்லிறப்பான் கண்.", meaningTa: "அடுத்தவன் மனைவியிடம் வரம்பு கடந்து செல்பவனை விட்டுப் பகை, பாவம், பயம், பழி என்ற நான்கும் விலகமாட்டா.", meaningEn: "Hatred, sin, fear, disgrace; these four will never leave God who goes in to his neighbour's partner." },
  { number: 147, line1: "அறனியலான் இல்வாழ்வான் என்பான் பிறனியலாள்", line2: "பெண்மை நயவா தவன்.", meaningTa: "அடுத்தவனுக்கு உரிமையானவனின் பெண்மையை விரும்பாதவன் அறத்துடன் குடும்பம் நடத்துபவன் எனப்படுவான்.", meaningEn: "He who wants not the womanhood of her who should walk according to the will of another will be praised as a good house-holder." },
  { number: 148, line1: "பிறன்மனை நோக்காத பேராண்மை சான்றோர்க்கு", line2: "அறனொன்றோ ஆன்ற வொழுக்கு.", meaningTa: "அடுத்தவன் மனைவியை மனத்துள் எண்ணாத பேராண்மை அறம் மட்டும் அன்று; சான்றோர்க்கு நிறைவான ஒழுக்கமும் ஆகும்.", meaningEn: "That noble manliness which looks not at the partner of another is the goodness and dignity of the great." },
  { number: 149, line1: "நலக்குரியார் யாரெனின் நாமநீர் வைப்பின்", line2: "பிறர்க்குரியாள் தோள்தோயா தார்.", meaningTa: "பிறன் மனைவியின் தோளைத் தீண்டாதவரே கடல் சூழ் இவ்வுலகின் பெருமைகளை அடைவதற்குத் தகுதியுடையவர்.", meaningEn: "Good in storm bound earth is with those Who clasp not arms of another's partner." },
  { number: 150, line1: "அறன்வரையான் அல்ல செயினும் பிறன்வரையாள்", line2: "பெண்மை நயவாமை நன்று.", meaningTa: "பிறன் மனைவியை விரும்பிச் செயல்படுவது அறவழியில் நடக்காதவர் செயலைவிடத் தீமையானதாகும்.", meaningEn: "Though a person perform no good deeds and commit (every) wrong, it will be well if he wants not the womanhood of her who is within the limit (of the." },
  { number: 151, line1: "அகழ்வாரைத் தாங்கும் நிலம்போலத் தம்மை", line2: "இகழ்வார்ப் பொறுத்தல் தலை.", meaningTa: "தன்னை வெட்டுவோரையும் விழாமல் தாங்குகின்ற நிலம் போல், தம்மை இகழ்வாரையும் பொறுப்பதே தலையான பண்பாகும்.", meaningEn: "To bear with those who revile us, just as the earth bears up those who dig it, is the first of goodnesss." },
  { number: 152, line1: "பொறுத்தல் இறப்பினை என்றும் அதனை", line2: "மறத்தல் அதனினும் நன்று.", meaningTa: "வரம்பு கடந்து பிறர் செய்யும் தீங்கை எப்போதும் பொறுக்க வேண்டும்; அத் தீங்கை நினைவிலும் கொள்ளாமல் மறந்து விடுதல்.", meaningEn: "Bear with reproach even when you can retaliate; but to forget it will be still better than that." },
  { number: 153, line1: "இன்மையுள் இன்மை விருந்தொரால் வன்மையுள்", line2: "வன்மை மடவார்ப் பொறை.", meaningTa: "வறுமையுள் வறுமை, வந்த விருந்தினரை உபசரிக்காதது; வலிமையுள் வலிமை அற்றவரின் ஆத்திர மூட்டல்களைப் பொறுத்துக் கொள்வது.", meaningEn: "To neglect hospitality is poverty of poverty To bear with the ignorant is might of might." },
  { number: 154, line1: "நிறையுடைமை நீங்காமை வேண்டின் பொற்யுடைமை", line2: "போற்றி யொழுகப் படும்.", meaningTa: "பொறுமையின் உறைவிடமாக இருப்பவரைத்தான் நிறைவான மனிதர் என்று உலகம் புகழும்.", meaningEn: "If you wants that greatness should never leave, you preserve in your conduct the exercise of patience." },
  { number: 155, line1: "ஒறுத்தாரை ஒன்றாக வையாரே வைப்பர்", line2: "பொறுத்தாரைப் பொன்போற் பொதிந்து.", meaningTa: "தனக்குத் தீமை செய்தவரைப் பொறுக்காமல் தண்டித்தவரைப் பெரியோர் ஒரு பொருட்டாக மதிக்கமாட்டார்; பொறுத்துக் கொண்டவரையோ.", meaningEn: "Won't at all esteem the resentful They will esteem the patient just as the gold which they lay up with care." },
  { number: 156, line1: "ஒறுத்தார்க்கு ஒருநாளை இன்பம் பொறுத்தார்க்குப்", line2: "பொன்றுந் துணையும் புகழ்.", meaningTa: "தீங்கு செய்தவரைப் பொறுக்காமல் வருத்தினவர்க்கு ஒருநாள் இன்பமே; பொறுத்தவர்க்கு உலகம் அழியும் வரைக்கும் புகழ் உண்டு.", meaningEn: "The pleasure of the resentful continues for a day The praise of the patient will continue until (the final destruction of) the world." },
  { number: 157, line1: "திறனல்ல தற்பிறர் செய்யினும் நோநொந்து", line2: "அறனல்ல செய்யாமை நன்று.", meaningTa: "பிறர் செய்திடும் இழிவான காரியங்களுக்காகத் துன்பமுற்று வருந்தி, பதிலுக்கு அதே காரியங்களைச் செய்து பழி.", meaningEn: "Though others inflict injuries on you, yet comstrong feelingsating the evil (that will come upon them) it will be well not to do them anything." },
  { number: 158, line1: "மிகுதியான் மிக்கவை செய்தாரைத் தாந்தம்", line2: "தகுதியான் வென்று விடல்.", meaningTa: "மனச் செருக்கால் தீமை செய்தவரைப் பொறுமையால் வென்றுவிடுக.", meaningEn: "A person should by patience overcome those who through pride commit excesses." },
  { number: 159, line1: "துறந்தாரின் தூய்மை உடையர் இறந்தார்வாய்", line2: "இன்னாச்சொல் நோற்கிற் பவர்.", meaningTa: "எல்லை கடந்து நடந்து கொள்பவர்களின் கொடிய சொற்களைப் பொறுத்துக் கொள்பவர்கள் தூய்மையான துறவிகளைப் போன்றவர்கள்.", meaningEn: "Those who bear with the uncourteous speech of the insolent are as pure as the people who live simply." },
  { number: 160, line1: "உண்ணாது நோற்பார் பெரியர் பிறர்சொல்லும்", line2: "இன்னாச்சொல் நோற்பாரின் பின்.", meaningTa: "பசி பொறுத்து உண்ணாநோன்பு இருக்கும் உறுதி படைத்தவர்கள்கூடப் பிறர்கூறும் கொடுஞ்சொற்களைப் பொறுத்துக் கொள்பவர்களுக்கு,.", meaningEn: "Those who endure abstinence from food are great, next to those who endure the uncourteous speech of others." },
  { number: 161, line1: "ஒழுக்காறாக் கொள்க ஒருவன்தன் நெஞ்சத்து", line2: "அழுக்காறு இலாத இயல்பு.", meaningTa: "உள்ளத்துள் பொறாமை இல்லாமல் வாழும் குணத்தை, ஒருவன் தனக்கு உரிய ஒழுக்கமாகக் கொள்க.", meaningEn: "A person should esteem that disposition which is free from envy in the same manner as propriety of conduct." },
  { number: 162, line1: "விழுப்பேற்றின் அஃதொப்பது இல்லையார் மாட்டும்", line2: "அழுக்காற்றின் அன்மை பெறின்.", meaningTa: "எவர் இடத்தும் பொறாமை கொள்ளாதிருப்பதை ஒருவன் பெற்றால் சீரிய சிறப்புகளுள் அது போன்றது வேறு இல்லை.", meaningEn: "Amongst all attainable excellences there is none equal to that of being free from envy towords others." },
  { number: 163, line1: "அறன்ஆக்கம் வேண்டாதான் என்பான் பிறனாக்கம்", line2: "பேணாது அழுக்கறுப் பான்.", meaningTa: "பிறர் உயர்வு கண்டு மகிழாமல் பொறாமைப்படுபவன், அறத்தால் வரும் புண்ணியத்தை வேண்டா என மறுப்பவன் ஆவான்.", meaningEn: "Of God who instead of rejoicing in the wealth of others, envies it, it will be said \"he neither wants goodness not wealth.\"." },
  { number: 164, line1: "அழுக்காற்றின் அல்லவை செய்யார் இழுக்காற்றின்", line2: "ஏதம் படுபாக்கு அறிந்து.", meaningTa: "பொறாமை கொண்டால் துன்பம் வரும் என்பதை அறிந்து அறிவுடையோர் பொறாமை காரணமாகத் தீமைகளைச் செய்யமாட்டார்.", meaningEn: "Knowing the misery that comes from transgression won't through envy commit unrighteous deeds." },
  { number: 165, line1: "அழுக்காறு உடையார்க்கு அதுசாலும் ஒன்னார்", line2: "வழுக்காயும் கேடீன் பது.", meaningTa: "பொறாமை உடையவர்க்குத் தீமை தரப் பகைவர் வேண்டியதில்லை; பொறாமையே போதும்.", meaningEn: "To those who cherish envy that is enough Though free from people who fight you that (envy) will bring destruction." },
  { number: 166, line1: "கொடுப்பது அழுக்கறுப்பான் சுற்றம் உடுப்பதூஉம்", line2: "உண்பதூஉம் இன்றிக் கெடும்.", meaningTa: "பிறர்க்குக் கொடுப்பதைக் கண்டு பொறாமைப் படுகிறவனின் குடும்பம், உடுக்கவும், உண்ணவும் இல்லாமல் அலையும்.", meaningEn: "He who is envious at a gift (made to another) will with his relations utterly perish destitute of food and rainment." },
  { number: 167, line1: "அவ்வித்து அழுக்காறு உடையானைச் செய்யவள்", line2: "தவ்வையைக் காட்டி விடும்.", meaningTa: "பொறாமை உடையவனைத் திருமகள் கண்டு பொறாமைப்பட்டுத் தன் தமக்கைக்கு அவனைக் காட்டி நீங்கி விடுவாள்.", meaningEn: "Lakshmi envying (the doing well) of the envious man will depart and introduce him to her sister." },
  { number: 168, line1: "அழுக்காறு எனஒரு பாவி திருச்செற்றுத்", line2: "தீயுழி உய்த்து விடும்.", meaningTa: "பொறாமை எனும் தீமை ஒருவனுடைய செல்வத்தையும் சிதைத்துத் தீய வழியிலும் அவனை விட்டுவிடும்.", meaningEn: "Envy will destroy (a person's) wealth (in his world) and drive him into the pit of fire (in the world to come.)." },
  { number: 169, line1: "அவ்விய நெஞ்சத்தான் ஆக்கமும் செவ்வியான்", line2: "கேடும் நினைக்கப் படும்.", meaningTa: "பொறாமை கொண்ட மனத்தவனின் உயர்வும், அது இல்லாத நல்லவனின் தாழ்வும் பற்றி ஆராய்க.", meaningEn: "The wealth of a person of envious mind and the poverty of the righteous will be pondered." },
  { number: 170, line1: "அழுக்கற்று அகன்றாரும் இல்லை அஃதுஇல்லார்", line2: "பெருக்கத்தில் தீர்ந்தாரும் இல்.", meaningTa: "பொறாமை கொண்டு உயர்ந்தவரும் இல்லை. அது இல்லாதபோது தாழ்ந்தவரும் இல்லை.", meaningEn: "Never have the envious become great; never have those who are free from envy been without greatness." },
  { number: 171, line1: "நடுவின்றி நன்பொருள் வெஃகின் குடிபொன்றிக்", line2: "குற்றமும் ஆங்கே தரும்.", meaningTa: "பிறர்க்குரிய பொருளை அநீதியாக விரும்பிக் கவர்ந்தால், கவர்ந்தவனின் குடும்பம் அழியும்; குற்றங்கள் பெருகும்.", meaningEn: "If a person departing from equity wants what others have the property (of others), at that very time will his family be destroyed and guilt be." },
  { number: 172, line1: "படுபயன் வெஃகிப் பழிப்படுவ செய்யார்", line2: "நடுவன்மை நாணு பவர்.", meaningTa: "பிறர் பொருளைக் கவர்ந்து அனுபவிக்க எண்ணிப் பழி தரும் செயல்களை, நீதிக்கு அஞ்சுபவர் செய்ய மாட்டார்.", meaningEn: "Those who blush at the want of equity won't commit disgraceful acts through wants of the profit that may be gained." },
  { number: 173, line1: "சிற்றின்பம் வெஃகி அறனல்ல செய்யாரே", line2: "மற்றின்பம் வேண்டு பவர்.", meaningTa: "அறவழியில் நிலையான பயனை விரும்புகிறவர் உடனடிப் பயன் கிடைக்கிறது என்பதற்காக அறவழி தவறி நடக்க மாட்டார்.", meaningEn: "Those who wants the higher pleasures (of heaven) won't act unjustly through wants of the trifling joy. (in this life.)." },
  { number: 174, line1: "இலமென்று வெஃகுதல் செய்யார் புலம்வென்ற", line2: "புன்மையில் காட்சி யவர்.", meaningTa: "புலனடக்கம் வாய்ந்த தூயவர், வறுமையில் வாடும் நிலையிலேகூடப் பிறர் பொருளைக் கவர்ந்திட விரும்ப மாட்டார்.", meaningEn: "The wise who have conquered their senses and are free from crime, won't wants what others have (the things of others), with the thought \"we are." },
  { number: 175, line1: "அஃகி அகன்ற அறிவென்னாம் யார்மாட்டும்", line2: "வெஃகி வெறிய செயின்.", meaningTa: "யாராயிருப்பினும் அவரது உடைமையை அறவழிக்குப் புறம்பாகக் கவர விரும்பினால் ஒருவருக்குப் பகுத்துணரும் நுண்ணிய அறிவு.", meaningEn: "What is the advantage of extensive and accurate knowledge if a person through wants what others have act senselessly towards all ?" },
  { number: 176, line1: "அருள்வெஃகி ஆற்றின்கண் நின்றான் பொருள்வெஃகிப்", line2: "பொல்லாத சூழக் கெடும்.", meaningTa: "அருளை விரும்பி அறநெறியில் நின்றவன், பிறனுடைய பொருளை விரும்பிப் பொல்லாத குற்றங்களை எண்ணினால் கெடுவான்.", meaningEn: "If he, who through wants of the goodness of kindness abides in the domestic state ie, the path in which it may be obtained, wants what others have." },
  { number: 177, line1: "வேண்டற்க வெஃகியாம் ஆக்கம் விளைவயின்", line2: "மாண்டற் கரிதாம் பயன்.", meaningTa: "பிறர் பொருளைக் கவர்ந்து ஒருவன் வளம்பெற விரும்பினால் அந்த வளத்தின் பயன், நலம் தருவதாக இருக்காது.", meaningEn: "Wants not the gain of wants what others have In the enjoyment of its fruits there is no glory." },
  { number: 178, line1: "அஃகாமை செல்வத்திற்கு யாதெனின் வெஃகாமை", line2: "வேண்டும் பிறன்கைப் பொருள்.", meaningTa: "செல்வம் குறையாமல் இருக்க வழி என்ன என்றால், பிறனுக்கு உரிய பொருளை விரும்பாமல் இருப்பதே.", meaningEn: "If it is weighed, \"what is the indestructibility of wealth,\" it is freedom from wants what others have." },
  { number: 179, line1: "அறனறிந்து வெஃகா அறிவுடையார்ச் சேரும்", line2: "திறன்அறிந் தாங்கே திரு.", meaningTa: "பிறர் பொருளைக் கவர விரும்பாத அறநெறி உணர்ந்த அறிஞர் பெருமக்களின் ஆற்றலுக்கேற்ப அவர்களிடம் செல்வம் சேரும்.", meaningEn: "Lakshmi, knowing the manner (in which she may approach) will immediately come to those wise people who, knowing that it is goodness, wants what." },
  { number: 180, line1: "இறலீனும் எண்ணாது வெஃகின் விறல்ஈனும்", line2: "வேண்டாமை என்னுஞ் செருக்கு.", meaningTa: "விளைவுகளைப் பற்றி நினைக்காமல் பிறர் பொருளைக் கவர்ந்துகொள்ள விரும்பினால் அழிவும், அத்தகைய விருப்பம் கொள்ளாதிருந்தால்.", meaningEn: "To wants what others have (the wealth of another) regardless of consequences will bring destruction That greatness (of mind) which wants what others." },
  { number: 181, line1: "அறங்கூறான் அல்ல செயினும் ஒருவன்", line2: "புறங்கூறான் என்றல் இனிது.", meaningTa: "ஒருவன் அறத்தைச் சொல்லாமல் பாவமே செய்தாலும், அடுத்தவரைப் பற்றிப் புறம் பேசமாட்டான் என்றால் அதுவே அவனுக்கு நல்லது.", meaningEn: "Though one don't even speak of goodness and live in sin, it will be well if it be said of him \"he does not backbite.\"." },
  { number: 182, line1: "அறனழீஇ அல்லவை செய்தலின் தீதே", line2: "புறனழீஇப் பொய்த்து நகை.", meaningTa: "அறம் என்பதே இல்லை என அடித்துப் பேசிப் பாவத்தைச் செய்வதைக் காட்டிலும் ஒருவனைக் காணாதபோது புறம்பேசிக் காணும்போது.", meaningEn: "To smile deceitfully (in another's presence) after having reviled him to his destruction (behind his back) is a greater evil than the commission of." },
  { number: 183, line1: "புறங்கூறிப் பொய்த்துயிர் வாழ்தலின் சாதல்", line2: "அறங்கூற்றும் ஆக்கத் தரும்.", meaningTa: "கண்ட இடத்தில் ஒன்றும், காணாத இடத்தில் வேறொன்றுமாகப் புறங்கூறிப் பொய்மையாக நடந்து உயிர் வாழ்வதைவிடச் சாவது நன்று.", meaningEn: "Death rather than life will confer upon the deceitful backbiter the profit which (the wise books on) goodness point out." },
  { number: 184, line1: "கண்ணின்று கண்ணறச் சொல்லினும் சொல்லற்க", line2: "முன்னின்று பின்நோக்காச் சொல்.", meaningTa: "நேருக்கு நேராக ஒருவரது குறைகளைக் கடுமையாகச் சொன்னாலும் சொல்லலாம், ஆனால் பின் விளைவுகளை எண்ணிப் பார்க்காமல் நேரில்.", meaningEn: "Though you speak without kindness before another's face speak not in his absence words which regard not the evil subsequently resulting from it." },
  { number: 185, line1: "அறஞ்சொல்லும் நெஞ்சத்தான் அன்மை புறஞ்சொல்லும்", line2: "புன்மையாற் காணப் படும்.", meaningTa: "அறத்தை நல்லதென்று போற்றும் நெஞ்சம் இல்லாததன்மை, ஒருவன் மற்றவனைப் பற்றிப் புறங்கூறுகின்ற சிறுமையால் காணப்படும்.", meaningEn: "The emptiness of that man's mind who (merely) praises goodness will be seen from the meanness of reviling another behind his back." },
  { number: 186, line1: "பிறன்பழி கூறுவான் தன்பழி யுள்ளும்", line2: "திறன்தெரிந்து கூறப் படும்.", meaningTa: "அடுத்தவன் குறையை அவன் இல்லாத போது எவன் கூறுகிறானோ, அவனது குறை அவன் இல்லாதபோது இன்னொருவனால் கூறப்படும்.", meaningEn: "The character of the faults of that man who publishes abroad the faults of others will be sought out and published." },
  { number: 187, line1: "பகச்சொல்லிக் கேளிர்ப் பிரிப்பர் நகச்சொல்லி", line2: "நட்பாடல் தேற்றா தவர்.", meaningTa: "கூடி மகிழுமாறு இனியன பேசி நட்பை வளர்க்கத் தெரியாதவர், புறம்பேசி நண்பர்களையும் பிரித்து விடுவர்.", meaningEn: "Those who know not to live in friendship with amusing conversation will by back-biting estrange even their relatives." },
  { number: 188, line1: "துன்னியார் குற்றமும் தூற்றும் மரபினார்", line2: "என்னைகொல் ஏதிலார் மாட்டு.", meaningTa: "நெருங்கிப் பழகியவரின் குற்றத்தையும் புறங்கூறித் தூற்றும் இயல்புடையவர், பழகாத அயலாரிடத்து என்ன செய்வாரோ?", meaningEn: "What will those not do to strangers whose nature leads them to publish abroad the faults of their intimate friends ?" },
  { number: 189, line1: "அறன்நோக்கி ஆற்றுங்கொல் வையம் புறன்நோக்கிப்", line2: "புன்சொல் உரைப்பான் பொறை.", meaningTa: "ஒருவர் நேரில் இல்லாதபோது பழிச்சொல் கூறுவோனுடைய உடலை `இவனைச் சுமப்பதும் அறமே' என்று கருதித்தான் நிலம் சுமக்கிறது.", meaningEn: "The world through charity supports the weight of those who reproach others observing their absence." },
  { number: 190, line1: "ஏதிலார் குற்றம்போல் தங்குற்றங் காண்கிற்பின்", line2: "தீதுண்டோ மன்னும் உயிர்க்கு.", meaningTa: "அயலாருடைய குற்றத்தைக் காண்பது போல் தம் குற்றத்தையும் காண வல்லவரானால், நிலைபெற்ற உயிர் வாழ்க்கைக்குத் துன்பம் உண்ட‌ோ?", meaningEn: "If they observed their own faults as they observe the faults of others, would any evil happen to people ?" },
  { number: 191, line1: "பல்லார் முனியப் பயனில சொல்லுவான்", line2: "எல்லாரும் எள்ளப் படும்.", meaningTa: "பலரும் கேட்டு வெறுக்கப், பயனற்ற சொற்களைச் சொல்லுபவன் எல்லாராலும் இகழப்படுவான்.", meaningEn: "He who to the disgust of many speaks useless things will be despised by all." },
  { number: 192, line1: "பயனில பல்லார்முன் சொல்லல் நயனில", line2: "நட்டார்கண் செய்தலிற் றீது.", meaningTa: "பலர்முன் பயனில்லாத சொற்களைக் கூறுவது, நட்புக்கு மாறாகச் செயல்படுவதைக் காட்டிலும் தீமையுடையதாகும்.", meaningEn: "To speak useless things in the presence of many is a greater evil than to do unkind things towards friends." },
  { number: 193, line1: "நயனிலன் என்பது சொல்லும் பயனில", line2: "பாரித் துரைக்கும் உரை.", meaningTa: "பயனற்ற சொற்களை விரித்துப் பேசும் ஒருவன் பேச்சு அவன் நீதியற்றவன் என்பதைக் காட்டிவிடும்.", meaningEn: "That conversation in which a person utters forth useless things will say of him \"he is without goodness.\"." },
  { number: 194, line1: "நயன்சாரா நன்மையின் நீக்கும் பயன்சாராப்", line2: "பண்பில்சொல் பல்லா ரகத்து.", meaningTa: "பயனற்றதும், பண்பற்றதுமான சொற்களைப் பலர்முன் பகர்தல் மகிழ்ச்சியைக் குலைத்து, நன்மையை மாய்க்கும்.", meaningEn: "The words devoid of profit or pleasure which a person speaks will, being inconsistent with goodness,." },
  { number: 195, line1: "சீர்மை சிறப்பொடு நீங்கும் பயனில", line2: "நீர்மை யுடையார் சொலின்.", meaningTa: "இனிய குணத்தவர் பயனற்ற சொற்களைச் சொன்னால், அவர் பெருமையும், புகழும் அப்பொழுதே நீங்கிவிடும்.", meaningEn: "If the good speak vain words their eminence and excellence will leave them." },
  { number: 196, line1: "பயனில்சொல் பாராட்டு வானை மகன்எனல்", line2: "மக்கட் பதடி யெனல்.", meaningTa: "பயனற்ற சொற்களையே பலகாலமும் சொல்பவனை மனிதன் என வேண்டா; மனிதருள் பதர் என்றே சொல்லுங்கள்.", meaningEn: "Call not him someone who parades forth his empty words Call him the chaff of people." },
  { number: 197, line1: "நயனில சொல்லினுஞ் சொல்லுக சான்றோர்", line2: "பயனில சொல்லாமை நன்று.", meaningTa: "நீதியற்ற சொற்களைச் சொன்னாலும் பயனற்ற சொற்களைச் சொல்லாமல் இருப்பது சான்றோர்க்கு நல்லது.", meaningEn: "Let the wise if they will, speak things without excellence; it will be well for them not to speak useless things." },
  { number: 198, line1: "அரும்பயன் ஆயும் அறிவினார் சொல்லார்", line2: "பெரும்பயன் இல்லாத சொல்.", meaningTa: "அரிய பயன்களை ஆராயும் அறிவுடையோர், பெரும்பயன் இல்லாத சொற்களைச் சொல்வார்.", meaningEn: "The wise who seek after rare pleasures won't speak words that have not much weight in them." },
  { number: 199, line1: "பொருள்தீர்ந்த பொச்சாந்துஞ் சொல்லார் மருள்தீர்ந்த", line2: "மாசறு காட்சி யவர்.", meaningTa: "மயக்கமற்ற தூய அறிவினை உடையவர், பொருளற்ற சொற்களை மறந்தும் சொல்லார்.", meaningEn: "Those wise people who are without faults and are freed from ignorance won't even forgetfully speak things that profit not." },
  { number: 200, line1: "சொல்லுக சொல்லிற் பயனுடைய சொல்லற்க", line2: "சொல்லிற் பயனிலாச் சொல்.", meaningTa: "பயனளிக்காத சொற்களை விடுத்து மனத்தில் பதிந்து பயனளிக்கக் கூடிய சொற்களையே கூற வேண்டும்.", meaningEn: "Speak what is useful, and speak not useless words." },
  { number: 201, line1: "தீவினையார் அஞ்சார் விழுமியார் அஞ்சுவர்", line2: "தீவினை என்னும் செருக்கு.", meaningTa: "தீமை என்னும் மயக்கத்தைச் செய்ய, முன்னைத் தீவினை உடையவர் பயப்படமாட்டார்; பெரியவர்களோ பயப்படுவர்.", meaningEn: "Those who have experience of evil deeds won't fear, but the excellent will fear the pride of sin." },
  { number: 202, line1: "தீயவை தீய பயத்தலால் தீயவை", line2: "தீயினும் அஞ்சப் படும்.", meaningTa: "நமக்கு நன்மை என்று பிறருக்குச் செய்யும் தீமைகள், நமக்குத் தீமையே தருவதால், தீமைகளைத் தீயினும் கொடியனவாக எண்ணிச் செய்ய.", meaningEn: "Because evil produces evil, so should evil be feared more than fire." },
  { number: 203, line1: "அறிவினுள் எல்லாந் தலையென்ப தீய", line2: "செறுவார்க்கும் செய்யா விடல்.", meaningTa: "தனக்குத் தீமை செய்பவர்க்கும் தீமை செய்யாது இருப்பதே, அறிவில் எல்லாம் முதன்மை அறிவு என்று கூறுவர்.", meaningEn: "So shalt you wisdom's highest law, 'tis said, fulfil." },
  { number: 204, line1: "மறந்தும் பிறன்கேடு சூழற்க சூழின்", line2: "அறஞ்சூழம் சூழ்ந்தவன் கேடு.", meaningTa: "மறந்தும் பிறர்க்குத் தீமை செய்ய எண்ணாதே; எண்ணினால் எண்ணியவனுக்கு அறக்கடவுளே தீமையைத் தர எண்ணும்.", meaningEn: "Even though forgetfulness meditate not the ruin of another goodness will meditate the ruin of God who so meditates." },
  { number: 205, line1: "இலன்என்று தீயவை செய்யற்க செய்யின்", line2: "இலனாகும் மற்றும் பெயர்த்து.", meaningTa: "தன் ஏழ்மையைப் போக்கப் பிறர்க்குத் தீமை செய்யாதே, செய்தால் மேலும் ஏழை ஆவாய்.", meaningEn: "Commit not evil, saying, \"I am poor\": if you do, you will become poorer still." },
  { number: 206, line1: "தீப்பால தான்பிறர்கண் செய்யற்க நோய்ப்பால", line2: "தன்னை அடல்வேண்டா தான்.", meaningTa: "துன்பம் தருவன தன்னைச் சூழ்ந்து வருத்த விரும்பாதவன், பிறர்க்குத் தீமை செய்யக்கூடாது.", meaningEn: "Let him not do evil to others who wants not that sorrows should pursue him." },
  { number: 207, line1: "எனைப்பகை யுற்றாரும் உய்வர் வினைப்பகை", line2: "வீயாது பின்சென்று அடும்.", meaningTa: "ஒருவர் நேரடியான பகைக்குத் தப்பி வாழ முடியும்; ஆனால், அவர் செய்யும் தீய வினைகள் பெரும் பகையாகி அவரைத் தொடர்ந்து.", meaningEn: "However great be the fighting people have incurred they may still live The fighting of sin will incessantly pursue and kill." },
  { number: 208, line1: "தீயவை செய்தார் கெடுதல் நிழல்தன்னை", line2: "வீயாது அஇஉறைந் தற்று.", meaningTa: "பிறர்க்குத் தீமை செய்தவர் அழிவது, அவரை அவரது நிழல் விடாது கால்களின் கீழே தங்கியிருப்பது போலாம்.", meaningEn: "Destruction will dwell at the heels of those who commit evil even as their shadow that leaves them not." },
  { number: 209, line1: "தன்னைத்தான் காதல னாயின் எனைத்தொன்றும்", line2: "துன்னற்க தீவினைப் பால்.", meaningTa: "தனது நலத்தை விரும்புகிறவன் தீய செயல்களின் பக்கம் சிறிதளவுகூட நெருங்கலாகாது.", meaningEn: "If a person caring himself, let him not commit any sin however small." },
  { number: 210, line1: "அருங்கேடன் என்பது அறிக மருங்கோடித்", line2: "தீவினை செய்யான் எனின்.", meaningTa: "தீய வழிகளில் பிறர்க்குத் தீமை செய்யாது வாழ்பவனே கேடு இல்லாதவன் என்று அறிக.", meaningEn: "Know you that he is freed from destruction who commits no evil, going to neither side of the right path." },
  { number: 211, line1: "கைம்மாறு வேண்டா கடப்பாடு மாரிமாட்டு", line2: "என் ஆற்றுங் கொல்லோ உலகு.", meaningTa: "இந்த உலகத்தார் மழைக்கு என்ன கைமாறு செய்கின்றனர்;, மழை போன்றவர் செய்யும் உதவிகளும் கைமாறு வேண்டாதவை.", meaningEn: "Kindness seeks not a return. What does the world give back to the clouds ?" },
  { number: 212, line1: "தாளாற்றித் தந்த பொருளெல்லாம் தக்கார்க்கு", line2: "வேளாண்மை செய்தற் பொருட்டு.", meaningTa: "தகுதியுடையோர் நலனுக்கு உதவிடும் பொருட்டே ஒருவன் முயன்று திரட்டிய பொருள் பயன்பட வேண்டும்.", meaningEn: "All the wealth acquired with perseverance by the worthy is for the exercise of kindness." },
  { number: 213, line1: "புத்தே ளுலகத்தும் ஈண்டும் பெறலரிதே", line2: "ஒப்புரவின் நல்ல பிற.", meaningTa: "தேவர்கள் உலகத்திலும் இப்பூவுலகிலும், உழைக்க முடியாதவர்க்கு உதவுவது போன்ற வேறு நல்ல செயல்களைப் பெறுவது கடினம்.", meaningEn: "It is difficult to obtain another good equal to kindness either in this world or in that of the gods." },
  { number: 214, line1: "ஒத்த தறவோன் உயிர்வாழ்வான் மற்றையான்", line2: "செத்தாருள் வைக்கப் படும்.", meaningTa: "உழைக்கும் சக்தி அற்றவர்க்கு உதவுபவனே உயிரோடு வாழ்பவன். உதவாதவன் இருந்தாலும் இறந்தவனாகவே எண்ணப்படுவான்.", meaningEn: "He truly lives who knows (and discharges) the proper duties (of kindness) He who knows them not will be reckoned among the dead." },
  { number: 215, line1: "ஊருணி நீர்நிறைந் தற்றே உலகவாம்", line2: "பேரறி வாளன் திரு.", meaningTa: "ஒப்புரவினால் உலகம் வாழுமாறு விரும்பும் பேரறிவாளியின் செல்வம், ஊரார் நீருண்ணும் குளம் நீரால் நிறைந்தாற் போன்றது.", meaningEn: "The wealth of that man of eminent knowledge who wants to exercise the kindness approved of by the world, is like the full waters of a city-tank." },
  { number: 216, line1: "பயன்மரம் உள்ளூர்ப் பழுத்தற்றால் செல்வம்", line2: "நயனுடை யான்கண் படின்.", meaningTa: "பிறரால் விரும்பப்படுபவனிடம் சேரும் செல்வம், உண்ணத் தகும், கனிதரும் மரம் ஊருக்கு உள்ளே பழுத்திருப்பதைப் போல.", meaningEn: "The wealth of a person (full of the goodness) of kindness is like the ripening of a fruitful tree in the midst of a town." },
  { number: 217, line1: "மருந்தாகித் தப்பா மரத்தற்றால் செல்வம்", line2: "பெருந்தகை யான்கண் படின்.", meaningTa: "பிறருக்கு உதவிடும் பெருந்தன்மையாம் ஒப்புரவு உடையவனிடம், செல்வம் சேர்ந்தால் அது ஒரு நல்ல மரத்தின் எல்லா உறுப்புகளும்.", meaningEn: "If wealth be in the possession of someone who has the great excellence (of kindness), it is like a tree which as a medicine is an infallible cure for." },
  { number: 218, line1: "இடனில் பருவத்தும் ஒப்புரவிற்கு ஒல்கார்", line2: "கடனறி காட்சி யவர்.", meaningTa: "தம்மிடம் வளம் நீங்கி, வறுமை வந்துற்ற காலத்திலும், பிறர்க்கு உதவிடும் ஒப்புரவில் தளராதவர், கடமையுணர்ந்த தகைமையாளர்.", meaningEn: "The wise who know what is duty won't scant their kindness even when they are without wealth." },
  { number: 219, line1: "நயனுடையான் நல்கூர்ந்தா னாதல் செயும்நீர", line2: "செய்யாது அமைகலா வாறு.", meaningTa: "ஒப்புரவாகிய நற்பண்பு உடையவன் வறுமை உடையவனாதல், செய்யத்தக்க உதவிகளைச் செய்யாமல் வருந்துகின்ற தன்மையாகும்.", meaningEn: "The poverty of a benevolent man, is nothing but his inability to exercise the same." },
  { number: 220, line1: "ஒப்புரவி னால்வரும் கேடெனின் அஃதொருவன்", line2: "விற்றுக்கோள் தக்க துடைத்து.", meaningTa: "ஒப்புரவால் கேடு வரும் என்றால் அக் கேடு ஒருவன் தன்னை விற்றாவது வாங்கிக்கொள்ளும் தகுதி உடையதாகும்.", meaningEn: "If it be said that loss will result from kindness, such loss is worth being procured even by the sale of one's self." },
  { number: 221, line1: "வறியார்க்கொன்று ஈவதே ஈகைமற் றெல்லாம்", line2: "குறியெதிர்ப்பை நீர துடைத்து.", meaningTa: "ஏதும் இல்லாதவர்க்குக் கொடுப்பதே ஈகை; பிற எல்லாம் கொடுத்ததைத் திரும்பப் பெறும் நோக்கம் உடையதே.", meaningEn: "To give to the destitute is true charity All other gifts have the nature of (what is done for) a measured return." },
  { number: 222, line1: "நல்லாறு எனினும் கொளல்தீது மேலுலகம்", line2: "இல்லெனினும் ஈதலே நன்று.", meaningTa: "பிறரிடமிருந்து நல்வழியில் பொருளைப் பெற்றாலும் அது பெருமையல்ல; சிறுமையே ஆகும் கொடை வழங்குவதால் மேலுலகம் என்று.", meaningEn: "To beg is evil, even though it were said that it is a good path (to heaven) To give is good, even though it were said that those who do so can't." },
  { number: 223, line1: "இலனென்னும் எவ்வம் உரையாமை ஈதல்", line2: "குலனுடையான் கண்ணே யுள.", meaningTa: "தமக்குள்ள வறுமைத் துன்பத்தைக் காட்டிக்கொள்ளாமல் பிறருக்கு ஈவது உயர்ந்த குடிப்பிறந்தவரின் பண்பாகும்.", meaningEn: "Not to adopt the mean expedient of saying \"I have nothing,\" but to give, is the characteristic of the mad of noble birth." },
  { number: 224, line1: "இன்னாது இரக்கப் படுதல் இரந்தவர்", line2: "இன்முகங் காணும் அளவு.", meaningTa: "கொடுக்க இருப்பவரின் நிலைகூட தம்மிடம் வந்து யாசித்து நிற்பவரின் மலர்ந்த முகத்தைக் காணும் வரை கொடியதே.", meaningEn: "To see people begging from us in disagreeable, until we see their pleasant countenance." },
  { number: 225, line1: "ஆற்றுவார் ஆற்றல் பசிஆற்றல் அப்பசியை", line2: "மாற்றுவார் ஆற்றலின் பின்.", meaningTa: "பசியைப் பொறுத்துக் கொள்ளும் நோன்பைக் கடைப்பிடிப்பதைவிடப் பசித்திருக்கும் ஒருவருக்கு உணவு அளிப்பதே சிறந்ததாகும்.", meaningEn: "The power of those who perform hard good practice is the power of enduring hunger It is inferior to the power of those who remove the hunger (of." },
  { number: 226, line1: "அற்றார் அழிபசி தீர்த்தல் அஃதொருவன்", line2: "பெற்றான் பொருள்வைப் புழி.", meaningTa: "ஏதும் இல்லாதவரின் கடும்பசியைத் தீர்த்து வையுங்கள். பொருளைப் பெற்றவன் சேமித்து வைக்கும் இடம் அதுவே.", meaningEn: "The removal of the killing hunger of the poor is the place for one to lay up his wealth." },
  { number: 227, line1: "பாத்தூண் மரீஇ யவனைப் பசியென்னும்", line2: "தீப்பிணி தீண்டல் அரிது.", meaningTa: "பகிர்ந்து உண்ணும் பழக்கம் உடையவர்களைப் பசியென்னும் கொடிய நோய் அணுகுவதில்லை.", meaningEn: "The fiery disease of hunger will never touch God who habitually distributes his food to others." },
  { number: 228, line1: "ஈத்துவக்கும் இன்பம் அறியார்கொல் தாமுடைமை", line2: "வைத்திழக்கும் வன்க ணவர்.", meaningTa: "ஏழை எளியோர்க்கு எதுவும் அளித்திடாமல் ஈ.ட்டிய பொருள் அனைத்தையும் இழந்திடும் ஈ.வு இரக்கமற்றோர், பிறர்க்கு வழங்கி.", meaningEn: "Do the hard-eyed who lay up and lose their possessions not know the happiness which springs from the pleasure of giving ?" },
  { number: 229, line1: "இரத்தலின் இன்னாது மன்ற நிரப்பிய", line2: "தாமே தமியர் உணல்.", meaningTa: "பொருளைப் பெருக்க எண்ணி, எவருக்கும் தராமல், தானே தனித்து உண்பது, பிறரிடம் கை ஏந்துவதைவிடக் கொடியது.", meaningEn: "Solitary and unshared eating for the sake of filling up one's own riches is certainly much more." },
  { number: 230, line1: "சாதலின் இன்னாத தில்லை இனிததூஉம்", line2: "ஈதல் இயையாக் கடை.", meaningTa: "சாவு எனும் துன்பத்தைவிட வறியவர்க்கு எதுவும் வழங்க இயலாத மனத்துன்பம் பெரியது.", meaningEn: "Nothing is more unpleasant than death: yet even that is pleasant where charity can't be exercised." },
  { number: 231, line1: "ஈதல் இசைபட வாழ்தல் அதுவல்லது", line2: "ஊதியம் இல்லை உயிர்க்கு.", meaningTa: "கொடைத் தன்மையும், குன்றாத புகழும்தவிர வாழ்க்கைக்கு ஆக்கம் தரக் கூடியது வேறெதுவும் இல்லை.", meaningEn: "Give to the poor and live with praise There is no greater profit to man than that." },
  { number: 232, line1: "உரைப்பார் உரைப்பவை எல்லாம் இரப்பார்க்கொன்று", line2: "ஈவார்மேல் நிற்கும் புகழ்.", meaningTa: "சொல்வார் சொல்வன எல்லாம், இல்லை என்று வருபவர்க்குத் தருபவர்மேல் சொல்லப்படும் புகழே.", meaningEn: "Whatsoever is spoken in the world will abide as praise upon that man who gives alms to the poor." },
  { number: 233, line1: "ஒன்றா உலகத்து உயர்ந்த புகழல்லால்", line2: "பொன்றாது நிற்பதொன் றில்.", meaningTa: "உயர்ந்த புகழ் அல்லாமல் உலகத்தில் ஒப்பற்ற ஒரு பொருளாக அழியாமல் நிலைநிற்க வல்லது வேறொன்றும் இல்லை.", meaningEn: "There is nothing that stands forth in the world imperishable, except a good name, exalted in solitary greatness." },
  { number: 234, line1: "நிலவரை நீள்புகழ் ஆற்றின் புலவரைப்", line2: "போற்றாது புத்தேள் உலகு.", meaningTa: "நிலவுலகின் எல்லையில் நெடுங்காலம் நிற்கவல்ல புகழைச் செய்தால், வானுலகம் தேவரைப் போற்றாது..", meaningEn: "If one has acquired extensive a good name within the limits of this earth, a wonderful place will no longer praise those sages who have attained that." },
  { number: 235, line1: "நத்தம்போல் கேடும் உளதாகும் சாக்காடும்", line2: "வித்தகர்க் கல்லால் அரிது.", meaningTa: "துன்பங்களுக்கிடையேகூட அவற்றைத் தாங்கும் வலிமையால் தமது புகழை வளர்த்துக் கொள்வதும், தமது சாவிலும்கூடப் புகழை நிலை.", meaningEn: "Doing well to the body of a good name, resulting in poverty to the body of flesh and the stability to the former arising from the death of the." },
  { number: 236, line1: "தோன்றின் புகழொடு தோன்றுக அஃதிலார்", line2: "தோன்றலின் தோன்றாமை நன்று.", meaningTa: "ஒரு துறையில் முற்பட்டுத் தோன்றுவதானால் புகழோடு தோன்ற வேண்டும், அத்தகைய சிறப்பு இல்லாதவர் அங்குத் தோன்றுவதைவிடத்.", meaningEn: "If you are born (in this world), be born with qualities conductive to a good name From those who are destitute of them it will be better not to be." },
  { number: 237, line1: "புகழ்பட வாழாதார் தந்நோவார் தம்மை", line2: "இகழ்வாரை நோவது எவன்?", meaningTa: "புகழ் பெருகுமாறு வாழமுடியாதவர் அதற்குக் காரணர் தாமே என்று தம்மீது வருந்தாமல், தம்மை இகழ்வார் மீது வருத்தம் கொள்வது.", meaningEn: "Why do those who can't live with praise, grieve those who despise them, instead of grieving themselves for their own inability." },
  { number: 238, line1: "வசையென்ப வையத்தார்க் கெல்லாம் இசையென்னும்", line2: "எச்சம் பெறாஅ விடின்.", meaningTa: "புகழ் என்னும் பெரும் செல்வத்தைப் பெறாது போனால், இந்த உலகத்தவர்க்கு அதுவே பழி என்று அறிந்தோர் கூறுவர்.", meaningEn: "Not to beget a good name will be esteemed a disgrace by the wise in this world." },
  { number: 239, line1: "வசையிலா வண்பயன் குன்றும் இசையிலா", line2: "யாக்கை பொறுத்த நிலம்.", meaningTa: "புகழ் இல்லாத உடம்பைச் சுமந்த பூமி, தன் வளம் மிக்க விளைச்சலில் குறைவு படும்.", meaningEn: "The ground which supports a body without a good name will get smaller in its rich produce." },
  { number: 240, line1: "வசையொழிய வாழ்வாரே வாழ்வார் இசையொழிய", line2: "வாழ்வாரே வாழா தவர்.", meaningTa: "பழி உண்டாகாமல் வாழ்வதே வாழ்க்கை எனப்படும், புகழ் இல்லாதவர் வாழ்வதும் வாழாததும் ஒன்றுதான்.", meaningEn: "Those live who live without disgrace Those who live without a good name live not." },
  { number: 241, line1: "அருட்செல்வம் செல்வத்துள் செல்வம் பொருட்செல்வம்", line2: "பூரியார் கண்ணும் உள.", meaningTa: "செல்வங்கள் பலவற்றுள்ளும் சிறந்தது அருள் என்னும் செல்வமே. பொருட்செல்வம் இழிந்த மனிதரிடமும் உண்டு.", meaningEn: "The wealth of kindness is wealth of wealth, in as much as the wealth of property is possessed by the basest of people." },
  { number: 242, line1: "நல்லாற்றாள் நாடி அருளாள்க பல்லாற்றால்", line2: "தேரினும் அஃதே துணை.", meaningTa: "பலவழிகளால் ஆராய்ந்து கண்டாலும் அருள் உடைமையே வாழ்க்கைக்குத் துணையாய் விளங்கும் நல்வழி எனக் கொள்ளல் வேண்டும்.", meaningEn: "In the good path, consider, and be kind. Even considering according to the conflicting tenets of the different sects, kindness will be your best aid,." },
  { number: 243, line1: "அருள்சேர்ந்த நெஞ்சினார்க் கில்லை இருள்சேர்ந்த", line2: "இன்னா உலகம் புகல்.", meaningTa: "அருள் நிறைந்த மனம் படைத்தவர் அறியாமை எனும் இருள் சூழ்ந்த துன்ப உலகில் உழலமாட்டார்.", meaningEn: "They will never enter the world of darkness and wretchedness whose minds are the abode of kindness." },
  { number: 244, line1: "மன்னுயிர் ஓம்பி அருளாள்வார்க்கு இல்லென்ப", line2: "தன்னுயிர் அஞ்சும் வினை.", meaningTa: "நிலைத்து வரும் உயிர்களைக் காத்து அவற்றின் மீது அருள் உள்ளவனுக்குத் தன் உயிரைப் பற்றிய பயம் வராது.", meaningEn: "Say that the evils, which his soul would dread, will never come upon the man who exercises kindness and protects the life (of other creatures)." },
  { number: 245, line1: "அல்லல் அருளாள்வார்க்கு இல்லை வளிவழங்கும்", line2: "மல்லன்மா ஞாலங் கரி.", meaningTa: "அருள் உடையவர்க்கு இவ்வுலகில் துன்பம் வராது; இதற்குக் காற்று உலவும், வளம் மிக்க இந்தப் பேருலகமே சான்று.", meaningEn: "This great rich earth over which the wind blows, is a witness that sorrow never comes upon the kindhearted." },
  { number: 246, line1: "பொருள்நீங்கிப் பொச்சாந்தார் என்பர் அருள்நீங்கி", line2: "அல்லவை செய்தொழுகு வார்.", meaningTa: "அருளற்றவர்களாய்த் தீமைகளைச் செய்து வாழ்பவர்கள், பொருளற்றவர்களாகவும், கடமை மறந்தவர்களாகவும் ஆவர்.", meaningEn: "Say that those who neglect kindness and practise cruelties, neglected goodness (in their former birth), and forgot (the sorrows which they must." },
  { number: 247, line1: "அருளில்லார்க்கு அவ்வுலகம் இல்லை பொருளில்லார்க்கு", line2: "இவ்வுலகம் இல்லாகி யாங்கு.", meaningTa: "பொருள் இல்லாதவர்க்கு இப்பூவுலக இன்பம் இல்லாதது போலவே, அருள் இல்லாதவர்க்கு மேல் உலக இன்பம் இல்லை.", meaningEn: "As this world isn't for those who are without wealth, so that world isn't for those who are without kindness." },
  { number: 248, line1: "பொருளற்றார் பூப்பர் ஒருகால் அருளற்றார்", line2: "அற்றார்மற் றாதல் அரிது.", meaningTa: "பொருளை இழந்தவர் அதனை மீண்டும் தேடிப் பெறலாம் அருளை இழந்தால் இழந்ததுதான்; மீண்டும் பெற இயலாது.", meaningEn: "Those who are without wealth may, at some future time, become do wellous; those who are destitute of kindness are utterly destitute; for them there." },
  { number: 249, line1: "தெருளாதான் மெய்ப்பொருள் கண்டற்றால் தேரின்", line2: "அருளாதான் செய்யும் அறம்.", meaningTa: "அறிவுத் தெளிவு இல்லாதவன் ஒரு நூலின் உண்மைப் பொருளைக் கண்டறிய முடியுமா? அது போலத்தான் அருள் இல்லாதவன் செய்யும்.", meaningEn: "If you consider, the goodness of God who is without kindness is like the perception of the true being by God who is without wisdom." },
  { number: 250, line1: "வலியார்முன் தன்னை நினைக்கதான் தன்னின்", line2: "மெலியார்மேல் செல்லு மிடத்து.", meaningTa: "அருள் இல்லாதவள், தன்னைவிட எளிய மனிதரைத் துன்புறுத்தச் செல்லும்போது, தன்னைவிட பலசாலி தன்னைத் துன்புறுத்த வந்தால்.", meaningEn: "When a person is about to rush upon those who are weaker than himself, let him remember how he has stood (trembling) before those who are stronger." },
  { number: 251, line1: "தன்னூன் பெருக்கற்குத் தான்பிறிது ஊனுண்பான்", line2: "எங்ஙனம் ஆளும் அருள்?", meaningTa: "தன் உடம்பை வளர்ப்பதற்காக இன்னோர் உடம்பைத் தின்பவன் மனத்துள் இரக்கம் எப்படி இருக்கும்?", meaningEn: "How can he be full of kindness, who to increase his own flesh, eats the flesh of other creatures." },
  { number: 252, line1: "பொருளாட்சி போற்றாதார்க்கு இல்லை அருளாட்சி", line2: "ஆங்கில்லை ஊன்தின் பவர்க்கு.", meaningTa: "பொருளால் பயன் பெறுவது அதைப் பாதுகாக்காதவர்க்கு இல்லை; அது போல, இரக்கத்தால் பயன்பெறுவது இறைச்சி தின்பவர்க்கு இல்லை.", meaningEn: "As those possess no property who don't take care of it, so those possess no kindness who feed on flesh." },
  { number: 253, line1: "படைகொண்டார் நெஞ்சம்போல் நன்னூக்காது ஒன்றன்", line2: "உடல்சுவை உண்டார் மனம்.", meaningTa: "படைக் கருவியைப் பயன்படுத்துவோர் நெஞ்சமும், ஓர் உயிரின் உடலைச் சுவைத்து உண்பவர் நெஞ்சமும், அருளுடைமையைப் போற்றக்.", meaningEn: "Like the (murderous) mind of God who carries a weapon (in his hand), the mind of God who feasts with pleasure on the body of another (creature), has." },
  { number: 254, line1: "அருளல்ல தியாதெனிற் கொல்லாமை கோறல்", line2: "பொருளல்லது அவ்வூன் தினல்.", meaningTa: "கொல்லாமை அருளுடைமையாகும்; கொல்லுதல் அருளற்ற செயலாகும் எனவே ஊன் அருந்துதல் அறம் ஆகாது.", meaningEn: "If it be asked what is kindness and what its opposite, the answer would be preservation and destruction of life; and so it isn't right to feed on the." },
  { number: 255, line1: "உண்ணாமை உள்ளது உயிர்நிலை ஊனுண்ண", line2: "அண்ணாத்தல் செய்யாது அளறு.", meaningTa: "உயிர்கள் உடம்பு பெற்று வாழும் நிலைமை, ஊன் உண்ணாதிருத்தலை அடிப்படையாகக் கொண்டது ஊன் உண்டால் நரகம் அவனை வெளிவிடாது.", meaningEn: "Not to eat flesh contributes to the continuance of life; so if a person eat flesh, hell won't open its mouth (to let him escape out, after he has." },
  { number: 256, line1: "தினற்பொருட்டால் கொல்லாது உலகெனின் யாரும்", line2: "விலைப்பொருட்டால் ஊன்றருவா ரில்.", meaningTa: "தின்பதற்காகவே கொலை செய்பவர் இல்லை என்றால், இறைச்சியை விலைக்குத் தருபவரும் உலகில் எங்கும் இருக்கமாட்டார்.", meaningEn: "If the world does not destroy life for the purpose of eating, then no one would sell flesh for the sake of money." },
  { number: 257, line1: "உண்ணாமை வேண்டும் புலாஅல் பிறிதொன்றன்", line2: "புண்ணது உணர்வார்ப் பெறின்.", meaningTa: "இறைச்சி, இன்னோர் உடம்பின் புண்; அறிந்தவர் அதை உண்ணக்கூடாது.", meaningEn: "If people should come to know that flesh is nothing but the unclean ulcer of a body, let them abstain from eating it." },
  { number: 258, line1: "செயிரின் தலைப்பிரிந்த காட்சியார் உண்ணார்", line2: "உயிரின் தலைப்பிரிந்த ஊன்.", meaningTa: "பிழையற்ற அறிவினை உடையவர், உயிர் பிரிந்த இறைச்சியை உண்ணமாட்டார்.", meaningEn: "The wise, who have freed themselves from mental delusion, won't eat the flesh which has been severed from an animal." },
  { number: 259, line1: "அவிசொரிந் தாயிரம் வேட்டலின் ஒன்றன்", line2: "உயிர்செகுத் துண்ணாமை நன்று.", meaningTa: "நெய் போன்ற பொருள்களைத் தீயிலிட்டு ஆயிரம் வேள்விகளை நடத்துவதைவிட உண்பதற்காக ஓர் உயிரைப் போக்காமலிருப்பது நல்லது.", meaningEn: "Not to kill and eat (the flesh of) an animal, is better than the pouring forth of ghee etc, in a thousand sacrifices." },
  { number: 260, line1: "கொல்லான் புலாலை மறுத்தானைக் கைகூப்பி", line2: "எல்லா உயிருந் தொழும்.", meaningTa: "புலால் உண்ணாதவர்களையும், அதற்காக உயிர்களைக் கொல்லாதவர்களையும் எல்லா உயிரினங்களும் வணங்கி வாழ்த்தும்.", meaningEn: "All creatures will join their hands together, and worship God who has never taken away life, nor eaten flesh." },
  { number: 261, line1: "உற்றநோய் நோன்றல் உயிர்க்குறுகண் செய்யாமை", line2: "அற்றே தவத்திற் குரு.", meaningTa: "தனக்கு உற்ற துன்பத்தை பொறுத்தலும் மற்ற உயிர்க்குத் துன்பம் செய்யாதிருத்தலும் ஆகிய அவ்வளவே தவத்திற்கு வடிவமாகும்.", meaningEn: "The nature of religious discipline consists, in the endurance (by the people who live simply) of the sufferings which it brings on himself, and in." },
  { number: 262, line1: "தவமும் தவமுடையார்க்கு ஆகும் அதனை", line2: "அஃதிலார் மேற்கொள் வது.", meaningTa: "உறுதிப்பாடும், மன அடக்கமும் உடையவருக்கே தவத்தின் பெருமை வாய்க்கும் எனவே கட்டுப்பாடான ஒழுக்கம் இல்லாதவர்கள், தவத்தை.", meaningEn: "Austerities can only be borne, and their benefits enjoyed, by those who have practised them (in a former birth); it will be useless for those who." },
  { number: 263, line1: "துறந்தார்க்குத் துப்புரவு வேண்டி மறந்தார்கொல்", line2: "மற்றை யவர்கள் தவம்.", meaningTa: "துறவு மேற்கொண்டவர்களுக்கு உதவ எண்ணி, மற்றவர்கள் தவம் செய்வதை மறந்து இருப்பார்கள் போலும்.", meaningEn: "It is to provide food etc, for the people who live simply who have abandoned (the wants of earthly possessions) that other persons have forgotten (to." },
  { number: 264, line1: "ஒன்னார்த் தெறலும் உவந்தாரை ஆக்கலும்", line2: "எண்ணின் தவத்தான் வரும்.", meaningTa: "பகைவர்களை மாற்றவும், நண்பர்களைப் பெருக்கவும் எண்ணினால், தவத்தால் அதைச் செய்ய முடியும்.", meaningEn: "If (the people who live simply) wants the destruction of his people who fight you, or the aggrandizement of his friends, it will be effected by (the." },
  { number: 265, line1: "வேண்டிய வேண்டியாங் கெய்தலால் செய்தவம்", line2: "ஈண்டு முயலப் படும்.", meaningTa: "விரும்பியவற்றை விரும்பியபடியே அடைய முடியுமாதலால் இப்பூமியில் தவம் முயன்று செய்யப்படும்.", meaningEn: "Religious dislipline is practised in this world, because it secures the attainment of whatever one may wish to enjoy (in the world to come)." },
  { number: 266, line1: "தவஞ்செய்வார் தங்கருமஞ் செய்வார்மற் றல்லார்", line2: "அவஞ்செய்வார் ஆசையுட் பட்டு.", meaningTa: "தவத்தைச் செய்பவரே தமக்குரிய செயலைச் செய்தவர்; மற்றவர்களோ ஆசை வலைப்பட்டு வீணானவற்றைச் செய்தவர் ஆவர்.", meaningEn: "Those discharge their duty who perform austerities; all others accomplish their own destruction, through the entanglement of the wants (of riches and." },
  { number: 267, line1: "சுடச்சுடரும் பொன்போல் ஒளிவிடும் துன்பஞ்", line2: "சுடச்சுட நோற்கிற் பவர்க்கு.", meaningTa: "புடமிட்டு சுடச்சுட ஒளிவிடுகின்ற பொன்னைப் போல் தவம் செய்கின்றவரை துன்பம் வருத்த வருத்த மெய்யுணர்வு மிகும்.", meaningEn: "Just as gold is purified as heated in the fire, will those shine, who have endured the burning of pain (in frequent austerities)." },
  { number: 268, line1: "தன்னுயிர் தான்அறப் பெற்றானை ஏனைய", line2: "மன்னுயி ரெல்லாந் தொழும்.", meaningTa: "தன் உயிர், தான் என்னும் எண்ணம் முற்றும் இல்லாதவனைப் பிற உயிர்கள் எல்லாம் தொழும்.", meaningEn: "All other creatures will worship God who has attained the control of his own soul." },
  { number: 269, line1: "கூற்றம் குதித்தலும் கைகூடும் நோற்றலின்", line2: "ஆற்றல் தலைப்பட் டவர்க்குல்.", meaningTa: "தவத்தால் வரும் வலிமையைப் பெற்றவரால் எமனையும் வெல்ல முடியும்.", meaningEn: "Those who have attained the power which religious discipline confers, will be able also to pass the limit of Yama, (the God of death)." },
  { number: 270, line1: "இலர்பல ராகிய காரணம் நோற்பார்", line2: "சிலர்பலர் நோலா தவர்.", meaningTa: "பிறர் செய்யும்தீமைகளைப் பொறுத்துக் கொள்வதும், அவர்க்குத் தீமை செய்யாது இருப்பதும் ஆகிய தவத்தைச் செய்பவர் சிலர்;.", meaningEn: "Because there are few who practise austerity and many who don't, there are many destitute and few rich in this world." },
  { number: 271, line1: "வஞ்ச மனத்தான் படிற்றொழுக்கம் பூதங்கள்", line2: "ஐந்தும் அகத்தே நகும்.", meaningTa: "வஞ்சமனம் உடையவனது பொய்யொழுக்கத்தை அவனுடைய உடம்பில் கலந்து நிற்க்கும் ஐந்து பூதங்களும் கண்டு தம்முள் சிரிக்கும்.", meaningEn: "The five elements (of his body) will laugh within him at the feigned conduct of the deceitful minded man." },
  { number: 272, line1: "வானுயர் தோற்றம் எவன்செய்யும் தன்னெஞ்சம்", line2: "தான்அறி குற்றப் படின்.", meaningTa: "தன் மீது தன் நெஞ்சமே குற்றம் சொல்லுமானால் மேலான நிலையினால் வரும் பலன்தான் என்ன?", meaningEn: "What avails an appearance (of sanctity) high as heaven, if his mind suffers (the indulgence) of conscious sin." },
  { number: 273, line1: "வலியில் நிலைமையான் வல்லுருவம் பெற்றம்", line2: "புலியின்தோல் போர்த்துமேய்ந் தற்று.", meaningTa: "கெட்டவன் நல்லவன் போல நடிப்பது, பசு புலியின் தோலைப் போர்த்திக் கொண்டு மேய்ந்தது போலாகும்.", meaningEn: "The assumed appearance of power, by someone who has no power (to restrain his senses and perform austerity), is like a cow feeding on grass covered." },
  { number: 274, line1: "தவமறைந்து அல்லவை செய்தல் புதல்மறைந்து", line2: "வேட்டுவன் புள்சிமிழ்த் தற்று.", meaningTa: "புதரில் மறைந்து கொண்டு வேடன் பறவைகளைக் கண்ணி வைத்துப் பிடிப்பதற்கும், தவக்கோலத்தில் இருப்பவர்கள் தகாத செயல்களில்.", meaningEn: "He who hides himself under the mask of an people who live simply and commits sins, like a sportsman who conceals himself in the thicket to catch birds." },
  { number: 275, line1: "பற்றற்றேம் என்பார் படிற்றொழுக்கம் எற்றெற்றென்று", line2: "ஏதம் பலவுந் தரும்.", meaningTa: "எத்தகைய செயல் புரிந்துவிட்டோம் என்று தமக்குத் தாமே வருந்த வேண்டிய துன்பம், பற்றுகளை விட்டு விட்டதாகப் பொய்கூறி, உலகை.", meaningEn: "The false conduct of those who say they have renounced all wants will one day bring them sorrows that will make them cry out, \"Oh! what have we done,." },
  { number: 276, line1: "நெஞ்சின் துறவார் துறந்தார்போல் வஞ்சித்து", line2: "வாழ்வாரின் வன்கணார் இல்.", meaningTa: "உண்மையிலேயே மனதாரப் பற்றுகளைத் துறக்காமல் துறந்தவரைப் போல் வாழ்கின்ற வஞ்சகர்களைவிட இரக்கமற்றவர் யாருமில்லை.", meaningEn: "Amongst living people there are none so hard-hearted as those who without to saleader (wants) in their heart, falsely take the appearance of those." },
  { number: 277, line1: "புறங்குன்றி கண்டனைய ரேனும் அகங்குன்றி", line2: "முக்கிற் கரியார் உடைத்து.", meaningTa: "குன்றிமணியின் மேனியைப் போல் வெளித் தோற்றத்தில் நல்லவராயும், குன்றிமணியின் மூக்கு கறுத்து இருப்பதுபோல் மனத்தால்.", meaningEn: "Contains persons whose outside appears (as fair) as the (red) berry of the Abrus, but whose inside is as black as the nose of that berry." },
  { number: 278, line1: "மனத்தது மாசாக மாண்டார் நீராடி", line2: "மறைந்தொழுகு மாந்தர் பலர்.", meaningTa: "நீருக்குள் மூழ்கியோர் தம்மை மறைத்துக் கொள்வது போல, மாண்புடையோர் எனும் பெயருக்குள் தம்மை மறைத்துக்கொண்டு மனத்தில்.", meaningEn: "There are many people of masked conduct, who perform their ablutions, and (make a show) of." },
  { number: 279, line1: "கணைகொடிது யாழ்கோடு செவ்விதுஆங் கன்ன", line2: "வினைபடு பாலால் கொளல்.", meaningTa: "நேராகத் தோன்றும் அம்பு, கொலைச் செயல் புரியும் வளைந்து தோன்றும் யாழ், இசை, இன்பம் பயக்கும் அது போலவே மக்களின்.", meaningEn: "As, in its use, the arrow is crooked, and the curved lute is straight, so by their deeds, (and not by their appearance) let (the uprightness or." },
  { number: 280, line1: "மழித்தலும் நீட்டலும் வேண்டா உலகம்", line2: "பழித்தது ஒழித்து விடின்.", meaningTa: "உலகம் பழிக்கும் தீயொழுக்கத்தை விட்டு விட்டால் மொட்டை அடித்தலும் சடை வளர்த்தலுமாகிய புறக்கோலங்கள் வேண்டா.", meaningEn: "There is no need of a shaven crown, nor of tangled hair, if a person abstain from those deeds which the wise have condemned." },
  { number: 281, line1: "எள்ளாமை வேண்டுவான் என்பான் எனைத்தொன்றும்", line2: "கள்ளாமை காக்கதன் நெஞ்சு.", meaningTa: "எந்தப் பொருளையும் களவாடும் நினைவு தன் நெஞ்சை அணுகாமல் பார்த்துக் கொள்பவனே இகழ்ச்சிக்கு ஆட்படாமல் வாழ முடியும்.", meaningEn: "Let him, who wants not to be despised, keep his mind from (the wants of) defrauding another of the smallest thing." },
  { number: 282, line1: "உள்ளத்தால் உள்ளலும் தீதே பிறன்பொருளைக்", line2: "கள்ளத்தால் கள்வேம் எனல்.", meaningTa: "அடுத்தவர் பொருளை அவருக்குத் தெரியாமல் திருடுவோம் என்று மனத்தால் நினைப்பதும் தீமையானது.", meaningEn: "Even the thought (of sin) is sin; think not then of crafiily stealing the property of another." },
  { number: 283, line1: "களவினால் ஆகிய ஆக்கம் அளவிறந்து", line2: "ஆவது போலக் கெடும்.", meaningTa: "திருடுவதால் வரும் செல்வம், பெருகுவது போலத் தோன்றி விரைவில் அழியும்.", meaningEn: "The property, which is acquired by fraud, will entirely perish, even while it seems to increase." },
  { number: 284, line1: "களவின்கண் கன்றிய காதல் விளைவின்கண்", line2: "வீயா விழுமம் தரும்.", meaningTa: "அடுத்தவர் பொருளைத் திருடும் ஆசை, நிறைவேறியபின் அழியாத துன்பத்தைத் தரும்.", meaningEn: "The eager wants of defrauding others will, when it brings forth its fruit, produce undying sorrow." },
  { number: 285, line1: "அருள்கருதி அன்புடைய ராதல் பொருள்கருதிப்", line2: "பொச்சாப்புப் பார்ப்பார்கண் இல்.", meaningTa: "அருளைப் பெரிதாகக்கருதி அன்பு உடையவராய் நடத்தல், பிறருடைய பொருளைக்கவர எண்ணி அவர் சோர்ந்திருக்கும் நிலையைப்.", meaningEn: "The study of kindness and the exercise of kindness isn't with those who watch for another's forgetfulness, though wants of his property." },
  { number: 286, line1: "அளவின்கண் நின்றொழுகல் ஆற்றார் களவின்கண்", line2: "கன்றிய காத லவர்.", meaningTa: "உயிர்களை நேசிக்கும் ஆசை இல்லாதவரே அடுத்தவர் பொருளைத் திருடும் பேராசை உடையவர் ஆவர்.", meaningEn: "They can't walk steadfastly, according to rule, who eagerly wants to defraud others." },
  { number: 287, line1: "களவென்னும் காரறி வாண்மை அளவென்னும்", line2: "ஆற்றல் புரிந்தார்கண்ட இல்.", meaningTa: "அளவறிந்து வாழ்க்கை நடத்துகிற ஆற்றலுடையவர்களிடம், களவாடுதல் எனும் சூதுமதி கிடையாது.", meaningEn: "That black-knowledge which is called fraud, isn't in those who wants that greatness which is called rectitude." },
  { number: 288, line1: "அளவறிந்தார் நெஞ்சத் தறம்போல நிற்கும்", line2: "களவறிந்தார் நெஞ்சில் கரவு.", meaningTa: "நேர்மையுள்ளவர் நெஞ்சம் அறவழியில் செல்லும்; கொள்ளையடிப்போர் நெஞ்சமோ குறுக்குவழியான வஞ்சக வழியில் செல்லும்.", meaningEn: "Deceit dwells in the mind of those who are conversant with fraud, even as goodness in the minds of those who are conversant with rectitude." },
  { number: 289, line1: "அளவல்ல செய்தாங்கே வீவர் களவல்ல", line2: "மற்றைய தேற்றா தவர்.", meaningTa: "அளவு என்பதைத் தவிர வேறு நல்வழிகளை நாடாதவர்கள், வரம்பு கடந்த செயல்களால் வாழ்விழந்து வீழ்வார்கள்.", meaningEn: "Those, who are acquainted with nothing but fraud, will perish in the very commission of transgression." },
  { number: 290, line1: "கள்வார்க்குத் தள்ளும் உயிர்நிலை கள்வார்க்குத்", line2: "தள்ளாது புத்தே ளுளகு.", meaningTa: "திருடுபவரை அவரது உயிரும் வெறுக்கும்; திருடாதவரையோ தேவர் உலகமும் வெறுக்காது.", meaningEn: "Even their body will fail the fraudulent; but even a wonderful place won't fail those who are free from fraud." },
  { number: 291, line1: "வாய்மை எனப்படுவது யாதெனின் யாதொன்றும்", line2: "தீமை இலாத சொலல்.", meaningTa: "பிறருக்கு எள்முனையளவு தீமையும் ஏற்படாத ஒரு சொல்லைச் சொல்வதுதான் வாய்மை எனப்படும்.", meaningEn: "Truth is the spealeader of such words as are free from the least degree of evil (to others)." },
  { number: 292, line1: "பொய்மையும் வாய்மை யிடத்த புரைதீர்ந்த", line2: "நன்மை பயக்கும் எனின்.", meaningTa: "குற்றம் அற்ற நன்மையைத் தரும் என்றால் உண்மை சொல்ல வேண்டிய இடத்தில் பொய்யும் சொல்லலாம்.", meaningEn: "Even falsehood has the nature of truth, if it confer a benefit that is free from fault." },
  { number: 293, line1: "தன்நெஞ் சறிவது பொய்யற்க பொய்த்தபின்", line2: "தன்நெஞ்சே தன்னைச் சுடும்.", meaningTa: "மனச்சாட்சிக்கு எதிராகப் பொய் சொல்லக்கூடாது; அப்படிச் சொன்னால், சொன்னவரின் மனமே அவரைத் தண்டிக்கும்.", meaningEn: "Let not a person knowingly tell a lie; for after he has told the lie, his mind will burn him (with the memory of his guilt)." },
  { number: 294, line1: "உள்ளத்தாற் பொய்யா தொழுகின் உலகத்தார்", line2: "உள்ளத்து ளெல்லாம் உளன்.", meaningTa: "மனத்தால்கூடப் பொய்யை நினைக்காமல் வாழ்பவர்கள், மக்கள் மனத்தில் நிலையான இடத்தைப் பெறுவார்கள்.", meaningEn: "He who, in his conduct, preserves a mind free from deceit, will dwell in the minds of all people." },
  { number: 295, line1: "மனத்தொடு வாய்மை மொழியின் தவத்தொடு", line2: "தானஞ்செய் வாரின் தலை.", meaningTa: "உள்ளம் அறிய உண்மை பேசுபவன், தவமும் தானமும் செய்பவரைக் காட்டிலும் உயர்ந்தவன் ஆவான்.", meaningEn: "He, who speaks truth with all his heart, is superior to those who make gifts and practise austerities." },
  { number: 296, line1: "பொய்யாமை அன்ன புகழில்லை எய்யாமை", line2: "எல்லா அறமுந் தரும்.", meaningTa: "பொய் இல்லாமல் வாழ்வது போன்ற புகழ் மிக்க வாழ்வு வேறு எதுவுமில்லை; என்றும் நீங்காத அறவழி நலன்களை அளிப்பது அந்த.", meaningEn: "There is no praise like the praise of never uttering a falsehood: without causing any suffering, it will lead to every goodness." },
  { number: 297, line1: "பொய்யாமை பொய்யாமை ஆற்றின் அறம்பிற", line2: "செய்யாமை செய்யாமை நன்று.", meaningTa: "பொய்யாமை ஆகிய அறத்தை உண்மையாகவே போற்றி வாழ முடிந்தால் மற்ற அறங்களைச் செய்தலும் நல்லது ஆகும்.", meaningEn: "If a person has the power to abstain from falsehood, it will be well with him, even though he practise no other goodness." },
  { number: 298, line1: "புறள்தூய்மை நீரான் அமையும் அகந்தூய்மை", line2: "வாய்மையால் காணப் படும்.", meaningTa: "உடம்பு தண்ணீரால் சுத்தமாகும்; உள்ளம் உண்மையால் சுத்தமாகும்.", meaningEn: "Purity of body is produced by water and purity of mind by truthfulness." },
  { number: 299, line1: "எல்லா விளக்கும் விளக்கல்ல சான்றோர்க்குப்", line2: "பொய்யா விளக்கே விளக்கு.", meaningTa: "விளக்குகள் எல்லாம் விளக்குகள் அல்ல, சான்றோர்க்கு பொய்யாமையாகிய விளக்கே விளக்கு ஆகும்.", meaningEn: "All lamps of nature aren't lamps; the lamp of truth is the lamp of the wise." },
  { number: 300, line1: "யாமெய்யாக் கண்டவற்றுள் இல்லை எனைத்தொன்றும்", line2: "வாய்மையின் நல்ல பிற.", meaningTa: "வாய்மையைப் போல் சிறந்த பண்பு வேறொன்றுமே இல்லை என்பதுதான் ஆராய்ந்து உணரப்பட்ட உண்மையாகும்.", meaningEn: "Amidst all that we have seen (described) as real (excellence), there is nothing so good as truthfulness." },
  { number: 301, line1: "செல்லிடத்துக் காப்பான் சினங்காப்பான் அல்லிடத்துக்", line2: "காக்கின்என் காவாக்கால் என்?", meaningTa: "தன் சினம் பலிதமாகுமிடத்தில் சினம் கொள்ளாமல் இருப்பவனே சினங்காப்பவன்; பலிக்காத இடத்தில் சினத்தைக் காத்தால் என்ன?", meaningEn: "He restrains his anger who restrains it when it can injure; when it can't injure, what does it matter whether he restrain it, or not ?" },
  { number: 302, line1: "செல்லா இடத்துச் சினந்தீது செல்லிடத்தும்", line2: "இல்அதனின் தீய பிற.", meaningTa: "பலிக்காத இடத்தில் சினம் கொள்வது தீங்கு. பலிக்கும் இடத்திலும் சினத்தைவிடத் தீயவை வேறு இல்லை.", meaningEn: "Anger is bad, even when it can't injure; when it can injure; there is no greater evil." },
  { number: 303, line1: "மறத்தல் வெகுளியை யார்மாட்டும் தீய", line2: "பிறத்தல் அதனான் வரும்.", meaningTa: "தீமை வருவது எல்லாம் கோபத்தால்தான்; அதனால் எவரிடமானாலும் சரி, கோபம் கொள்வதை விட்டுவிடுக.", meaningEn: "Forget anger towards every one, as fountains of evil spring from it." },
  { number: 304, line1: "நகையும் உவகையும் கொல்லும் சினத்தின்", line2: "பகையும் உளவோ பிற.", meaningTa: "சினம் கொள்கிறவர்களுக்கு முகமலர்ச்சி மாத்திரமின்றி மனமகிழ்ச்சியும் மறைந்து போய் விடும்.", meaningEn: "What other foe to man works such annoy?" },
  { number: 305, line1: "தன்னைத்தான் காக்கின் சினங்காக்க காவாக்கால்", line2: "தன்னையே கொல்லுஞ் சினம்.", meaningTa: "ஒருவன் தன்னைத்தானே காத்துக் கொள்ள வேண்டுமானால், சினத்தைக் கைவிட வேண்டும் இல்லையேல் சினம், அவனை அழித்துவிடும்.", meaningEn: "If a person would guard himself, let him guard against anger; if he don't guard it, anger will kill him." },
  { number: 306, line1: "சினமென்னும் சேர்ந்தாரைக் கொல்லி இனமென்னும்", line2: "ஏமப் புணையைச் சுடும்.", meaningTa: "சினம் என்னும் சேர்ந்தவரை அழிக்கும் நெருப்பு ஒருவனுக்கு இனம் இன்பத் தெப்பத்தையும் சுட்டழிக்கும்.", meaningEn: "The fire of anger will burn up even the pleasant raft of friendship." },
  { number: 307, line1: "சினத்தைப் பொருளென்று கொண்டவன் கேடு", line2: "நிலத்தறைந்தான் கைபிழையா தற்று.", meaningTa: "சினத்தை பொருளென்று கொண்டவன் அழிதல், நிலத்தை அறைந்தவனுடைய கை தப்பாதது போல் ஆகும்.", meaningEn: "Destruction will come upon God who ragards anger as a good thing, as surely as the hand of God who strikes the ground won't fail." },
  { number: 308, line1: "இணர்எரி தோய்வன்ன இன்னா செயினும்", line2: "புணரின் வெகுளாமை நன்று.", meaningTa: "பலச் சுடர்களை உடைய பெரு நெருப்பில் தோய்வது போன்ற துன்பத்தை ஒருவன் செய்த போதிலும் கூடுமானால் அவன் மேல் சினங்.", meaningEn: "Though one commit things against you as painful (to bear) as if a bundle of fire had been thrust upon you, it will be well, to refrain, if possible,." },
  { number: 309, line1: "உள்ளிய தெல்லாம் உடனெய்தும் உள்ளத்தால்", line2: "உள்ளான் வெகுளி எனின்.", meaningTa: "உள்ளத்துள் கோபம் கொள்ள ஒருபோதும் எண்ணாதவன், தான் நினைத்ததை எல்லாம் உடனே அடைவான்.", meaningEn: "If a person never indulges anger in his heart, he will at once obtain whatever he has thought of." },
  { number: 310, line1: "இறந்தார் இறந்தார் அனையர் சினத்தைத்", line2: "துறந்தார் துறந்தார் துணை.", meaningTa: "எல்லையற்ற சினம் கொள்வார் இறந்தவர்க்கு ஒப்பாவார் சினத்தை அறவே துறந்தவர் துறவிக்கு ஒப்பாவார்.", meaningEn: "Those, who give way to excessive anger, are no better than dead people; but those, who are freed from it, are equal to those who are freed (from." },
  { number: 311, line1: "சிறப்பீனும் செல்வம் பெறினும் பிறர்க்குஇன்னா", line2: "செய்யாமை மாசற்றார் கோள்.", meaningTa: "மிகுந்த செழிப்பைத் தருகின்ற செல்வத்தைப் பெறக் கூடுமென்றாலும் அதன் பொருட்டுப் பிறருக்குப் கேடு செய்யாமலிருப்பதே.", meaningEn: "It is the determination of the spotless not to cause sorrow to others, although they could (by so causing) obtain the wealth which confers greatness." },
  { number: 312, line1: "கறுத்துஇன்னா செய்தவக் கண்ணும் மறுத்தின்னா", line2: "செய்யாமை மாசற்றார் கோள்.", meaningTa: "நம்மீது கோபம் கொண்டு தீமை செய்தாலும், பதிலுக்குத் தீமை செய்யாதிருப்பது குற்றமற்றவரின் கொள்கை.", meaningEn: "It is the determination of the spotless not to do evil, even in return, to those who have cherished fighting and done them evil." },
  { number: 313, line1: "செய்யாமல் செற்றார்க்கும் இன்னாத செய்தபின்", line2: "உய்யா விழுமந் தரும்.", meaningTa: "தான் ஒன்றும் செய்யாதிருக்கத் தனக்குத் தீங்கு செய்தவர்க்கும் துன்பமானாவற்றைச் செய்தால் செய்தபிறகு தப்பமுடியாத.", meaningEn: "In an people who live simply inflict suffering even on those who hate him, when he has not done them any evil, it will afterwards give him." },
  { number: 314, line1: "இன்னாசெய் தாரை ஒறுத்தல் அவர்நாண", line2: "நன்னயஞ் செய்து விடல்.", meaningTa: "இன்னா செய்தவரைத் தண்டித்தல் அவரே நாணும் படியாக அவருக்கு நல்லுதவி செய்து அவருடைய தீமையையும் நன்மையையும் மறந்து.", meaningEn: "The (proper) punishment to those who have done evil (to you), is to put them to shame by showing them kindness, in return and to forget both the evil." },
  { number: 315, line1: "அறிவினான் ஆகுவ துண்டோ பிறிதின்நோய்", line2: "தந்நோய்போல் போற்றாக் கடை.", meaningTa: "அடுத்த உயிர்க்கு வரும் துன்பத்தைத் தமக்கு வந்ததாக எண்ணாவிட்டால், அறிவைப் பெற்றதால் ஆகும் பயன்தான் என்ன?", meaningEn: "What benefit has he from his knowledge, who does not endeavour to keep off pain from another as much as from himself ?" },
  { number: 316, line1: "இன்னா எனத்தான் உணர்ந்தவை துன்னாமை", line2: "வேண்டும் பிறன்கண் செயல்.", meaningTa: "தீமை எனத் தான் அறிந்தவற்றை அடுத்தவர்க்குச் செய்யாது இருக்க வேண்டும்.", meaningEn: "Let not a person consent to do those things to another which, he knows, will cause sorrow." },
  { number: 317, line1: "எனைத்தானும் எஞ்ஞான்றும் யார்க்கும் மனத்தானாம்", line2: "மாணாசெய் யாமை தலை.", meaningTa: "எவ்வளவிலும், எப்பொழுதும், எவரையும் இழிவுபடுத்தும் செயலை மனத்தால்கூட நினைக்காமல் இருப்பதே முதன்மையான சிறப்பாகும்.", meaningEn: "It is the chief of all goodnesss not knowingly to do any person evil, even in the lowest degree, and at any time." },
  { number: 318, line1: "தன்னுயிர்ககு ஏன்னாமை தானறிவான் என்கொலோ", line2: "மன்னுயிர்க்கு இன்னா செயல்.", meaningTa: "தன் உயிருக்குத் துன்பமானவை இவை என்று உணர்ந்தவன், அத் துன்பத்தை மற்ற உயிருக்குச் செய்தல் என்ன காரணத்தாலோ.", meaningEn: "Why does a person inflict upon other creatures those sufferings, which he has found by experience are sufferings to himself ?" },
  { number: 319, line1: "பிறர்க்கின்னா முற்பகல் செய்யின் தமக்குஇன்னா", line2: "பிற்பகல் தாமே வரும்.", meaningTa: "அடுத்தவர்க்குத் தீமையைக் காலையில் செய்தால், நமக்குத் தீமை நம்மைத் தேடி மாலையில் தானாக வரும்.", meaningEn: "If a person inflict sorrow upon others in the morning, it will come upon him unsought in the very evening." },
  { number: 320, line1: "நோயெல்லாம் நோய்செய்தார் மேலவாம் நோய்செய்யார்", line2: "நோயின்மை வேண்டு பவர்.", meaningTa: "செய்யும் தீமை எல்லாம் செய்தவர்க்கே, அதனால் நமக்குத் தீமை வேண்டா என்பவர், அடுத்தவர்க்குத் தீமை செய்யமாட்டார்.", meaningEn: "Sorrow will come upon those who cause pain to others; therfore those, who wants to be free from sorrow, give no pain to others." },
  { number: 321, line1: "அறவினை யாதெனின் கொல்லாமை கோறல்", line2: "பிறவினை எல்லாந் தரும்.", meaningTa: "எந்த உயிரையும் கொல்லாதிருப்பதே அறச்செயலாகும் கொலை செய்தல் தீயவினைகள் அனைத்தையும் விளைவிக்கும்.", meaningEn: "Never to destroy life is the sum of all good conduct The destruction of life leads to every evil." },
  { number: 322, line1: "பகுத்துண்டு பல்லுயிர் ஓம்புதல் நூலோர்", line2: "தொகுத்தவற்றுள் எல்லாந் தலை.", meaningTa: "இருப்பதைப் பகிர்ந்து உண்டு, பல உயிர்களையும் பாதுகாப்பது, நூல் எழுதியவர்கள் தொகுத்த அறங்களுள் எல்லாம் முதன்மையான.", meaningEn: "The chief of all (the goodnesss) which authors have summed up, is the partaleader of food that has been shared with others, and the preservation of." },
  { number: 323, line1: "ஒன்றாக நல்லது கொல்லாமை மற்றதன்", line2: "பின்சாரப் பொய்யாமை நன்று.", meaningTa: "அறங்களின் வரிசையில் முதலில் கொல்லாமையும் அதற்கடுத்துப் பொய்யாமையும் இடம் பெறுகின்றன.", meaningEn: "Not to destroy life is an incomparably (great) good next to it in goodness ranks freedom from falsehood." },
  { number: 324, line1: "நல்லாறு எனப்படுவது யாதெனின் யாதொன்றும்", line2: "கொல்லாமை சூழும் நெறி.", meaningTa: "எந்த உயிரையும் கொல்லக் கூடாது எனும் நெறி காப்பதுதான் நல்லற வழி எனப்படும்.", meaningEn: "Good path is that which considers how it may avoid killing any creature." },
  { number: 325, line1: "நிலைஅஞ்சி நீத்தாருள் எல்லாம் கொலைஅஞ்சிக்", line2: "கொல்லாமை சூழ்வான் தலை.", meaningTa: "உலகியல் நிலையை வெறுத்துத் துறவு பூண்டவர் எல்லோரையும்விடக் கொலையை வெறுத்துக் கொல்லாமையைக் கடைப்பிடிப்பவரே சிறந்தவராவார்.", meaningEn: "Of all those who, fearing the permanence of earthly births, have abandoned wants, he is the chief who, fearing (the guilt of) murder, considers how." },
  { number: 326, line1: "கொல்லாமை மேற்கொண் டொழுகுவான் வாழ்நாள்மேல்", line2: "செல்லாது உயிருண்ணுங் கூற்று.", meaningTa: "கொலை செய்யாமல் வாழ்வதைக் குறிக்கோளாகக் கொண்டு வாழ்பவனின் வாழ்நாளின்மேல் உயிர் உண்ணும் கூற்று குறுக்கிடாது.", meaningEn: "Yama, the destroyer of life, won't attack the life of him, who acts under the determination of never destroying life." },
  { number: 327, line1: "தன்னுயிர் நீப்பினும் செய்யற்க தான்பிறிது", line2: "இன்னுயிர் நீக்கும் வினை.", meaningTa: "தன்னுயிரே போவதாக இருப்பினும்கூட அதற்காக இன்னொரு உயிரைப் போக்கும் செயலில் ஈடுபடக்கூடாது.", meaningEn: "Let no one do that which would destroy the life of another, although he should by so doing, lose his own life." },
  { number: 328, line1: "நன்றாகும் ஆக்கம் பெரிதெனினும் சான்றோர்க்குக்", line2: "கொன்றாகும் ஆக்கங் கடை.", meaningTa: "கொலையால் நன்மையாக விளையும் ஆக்கம் பெரிதாக இருந்தாலும், சான்றோர்க்குக் கொலையால் வரும் ஆக்கம் மிக இழிவானதாகும்.", meaningEn: "The advantage which might flow from destroying life in sacrifice, is dishonourable to the wise (who live simply), even although it should be said to." },
  { number: 329, line1: "கொலைவினைய ராகிய மாக்கள் புலைவினையர்", line2: "புன்மை தெரிவா ரகத்து.", meaningTa: "பகுத்தறிவை இழந்து செயல்படும் கொலைகாரர்களைச் சான்றோர் உள்ளம், இழிதகைப் பிறவிகளாகவே கருதும்.", meaningEn: "To minds of them who what is vileness know." },
  { number: 330, line1: "உயிருடம்பின் நீக்கியா ரென்ப செயிருடம்பின்", line2: "செல்லாத்தீ வாழ்க்கை யவர்.", meaningTa: "வறுமையும் நோயும் மிகுந்த தீய வாழ்க்கையில் உழல்வோர், ஏற்கனவே கொலைகள் பல செய்தவராக இருப்பர் என்று முன்னோர் கூறுவர்.", meaningEn: "Will say that people of diseased bodies, who live in degradation and in poverty, are those who separated the life from the body of animals (in a." },
  { number: 331, line1: "நில்லாத வற்றை நிலையின என்றுணரும்", line2: "புல்லறி வாண்மை கடை.", meaningTa: "நிலையற்றவைகளை நிலையானவை என நம்புகின்ற அறியாமை மிக இழிவானதாகும்.", meaningEn: "That ignorance which considers those things to be stable which aren't so, is dishonourable (to the wise)." },
  { number: 332, line1: "கூத்தாட்டு அவைக்குழாத் தற்றே பெருஞ்செல்வம்", line2: "போக்கும் அதுவிளிந் தற்று.", meaningTa: "பெரிய செல்வம் வந்து சேர்தல், கூத்தாடும் இடத்தில் கூட்டம் சேர்வதைப் போன்றது, அது நீங்கிப் போதலும் கூத்து முடிந்ததும்.", meaningEn: "The acquisition of wealth is like the gathering together of an assembly for a theatre; its expenditure is like the brealeader up of that assembly." },
  { number: 333, line1: "அற்கா இயல்பிற்றுச் செல்வம் அதுபெற்றால்", line2: "அற்குப ஆங்கே செயல்.", meaningTa: "நிலையாத இயல்பினை உடையது செல்வம்; அது கிடைத்தால் நிலையான அறங்களைச் செய்க.", meaningEn: "Wealth is perishable; let those who obtain it immediately practise those (goodnesss) which are imperishable." },
  { number: 334, line1: "நாளென ஒன்றுபோற் காட்டி உயிர்ஈரும்", line2: "வாளது உணர்வார்ப் பெறின்.", meaningTa: "நாள் என நமக்குத் தோன்றும் காலம், நம் உயிரைப் பிளந்து செல்லும் வாளே; அறிஞர்க்குத்தான் இது விளங்கும்.", meaningEn: "Time, which shows itself (to the ignorant) as if it were something (real) is in the estimation of the wise (only) a saw which cuts down life." },
  { number: 335, line1: "நாச்செற்று விக்குள்மேல் வாராமுன் நல்வினை", line2: "மேற்சென்று செய்யப் படும்", meaningTa: "நாவை அடைத்து விக்கல் வருவதற்கு முன், நல்ல செயல்களை விரைந்து செய்ய வேண்டும்.", meaningEn: "Let good deeds be done quickly, before the hiccup comes maleader the tongue silent." },
  { number: 336, line1: "நெருநல் உளனொருவன் இன்றில்லை என்னும்", line2: "பெருமை உடைத்துஇவ் வுலகு.", meaningTa: "நேற்று இருந்த ஒருவன் இன்று இல்லை என்று சொல்லும்படி நிலையாமையை உடையது இவ்வுலகம்.", meaningEn: "This world possesses the greatness that one who yesterday was isn't today." },
  { number: 337, line1: "ஒருபொழுதும் வாழ்வது அறியார் கருதுப", line2: "கோடியும் அல்ல பல.", meaningTa: "ஒரு பொழுதுகூட வாழ்க்கையைப் பற்றி உண்மையைச் சிந்தித்து அறியாதவர்களே, ஆசைக்கோர் அளவின்றி மனக் கோட்டைகள் கட்டுவார்கள்.", meaningEn: "Man knows not his next moment On crores of things he is intent." },
  { number: 338, line1: "குடம்பை தனித்துஒழியப் புள்பறந் தற்றே", line2: "உடம்பொடு உயிரிடை நட்பு.", meaningTa: "உடலுக்கும் உயிருக்கும் உள்ள உறவு முட்டைக்கும் பறவைக் குஞ்சுக்கும் உண்டான உறவு போன்றதுதான்.", meaningEn: "The caring of the soul to the body is like (the caring of) a bird to its egg which it flies away from and leaves empty." },
  { number: 339, line1: "உறங்கு வதுபோலுஞ் சாக்காடு உறங்கி", line2: "விழிப்பது போலும் பிறப்பு.", meaningTa: "உறங்குவது போன்றது சாவு; உறங்கி விழிப்பது போன்றது பிறப்பு.", meaningEn: "Death is like sleep; birth is like awaleader from it." },
  { number: 340, line1: "புக்கில் அமைந்தின்று கொல்லோ உடம்பினுள்", line2: "துச்சில் இருந்த உயிர்க்கு.", meaningTa: "உடலுடன் தங்கியுள்ள உயிருக்கு அதனைப் பிரிந்தால் வேறு புகலிடம் கிடையாது.", meaningEn: "It seems as if the soul, which takes a temporary shelter in a body, had not attained a home." },
  { number: 341, line1: "யாதனின் யாதனின் நீங்கியான் நோதல்", line2: "அதனின் அதனின் இலன்.", meaningTa: "எந்த எந்தப் பொருள்களின் மேல் விருப்பம் இல்லாதவனாய் விலகுகிறானோ அவன் அந்த அந்த பொருள்களால் துன்பப்படமாட்டான்.", meaningEn: "Whatever thing, a person has renounced, by that thing; he can't suffer pain." },
  { number: 342, line1: "வேண்டின்உண் டாகத் துறக்க துறந்தபின்", line2: "ஈண்டுஇயற் பால பல.", meaningTa: "பொருள்களின் மீதுள்ள பற்றைத் துறந்தபின் வந்து சேரும் இன்பங்கள் பல; இன்பங்களை விரும்பினால் துறவு கொள்க.", meaningEn: "After a person has renounced (all things), there will still be many things in this world (which he may enjoy); if he should wants them, let him,." },
  { number: 343, line1: "அடல்வேண்டும் ஐந்தன் புலத்தை விடல்வேண்டும்", line2: "வேண்டிய வெல்லாம் ஒருங்கு.", meaningTa: "ஐம் புலன்களையும் அடக்கி வெல்வதும், அப்புலன்கள் விரும்புகின்றவற்றையெல்லாம் விட்டுவிடுவதும் துறவுக்கு இலக்கணமாகும்.", meaningEn: "Let the five senses be destroyed; and at the same time, let everything be abandoned that (the people who live simply) has (formerly) wantsd." },
  { number: 344, line1: "இயல்பாகும் நோன்பிற்கொன்று இன்மை உடைமை", line2: "மயலாகும் மற்றும் பெயர்த்து.", meaningTa: "உடைமை ஏதும் இல்லாதிருப்பது துறவின் இயல்பு. உடைமைகளை வைத்திருப்பதோ ஆசை என்னும் மயக்கத்தை மறுபடியும் தரும்.", meaningEn: "To be altogether destitute is the proper condition of those who perform austerities; if they possess anything, it will change (their resolution) and." },
  { number: 345, line1: "மற்றும் தொடர்ப்பாடு எவன்கொல் பிறப்பறுக்கல்", line2: "உற்றார்க்கு உடம்பும் மிகை.", meaningTa: "பிறவித் துன்பத்தைப் போக்க முயல்கின்றவர்க்கு உடம்பும் மிகையான பொருள் ஆகையால் அதற்கு மேல் வேறு தொடர்பு கொள்வது ஏனோ.", meaningEn: "What means the addition of other things those who are attempting to cut off (future) births, when even their body is too much (for them)." },
  { number: 346, line1: "யான்எனது என்னும் செருக்குஅறுப்பான் வானோர்க்கு", line2: "உயர்ந்த உலகம் புகும்.", meaningTa: "யான், எனது என்கின்ற ஆணவத்தை அறவே விலக்கி விட்டவன், வான்புகழையும் மிஞ்சுகின்ற உலகப் புகழுக்கு உரியவனாவான்.", meaningEn: "Who curbs the pride of I and mine Gets a world rare for gods to gain." },
  { number: 347, line1: "பற்றி விடாஅ இடும்பைகள் பற்றினைப்", line2: "பற்றி விடாஅ தவர் க்கு.", meaningTa: "பற்றுகளைப் பற்றிக்கொண்டு விடாதவர்களைத் துன்பங்களும் விடாமல் பற்றிக் கொள்கின்றன.", meaningEn: "Sorrows will never let go their hold of those who give not up their hold of wants." },
  { number: 348, line1: "தலைப்பட்டார் தீரத் துறந்தார் மயங்கி", line2: "வலைப்பட்டார் மற்றை யவர்.", meaningTa: "ஆசைகளை முழுவதுமாக விட்டு விட்டவரே நல்வாழ்விற்கு முயன்றவர். விடாதவரோ மயங்கி, பிறவி வலைக்குள் அகப்பட்டவரே.", meaningEn: "Those who have entirely renounced (all things and all wants) have obtained (absorption into God); all others wander in confusion, entangled in the." },
  { number: 349, line1: "பற்றற்ற கண்ணே பிறப்பறுக்கும் மற்று", line2: "நிலையாமை காணப் படும்.", meaningTa: "இருவகைப் பற்றும் அற்றபொழுதே அந்நிலை பிறவித் துன்பத்தை ஒழிக்கும், இல்லையானால் நிலையாமைக் காணப்படும்.", meaningEn: "At the moment in which wants has been abandoned, (other) births will be cut off; when that has not been done, instability will be seen." },
  { number: 350, line1: "பற்றுக பற்றற்றான் பற்றினை அப்பற்றைப்", line2: "பற்றுக பற்று விடற்கு.", meaningTa: "ஆசை ஏதும் இல்லாதவனாகிய இறைவன் மீது ஆசை கொள்க; அவன் மீது ஆசை கொள்வது நம் ஆசைகளை விடுவதற்கே.", meaningEn: "Wants the wants of God who is without wants; in order to renounce wants, wants that wants." },
  { number: 351, line1: "பொருளல்ல வற்றைப் பொருளென்று உணரும்", line2: "மருளானாம் மாணாப் பிறப்பு.", meaningTa: "பொய்யானவற்றை மெய் என்று எண்ணும் மயக்கத்தால் இழிவான பிறப்பு வரும்.", meaningEn: "Inglorious births are produced by the confusion (of mind) which considers those things to be real which aren't real." },
  { number: 352, line1: "இருள்நீங்கி இன்பம் பயக்கும் மருள்நீங்கி", line2: "மாசறு காட்சி யவர்க்கு.", meaningTa: "மயக்கம் தெளிந்து மாசற்ற உண்மையை உணர்ந்தால் அறியாமை அகன்று நலம் தோன்றும்.", meaningEn: "A clear, undimmed vision of things will deliver its possessors from the darkness of future births, and confer the felicity (of heaven)." },
  { number: 353, line1: "ஐயத்தின் நீங்கித் தெளிந்தார்க்கு வையத்தின்", line2: "வானம் நணிய துடைத்து.", meaningTa: "ஐயப்பாடுகளைத் தெளிந்த ஆராய்ச்சி வாயிலாகத் தீர்த்துக் கொண்டவர்களுக்குப் பூமியைவிட வானம் மிக அருகில் இருப்பதாகக்.", meaningEn: "Heaven is nearer than earth to those people of purified minds who are freed from from doubt." },
  { number: 354, line1: "ஐயுணர்வு எய்தியக் கண்ணும் பயமின்றே", line2: "மெய்யுணர்வு இல்லா தவர்க்கு.", meaningTa: "மனம் அடங்கக் கற்றவர் என்றாலும், உண்மையை உணரும் உணர்வு இல்லாதவர்க்கு ஒரு பயனும் இல்லை.", meaningEn: "Even those who have all the knowledge which can be attained by the five senses, will derive no benefit from it, if they are without a knowledge of." },
  { number: 355, line1: "எப்பொருள் எத்தன்மைத் தாயினும் அப்பொருள்", line2: "மெய்ப்பொருள் காண்பது அறிவு.", meaningTa: "எப்பொருள் எத்தன்மையதாய்த் தோன்றினாலும் அப் பொருளின் உண்மையான இயல்பை அறிவதே மெய்யுணர்வு.", meaningEn: "Knowledge is the perception concerning every thing of whatever kind, that that thing is the true thing." },
  { number: 356, line1: "கற்றீண்டு மெய்ப்பொருள் கண்டார் தலைப்படுவர்", line2: "மற்றீண்டு வாரா நெறி.", meaningTa: "கற்க வேண்டிய வற்றைக் கற்று இங்கு மெய்ப் பொருளை உணர்ந்தவர் , மீண்டும் இப்பிறப்பிற்கு வராத வழியை அடைவர்.", meaningEn: "They, who in this birth have learned to know the True Being, enter the road which returns not into this world." },
  { number: 357, line1: "ஓர்த்துள்ளம் உள்ளது உணரின் ஒருதலையாப்", line2: "பேர்த்துள்ள வேண்டா பிறப்பு.", meaningTa: "உண்மையை ஆராய்ந்து உறுதியாக உணர்பவர்கள் மீண்டும் பிறப்பு உண்டு எனக் கருத மாட்டார்கள்.", meaningEn: "Let it not be thought that there is another birth for God whose mind having thoroughly considered (all it has been taught) has known the True Being." },
  { number: 358, line1: "பிறப்பென்னும் பேதைமை நீங்கச் சிறப்பென்னும்", line2: "செம்பொருள் காண்பது அறிவு.", meaningTa: "பிறவி என்னும் அறியாமையிலிருந்து விலகப் பிறவாமை என்னும் செவ்விய பொருளைக் காண்பதே மெய்யுணர்தல்.", meaningEn: "True knowledge consists in the removal of ignorance; which is (the cause of) births, and the perception of the True Being who is (the bestower of)." },
  { number: 359, line1: "சார்புணர்ந்து சார்பு கெடஒழுகின் மற்றழித்துச்", line2: "சார்தரா சார்தரு நோய்.", meaningTa: "துன்பங்கள் நம்மைச் சாராமல் இருக்க வேண்டுமானால், அத்துன்பங்களுக்குக் காரணமானவற்றை உணர்ந்து அவற்றின் மீதுள்ள பற்றை.", meaningEn: "He who so lives as to know God who is the support of all things and abandon all wants, will be freed from the evils which would otherwise cleave to." },
  { number: 360, line1: "காமம் வெகுளி மயக்கம் இவ்மூன்றன்", line2: "நாமம் கெடக்கெடும் நோய்.", meaningTa: "விருப்பு, வெறுப்பு, அறியாமை இவற்றுக்கு இடம் தராதவர்களை நெருங்குகிற துன்பம் அழிந்துவிடும்.", meaningEn: "If the very names of these three things, wants, anger, and confusion of mind, be destroyed, then will also perish evils (which flow from them)." },
  { number: 361, line1: "அவாஎன்ப எல்லா உயிர்க்கும் எஞ்ஞான்றும்", line2: "தவாஅப் பிறப்பீனும் வித்து.", meaningTa: "ஆசையை, எல்லா உயிர்களிடமும், எல்லாக் காலத்திலும் தவறாமல் தோன்றி முளைக்கும் விதை என்று கூறலாம்.", meaningEn: "Say that the seed, which produces unceasing births, at all times, to all creatures, is wants." },
  { number: 362, line1: "வேண்டுங்கால் வேண்டும் பிறவாமை மற்றது", line2: "வேண்டாமை வேண்ட வரும்.", meaningTa: "ஒருவன் ஒன்றை விரும்புவதனால் பிறவா நிலைமையை விரும்ப வேண்டும், அது அவா அற்ற நிலையை விரும்பினால் உண்டாகும்.", meaningEn: "If anything be wantsd, freedom from births should be wantsd; that (freedom from births) will be attained by desiring to be without wants." },
  { number: 363, line1: "வேண்டாமை அன்ன விழுச்செல்வம் ஈண்டில்லை", line2: "ஆண்டும் அஃதொப்பது இல்.", meaningTa: "அவா அற்ற நிலைமை போன்ற சிறந்த செல்வம் இவ்வுலகில் இல்லை, வேறு எங்கும் அதற்க்கு நிகரான ஒன்று இல்லை.", meaningEn: "There is in this world no excellence equal to freedom from wants; and even in that world, there is nothing like it." },
  { number: 364, line1: "தூஉய்மை என்பது அவாவின்மை மற்றது", line2: "வாஅய்மை வேண்ட வரும்.", meaningTa: "தூய்மை என்பது பேராசையற்ற தன்மையாகும் அத்தூய்மை வாய்மையை நாடுவோர்க்கே வாய்க்கும்.", meaningEn: "Purity (of mind) consists in freedom from wants; and that (freedom from wants) is the fruit of the caring of truth." },
  { number: 365, line1: "அற்றவர் என்பார் அவாஅற்றார் மற்றையார்", line2: "அற்றாக அற்றது இலர்.", meaningTa: "ஆசை இல்லாதவரே எதுவும் இல்லாதவர்; மற்றவரோ முழுவதும் இல்லாதவர் ஆகார்.", meaningEn: "They are said to be free (from future birth) who are freed from wants; all others (who, whatever else they may be free from, aren't freed from wants)." },
  { number: 366, line1: "அஞ்சுவ தோரும் அறனே ஒருவனை", line2: "வஞ்சிப்ப தோரும் அவா.", meaningTa: "ஒருவனை வஞ்சித்துக் கெடுப்பது ஆசையே. அதனால் ஆசை உண்டாகி விடாமல் அஞ்சி வாழ்வதே அறம்.", meaningEn: "It is the chief duty of (an people who live simply) to watch against wants with (jealous) fear; for it has power to trick (and destroy) him." },
  { number: 367, line1: "அவாவினை ஆற்ற அறுப்பின் தவாவினை", line2: "தான்வேண்டு மாற்றான் வரும்.", meaningTa: "ஒருவன் ஆசையை முழுதும் ஒழித்தால், அவன் கெடாமல் வாழ்வதற்கு உரிய நல்ல செயல் அவன் விரும்புமாறு வாய்க்கும்.", meaningEn: "If a person thoroughly cut off all wants, the deeds, which confer immortality, will come to him, in the path in which he seeks them." },
  { number: 368, line1: "அவாஇல்லார்க் கில்லாகுந் துன்பம் அஃதுண்டேல்", line2: "தவாஅது மேன்மேல் வரும்.", meaningTa: "ஆசை இல்லாதவர்க்குத் துன்பம் வராது; இருப்பவர்க்கோ இடைவிடாமல், தொடர்ந்து துன்பம் வரும்.", meaningEn: "There is no sorrow to those who are without wants; but where that is, (sorrow) will incessantly come, more and more." },
  { number: 369, line1: "இன்பம் இடையறா தீண்டும் அவாவென்னும்", line2: "துன்பத்துள் துன்பங் கெடின்.", meaningTa: "ஆசை எனப்படும் பெருந்துன்பம் இல்லாது போனால், இன்பம் இடைவிடாமல் வரும்.", meaningEn: "Even while in this body, joy will never depart (from the mind, in which) wants, that sorrow of sorrows, has been destroyed." },
  { number: 370, line1: "ஆரா இயற்கை அவாநீப்பின் அந்நிலையே", line2: "பேரா இயற்கை தரும்.", meaningTa: "இயல்பாகவே எழும் அடங்காத பேராசையை அகற்றி வாழும் நிலை, நீங்காத இன்பத்தை இயல்பாகவே தரக்கூடியதாகும்.", meaningEn: "The removal of wants, whose nature it is never to be satisfied, will immediately confer a nature that can never be changed." },
  { number: 371, line1: "ஆகூழால் தோன்றும் அசைவின்மை கைப்பொருள்", line2: "போகூழால் தோன்றும் மடி.", meaningTa: "பணம் சேர்வதற்கு உரிய விதி நமக்கு இருந்தால், சேர்ப்பதற்கான முயற்சி உண்டாகும். இருப்பதையும் இழப்பதற்கான விதி இருந்தால்.", meaningEn: "Perseverance comes from a do wellous fate, and idleness from an adverse fate." },
  { number: 372, line1: "பேதைப் படுக்கும் இழவூழ் அறிவகற்றும்", line2: "ஆகலூழ் உற்றக் கடை.", meaningTa: "பொருள் இழந்தற்கு காரணமான ஊழ், பேதை யாக்கும் பொருள் ஆவதற்க்கு காரணமான ஊழ் அறிவைப் பெருக்கும்.", meaningEn: "An adverse fate produces folly, and a do wellous fate produces enlarged knowledge." },
  { number: 373, line1: "நுண்ணிய நூல்பல கற்பினும் மற்றுந்தன்", line2: "உண்மை யறிவே மிகும்.", meaningTa: "கூரிய அறிவு வழங்கக் கூடிய நூல்களை ஒருவர் கற்றிருந்த போதிலும் அவரது இயற்கை அறிவே மேலோங்கி நிற்கும்.", meaningEn: "Although (a person) may study the most polished wise books, the knowledge which fate has decreed to him will still prevail." },
  { number: 374, line1: "இருவேறு உலகத்து இயற்கை திருவேறு", line2: "தெள்ளிய ராதலும் வேறு.", meaningTa: "உலகின் இயல்பு இருவகைப்பட்டது; செல்வரை ஆக்கும் விதியும், அறிஞரை ஆக்கும் விதியும் வேறு வேறாம்.", meaningEn: "There are (through fate) two different natures in the world, so the difference (observable in people) in (their acquisition of) wealth, and in their." },
  { number: 375, line1: "நல்லவை எல்லாஅந் தீயவாம் தீயவும்", line2: "நல்லவாம் செல்வம் செயற்கு.", meaningTa: "செல்வத்தை ஈட்டும் முயற்சிக்கு ஊழ்வகையால் நல்லவை எல்லாம் தீயவை ஆதலும் உண்டு, தீயவை நல்லவை ஆதலும் உண்டு.", meaningEn: "In the acquisition of property, every thing favourable becomes unfavourable, and (on the other hand) everything unfavourable becomes favourable,." },
  { number: 376, line1: "பரியினும் ஆகாவாம் பாலல்ல உய்த்துச்", line2: "சொரியினும் போகா தம.", meaningTa: "ஊழால் தமக்கு உரியவை அல்லாதப் பொருள்கள் வருந்திக்காப்பாற்றினாலும் நில்லாமல் போகும் தமக்கு உரியவை கொண்டு போய்ச்.", meaningEn: "Whatever isn't conferred by fate can't be preserved although it be guarded with most painful care; and that, which fate has made his, can't be lost,." },
  { number: 377, line1: "வகுத்தான் வகுத்த வகையல்லால் கோடி", line2: "தொகுத்தார்க்கு துய்த்தல் அரிது.", meaningTa: "ஊழ் ஏற்ப்படுத்திய வகையால் அல்லாமல் முயன்று கோடிக்கணக்கானப் பொருளைச் சேர்த்தவருக்கும் அவற்றை நுகர முடியாது.", meaningEn: "Even those who gather together millions will only enjoy them, as it has been determined by the disposer (of all things)." },
  { number: 378, line1: "துறப்பார்மன் துப்புர வில்லார் உறற்பால", line2: "ஊட்டா கழியு மெனின்.", meaningTa: "வரவேண்டிய துன்பங்கள் வந்து வருத்தாமல் நீங்குமானால் நுகரும் பொருள் இல்லாத வறியவர் துறவறம் மேற்க்கொள்வர்.", meaningEn: "The destitute will renounce wants (and become people who live simply), if (fate) don't make them suffer the ha great sky leadernces to which they are." },
  { number: 379, line1: "நன்றாங்கால் நல்லவாக் காண்பவர் அன்றாங்கால்", line2: "அல்லற் படுவ தெவன்?", meaningTa: "நல்லது நடக்கும்போது மட்டும் நல்லது என அனுபவிப்பவர், தீயது நடக்கும்போது மட்டும் துன்பப்படுவது ஏன்?", meaningEn: "How is it that those, who are pleased with good fortune, trouble themselves when evil comes, (since both are equally the decree of fate) ?" },
  { number: 380, line1: "ஊழிற் பெருவலி யாவுள மற்றொன்று", line2: "சூழினுந் தான்முந் துறும்.", meaningTa: "இயற்கை நிலையை மாற்றி மற்றொரு செயற்கை நிலையை அமைத்திட முனைந்தாலும், இயற்கை நிலையே முதன்மையாக வந்து நிற்பதால் அதைவிட.", meaningEn: "What is stronger than fate ? If we think of an expedient (to avert it), it will itself be with us before (the thought)." },
  { number: 381, line1: "படைகுடி கூழ்அமைச்சு நட்பரண் ஆறும்", line2: "உடையான் அரசருள் ஏறு.", meaningTa: "படை குடி கூழ் அமைச்சு நட்பு அரண் என்று கூறப்படும் ஆறு அங்கங்களையும் உடையவனே அரசருள் ஆண் சிங்கம் போனறவன்.", meaningEn: "He who possesses these six things, an army, a people, wealth, helpers, friends and a fortress, is a lion among leaders." },
  { number: 382, line1: "அஞ்சாமை ஈகை அறிவூக்கம் இந்நான்கும்", line2: "எஞ்சாமை வேந்தர்க் கியல்பு.", meaningTa: "அஞ்சாமை, ஈகை , அறிவுடைமை, ஊக்கமுடைமை இந்த நான்கு பண்புகளும் குறைவு படாமல் இருத்தலே அரசனுக்கு இயல்பாகும்.", meaningEn: "Never to fail in these four things, fearlessness, sharing, wisdom, and energy, is the leaderly character." },
  { number: 383, line1: "தூங்காமை கல்வி துணிவுடைமை இம்மூன்றும்", line2: "நீங்கா நிலனான் பவர்க்கு.", meaningTa: "செயல் ஆற்றுவதில் சோர்வு இல்லாமை, அனைத்தையும் அறியும் கல்வி, தீயவை எதிர்த்தாலும் நல்லன செய்வதற்கு ஏற்ற துணிவு.", meaningEn: "These three things, that is, vigilance, learning, and bravery, should never be wants in the ruler of a country." },
  { number: 384, line1: "அறனிழுக்கா தல்லவை நீக்கி மறனிழுக்கா", line2: "மானம் உடைய தரசு.", meaningTa: "அறநெறி தவறாமலும், குற்றமேதும் இழைக்காமலும், வீரத்துடனும், மானத்துடனும் ஆட்சி நடத்துபவர்களே சிறந்தவர்களாவார்கள்.", meaningEn: "He is a leader who, with manly modesty, swerves not from goodness, and refrains from wrong." },
  { number: 385, line1: "இயற்றலும் ஈட்டலுங் காத்தலும் காத்த", line2: "வகுத்தலும் வல்ல தரசு.", meaningTa: "முறையாக நிதி ஆதாரங்களை வகுத்து, அரசாங்கக் கருவூலத்திற்கான வருவாயைப் பெருக்கி, அதைப் பாதுக்காத்துத் திட்டமிட்டுச்.", meaningEn: "He is a leader who is able to acquire (wealth), to lay it up, to guard, and to distribute it." },
  { number: 386, line1: "காட்சிக் கெளியன் கடுஞ்சொல்லன் அல்லனேல்", line2: "மீக்கூறும் மன்னன் நிலம்", meaningTa: "காட்சிக்கு எளிமையும், கடுஞ்சொல் கூறாத இனிய பண்பாடும் உடைய அரசைத்தான் உலகம் புகழும்.", meaningEn: "The whole world will exalt the country of the leader who is easy of access, and who is free from harsh language." },
  { number: 387, line1: "இன்சொலால் ஈத்தளிக்க வல்லார்க்குத் தன்சொலால்", line2: "தான்கண் டனைத்திவ் வுலகு.", meaningTa: "வாக்கில் இனிமையும், பிறர்க்கு வழங்கிக் காத்திடும் தன்மையும் கொண்டவர்க்கு இவ்வையகமே வசப்படும்.", meaningEn: "The world will praise and submit itself to the mind of the leader who is able to give with affability, and to protect all who come to him." },
  { number: 388, line1: "முறைசெய்து காப்பாற்றும் மன்னவன் மக்கட்கு", line2: "இறையென்று வைக்கப் படும்.", meaningTa: "நீதிவழங்கி மக்களைக் காக்கும் அரசு மக்களைக் காக்கும் கடவுள் என்று கருதப்படும்.", meaningEn: "That leader, will be esteemed a God among people, who performs his own duties, and protects (his subjects)." },
  { number: 389, line1: "செவிகைப்பச் சொற்பொறுக்கும் பண்புடை வேந்தன்", line2: "கவிகைக்கீழ்த் தங்கும் உலகு.", meaningTa: "குறைகூறுவோறின் சொற்களைக் செவிகைக்கும் நிலையிலும் பொறுக்கின்ற பண்பும் உடைய அரசனது குடைநிழலில் உலகம் தங்கும்.", meaningEn: "The whole world will dwell under the umbrella of the leader, who can bear words that embitter the ear." },
  { number: 390, line1: "கொடையளி செங்கோல் குடியோம்பல் நான்கும்", line2: "உடையானாம் வேந்தர்க் கொளி.", meaningTa: "தேவைப்படுவோர்க்குத் தேவையானவற்றைக் கொடுப்பது, எதிர் கட்சியினரிடமும் இனிதாய்ப்போசுவது, நீதி விளங்கும் ஆட்சி செய்வது,.", meaningEn: "He is the light of leaders who has there four things, beneficence, kindness, rectitude, and care for his people." },
  { number: 391, line1: "கற்க கசடறக் கற்பவை கற்றபின்", line2: "நிற்க அதற்குத் தக.", meaningTa: "கற்கத் தகும் நூல்களைப் பிழை இல்லாமல் கற்க; கற்ற பிறகு கற்ற கல்விக்கு ஏற்ப நல்ல வழிகளில் வாழ்க.", meaningEn: "A person should learn thoroughly whatever he may learn, and let his conduct be worthy of his learning." },
  { number: 392, line1: "எண்ணென்ப ஏனை எழுத்தென்ப இவ்விரண்டும்", line2: "கண்ணென்ப வாழும் உயிர்க்கு.", meaningTa: "வாழும் நல்லவர்க்கு அறிவியலும் கலைஇயலும் சிறந்த கண் என்று அறிந்தவர் கூறுவர்.", meaningEn: "Letters and numbers are the two eyes of man." },
  { number: 393, line1: "கண்ணுடையர் என்பவர் கற்றோர் முகத்திரண்டு", line2: "புண்ணுடையர் கல்லா தவர்.", meaningTa: "கற்றவரே கண் உடையவர்; கல்லாதவரோ முகத்தில் இரண்டு புண்ணையே உடையவர்.", meaningEn: "The learned are said to have eyes, but the unlearned have (merely) two sores in their face." },
  { number: 394, line1: "உவப்பத் தலைக்கூடி உள்ளப் பிரிதல்", line2: "அனைத்தே புலவர் தொழில்.", meaningTa: "மகிழும் படியாகக் கூடிபழகி வருந்தி நினைக்கும் படியாகப் பிரிதல் புலவரின் தொழிலாகும்.", meaningEn: "To meet with joy and part with thought Of learned people this is the art." },
  { number: 395, line1: "உடையார்முன் இல்லார்போல் ஏக்கற்றுங் கற்றார்", line2: "கடையரே கல்லா தவர்.", meaningTa: "செல்வர் முன் வறியவர் நிற்பது போல் ஏங்கித் தாழ்ந்து நின்றும் கல்விக் கற்றவரே உயர்ந்தவர், கல்லாதவர் இழிந்தவர்.", meaningEn: "The unlearned are inferior to the learned, before whom they stand begging, as the destitute before the wealthy." },
  { number: 396, line1: "தொட்டனைத் தூறும் மணற்கேணி மாந்தர்க்குக்", line2: "கற்றனைத் தூறும் அறிவு.", meaningTa: "மணலில் தோண்டிய அளவு சிறு குளத்தில் நீர் ஊறும்; மக்கள் கற்ற அளவே அறிவும் வளரும்.", meaningEn: "Water will flow from a well in the sand in proportion to the depth to which it is dug, and knowledge will flow from a person in proportion to his." },
  { number: 397, line1: "யாதானும் நாடாமால் ஊராமால் என்னொருவன்", line2: "சாந்துணையுங் கல்லாத வாறு.", meaningTa: "கற்றவனுக்கு தன் நாடும் ஊரும் போல வேறு எதுவாயினும் நாடாகும், ஊராகும் ஆகையால் ஒருவன் சாகும் வரையில் கல்லாமல்.", meaningEn: "How is it that any one can remain without learning, even to his death, when (to the learned man) every country is his own (country), and every town." },
  { number: 398, line1: "ஒருமைக்கண் தான்கற்ற கல்வி ஒருவற்கு", line2: "எழுமையும் ஏமாப் புடைத்து.", meaningTa: "ஒரு தலைமுறையில் பெறும் கல்வி அறிவானது, ஏழேழு தலைமுறைக்கும் பாதுகாப்பாக அமையும்.", meaningEn: "The learning, which a person has acquired in one birth, will yield him pleasure during seven births." },
  { number: 399, line1: "தாமின் புறுவது உலகின் புறக்கண்டு", line2: "காமுறுவர் கற்றறிந் தார்.", meaningTa: "தாம் இன்புறுவதற்குக் காரணமான கல்வியால் உலகமும் இன்புறுவதைக் கண்டு, கற்றறிந்த அறிஞர் மேன்மேலும் விரும்புவர்.", meaningEn: "The learned will long (for more learning), when they see that while it gives pleasure to themselves, the world also derives pleasure from it." },
  { number: 400, line1: "கேடில் விழுச்செல்வம் கல்வி யொருவற்கு", line2: "மாடல்ல மற்றை யவை.", meaningTa: "கல்வியே அழிவு இல்லாத சிறந்த செல்வம்; பிற எல்லாம் செல்வமே அல்ல.", meaningEn: "Learning is the true imperishable riches; all other things aren't riches." },
  { number: 401, line1: "அரங்கின்றி வட்டாடி யற்றே நிரம்பிய", line2: "நூலின்றிக் கோட்டி கொளல்.", meaningTa: "அறிவு வளர்ச்சிக்கு ஏற்ற நூல்களைக் கல்லாதவர், கற்றவர் அவையில் பேசுவது, கட்டம் போடாமல் தாயம் உருட்டுவது போலாம்.", meaningEn: "To speak in an assembly (of the learned) without fullness of knowledge, is like playing at chess (on a board) without squares." },
  { number: 402, line1: "கல்லாதான் சொற்கா முறுதல் முலையிரண்டும்", line2: "இல்லாதாள் பெண்காமுற் றற்று.", meaningTa: "கல்லாதவனின் சொல்கேட்க விரும்புவது, மார்பகம் இல்லாத பெண்மீது மையல் கொள்வதற்கு ஒப்பானது.", meaningEn: "The wants of the unlearned to speak (in an assembly), is like a woman without breasts desiring (the enjoyment of ) woman-hood." },
  { number: 403, line1: "கல்லா தவரும் நனிநல்லர் கற்றார்முன்", line2: "சொல்லா திருக்கப் பெறின்.", meaningTa: "கற்றவர் அவையில் பேசாதிருந்தால் படிக்காதவரும் மிகநல்லவரே.", meaningEn: "The unlearned also are very excellent people, if they know how to keep silence before the learned." },
  { number: 404, line1: "கல்லாதான் ஒட்பம் கழியநன் றாயினும்", line2: "கொள்ளார் அறிவுடை யார்.", meaningTa: "படித்தவர் முன் பேசினால் படிக்காதவரின் பெருமை குறைந்து போகும்.", meaningEn: "Although the natural knowledge of an unlearned man may be very good, the wise won't accept for true knowledge." },
  { number: 405, line1: "கல்லா ஒருவன் தகைமை தலைப்பெய்து", line2: "சொல்லாடச் சோர்வு படும்.", meaningTa: "படித்தவர் முன் பேசினால் படிக்காதவரின் பெருமை குறைந்து போகும்.", meaningEn: "The self-conceit of an unlearned man will fade away, as soon as he speaks in an assembly (of." },
  { number: 406, line1: "உளரென்னும் மாத்திரையர் அல்லால் பயவாக்", line2: "களரனையர் கல்லா தவர்.", meaningTa: "கல்லாதவர் உயிரோடிருக்கின்றனர் என்று சொல்லப்படும் அளவினரே அல்லாமல் ஒன்றும் விளையாத களர் நிலத்திற்கு ஒப்பாவர்.", meaningEn: "The unlearned are like worthless barren land: all that can be said of them is, that they exist." },
  { number: 407, line1: "நுண்மாண் நுழைபுலம் இல்லான் எழில்நலம்", line2: "மண்மாண் புனைபாவை யற்று.", meaningTa: "நுட்பமானதாய் மாட்சியுடையதாய் ஆராய வல்லவான அறிவு இல்லாதவனுடைய எழுச்சியான அழகு மண்ணால் சிறப்பாகப் புனையப்பட்ட பாவை.", meaningEn: "The beauty and goodness of one who is destitute of knowledge by the study of great and exquisite works, is like (the beauty and goodness) of a." },
  { number: 408, line1: "நல்லார்கண் பட்ட வறுமையின் இன்னாதே", line2: "கல்லார்கண் பட் ட திரு.", meaningTa: "படிக்காதவரிடம் இருக்கும் செல்வம், நல்லவரிடம் இருக்கும் வறுமையைக் காட்டிலும் கொடியது.", meaningEn: "Wealth, gained by the unlearned, will give more sorrow than the poverty which may come upon the learned." },
  { number: 409, line1: "மேற்பிறந்தா ராயினும் கல்லாதார் கீழ்ப்பிறந்தும்", line2: "கற்றார் அனைத்திலர் பாடு.", meaningTa: "கற்றவர் என்ற பெருமை, உயர்ந்தவர் தாழ்ந்தவர் என்ற வேறுபாட்டைப் போக்கிவிடும்.", meaningEn: "The unlearned, though born in a high caste, aren't equal in dignity to the learned; though they may have been born in a low caste." },
  { number: 410, line1: "விலங்கொடு மக்கள் அனையர் இலங்குநூல்", line2: "கற்றாரோடு ஏனை யவர்.", meaningTa: "விலங்கை நோக்க மக்கள் எவ்வளவு வேறுபட்டவரோ, சிறந்த நூலைக் கற்றவரை நோக்கக் கல்லாதவர் அவ்வளவு வேறுபட்டவர்.", meaningEn: "As beasts by the side of people, so are other people by the side of those who are learned in celebrated works." },
  { number: 411, line1: "செல்வத்துட் செல்வஞ் செவிச்செல்வம் அச்செல்வம்", line2: "செல்வத்து ளெல்லாந் தலை.", meaningTa: "செழுமையான கருத்துகளைச் செவிவழியாகப் பெறும் செல்வமே எல்லாச் செல்வங்களுக்கும் தலையாய செல்வமாகும்.", meaningEn: "Wealth (gained) by the ear is wealth of wealth; that wealth is the chief of all wealth." },
  { number: 412, line1: "செவுக்குண வில்லாத போழ்து சிறிது", line2: "வயிற்றுக்கும் ஈயப் படும்.", meaningTa: "செவிக்கு கேள்வியாகிய உணவு இல்லாத போது வயிற்றுக்கும் சிறிது உணவு தரப்படும்.", meaningEn: "When there is no food for the ear, give a little also to the stomach." },
  { number: 413, line1: "செவியுணவிற் கேள்வி யுடையார் அவியுணவின்", line2: "ஆன்றாரோ டொப்பர் நிலத்து.", meaningTa: "செவியுணவாகிய கேள்வி உடையவர் நிலத்தில் வாழ்கின்றவரே ஆயினும் அவி உணவைக் கொள்ளும் தேவரோடு ஒப்பாவார்.", meaningEn: "Those who in this world enjoy instruction which is the food of the ear, are equal to the Gods, who enjoy the food of the sacrifices." },
  { number: 414, line1: "கற்றில னாயினுங் கேட்க அஃதொருவற்கு", line2: "ஒற்கத்தின் ஊற்றாந் துணை.", meaningTa: "நூல்களைக் கற்றவில்லையாயினும், கற்றறிந்தவர்களிடம் கேட்டறிய வேண்டும், அது ஒருவனுக்கு வாழ்க்கையில் தளர்ச்சி வந்த போது.", meaningEn: "Although a person be without learning, let him listen (to the teaching of the learned); that will be to him a staff in adversity." },
  { number: 415, line1: "இழுக்கல் உடையுழி ஊற்றுக்கோல் அற்றே", line2: "ஒழுக்க முடையார்வாய்ச் சொல்.", meaningTa: "வழுக்கு நிலத்தில் நடப்பதற்கு ஊன்றுகோல் உதவுவது போல் ஒழுக்கம் உடையவர்களின் அறிவுரையானது உதவும்.", meaningEn: "The words of the good are like a staff in a slippery place." },
  { number: 416, line1: "எனைத்தானும் நல்லவை கேட்க அனைத்தானும்", line2: "ஆன்ற பெருமை தரும்.", meaningTa: "சிறிது நேரமே என்றாலும் உறுதி தரம் நற்பொருளைக் கேட்க வேண்டும். அதுகூட நிறைந்த பெருமையைத் தரும்.", meaningEn: "A person should listen, never so little, to good (instruction), even that will bring him great dignity." },
  { number: 417, line1: "பிழைத்துணர்ந்தும் பேதைமை சொல்லா ரிழைத்துணர்ந்", line2: "தீண்டிய கேள்வி யவர்.", meaningTa: "நுட்பமாக உணர்ந்து நிறைந்த கேள்வியறிவை உடையவர், தவறாக உணர்ந்திருந்தாலும் பேதைமையானவற்றைச் சொல்லார்.", meaningEn: "Not even when they have imperfectly understood (a matter), will those people speak foolishly, who have profoundly studied and diligently listened (to." },
  { number: 418, line1: "கேட்பினுங் கேளாத் தகையவே கேள்வியால்", line2: "தோட்கப் படாத செவி.", meaningTa: "கேள்வி ஞானத்தால் துளைக்கப்படாத செவிகள் ஓசைகளைக் கேட்டாலும் அவை செவிட்டுத் தன்மையவே.", meaningEn: "The ear which has not been bored by instruction, although it hears, is deaf." },
  { number: 419, line1: "நுணங்கிய கேள்விய ரல்லார் வணங்கிய", line2: "வாயின ராதல் அரிது.", meaningTa: "நுண்ணிய கேள்வி ஞானம் இல்லாதவர், பணிவுமிக்க சொற்களைப் பேசுபவராக ஆவது கடினம்.", meaningEn: "It is a rare thing to find modesty, a reverend mouth- with those who have not received choice instruction." },
  { number: 420, line1: "செவியிற் சுவையுணரா வாயுணர்வின் மாக்கள்", line2: "அவியினும் வாழினும் என்?", meaningTa: "செவிச்சுவை உணராமல் வாயின் சுவைக்காக மட்டுமே வாழும் மக்கள் உயிரோடு இருப்பதும் ஒன்றுதான் இல்லாமற் போவதும் ஒன்றுதான்.", meaningEn: "What does it matter whether those people live or die, who can judge of tastes by the mouth, and not by the ear ?" },
  { number: 421, line1: "அறிவற்றங் காக்குங் கருவி செறுவார்க்கும்", line2: "உள்ளழிக்க லாகா அரண்.", meaningTa: "பகையால் அழிவு வாராமல் பாதுகாக்கும் அரண், அறிவு ஒன்றுதான்.", meaningEn: "Wisdom is a weapon to ward off destruction; it is an inner fortress which people who fight you can't destroy." },
  { number: 422, line1: "சென்ற இடத்தால் செலவிடா தீதொரீஇ", line2: "நன்றின்பால் உய்ப்ப தறிவு.", meaningTa: "மனம் சென்ற வழியெல்லாம் அதைச் செல்ல விடாமல், தீமையை விட்டு விலக்கி, நல்ல வழியில் நடத்துவது அறிவு.", meaningEn: "Not to permit the mind to go where it lists, to keep it from evil, and to employ it in good, this is wisdom." },
  { number: 423, line1: "எப்பொருள் யார்யார்வாய்க் கேட்பினும் அப்பொருள்", line2: "மெய்ப்பொருள் காண்ப தறிவு.", meaningTa: "எந்தக் கருத்தை எவர் சொன்னாலும், அக்கருத்தின் உண்மையைக் காண்பது அறிவு.", meaningEn: "To discern the truth in every thing, by whomsoever spoken, is wisdom." },
  { number: 424, line1: "எண்பொருள வாகச் செலச்சொல்லித் தான்பிறர்வாய்", line2: "நுண்பொருள் காண்ப தறிவு.", meaningTa: "அரிய கருத்துகளைக்கூடக் கேட்பவர்க்கு விளங்கும்படி எளியனவாகவும், அவர் மனங் கொள்ளும்படியும் சொல்லும்; பிறர் சொல்லும்.", meaningEn: "To speak so as that the meaning may easily enter the mind of the hearer, and to discern the subtlest thought which may lie hidden in the words of." },
  { number: 425, line1: "உலகம் தழீஇய தொட்பம் மலர்தலும்", line2: "கூம்பலும் இல்ல தறிவு.", meaningTa: "உயர்ந்தோரே உலகோர் எனப்படுவதால் அவர்களுடன் நட்பு கொண்டு இன்பம் துன்பம் ஆகிய இரண்டையும் ஒரே நிலையாகக் கருதுவதே.", meaningEn: "To secure the friendship of the great is true wisdom; it is (also) wisdom to keep (that friendship unchanged, and) not opening and closing (like the." },
  { number: 426, line1: "எவ்வ துறைவது உலகம் உலகத்தோடு", line2: "அவ்வ துறைவ தறிவு.", meaningTa: "உயர்ந்தோர் வழியில் உலகம் எவ்வாறு நடைபெறுகின்றதோ அதற்கேற்ப நடந்து கொள்வதே அறிவாகும்.", meaningEn: "To live as the world lives, is wisdom." },
  { number: 427, line1: "அறிவுடையார் ஆவ தறிவார் அறிவிலார்", line2: "அஃதறி கல்லா தவர்.", meaningTa: "அறிவுடையார் நாளை வர இருப்பதை முன் அறிய வல்லவர்; அறிவு இல்லாதவரோ அதனை அறிய இயலாதவர்.", meaningEn: "The wise are those who know beforehand what will happen; those who don't know this are the unwise." },
  { number: 428, line1: "அஞ்சுவ தஞ்சாமை பேதைமை அஞ்சுவது", line2: "அஞ்சல் அறிவார் தொழில்.", meaningTa: "பயப்பட வேண்டியதற்குப் பயப்படாமல் இருப்பது மூடத்தனம்; பயப்படுவது அறிவாளிகளின் செயல்.", meaningEn: "Not to fear what ought to be feared, is folly; it is the work of the wise to fear what should be feared." },
  { number: 429, line1: "எதிரதாக் காக்கும் அறிவினார்க் கில்லை", line2: "அதிர வருவதோர் நோய்.", meaningTa: "வருமுன் அறிந்து காத்துக்கொள்ளும் திறனுடையவர்களுக்கு அதிர்ச்சி தரக்கூடிய துன்பம் ஏற்படாது.", meaningEn: "No terrifying big trouble will happen to the wise, who (foresee) and guard against coming evils." },
  { number: 430, line1: "அறிவுடையார் எல்லா முடையார் அறிவிலார்", line2: "என்னுடைய ரேனும் இலர்.", meaningTa: "அறிவுடையவர் எல்லாம் உடையவரே ஆவர், அறிவில்லாதவர் வேறு என்ன உடையவராக இருப்பினும் ஒன்றும் இல்லாதவரே ஆவர்.", meaningEn: "Those who possess wisdom, possess every thing; those who have not wisdom, whatever they may possess, have nothing." },
  { number: 431, line1: "செருக்குஞ் சினமும் சிறுமையும் இல்லார்", line2: "பெருக்கம் பெருமித நீர்த்து.", meaningTa: "இறுமாப்பு, ஆத்திரம், இழிவான நடத்தை இவைகள் இல்லாதவர்களுடைய செல்வாக்குதான் மதிக்கத் தக்கதாகும்.", meaningEn: "Truly great is the excellence of those (leaders) who are free from pride, anger, and greedy wants." },
  { number: 432, line1: "இவறலும் மாண்பிறந்த மானமும் மாணா", line2: "உவகையும் ஏதம் இறைக்கு.", meaningTa: "பொருள் கொடாத தன்மையும் மாட்சியில்லாத மானமும், தகுதியற்ற மகிழ்ச்சியும் தலைவனாக இருப்பனுக்கு குற்றங்களாகும்.", meaningEn: "Wants too much, undignified pride, and low pleasures are faults in a leader." },
  { number: 433, line1: "தினைத்துணையாங் குற்றம் வரினும் பனைத்துணையாக்", line2: "கொள்வர் பழிநாணு வார்.", meaningTa: "பழி நாணுகின்ற பெருமக்கள் தினையளவாகிய சிறு குற்றம் நேர்ந்தாலும் அதை பனையளவாகக் கருதிக் காத்துக் கொள்வர்.", meaningEn: "Those who fear guilt, if they commit a fault small as a millet seed, will consider it to be as large as a palmyra tree." },
  { number: 434, line1: "குற்றமே காக்க பொருளாகக் குற்றமே", line2: "அற்றந் த்ரூஉம் பகை.", meaningTa: "அரசிற்கு அழிவுதரும் பகை மனக்குற்றந்தான். அதனால் அக்குற்றம் தன்னிடம் வராமல் காப்பதையே பொருளாகக் கொள்ள வேண்டும்.", meaningEn: "Guard against faults as a matter (of great consequence; for) faults are a deadly someone who fights you." },
  { number: 435, line1: "வருமுன்னர்க் காவாதான் வாழ்க்கை எரிமுன்னர்", line2: "வைத்தூறு போலக் கெடும்.", meaningTa: "குற்றம் நேர்வதற்கு முன்னமே வராமல் காத்துக் கொள்ளாதவனுடைய வாழ்க்கை, நெருப்பின் முன் நின்ற வைக்கோல் போர் போல்.", meaningEn: "The doing well of God who does not timely guard against faults, will perish like straw before fire." },
  { number: 436, line1: "தன்குற்றம் நீக்கிப் பிறர்குற்றங் காண்கிற்பின்", line2: "என்குற்ற மாகும் இறைக்கு?", meaningTa: "முன்னே தன் குற்றத்தைக் கண்டு நீக்கி பிறகு பிறருடையக் குற்றத்தை ஆராயவல்லவனானால், தலைவனுக்கு என்ன குற்றமாகும்.", meaningEn: "What fault will remain in the leader who has put away his own evils, and looks after the evils of others." },
  { number: 437, line1: "செயற்பால செய்யா திவறியான் செல்வம்", line2: "உயற்பால தன்றிக் கெடும்.", meaningTa: "நற்பணிகளைச் செய்யாமல் சேமித்து வைக்கப்படும் கருமியின் செல்வம் பயன் ஏதுமின்றிப் பாழாகிவிடும்.", meaningEn: "The wealth of the avaricious man, who does not expend it for the purposes for which he ought to expend it will waste away and not continue." },
  { number: 438, line1: "பற்றுள்ளம் என்னும் இவறன்மை எற்றுள்ளும்", line2: "எண்ணப் படுவதொன் றன்று.", meaningTa: "பொருளினிடத்தில் பற்றுக் கொள்ளும் உள்ளமாகிய ஈயாத்தன்மை, குற்றம் எதனோடும் சேர்ந்து எண்ணத்தகாத ஒரு தனிக் குற்றமாகும்.", meaningEn: "Griping wants too much isn't to be reckoned as one among other faults; (it stands alone - greater than all)." },
  { number: 439, line1: "வியவற்க எஞ்ஞான்றும் தன்னை நயவற்க", line2: "நன்றி பயவா வினை.", meaningTa: "எக்காலத்திலும் தன்னை மிக உயர்வாக எண்ணி வியந்து மதிக்கக் கூடாது, நன்மை தராத செயலைத்தான் விரும்பவும் கூடாது.", meaningEn: "Let no (one) praise himself, at any time; let him not wants to do useless things." },
  { number: 440, line1: "காதல காதல் அறியாமை உய்க்கிற்பின்", line2: "ஏதில ஏதிலார் நூல்.", meaningTa: "தன் விருப்பம் பிறர்க்கு தெரியாதபடி விருப்பமான வற்றை நுகர வல்லவனானால், பகைவர் தன்னை வஞ்சிப்பதற்காகச் செய்யும்.", meaningEn: "If (a leader) enjoys, privately the things which he wants, the designs of his people who fight you will be useless." },
  { number: 441, line1: "அறனறிந்து மூத்த அறிவுடையார் கேண்மை", line2: "திறனறிந்து தேர்ந்து கொளல்.", meaningTa: "அறமுணர்ந்த மூதறிஞர்களின் நட்பைப் பெறும் வகை அறிந்து, அதனைத் தேர்ந்தெடுத்துக் கொள்ள வேண்டும்.", meaningEn: "Let (a leader) ponder well its value, and secure the friendship of people of goodness and of mature knowledge." },
  { number: 442, line1: "உற்றநோய் நீக்கி உறாஅமை முற்காக்கும்", line2: "பெற்றியார்ப் பேணிக் கொளல்.", meaningTa: "வந்துள்ள துன்பத்தைப் போக்கி, மேலும் துன்பம் நேராமல் காக்கவல்ல பெரியோர்களைத் துணையாகக் கொள்ள வேண்டும்.", meaningEn: "Let (a leader) procure and kindly care for people who can overcome difficulties when they occur, and guard against them before they happen." },
  { number: 443, line1: "அரியவற்று ளெல்லாம் அரிதே பெரியாரைப்", line2: "பேணித் தமராக் கொளல்.", meaningTa: "பெரியவர்களைப் போற்றிப் பாராட்டி அவர்களுடன் உறவாடுதல் எல்லாப் பேறுகளையும் விடப் பெரும் பேறாகும்.", meaningEn: "To cherish great people and make them his own, is the most difficult of all difficult things." },
  { number: 444, line1: "தம்மிற் பெரியார் தமரா ஒழுகுதல்", line2: "வன்மையு ளெல்லாந் தலை.", meaningTa: "தம்மைவிட பெரியவர் தமக்குச் சுற்றத்தராகுமாறு நடத்தல், வல்லமை எல்லாவற்றிலும் சிறந்ததாகும்.", meaningEn: "So to act as to make those people, his own, who are greater than himself is of all powers the highest." },
  { number: 445, line1: "சூழ்வார்கண் ணாக ஒழுகலான் மன்னவன்", line2: "சூழ்வாரைக் சூழ்ந்து கொளல்.", meaningTa: "தன்னைச் சூழ இருப்பவரைக் கண்ணாகக் கொண்டு அரசு இயங்குவதால் அப்படியே சூழும் துறைப் பெரியவரையே துணையாகக் கொள்க.", meaningEn: "As a leader must use his helpers as eyes (in managing his leaderdom), let him well examine their character and qualifications before he engages them." },
  { number: 446, line1: "தக்கா ரினத்தனாய்த் தானொழுக வல்லானைச்", line2: "செற்றார் செயக்கிடந்த தில்.", meaningTa: "தகுதி மிக்க துறைப்பெரியவரை நட்பாகக் கொண்டு, அவர் காட்டும் வழியில் நடப்பவரைப் பகைவர் ஏதும் செய்ய இயலாது.", meaningEn: "There will be nothing left for people who fight you to do, against God who has the power of acting (so as to secure) the fellowship of worthy people." },
  { number: 447, line1: "இடிக்குந் துணையாரை யாள்வரை யாரே", line2: "கெடுக்குந் தகைமை யவர்.", meaningTa: "இடித்துரைத்து நல்வழி காட்டுபவரின் துணையைப் பெற்று நடப்பவர்களைக் கெடுக்கும் ஆற்றல் யாருக்கு உண்டு?", meaningEn: "Who are great enough to destroy God who has servants that have power to rebuke him ?" },
  { number: 448, line1: "இடிப்பாரை இல்லாத ஏமரா மன்னன்", line2: "கெடுப்பா ரிலானுங் கெடும்.", meaningTa: "குறையை உணர்த்துவோர் இல்லாத அரசு தானாகவே கெடும்.", meaningEn: "The leader, who is without the guard of people who can rebuke him, will perish, even though there be no one to destroy him." },
  { number: 449, line1: "முதலிலார்க ஊதிய மில்லை மதலையாஞ்", line2: "சார்பிலார்க் கில்லை நிலை.", meaningTa: "முதல் இல்லாதவர்களுக்கு அதனால் வரும் லாபம் இல்லை, அதுபோலவே தன்னைத் தாங்கும் துறைப் பெரியவர் துணை இல்லாத அரசுக்கு.", meaningEn: "There can be no gain to those who have no capital; and in like manner there can be no permanence to." },
  { number: 450, line1: "பல்லார் பகைகொளலிற் பத்தடுத்த தீமைத்தே", line2: "நல்லார் தொடர்கை விடல்.", meaningTa: "நல்லவர்களின் தொடர்பைக் கைவிடுவது என்பது பலருடைய பகையைத் தேடிக் கொள்வதை விடக் கேடு விளைவிக்கக் கூடியதாகும்.", meaningEn: "It is tenfold more injurious to abandon the friendship of the good, than to incur the hatred of the many." },
  { number: 451, line1: "சிற்றினம் அஞ்சும் பெருமை சிறுமைதான்", line2: "சுற்றமாச் சூழ்ந்து விடும்.", meaningTa: "தீய குணத்தாரோடு சேரப் பெரியோர் அஞ்சுவர்; சிறியாரோ அவர்களைத் தம் உறவாகவே கருதி விடுவர்.", meaningEn: "Greatness fears the society of the base; it is only the low - minded who will regard them as friends." },
  { number: 452, line1: "நிலத்தியல்பால் நீர்திரிந் தற்றாகும் மாந்தர்க்கு", line2: "இனத்தியல்ப தாகும் அறிவு.", meaningTa: "சேர்ந்த நிலத்தின் இயல்பால் அந்த நீர் வேறுபட்டு அந் நிலத்தின் தன்மையுடையதாகும், அதுபோல் மக்களுடைய அறிவு இனத்தின்.", meaningEn: "As water changes (its nature), from the nature of the soil (in which it flows), so will the character of people resemble that of their associates." },
  { number: 453, line1: "மனத்தானாம் மாந்தர்க் குணர்ச்சி இனத்தானாம்", line2: "இன்னான் எனப்படுஞ் சொல்.", meaningTa: "மக்களுக்கு இயற்கையறிவு மனத்தால் ஏற்படும், இப்படிப் பட்டவன் என்று உலகத்தாரால் மதிக்கப்படும் சொல், சேர்ந்த இனத்தால்.", meaningEn: "The power of knowing is from the mind; (but) his character is from that of his associates." },
  { number: 454, line1: "மனத்து ளதுபோலக் காட்டி ஒருவற்கு", line2: "இனத்துள தாகும் அறிவு.", meaningTa: "ஒருவனுக்கு சிறப்பறிவு மனத்தில் உள்ளது போலக் காட்டி அவன் சேர்ந்த இனத்தில் உள்ளதாகும்.", meaningEn: "Wisdom appears to rest in the mind, but it really exists to a person in his companions." },
  { number: 455, line1: "மனந்தூய்மை செய்வினை தூய்மை இரண்டும்", line2: "இனந்தூய்மை தூவா வரும்.", meaningTa: "ஒருவன் கொண்டுள்ள தொடர்பு தூய்மையானதாக இருந்தால்தான் அவனுடைய மனமும் செயலும் தூய்மையானவையாக இருக்கும்.", meaningEn: "Chaste company is the staff on which come, these two things, that is, purity of mind and purity of conduct." },
  { number: 456, line1: "மனந்தூயார்க் கெச்சம்நன் றாகும் இனந்தூயார்க்கு", line2: "இல்லைநன் றாகா வினை.", meaningTa: "மனத்தின் தூய்மையால் புகழும், சேர்ந்த இனத்தின் தூய்மையால் நற்செயல்களும் விளையும்.", meaningEn: "To the pure-minded there will be a good posterity By those whose associates are pure, no deeds will be done that aren't good." },
  { number: 457, line1: "மனநலம் மன்னுயிர்க் காக்கம் இனநலம்", line2: "எல்லாப் புகழும் தரும்.", meaningTa: "மனதின் நன்மை உயிர்க்கு ஆக்கமாகும், இனத்தின் தன்மை எல்லாப் புகழையும் கொடுக்கும்.", meaningEn: "Goodness of mind will give wealth, and good society will bring with it all praise, to people." },
  { number: 458, line1: "மனநலம் நன்குடைய ராயினும் சான்றோர்க்கு", line2: "இனநலம் ஏமாப் புடைத்து.", meaningTa: "மனநலத்தைச் சிறப்பாகப் பெற்றவரே ஆயினும், நல்ல குணம் உடையவர்க்கு இனநலம் பாதுகாப்பாக இருக்கும்.", meaningEn: "Yet good companionship is confirmation strong." },
  { number: 459, line1: "மனநலத்தின் ஆகும் மறுமைமற் றஃதும்", line2: "இனநலத்தின் ஏமாப் புடைத்து.", meaningTa: "ஒருவனுக்கு மனநலத்தால் மறுமை இன்பம் கிடைக்கும். அதுவுங்கூட இனநலத்தால் வலிமை பெறும்.", meaningEn: "Future bliss is (the result) of goodness of mind; and even this acquires strength from the society of the good." },
  { number: 460, line1: "நல்லினத்தி னூங்குந் துணையில்லை தீயினத்தின்", line2: "அல்லற் படுப்பதூஉம் இல்.", meaningTa: "நல்ல இனத்தைவிடச் சிறந்ததாகிய துணையும் உலகத்தில் இல்லை, தீய இனத்தைவிடத் துன்பப்படுத்தும் பகையும் இல்லை.", meaningEn: "There is no greater help than the company of the good; there is no greater source of sorrow than the company of the mean." },
  { number: 461, line1: "அழிவதூஉம் ஆவதூஉம் ஆகி வழிபயக்கும்", line2: "ஊதியமும் சூழ்ந்து செயல்.", meaningTa: "அதனால் அழிவதையும் அழிந்த பின் ஆவதையும், பின்பு உண்டாகும் ஊதியத்தையும் ஆராய்ந்து செய்ய வேண்டும்.", meaningEn: "A person should reflect on what will be lost, what will be acquired and (from these) what will be his ultimate gain, and (then, let him) act." },
  { number: 462, line1: "தெரிந்த இனத்தொடு தேர்ந்தெண்ணிச் செய்வார்க்கு", line2: "அரும்பொருள் யாதொன்றும் இல்", meaningTa: "தெளிந்து தேர்ந்த நண்பர்களுடன், சேர்ந்து, ஆற்ற வேண்டிய செயலை ஆராய்ந்து, தாமும் நன்கு சிந்தித்துச் செய்தால் ஆகாதது.", meaningEn: "There is nothing too difficult to (be attained by) those who, before they act, reflect well themselves, and thoroughly consider (the matter) with." },
  { number: 463, line1: "ஆக்கம் கருதி முதலிழக்கும் செய்வினை", line2: "ஊக்கார் அறிவுடை யார்.", meaningTa: "வரும் லாபத்தை எண்ணி, இருக்கும் முதலையும் இழந்துவிடுவதற்கு ஏற்ற செயலை அறிவுள்ளவர் செய்யமாட்டார்.", meaningEn: "Wise people won't, in the hopes of profit, undertake works that will consume their principal." },
  { number: 464, line1: "தெளிவி லதனைத் தொடங்கார் இளிவென்னும்", line2: "ஏதப்பாடு அஞ்சு பவர்.", meaningTa: "இழிவு தருவதாகியக் குற்றத்திற்கு அஞ்சுகின்றவர் தெளிவு இல்லாத செயலைத் தொடங்கமாட்டார்.", meaningEn: "Those who fear reproach won't commence anything which has not been (thoroughly considered) and made clear to them." },
  { number: 465, line1: "வகையறச் சூழா தெழுதல் பகைவரைப்", line2: "பாத்திப் படுப்பதோ ராறு.", meaningTa: "முறையாகத் திட்டமிடாது ஒரு செயலைத் தொடங்குவது, வளரும் நிலத்திலே எதிர் அணியினரை நிலைபெறச் செய்யும் வழியாகும்.", meaningEn: "One way to promote the doing well of an someone who fights you, is (for a leader) to set out (to war) without having thoroughly weighed his ability." },
  { number: 466, line1: "செய்தக்க அல்ல செயக்கெடும் செய்தக்க", line2: "செய்யாமை யானுங் கெடும்.", meaningTa: "செய்யக்கூடாதவற்றைச் செய்தாலும் செய்ய வேண்டியவற்றைச் செய்யாமல் விட்டாலும் அழிவு வரும்.", meaningEn: "He will perish who does not what isn't fit to do; and he also will perish who does not do what it is fit to." },
  { number: 467, line1: "எண்ணித் துணிக கருமம் துணிந்தபின்", line2: "எண்ணுவம் என்பது இழுக்கு.", meaningTa: "நன்றாகச் சிந்தித்த பிறகே செயலில் இறங்க வேண்டும்; இறங்கிய பிறகு சிந்திக்கலாம் என்பது தவறு.", meaningEn: "Consider, and then undertake a matter; after having undertaken it, to say \"We will consider,\" is folly." },
  { number: 468, line1: "ஆற்றின் வருந்தா வருத்தம் பலர்நின்று", line2: "போற்றினும் பொத்துப் படும்.", meaningTa: "தக்கவழியில் செய்யப்படாத முயற்சி பலர் துணையாக நின்று காத்த போதிலும் குறையாகிவிடும்.", meaningEn: "The work, which isn't done by suitable methods, will fail though many stand to uphold it." },
  { number: 469, line1: "நன்றாற்ற லுள்ளுந் தவுறுண்டு அவரவர்", line2: "பண்பறிந் தாற்றாக் கடை.", meaningTa: "அவர் அவர் குணநலன்களை அறிந்து செயல் ஆற்றாவிட்டால் நல்லது செய்வதிலும் பிழை நேர்ந்து விடும்.", meaningEn: "There are failures even in acting well, when it is done without knowing the various dispositions of people." },
  { number: 470, line1: "எள்ளாத எண்ணிச் செயல்வேண்டும் தம்மோடு", line2: "கொள்ளாத கொள்ளாது உலகு.", meaningTa: "தன் தகுதிக்குப் பொருந்தாத வழிமுறைகளைச் செய்தால் மக்கள் அதை இகழ்வர்; அதனால் மக்கள் இகழாத வழிமுறைகளை எண்ணிச் செய்ய.", meaningEn: "A person should reflect, and do things which bring no reproach; the world won't approve, with him, of things which don't become of his position to." },
  { number: 471, line1: "வினைவலியும் தன்வலியும் மாற்றான் வலியும்", line2: "துணைவலியும் தூக்கிச் செயல்.", meaningTa: "செயலின் வலிமையும் தன் வலிமையும் பகைவனுடைய வலிமையும் ,இருவருக்கும் துணையானவரின் வலிமையும் ஆராய்ந்து செயல்பட வேண்டும்.", meaningEn: "Let (one) weigh well the strength of the deed (he purposes to do), his own strength, the strength of his someone who fights you, and the strength of." },
  { number: 472, line1: "ஒல்வ தறிவது அறிந்ததன் கண்தங்கிச்", line2: "செல்வார்க்குச் செல்லாதது இல்.", meaningTa: "ஒரு செயலில் ஈடுபடும்போது அச்செயலைப் பற்றிய அனைத்தையும் ஆராய்ந்தறிந்து முயற்சி மேற்கொண்டால் முடியாதது எதுவுமில்லை.", meaningEn: "There is nothing which may not be accomplished by those who, before they attack (an someone who fights you), make themselves acquainted with their." },
  { number: 473, line1: "உடைத்தம் வலியறியார் ஊக்கத்தின் ஊக்கி", line2: "இடைக்கண் முரிந்தார் பலர்.", meaningTa: "தம் ஆற்றலை அறியாமல், ஒரு வேகத்தில் செயலைச் செய்யத் தொடங்கித் தொடரமுடியாமல் இடையே விட்டுக் கெட்டவர் பலர்.", meaningEn: "There are many who, ignorant of their (want of) power (to meet it), have haughtily set out to war, and broken down in the midst of it." },
  { number: 474, line1: "அமைந்தாங் கொழுகான் அளவறியான் தன்னை", line2: "வியந்தான் விரைந்து கெடும்.", meaningTa: "பிறருடன் மனங்கலந்து பழகாமல், தன் சொந்த பலத்தையும் அறியாமல் தன்னைப் பெரிதாக எண்ணியவன் விரைவில் அழிவான்.", meaningEn: "He will quickly perish who, ignorant of his own resources flatters himself of his greatness, and does." },
  { number: 475, line1: "பீலிபெய் சாகாடும் அச்சிறும் அப்பண்டஞ்", line2: "சால மிகுத்துப் பெயின்.", meaningTa: "மயில்தோகைதானே என்று அதை அளவுக்கு அதிகமாக வண்டியில் ஏற்றினால் வண்டியின் அச்சு முறிந்துபோகும்.", meaningEn: "The axle tree of a bandy, loaded only with peacocks' feathers will break, if it be greatly overloaded." },
  { number: 476, line1: "நுனிக்கொம்பர் ஏறினார் அஃதிறந் தூக்கின்", line2: "உயிர்க்கிறுதி ஆகி விடும்.", meaningTa: "ஒரு மரக்கிளையின் நுனியில் ஏறிவிட்டவர், அந்த அளவையும் கடந்து மேலும் ஏற முயன்றால், அம் முயற்சியே அவர் உயிருக்கு.", meaningEn: "There will be an end to the life of God who, having climbed out to the end of a branch, ventures to go further." },
  { number: 477, line1: "ஆற்றின் அறவறிந்து ஈக அதுபொருள்", line2: "போற்றி வழங்கு நெறி.", meaningTa: "வருவாய் அளவை அறிந்து, அதனை வகுத்து வழங்குவதே பொருளைச் சீராகக் காத்து வாழும் வழியாகும்.", meaningEn: "A person should know the measure of his ability (to give), and let him give accordingly; such giving is the way to preserve his property." },
  { number: 478, line1: "ஆகாறு அளவிட்டி தாயினுங் கேடில்லை", line2: "போகாறு அகலாக் கடை.", meaningTa: "வருமானம் அளவில் சிறிது என்றாலும் செலவினம் பெரிதாகாதபோது கேடு இல்லை.", meaningEn: "Even though the income (of a leader) be small, it won't cause his (ruin), if his outgoings be not larger than his income." },
  { number: 479, line1: "அளவறிந்து வாழாதான் வாழ்க்கை உளபோல", line2: "இல்லாகித் தோன்றாக் கெடும்.", meaningTa: "பொருளின் அளவு அறிந்து வாழாதவனுடைய வாழ்க்கை இருப்பது போல் தோன்றி இல்லாமல் மறைந்து கெட்டு விடும்.", meaningEn: "The doing well of God who lives without knowing the measure (of his property), will perish, even while it seems to continue." },
  { number: 480, line1: "உளவரை தூக்காத ஒப்புர வாண்மை", line2: "வளவரை வல்லைக் கெடும்.", meaningTa: "பொருளாதார நிலையை எண்ணாது பிறர்க்குச் செய்யும் உபகாரத்தால் ஒருவனது செல்வத்தின் அளவு, விரைவில் கெடும்.", meaningEn: "The measure of his wealth will quickly perish, whose sharing weighs not the measure of his property." },
  { number: 481, line1: "பகல்வெல்லும் கூகையைக் காக்கை இகல்வெல்லும்", line2: "வேந்தர்க்கு வேண்டும் பொழுது.", meaningTa: "காக்கை தன்னைவிட வலிய கோட்டானைப் பகலில் வென்றுவிடும், அதுபோல் பகையை வெல்லக்கருதும் அரசர்க்கும் அதற்கு ஏற்ற காலம்.", meaningEn: "A crow will overcome an owl in the day time; so the leader who would conquer his someone who fights you must have (a suitable) time." },
  { number: 482, line1: "பருவத்தோடு ஒட்ட ஒழுகல் திருவினைத்", line2: "தீராமை ஆர்க்குங் கயிறு.", meaningTa: "காலந் தவறாமல் காரியம் ஆற்றுவது, ஓடும் செல்வத்தை ஓடாமல் கட்டும் கயிறு ஆகும்.", meaningEn: "Acting at the right season, is a cord that will immoveably bind success (to a leader)." },
  { number: 483, line1: "அருவினை யென்ப உளவோ கருவியான்", line2: "காலம் அற஧ந்து செயின்.", meaningTa: "கருவிகளுடன் ஏற்றக் காலத்தையும் அறிந்து செய்தால் அரிய செயல்கள் என்பது உண்டோ.", meaningEn: "Is there anything difficult for him to do, who acts, with (the right) instruments at the right time ?" },
  { number: 484, line1: "ஞாலம் கருதினுங் கைகூடுங் காலம்", line2: "கருதி இடத்தாற் செயின்.", meaningTa: "உரிய காலத்தையும் இடத்தையும் ஆய்ந்தறிந்து செயல்பட்டால் உலகமேகூடக் கைக்குள் வந்துவிடும்.", meaningEn: "Though (a person) should meditate (the conquest of) the world, he may accomplish it if he acts in the right time, and at the right place." },
  { number: 485, line1: "காலம் கருதி இருப்பர் கலங்காது", line2: "ஞாலம் கருது பவர்.", meaningTa: "பூவுலகம் முழுவதும் வேண்டும் என்போர், ஏற்ற காலத்தை எண்ணித் தவறாமல் காத்து இருப்பர்.", meaningEn: "They who thoughtfully consider and wait for the (right) time (for action), may successfully meditate (the conquest of) the world." },
  { number: 486, line1: "ஊக்க முடையான் ஒடுக்கம் பொருதகர்", line2: "தாக்கற்குப் பேருந் தகைத்து.", meaningTa: "கொடுமைகளைக் கண்டும்கூட உறுதி படைத்தவர்கள் அமைதியாக இருப்பது அச்சத்தினால் அல்ல; அது ஆட்டுக்கடா ஒன்று தனது பகையைத்.", meaningEn: "The self-restraint of the energetic (while waiting for a suitable opportunity), is like the drawing back of a fighting-ram in order to butt." },
  { number: 487, line1: "பொள்ளென ஆங்கே புறம்வேரார் காலம்பார்த்து", line2: "உள்வேர்ப்பர் ஒள்ளி யவர்.", meaningTa: "அறிவுடையவர் அப்பொழுதே உடனே புறத்தில் சினம் கொள்ளமாட்டார், காலம் பார்த்து அகத்தில் சினம் கொள்வார்.", meaningEn: "The wise won't immediately and hastily show out their anger; they will watch their time, and restrain it within." },
  { number: 488, line1: "செறுநரைக் காணின் சுமக்க இறுவரை", line2: "காணின் கிழக்காம் தலை.", meaningTa: "பகைவர்க்கு அழிவுகாலம் வரும்வரை அவரைக் கண்டால் பணிக; அழிவுகாலம் வரும்போது தடை இன்றி அழிந்தபோவர்.", meaningEn: "If one meets his someone who fights you, let him show him all respect, until the time for his destruction is come; when that is come, his head will." },
  { number: 489, line1: "எய்தற் கரியது இயைந்தக்கால் அந்நிலையே", line2: "செய்தற் கரிய செயல்.", meaningTa: "கிடைப்பதற்கு அரிய காலம் வாயக்கும்போது அதைப் பயன்படுத்திக் கொண்டு அப்போதே செயற்கரிய செய்து முடிக்க வேண்டும்.", meaningEn: "If a rare opportunity occurs, while it lasts, a person should do that which is rarely to be accomplished (but for such an opportunity)." },
  { number: 490, line1: "கொக்கொக்க கூம்பும் பருவத்து மற்றதன்", line2: "குத்தொக்க சீர்த்த இடத்து.", meaningTa: "காலம் கைகூடும் வரையில் கொக்குபோல் பொறுமையாகக் காத்திருக்கவேண்டும் காலம் வாய்ப்பாகக் கிடைத்ததும் அது குறி தவறாமல்.", meaningEn: "At the time when one should use self-control, let him restrain himself like a heron; and, let him like it, strike, when there is a favourable." },
  { number: 491, line1: "தொடங்கற்க எவ்வினையும் எள்ளற்க முற்றும்", line2: "இடங்கண்ட பின்அல் லது.", meaningTa: "முற்றுகை செய்வதற்கு ஏற்ற இடத்தைக் கண்டபின் அல்லாமல் எச் செயலையும் தொடங்கக்கூடாது, பகைவரை இகழவும் கூடாது.", meaningEn: "Let not (a leader) despise (an someone who fights you), nor undertake any thing (against him), until he has obtained (a suitable) place for besieging." },
  { number: 492, line1: "முரண்சேர்ந்த மொய்ம்பி னவர்க்கும் அரண்சேர்ந்தாம்", line2: "ஆக்கம் பலவுந் தரும்.", meaningTa: "மாறுபாடு பொருந்திய வலிமை உடையவர்க்கும் அரணோடு பொருந்தி ஏற்படுகின்ற வெற்றியானது பல வகைப் பயன்களையும் கொடுக்கும்.", meaningEn: "Even to those who are people of power and expedients, an attack in connection with a fortification will yield many advantages." },
  { number: 493, line1: "ஆற்றாரும் ஆற்றி அடுப இடனறிந்து", line2: "போற்றார்கண் போற்றிச் செயின்.", meaningTa: "பலம் இல்லாதவர் என்றாலும்கூட ஏற்ற இடத்தை அறிந்து, தம்மையும் காத்து, பகைவரோடு மோதுபவர், பலம் உள்ளவராய்ப் பகையை அழிப்பர்.", meaningEn: "Even the powerless will become powerful and conquer, if they select a proper field (of action), and guard themselves, while they make war on their." },
  { number: 494, line1: "எண்ணியார் எண்ணம் இழப்பர் இடனறிந்து", line2: "துன்னியார் துன்னிச் செயின்.", meaningTa: "ஏற்ற இடமறிந்து தொடர்ந்து தாக்கினால் பகைவர்கள், வெற்றி என்பதை நினைத்துக்கூடப் பார்க்க மாட்டார்கள்.", meaningEn: "If they who draw near (to fight) choose a suitable place to approach (their someone who fights you), the latter, will have to relinquish the thought." },
  { number: 495, line1: "நெடும்புனலுள் வெல்லும் முதலை அடும்புனலின்", line2: "நீங்கின் அதனைப் பிற.", meaningTa: "முதலை நீரில் வெற்றி பெறும்; நீரைவிட்டு வெளியே வந்தால் அதனை மற்றவை வெல்லும்.", meaningEn: "In deep water, a crocodile will conquer (all other animals); but if it leave the water, other animals will conquer it." },
  { number: 496, line1: "கடலோடா கால்வல் நெடுந்தேர் கடலோடும்", line2: "நாவாயும் ஓடா நிலத்து.", meaningTa: "வலிய சக்கரங்களை உடைய நெடிய தேர்கள் கடலில் ஒடமாட்டா; கடலில் ஓடும் கப்பல்கள் நிலத்தில் ஓடமாட்டா.", meaningEn: "Wide chariots, with mighty wheels, won't run on the ocean; neither will ships that the traverse ocean, move on the earth." },
  { number: 497, line1: "அஞ்சாமை அல்லால் துணைவேண்டா எஞ்சாமை", line2: "எண்ணி இடத்தால் செயின்.", meaningTa: "குறைவில்லாமல் எண்ணித் தக்க இடத்தில் பொருந்திச் செய்தால், அஞ்சாமை அல்லாமல் வேறு துணை வேண்டியதில்லை.", meaningEn: "You will need no other aid than fearlessness, if you thoroughly reflect (on what you are to do), and select (a suitable) place for your operations." },
  { number: 498, line1: "சிறுபடையான் செல்லிடம் சேரின் உறுபடையான்", line2: "ஊக்கம் அழிந்து விடும்.", meaningTa: "சிறிய படை என்றாலும் அது தனக்குரிய இடத்தில் இருந்து போரிட்டால் பெரிய படையை வென்று விட முடியும்.", meaningEn: "The power of one who has a large army will perish, if he goes into ground where only a small army can act." },
  { number: 499, line1: "சிறைநலனும் சீரும் இலரெனினும் மாந்தர்", line2: "உறைநிலத்தோடு ஒட்டல் அரிது.", meaningTa: "அரணாகிய நன்மையும் மற்றச் சிறப்பும் இல்லாதவராயினும் பகைவர் வாழ்கின்ற இடத்திற்குச் சென்று அவரைத் தாக்குதல் அரிது.", meaningEn: "It is a hazardous thing to attack people in their own country, although they may neither have power nor a good fortress." },
  { number: 500, line1: "காலாழ் களரில் நரியடும் கண்ணஞ்சா", line2: "வேலாள் முகத்த களிறு.", meaningTa: "வேல் ஏந்திய வீரரைக் கோர்த்தெடுத்த கொம்பு உடைய யானையையும், கால் ஆழும் சேற்று நில்த்தில் அகப்பட்ட போது நரிகள்.", meaningEn: "A fox can kill a fearless, warrior-faced elephant, if it go into mud in which its legs sink down." },
  { number: 501, line1: "அறம்பொருள் இன்பம் உயிரச்சம் நான்கின்", line2: "திறந்தெரிந்து தேறப் படும்.", meaningTa: "அறம், பொருள், இன்பம், உயிர்காக அஞ்சும் அச்சம் ஆகிய நான்கு வகையாலும் ஆராயப்பட்ட பிறகே ஒருவன் தெளியப்படுவான்.", meaningEn: "Let (a helpers) be chosen, after he has been tried by means of these four things, that is,-his goodness, (caring of) money, (caring of) wants only." },
  { number: 502, line1: "குடிப்பிறந்து குற்றத்தின் நீங்கி வடுப்பரியும்", line2: "நாணுடையான் சுட்டே தெளிவு.", meaningTa: "நல்லகுடியில் பிறந்து குற்றங்களிலிருந்து நீங்கிப் பழியாச் செயல்களைச் செய்ய அஞ்சுகின்ற நாணம் உடையவனையே நம்பித் தெளிய.", meaningEn: "Choice should (fall) on him, who is of good family, who is free from faults, and who has the modesty which fears the wounds (of sin)." },
  { number: 503, line1: "அரியகற்று ஆசற்றார் கண்ணும் தெரியுங்கால்", line2: "இன்மை அரிதே வெளிறு.", meaningTa: "அரிய நூல்களைத் கற்றுத் தேர்ந்து குற்றம் அற்றவரிடத்திலும் ஆராய்ந்துப் பார்க்குமிடத்தில் அறியாமை இல்லாதிருப்பது.", meaningEn: "When even people, who have studied the most difficult works, and who are free from faults, are (carefully) examined, it is a rare thing to find them." },
  { number: 504, line1: "குணம்நாடிக் குற்றமும் நாடி அவற்றுள்", line2: "மிகைநாடி மிக்க கொளல்.", meaningTa: "ஒருவரின் குணங்களையும், அவரது குறைகளையும் ஆராய்ந்து பார்த்து அவற்றில் மிகுதியாக இருப்பவை எவை என்பதைத் தெரிந்து அதன்.", meaningEn: "Let (a leader) consider (a person's) good qualities, as well as his faults, and then judge (of his character) by that which prevails." },
  { number: 505, line1: "பெருமைக்கும் ஏனைச் சிறுமைக்கும் தத்தம்", line2: "கருமமே கட்டளைக் கல்.", meaningTa: "பெருமைக்கும் சிறுமைக்கும் தேர்ந்தறியும் உரைக் கல்லாக இருப்பவை அவரவருடைய செயல்களே ஆகும்.", meaningEn: "A person's deeds are the touchstone of his greatness and littleness." },
  { number: 506, line1: "அற்றாரைத் தேறுதல் ஓம்புக மற்றவர்", line2: "பற்றிலர் நாணார் பழி.", meaningTa: "நெறியற்றவர்களை ஒரு பணிக்குத் தேர்வு செய்வது கூடாது அவர்கள் உலகத்தைப் பற்றிக் கவலைப்படாமல், பழிக்கு நாணாமல்.", meaningEn: "Let (a leader) avoid choosing people who have no relations; such people have no attachment, and thereforehave no fear of crime." },
  { number: 507, line1: "காதன்மை கந்தா அறிவறியார்த் தேறுதல்", line2: "பேதைமை எல்லாந் தரும்.", meaningTa: "அறியவேண்டியவற்றை அறியாதிருப்பவரை அன்புடைமை காரணமாக நம்பித்தெளிதல், எல்லா அறியாமையும் கெடும்.", meaningEn: "Yields all his being up to folly's blind control." },
  { number: 508, line1: "தேரான் பிறனைத் தெளிந்தான் வழிமுறை", line2: "தீரா இடும்பை தரும்.", meaningTa: "மற்றவனை ஒன்றும் ஆராயாமல் தெளிந்தால் அஃது அவனுடைய வழிமுறையில் தோன்றினவருக்கும் துன்பத்தைக் கொடுக்கும்.", meaningEn: "Sorrow that won't leave even his posterity will come upon him chooses a stranger whose character he has not known." },
  { number: 509, line1: "தேறற்க யாரையும் தேராது தேர்ந்தபின்", line2: "தேறுக தேறும் பொருள்.", meaningTa: "எவரையும் ஆராயாமல் பதவியில் அமர்த்த வேண்டா; ஆராய்ந்த பிறகு தேர்ந்தவற்றின்மேல் சந்தேகம் கொள்ளவும் வேண்டா.", meaningEn: "Let (a leader) choose no one without previous consideration; after he has made his choice, let him unhesitatingly select for each such duties as are." },
  { number: 510, line1: "தேரான் தெளிவும் தெளிந்தான்கண் ஐயுறவும்", line2: "தீரா இடும்பை தரும்.", meaningTa: "ஒருவனை ஆராயாமல் பதவியில் அமர்த்துவதும், அமர்த்தியபின் அவன்மீதே சந்தேகம் கொள்வதும் நீங்காத துன்பத்தைத் தரும்.", meaningEn: "To make choice of one who has not been examined, and to entertain doubts respecting one who has been chosen, will produce irremediable sorrow." },
  { number: 511, line1: "நன்மையும் தீமையும் நாடி நலம்புரிந்த", line2: "தன்மையான் ஆளப் படும்.", meaningTa: "நன்மையும் தீமையுமாகிய இரண்டையும் ஆராய்ந்து நன்மை தருகின்றவற்றையே விரும்புகின்ற இயல்புடையவன் ஆளப்படுவான்.", meaningEn: "He should be employed (by a leader), whose nature leads him to choose the good, after having weighed both the evil and the good in any undertaleader." },
  { number: 512, line1: "வாரி பெருக்கி வளம்படுத்து உற்றவை", line2: "ஆராய்வான் செய்க வினை.", meaningTa: "வருமானம் வரக்கூடிய வழிகளை விரிவாக்கி, வளங்களையும் பெருக்கி, இடையூறுகளையும் ஆராய்ந்து நீக்கிட வல்லவனே செயலாற்றும்.", meaningEn: "Let him do (the leader's) work who can enlarge the sources (of revenue), increase wealth and considerately prevent the accidents (which would destroy." },
  { number: 513, line1: "அன்பறிவு தேற்றம் அவாவின்மை இந்நான்கும்", line2: "நன்குடையான் கட்டே தெளிவு.", meaningTa: "அன்பு, அறிவு, ஐயமில்லாமல் தெளியும் ஆற்றல், அவா இல்லாமை ஆகிய இந் நான்கு பண்புகளையும் நிலையாக உடையவனைத் தெளியலாம்.", meaningEn: "Let the choice (of a leader) fall upon God who largely possesses these four things, caring, knowledge, a clear mind and freedom from wants what." },
  { number: 514, line1: "எனைவகையான் தேறியக் கண்ணும் வினைவகையான்", line2: "வேறாகும் மாந்தர் பலர்.", meaningTa: "எவ்வகையால் ஆராய்ந்து தெளிந்த பிறகும் அச் செயல்வகையால் வேறுபடும் மக்கள் உலகத்தில் பலர் உண்டு.", meaningEn: "Even when (a leader) has tried them in every possible way, there are many people who change, from the nature of the works (in which they may be." },
  { number: 515, line1: "அறிந்தாற்றிச் செய்கிற்பாற்கு அல்லால் வினைதான்", line2: "சிறந்தானென்று ஏவற்பாற் றன்று.", meaningTa: "அறிந்து இடையூறுகளைத்தாங்கிச் செய்து முடிக்க வல்லவனை அல்லாமல், மற்றவனைச் சிறந்தவன் என்றுக் கருதி ஒருச் செயலைச்.", meaningEn: "Work can only be accomplished by a person of wisdom and patient endurance; it isn't of a nature to be given to one from mere personal attachment." },
  { number: 516, line1: "செய்வானை நாடி வினைநாடிக் காலத்தோடு", line2: "எய்த உணர்ந்து செயல்.", meaningTa: "செயலாற்ற வல்லவனைத் தேர்ந்து, செய்யப்பட வேண்டிய செயலையும் ஆராய்ந்த, காலமுணர்ந்து அதனைச் செயல்படுத்தவேண்டும்.", meaningEn: "Let (a leader) act, after having considered the agent (whom he is to employ), the deed (he wants to do), and the time which is suitable to it." },
  { number: 517, line1: "இதனை இதனால் இவன்முடிக்கும் என்றாய்ந்து", line2: "அதனை அவன்கண் விடல்.", meaningTa: "இந்தச் செயலை இக்கருவியால் இன்னவன் செய்துமுடிப்பான் என்று ஆராய்ந்த பிறகே அத் தொழிலை அவனிடம் ஒப்படைக்க வேண்டும்.", meaningEn: "After having considered, \"this man can accomplish this, by these means\", let (the leader) leave with him the discharge of that duty." },
  { number: 518, line1: "வினைக்குரிமை நாடிய பின்றை அவனை", line2: "அதற்குரிய னாகச் செயல்.", meaningTa: "ஒருவனை ஒரு பதவிக்கு உரியவனாக நியமித்த பிறகு, அப்பதவிக்கு உரிய செயல்களை அவனே செய்யுமாறு விட்டுவிடுக.", meaningEn: "Having considered what work a person is fit for, let (the leader) employ him in that work." },
  { number: 519, line1: "வினைக்கண் வினையுடையான் கேண்மைவே றாக", line2: "நினைப்பானை நீங்கும் திரு.", meaningTa: "மேற்க்கொண்ட தொழிலில் எப்போதும் முயற்சி உடையவனின் உறவைத் தவறாக நினைக்கும் தலைவனை விட்டுச் செல்வம் நீங்கும்.", meaningEn: "Doing well will leave (the leader) who doubts the friendship of the man who steadily labours in the discharge of his duties." },
  { number: 520, line1: "நாடோறும் நாடுக மன்னன் வினைசெய்வான்", line2: "கோடாமை கோடா துலகு.", meaningTa: "தொழில் செய்கின்றவன் கோணாதிருக்கும் வரையில் உலகம் கெடாது, ஆகையால் மன்னன் நாள்தோறும் அவனுடைய நிலைமையை ஆராய வேண்டும்.", meaningEn: "Let a leader daily examine the conduct of his servants; if they don't act crookedly, the world won't act crookedly." },
  { number: 521, line1: "பற்றற்ற கண்ணும் பழைமைபா ராட்டுதல்", line2: "சுற்றத்தார் கண்ணே உள.", meaningTa: "ஒருவருக்கு வறுமை வந்த நேரத்திலும் அவரிடம் பழைய உறவைப் பாராட்டும் பண்பு உடையவர்களே சுற்றத்தார் ஆவார்கள்.", meaningEn: "Even when (a person's) property is all gone, relatives will act towards him with their accustomed (kindness)." },
  { number: 522, line1: "விருப்பறாச் சுற்றம் இயையின் அருப்பறா", line2: "ஆக்கம் பலவும் தரும்.", meaningTa: "ஒருவனுக்கு அன்பு நீங்காத சுற்றம் மட்டும் அமைந்து விடுமானால், அவனுக்கு அது வளர்ச்சி குறையாத செல்வங்கள் பலவற்றையும்.", meaningEn: "If (a person's) relatives remain attached to him with unchanging caring, it will be a source of everincreasing wealth." },
  { number: 523, line1: "அளவளா வில்லாதான் வாழ்க்கை குளவளாக்", line2: "கோடின்றி நீர்நிறைந் தற்று.", meaningTa: "சுற்றத்தாரோடு மனந்திறந்து உறவாடாதவன் வாழ்க்கை, கரை இல்லாத குளப்பரப்பில் நீர் நிறைந்திருப்பது போன்றது.", meaningEn: "The wealth of one who does not mingle freely with his relatives, will be like the filling of water in a." },
  { number: 524, line1: "சுற்றத்தால் சுற்றப் படஒழுகல் செல்வந்தான்", line2: "பெற்றத்தால் பெற்ற பயன்.", meaningTa: "தக்கவழியில் செய்யப்படாத முயற்சி பலர் துணையாக நின்று காத்த போதிலும் குறையாகிவிடும்.", meaningEn: "To live surrounded by relatives, is the advantage to be from the acquisition of wealth." },
  { number: 525, line1: "கொடுத்தலும் இன்சொலும் ஆற்றின் அடுக்கிய", line2: "சுற்றத்தால் சுற்றப் படும்.", meaningTa: "வள்ளல் தன்மையும், வாஞ்சைமிகு சொல்லும் உடையவனை அடுத்தடுத்துச் சுற்றத்தார் சூழ்ந்து கொண்டேயிருப்பார்கள்.", meaningEn: "He will be surrounded by numerous relatives who manifests generosity and affability." },
  { number: 526, line1: "பெருங்கொடையான் பேணான் வெகுளி அவனின்", line2: "மருங்குடையார் மாநிலத்து இல்.", meaningTa: "பெரிய கொடையாளியாகவும் சினமற்றவனாகவும் ஒருவன் இருந்தால் அவனைப் போல் சுற்றத்தாரை உடையவர் உலகத்தில் யாரும் இல்லை.", meaningEn: "No one, in all the world, will have so many relatives (about him), as he who makes large gift, and does not give way to anger." },
  { number: 527, line1: "காக்கை கரவா கரைந்துண்ணும் ஆக்கமும்", line2: "அன்னநீ ரார்க்கே உள.", meaningTa: "காக்கை மறைத்து வைக்காமல் சுற்றத்தைக் கூவி அழைத்து உண்ணும். ஆக்கமும் அத்தகைய இயல்பு உடையவர்க்கே உண்டு.", meaningEn: "The crows don't conceal (their prey), but will call out for others (to share with them) while they eat it; wealth will be with those who show a." },
  { number: 528, line1: "பொதுநோக்கான் வேந்தன் வரிசையா நோக்கின்", line2: "அதுநோக்கி வாழ்வார் பலர்.", meaningTa: "சுற்றத்தார் எல்லாரையும் ஒன்று போலவே எண்ணாமல், அவரவர் தகுதிக்கு ஏற்ப ஆட்சியாளன் உபசரிப்பான் என்றால், அச்சிறப்பை எண்ணி.", meaningEn: "Many relatives will live near a leader, when they observe that he does not look on all alike, but that he looks on each man according to his merit." },
  { number: 529, line1: "தமராகிக் தற்றுறந்தார் சுற்றம் அமராமைக்", line2: "காரணம் இன்றி வரும்.", meaningTa: "முன்பு தன் அரசியல் இயக்கத்தில் இருந்து, ஆட்சியாளனிடம் உள்ள ஒழுக்கமின்மை காரணமாகப் பிரிந்து போனவர்கள், ஆட்சியாளனிடம்.", meaningEn: "Those who have been friends and have afterwards forsaken him, will return and join themselves (to him), when the cause of disagreement isn't to be." },
  { number: 530, line1: "உழைப்பிரிந்து காரணத்தின் வந்தானை வேந்தன்", line2: "இழைத் திருந்து எண்ணிக் கொளல்.", meaningTa: "ஒரு காரணமும் இல்லாமல், தானே இயக்கத்தை விட்டுப் பிரிந்து போன ஒருவன் ஏதோ ஒரு காரணத்தோடு திரும்ப வந்தாள் என்றால்,.", meaningEn: "When one may have left him, and for some cause has returned to him, let the leader fulfil the object (for which he has come back) and thoughtfully." },
  { number: 531, line1: "இறந்த வெகுளியின் தீதே சிறந்த", line2: "உவகை மகிழ்ச்சியிற் சோர்வு.", meaningTa: "அகமகிழ்ச்சியினால் ஏற்படும் மறதி, அடங்காத சினத்தினால் ஏற்படும் விளைவை விடத் தீமையானது.", meaningEn: "More evil than excessive anger, is forgetfulness which springs from the intoxication of great joy." },
  { number: 532, line1: "பொச்சாப்புக் கொல்லும் புகழை அறிவினை", line2: "நிச்ச நிரப்புக் கொன் றாங்கு.", meaningTa: "நித்த வறுமை அறிவைக் கொன்றுவிடுவது போல, மறதி புகழைக் கெடுத்துவிடும்.", meaningEn: "Forgetfulness will destroy a good name, even as constant poverty destroys knowledge." },
  { number: 533, line1: "பொச்சாப்பார்க் கில்லை புகழ்மை அதுஉலகத்து", line2: "எப்பால்நூ லோர்க்கும் துணிவு.", meaningTa: "மறதி உடையவர்களுக்கு, மங்காப் புகழ் இல்லை என்பதே அனைத்தும் கற்றுணர்ந்த அறிஞர்களின் முடிவான கருத்தாகும்.", meaningEn: "Thoughtlessness will never acquire a good name; and this tenet is upheld by all wise books in the world." },
  { number: 534, line1: "அச்ச முடையார்க்கு அரணில்லை ஆங்கில்லை", line2: "பொச்சாப் புடையார்க்கு நன்கு.", meaningTa: "மனத்துள் பயம் உள்ளவர்க்கு எத்தகைய பாதுகாப்பாலும் பயன் இல்லை. அதுபோலவே மறதி உடையவர்க்கும் பாதுகாப்பால் பயன் இல்லை.", meaningEn: "Just as the coward has no defence (by whatever fortifications ha may be surrounded), so the thoughtless has no good (whatever advantages he may." },
  { number: 535, line1: "முன்னுறக் காவாது இழுக்கியான் தன்பிழை", line2: "பின்னூறு இரங்கி விடும்.", meaningTa: "துன்பங்கள் வரும் முன்பே அவற்றைத் தடுக்காமல் மறந்திருந்தவன், பின் அவை வந்தபோது தடுக்க முடியாமல் தன் பிழையை எண்ணி.", meaningEn: "The thoughtless man, who provides not against the calamities that may happen, will afterwards repent for his fault." },
  { number: 536, line1: "இழுக்காமை யார்மாட்டும் என்றும் வழுக்காமை", line2: "வாயின் அதுவொப்பது இல்.", meaningTa: "எவரிடத்திலேனும் எப்போதும் விடாமல் மறதி இல்லாத குணம் மட்டும் இருக்கும் என்றால், அதைப் போன்ற நன்மை வேறு இல்லை.", meaningEn: "There is nothing comparable with the possession of unfailing thoughtfulness at all times; and towards all persons." },
  { number: 537, line1: "அரியஎன்று ஆகாத இல்லைபொச் சாவாக்", line2: "கருவியால் போற்றிச் செயின்.", meaningTa: "மறதியில்லாமலும், அக்கறையுடனும் செயல்பட்டால், முடியாதது என்று எதுவுமே இல்லை.", meaningEn: "There is nothing too difficult to be accomplished, if a person set about it carefully, with unflinching endeavour." },
  { number: 538, line1: "புகழ்ந்தவை போற்றிச் செயல்வேண்டும் செய்யாது", line2: "இகழ்ந்தார்க்கு எழுமையும் இல்.", meaningTa: "சான்றோர் புகழ்ந்து சொல்லியச் செயல்களைப் போற்றிச் செய்யவேண்டும், அவ்வாறு செய்யாமல் மறந்து சோர்ந்தவர்க்கு ஏழுப்.", meaningEn: "Let (a person) observe and do these things which have been praised (by the wise); if he neglects and fails to perform them, for him there will be no." },
  { number: 539, line1: "இகழ்ச்சியின் கெட்டாரை உள்ளுக தாந்தம்", line2: "மகிழ்ச்சியின் மைந்துறும் போழ்து.", meaningTa: "மமதையால் பூரித்துப்போய்க் கடமைகளை மறந்திருப்பவர்கள், அப்படி மறந்துபோய் அழிந்து போனவர்களை நினைத்துப் பார்த்துத்.", meaningEn: "Let (a leader) think of those who have been ruined by neglect, when his mind is elated with joy." },
  { number: 540, line1: "உள்ளியது எய்தல் எளிதுமன் மற்றுந்தான்", line2: "உள்ளியது உள்ளப் பெறின்.", meaningTa: "ஒருவன் எண்ணியதை விடாமல் எண்ணி இருக்கப் பெற்றால், அவன் கருதியதை அடைதல் எளிதாகும்.", meaningEn: "It is easy for (one) to obtain whatever he may think of, if he can again think of it." },
  { number: 541, line1: "ஓர்ந்துகண் ணோடாது இறைபுரிந்து யார்மாட்டும்", line2: "தேர்ந்துசெய் வஃதே முறை.", meaningTa: "குற்றம் இன்னதென்று ஆராய்ந்து எந்தப் பக்கமும் சாயாமல் நடுவுநிலைமை தவறாமல் வழங்கப்படுவதே நீதியாகும்.", meaningEn: "To examine into (the crimes which may be committed), to show no favour (to any one), to wants to act with being fair towards all, and to inflict." },
  { number: 542, line1: "வானோக்கி வாழும் உலகெல்லாம் மன்னவன்", line2: "கோல் நோக்கி வாழுங் குடி.", meaningTa: "உயிர்கள் எல்லாம் மழையை எதிர்பார்த்தே வாழும்; குடிமக்களோ ஆளுவோரின் நேர்மையான ஆட்சியை எதிர்பார்த்தே வாழ்வர்.", meaningEn: "When there is rain, the living creation thrives; and so when the leader rules justly, his subjects thrive." },
  { number: 543, line1: "அந்தணர் நூற்கும் அறத்திற்கும் ஆதியாய்", line2: "நின்றது மன்னவன் கோல்.", meaningTa: "ஓர் அரசின் செங்கோன்மைதான் அறவோர் நூல்களுக்கும் அறவழிச் செயல்களுக்கும் அடிப்படையாக அமையும்.", meaningEn: "The sceptre of the leader is the firm support of the Vedas of the Brahmin, and of all goodnesss therein described." },
  { number: 544, line1: "குடிதழீஇக் கோலோச்சும் மாநில மன்னன்", line2: "அடிதழீஇ நிற்கும் உலகு.", meaningTa: "குடிமக்களை அரவணைத்து ஆட்சி நடத்தும் நல்லரசின் அடிச்சுவட்டை நானிலமே போற்றி நிற்கும்.", meaningEn: "The world will constantly warm hug the feet of the great leader who rules over his subjects with caring." },
  { number: 545, line1: "இயல்புளிக் கோலோச்சும் மன்னவன் நாட்ட", line2: "பெயலும் விளையுளும் தொக்கு.", meaningTa: "நீதி முறைப்படி செங்கோல் செலுத்தும் அரசனுடைய நாட்டில் பருவ மழையும் நிறைந்த விளைவும் ஒருசேர ஏற்படுவனவாகும்.", meaningEn: "Rain and plentiful crops will ever dwell together in the country of the leader who sways his sceptre with justice." },
  { number: 546, line1: "வேலன்று வென்றி தருவது மன்னவன்", line2: "கோலதூஉங் கோடா தெனின்.", meaningTa: "ஓர் அரசுக்கு வெற்றியைத் தருவது பகைவரை வீழ்த்தும் வேலல்ல; குடிமக்களை வாழவைக்கும் வளையாத செங்கோல்தான்.", meaningEn: "It isn't the javelin that gives victory, but the leader's sceptre, if it do no injustice." },
  { number: 547, line1: "இறைகாக்கும் வையகம் எல்லாம் அவனை", line2: "முறைகாக்கும் முட்டாச் செயின்.", meaningTa: "நீதி வழுவாமல் ஓர் அரசு நடைபெற்றால் அந்த அரசை அந்த நீதியே காப்பாற்றும்.", meaningEn: "The leader defends the whole world; and justice, when adhelpersed without defect, defends the leader." },
  { number: 548, line1: "எண்பதத்தான் ஓரா முறைசெய்யா மன்னவன்", line2: "தண்பதத்தான் தானே கெடும்.", meaningTa: "எளிய செவ்வி உடையவனாய் ஆராய்ந்து நீதி முறை செய்யாத அரசன், தாழ்ந்த நிலையில் நின்று தானே கெடுவான்.", meaningEn: "The leader who gives not facile audience (to those who approach him), and who does not examine and pass judgment (on their complaints), will perish." },
  { number: 549, line1: "குடிபுறங் காத்தோம்பிக் குற்றம் கடிதல்", line2: "வடுவன்று வேந்தன் தொழில்.", meaningTa: "குடிமக்களைப் பாதுகாத்துத் துணை நிற்பதும், குற்றம் செய்தவர்கள் யாராயினும் தனக்கு இழுக்கு வரும் என்று கருதாமல்.", meaningEn: "In guarding his subjects (against injury from others), and in preserving them himself; to punish crime." },
  { number: 550, line1: "கொலையிற் கொடியாரை வேந்தொறுத்தல் பைங்கூழ்", line2: "களைகட் டதனொடு நேர்.", meaningTa: "கொடியவர்களுக்கு மரண தண்டனை கொடுத்துத் தக்கவரைக் காப்பது, உழவன் களையைக் களைந்து பயிரைக் காப்பதற்குச் சமம்.", meaningEn: "For a leader to punish criminals with death, is like pulling up the weeds in the green corn." },
  { number: 551, line1: "கொலைமேற்கொண் டாரிற் கொடிதே அலைமேற்கொண்டு", line2: "அல்லவை செய்தொழுகும் வேந்து.", meaningTa: "அறவழி மீறிக் குடிமக்களைத் துன்புறுத்தும் அரசு, கொலையைத் தொழிலாகக் கொண்டவரைவிடக் கொடியதாகும்.", meaningEn: "The leader who gives himself up to oppression and acts unjustly (towards his subjects) is more cruel than the man who leads the life of a murderer." },
  { number: 552, line1: "வேலொடு நின்றான் இடுவென் றதுபோலும்", line2: "கோலொடு நின்றான் இரவு.", meaningTa: "ஆட்சிக்குறிய கோலை ஏந்தி நின்ற அரசன் குடிகளைப் பொருள் கேட்டல் , போகும் வழியில் கள்வன் கொடு என்று கேட்பதைப் போன்றது.", meaningEn: "The request (for money) of God who holds the sceptre is like the word of a highway robber who stands with a weapon in hand and says \"give up your." },
  { number: 553, line1: "நாடொறும் நாடி முறைசெய்யா மன்னவன்", line2: "நாடொறும் நாடு கெடும்.", meaningTa: "நாள் தோறும் தன் ஆட்சியில் நன்மை தீமைகளை ஆராய்ந்து முறைசெய்யாத அரசன், நாள் தோறும் தன் நாட்டை இழந்து வருவான்.", meaningEn: "The country of the leader who does not daily examine into the wrongs done and distribute justice, will daily fall to ruin." },
  { number: 554, line1: "கூழுங் குடியும் ஒருங்கிழக்கும் கோல்கோடிச்", line2: "சூழாது செய்யும் அரசு.", meaningTa: "கொடுங்கோலனாகி ஆராயாமல் எதையும் செய்யும் அரசன், பொருளையும் குடிகளையும் ஒரு சேர இழந்து விடுவான்.", meaningEn: "The leader, who, without reflecting (on its evil consequences), perverts justice, will lose at once both his wealth and his subjects." },
  { number: 555, line1: "அல்லற்பட்டு ஆற்றாது அழுதகண் ணீரன்றே", line2: "செல்வத்தைத் தேய்க்கும் படை", meaningTa: "கொடுமை பொறுக்க முடியாமல் மக்கள் சிந்தும் கண்ணீர் ஆட்சியை அழிக்கும் படைக்கருவியாகும்.", meaningEn: "Won't the tears, shed by a people who can't endure the oppression which they suffer (from their leader), become a saw to waste away his wealth ?" },
  { number: 556, line1: "மன்னர்க்கு மன்னுதல் செங்கோன்மை அஃதின்றேல்", line2: "மன்னாவாம் மன்னர்க் கொளி.", meaningTa: "அரசர்க்கு புகழ் நிலைபெறக் காரணம் செங்கோல் முறையாகும், அஃது இல்லையானால் அரசர்க்கு புகழ் நிலைபெறாமல் போகும்.", meaningEn: "Righteous government gives permanence to (the a good name of) leaders; without that their a good name will have no endurance." },
  { number: 557, line1: "துளியின்மை ஞாலத்திற்கு எற்றற்றே வேந்தன்", line2: "அளியின்மை வாழும் உயிர்க்கு.", meaningTa: "மழையில்லாவிடில் துன்பமுறும் உலகத்தைப் போல் அருள் இல்லாத அரசினால் குடிமக்கள் தொல்லைப்படுவார்கள்.", meaningEn: "As is the world without rain, so live a people whose leader is without kindness." },
  { number: 558, line1: "இன்மையின் இன்னாது உடைமை முறைசெய்யா", line2: "மன்னவன் கோற்கீழ்ப் படின்.", meaningTa: "தவறாக ஆள்பவரின் ஆட்சிக்குக் கீழ் ஏழையாய் வாழ்வதைக் காட்டிலும் பணக்காரனாய் வாழ்வது துன்பம்.", meaningEn: "Property gives more sorrow than poverty, to those who live under the sceptre of a leader without justice." },
  { number: 559, line1: "முறைகோடி மன்னவன் செய்யின் உறைகோடி", line2: "ஒல்லாது வானம் பெயல்.", meaningTa: "ஆட்சியாளர் நீதி தவறினால் நாட்டில் பருவகாலமும் தவறி மழையும் பெய்யாது போகும்.", meaningEn: "If the leader acts contrary to justice, rain will become unseasonable, and the heavens will withhold their showers." },
  { number: 560, line1: "ஆபயன் குன்றும் அறுதொழிலோர் நூல்மறப்பர்", line2: "காவலன் காவான் எனின்.", meaningTa: "காவல் செய்யவேண்டிய ஆட்சியாளர் மக்களைக் காவாத, போனால், அறனற்ற அவர் நாட்டில் பால் வளம் குறையும். ஞானியர் நூல்களை.", meaningEn: "If the guardian (of the country) neglects to guard it, the produce of the cows will fail, and the people of six duties that is, the Brahmins will." },
  { number: 561, line1: "தக்காங்கு நாடித் தலைச்செல்லா வண்ணத்தால்", line2: "ஒத்தாங்கு ஒறுப்பது வேந்து.", meaningTa: "தவறு செய்வோரைக் கண்டு, நடுநிலையில் நின்று ஆய்ந்து, அத்தவற்றை அவர் திரும்பவும் செய்யாமல் இருக்கத் தவற்றுக்கு ஏற்பத்.", meaningEn: "He is a leader who having equitably examined (any injustice which has been brought to his notice), suitably punishes it, so that it may not be again." },
  { number: 562, line1: "கடிதோச்சி மெல்ல எறிக நெடிதாக்கம்", line2: "நீங்காமை வேண்டு பவர்.", meaningTa: "நெடுங்காலம் ஆட்சி செய்ய விரும்புபவர் தண்டிக்கும்போது கடுமையாகத் தண்டிப்பவர்போல தொடங்கி வரம்பு கடவாமல் செய்க.", meaningEn: "Let the leader, who wants that his doing well may long remain, commence his preliminary enquires with strictness, and then punish with mildness." },
  { number: 563, line1: "வெருவந்த செய்தொழுகும் வெங்கோல னாயின்", line2: "ஒருவந்தம் ஒல்லைக் கெடும்.", meaningTa: "குடிமக்கள் அஞ்சும்படியாகச் செயல் செய்யும் கொடிய ஆட்சி விரைந்து அழிவது உறுதி.", meaningEn: "The cruel-sceptred leader, who acts so as to put his subjects in fear, will certainly and quickly come to ruin." },
  { number: 564, line1: "இறைகடியன் என்றுரைக்கும் இன்னாச்சொல் வேந்தன்", line2: "உறைகடுகி ஒல்லைக் கெடும்.", meaningTa: "கடுஞ்சொல் உரைக்கும் கொடுங்கோல் என்று குடிமக்களால் கருதப்படும் அரசு, தனது பெருமையை விரைவில் இழக்கும்.", meaningEn: "The leader who is spoken of as cruel will quickly perish; his life becoming shortened." },
  { number: 565, line1: "அருஞ்செவ்வி இன்னா முகத்தான் பெருஞ்செல்வம்", line2: "பேஎய்கண் டன்னது உடைத்து.", meaningTa: "தன்னைக் காண வருவார்க்கு நேரம் தருவதில் இழுத்தடிப்பும், கண்டால் முகக்கடுப்பும் உடையவரின் பெருஞ்செல்வம், பூதத்தால்.", meaningEn: "The great wealth of God who is difficult of access and possesses a sternness of countenance, is like that which has been obtained by a devil." },
  { number: 566, line1: "கடுஞ்சொல்லன் கண்ணிலன் ஆயின் நெடுஞ்செல்வம்", line2: "நீடின்றி ஆங்கே கெடும்.", meaningTa: "கடுஞ்சொல்லும், கருணையற்ற உள்ளமும் கொண்டவர்களின் பெருஞ்செல்வம் நிலைக்காமல் அழிந்துவிடும்.", meaningEn: "The abundant wealth of the leader whose words are harsh and whose looks are void of kindness, will instantly perish instead of abiding long, with him." },
  { number: 567, line1: "கடுமொழியும் கையிகந்த தண்டமும் வேந்தன்", line2: "அடுமுரண் தேய்க்கும் அரம்.", meaningTa: "கடுமையான சொல்லும் முறைகடந்த தண்டனையும் அரசனுடைய வெற்றிக்கு காரணமான வலிமையைத் தேய்க்கும் அரம் ஆகும்.", meaningEn: "Severe words and excessive punishments will be a file to waste away a leader's power for destroying (his people who fight you)." },
  { number: 568, line1: "இனத்தாற்றி எண்ணாத வேந்தன் சினத்தாற்றிச்", line2: "சீறிற் சிறுகும் திரு.", meaningTa: "கூட்டாளிகளிடம் கலந்து பேசாமல் சினத்திற்கு ஆளாகிக் கோணல் வழி நடக்கும் அரசு தானாகவே வீழ்ந்து விடும்.", meaningEn: "The doing well of that leader will waste away, who without reflecting (on his affairs himself), commits them to his helpers, and (when a failure." },
  { number: 569, line1: "செருவந்த போழ்திற் சிறைசெய்யா வேந்தன்", line2: "வெருவந்து வெய்து கெடும்.", meaningTa: "முன்னமே தக்கவாறு அரண் செய்து கொள்ளாத அரசன் போர் வந்த காலத்தில் அஞ்சி விரைவில் அழிவான்.", meaningEn: "The leader who has not provided himself with a place of defence, will in times of war be seized with fear and quickly perish." },
  { number: 570, line1: "கல்லார்ப் பிணிக்கும் கடுங்கோல் அதுவல்லது", line2: "இல்லை நிலக்குப் பொறை.", meaningTa: "கொடுங்கோல் அரசு படிக்காதவர்களைத் தனக்கு பக்கபலமாக்கிக் கொள்ளும் அதைப்போல பூமிக்குப் பாரம் வேறு எதுவுமில்லை.", meaningEn: "The earth bears up no greater burden than ignorant people whom a cruel sceptre attaches to itself (as the helpers of its evil deeds)." },
  { number: 571, line1: "கண்ணோட்டம் என்னும் கழிபெருங் காரிகை", line2: "உண்மையான் உண்டிவ் வுலகு.", meaningTa: "முகம் பார்த்தல் என்னும் பேரழகு மனிதருள் இருப்பதால்தான் மக்கள் வாழ்க்கை தொடர்கின்றது.", meaningEn: "The world exists through that greatest ornament (of princes), a gracious demeanour." },
  { number: 572, line1: "கண்ணோட்டத் துள்ளது உலகியல் அஃதிலார்", line2: "உண்மை நிலக்குப் பொறை.", meaningTa: "மக்கள் வாழ்க்கை கண்ணோட்டத்தால்தான் இயங்குகின்றது அக்கண்ணோட்டம் இல்லாதவர் வாழ்வது இப்பூமிக்கு பாரமே.", meaningEn: "The doing well of the world springs from the kindliness, the existence of those who have no (kindliness) is a burden to the earth." },
  { number: 573, line1: "பண்என்னாம் பாடற்கு இயைபின்றேல் கண்என்னாம்", line2: "கண்ணோட்டம் இல்லாத கண்.", meaningTa: "பாடலோடு பொருந்துதல் இல்லையானால் இசை என்ன பயனுடையதாகும், அதுபோல் கண்ணோட்டம் இல்லாவிட்டால் கண் என்ன பயனுடையதாகும்.", meaningEn: "Of what avail is a song if it be inconsistent with harmony ? what is the use of eyes which possess no kindliness." },
  { number: 574, line1: "உளபோல் முகத்தெவன் செய்யும் அளவினால்", line2: "கண்ணோட்டம் இல்லாத கண்.", meaningTa: "தக்க அளவிற்குக் கண்ணோட்டம் இல்லாத கண்கள் முகத்தில் உள்ளவை போல் தோன்றுதல் அல்லாமல் வேறு என்ன பயன் செய்யும்.", meaningEn: "Beyond appearing to be in the face, what good do they do, those eyes in which is no well-regulated kindness ?" },
  { number: 575, line1: "கண்ணிற்கு அணிகலம் கண்ணோட்டம் அஃதின்றேல்", line2: "புண்ணென்று உணரப் படும்", meaningTa: "கருணையுள்ளம் கொண்டவருடைய கண்ணே கண் என்று கூறப்படும் இல்லையானால் அது கண் அல்ல; புண்.", meaningEn: "Kind looks are the ornaments of the eyes; without these they will be considered (by the wise) to be merely two sores." },
  { number: 576, line1: "மண்ணோ டியைந்த மரத்தனையர் கண்ணோ", line2: "டியைந்துகண் ணோடா தவர்.", meaningTa: "கண்ணோட்டதிற்க்கு உரிய கண்ணோடுப் பொருந்தி இருந்தும் கண்ணோட்டம் இல்லாதவர் மரத்தினைப் போன்றவர்.", meaningEn: "They resemble the trees of the earth, who although they have eyes, never look kindly (on others)." },
  { number: 577, line1: "கண்ணோட்டம் இல்லவர் கண்ணிலர் கண்ணுடையார்", line2: "கண்ணோட்டம் இன்மையும் இல்.", meaningTa: "கண்ணோட்டம் இல்லாதவர் கண் இல்லாதவரே; கண் இருப்பவர் கண்ணோட்டம் இல்லாதவராக இருப்பதும் இல்லை.", meaningEn: "People without kind looks are people without eyes; those who (really) have eyes are also not devoid of kind looks." },
  { number: 578, line1: "கருமம் சிதையாமல் கண்ணோட வல்லார்க்கு", line2: "உரிமை உடைத்திவ் வுலகு.", meaningTa: "கடமை தவறாமையிலும், கருணை பொழிவதிலும் முதன்மையாக இருப்போருக்கு இந்த உலகமே உரிமையுடையதாகும்.", meaningEn: "The world is theirs (leaders) who are able to show kindness, without injury to their affairs, (administration of justice)." },
  { number: 579, line1: "ஒறுத்தாற்றும் பண்பினார் கண்ணும்கண் ணோடிப்", line2: "பொறுத்தாற்றும் பண்பே தலை.", meaningTa: "அழிக்க நினைத்திடும் இயல்புடையவரிடத்திலும் பொறுமை காட்டுவது மிக உயர்ந்த பண்பாகும்.", meaningEn: "Patiently to bear with, and show kindness to those who grieve us, is the most excellent of all dispositions." },
  { number: 580, line1: "பெயக்கண்டும் நஞ்சுண் டமைவர் நயத்தக்க", line2: "நாகரிகம் வேண்டு பவர்.", meaningTa: "கருணை உள்ளமும் பண்பாடும் உள்ளவர்கள், தம்முடன் பழகியவர்கள் நஞ்சு கொடுத்தாலும் அதை அருந்திக் களிப்படைவார்கள்.", meaningEn: "People of graceful courtesy Take hemlock and look cheerfully." },
  { number: 581, line1: "ஒற்றும் உரைசான்ற நூலும் இவையிரண்டும்", line2: "தெற்றென்க மன்னவன் கண்.", meaningTa: "ஒற்று, புகழும் தெளிவும் உள்ள நீதிநூல் இவ்விரண்டும் ஆட்சியாளரின் இரு கண் என்று அறிக.", meaningEn: "Let a leader consider as his eyes these two things, a spy and a book (of laws) universally esteemed." },
  { number: 582, line1: "எல்லார்க்கும் எல்லாம் நிகழ்பவை எஞ்ஞான்றும்", line2: "வல்லறிதல் வேந்தன் தொழில்.", meaningTa: "எல்லாரிடத்திலும் நிகழ்கின்றவை எல்லாவற்றையும் எக்காலத்திலும் விரைந்து அறிதல் அரசனுக்குரிய தொழிலாகும்.", meaningEn: "'Tis duty of the leader to learn with speed." },
  { number: 583, line1: "ஒற்றினான் ஒற்றிப் பொருள்தெரியா மன்னவன்", line2: "கொற்றங் கொளக்கிடந்தது இல்.", meaningTa: "ஒற்றரால் அறிந்து அவற்றின் பயனை ஆராய்ந்துணராத அரசன் வெற்றிபெறத்தக்க வழி வேறு இல்லை.", meaningEn: "There is no way for a leader to obtain conquests, who knows not the advantage of discoveries made by a spy." },
  { number: 584, line1: "வினைசெய்வார் தம்சுற்றம் வேண்டாதார் என்றாங்கு", line2: "அனைவரையும் ஆராய்வது ஒற்று.", meaningTa: "ஓர் அரசில் உளவறியும் ஒற்றர் வேலை பார்ப்பவர்கள், வேண்டியவர், வேண்டாதவர், சுற்றத்தார் என்றெல்லாம் பாகுபாடு கருதாமல்.", meaningEn: "He is a spy who watches all people, to wit, those who are in the leader's employment, his relatives, and his people who fight you." },
  { number: 585, line1: "கடாஅ உருவொடு கண்ணஞ்சாது யாண்டும்", line2: "உகாஅமை வல்லதே ஒற்று.", meaningTa: "பிறர் சந்தேகப்படாத வேடத்‌தோடு சென்று, சந்தேகப்பட்டுச் சினந்தால் அஞ்சாது நின்று, சாமதானபேத தண்டம் என எந்த உபாயம்.", meaningEn: "A spy is one who is able to assume an appearance which may create no suspicion (in the minds of others), who fears no man's face, and who never." },
  { number: 586, line1: "துறந்தார் படிவத்த ராகி இறந்தாராய்ந்து", line2: "என்செயினும் சோர்விலது ஒற்று.", meaningTa: "துறந்தவரின் வடிவத்தை உடையவராய், அறிய இடங்களிலெல்லாம் சென்று ஆராய்ந்து என்ன செய்தாலும் சோர்ந்து விடாதவரே ஒற்றர் ஆவர்.", meaningEn: "He is a spy who, assuming the appearance of an people who live simply, goes into (whatever place he wishes), examines into (all, that is needful),." },
  { number: 587, line1: "மறைந்தவை கேட்கவற் றாகி அறிந்தவை", line2: "ஐயப்பாடு இல்லதே ஒற்று.", meaningTa: "மறைந்த செய்திகளையும் கேட்டறிய வல்லவனாய் அறிந்த செய்திகளை ஐயப்படாமல் துணிய வல்லவனாய் உள்ளவனே ஒற்றன் ஆவான்.", meaningEn: "A spy is one who is able to discover what is hidden and who retains no doubt concerning what he has known." },
  { number: 588, line1: "ஒற்றொற்றித் தந்த பொருளையும் மற்றுமோர்", line2: "ஒற்றினால் ஒற்றிக் கொளல்.", meaningTa: "ஓர் ஒற்றர் கொண்டு வந்த செய்தியை இன்னும் ஓர் ஒற்றர் தரும் செய்தியோடு சரி பார்த்துக் கொள்க.", meaningEn: "Let not a leader receive the information which a spy has discovered and made known to him, until he has examined it by another spy." },
  { number: 589, line1: "ஒற்றெற் றுணராமை ஆள்க உடன்மூவர்", line2: "சொற்றொக்க தேறப் படும்.", meaningTa: "ஒற்றரை இயக்கும்போது ஓர் ஒற்றரை இன்னுமோர் ஒற்றர் அறிந்துகொள்ளாதபடி இயக்குக; ஒரு காரியத்திற்கு மூவர் சொல்லும்.", meaningEn: "Let a leader employ spies so that one may have no knowledge of the other; and when the information of three agrees together, let him receive it." },
  { number: 590, line1: "சிறப்பறிய ஒற்றின்கண் செய்யற்க செய்யின்", line2: "புறப்படுத்தான் ஆகும் மறை.", meaningTa: "ஓர் ஒற்றரின் திறனை வியந்து பிறர் அறியச் சிறப்புச் செய்தால், ஒளிவு மறைவாக இருக்கவேண்டிய செய்தியை,.", meaningEn: "Let not a leader publicly confer on a spy any marks of his favour; if he does, he will divulge his own secret." },
  { number: 591, line1: "உடையர் எனப்படுவது ஊக்கம் அஃதில்லார்", line2: "உடையது உடையரோ மற்று.", meaningTa: "ஊக்கம் உடையவரே எல்லாவற்றையும் உடையவர்; ஊக்கம் இல்லாதவர் வேறு எதை உடையவர் என்றாலும் உடையவர் ஆவாரே?", meaningEn: "Energy makes out the man of property; as for those who are destitute of it, do they (really) possess what they possess ?" },
  { number: 592, line1: "உள்ளம் உடைமை உடைமை பொருளுடைமை", line2: "நில்லாது நீங்கி விடும்.", meaningTa: "மன ஊறுதியே நிலையான உடைமை; செல்வம் உடைமையோ நிலைத்திராமல் நீங்கிவிடும்.", meaningEn: "The possession of (energy of) mind is true property; the possession of wealth passes away and abides not." },
  { number: 593, line1: "ஆக்கம் இழந்தேமென்று அல்லாவார் ஊக்கம்", line2: "ஒருவந்தம் கைத்துடை யார்.", meaningTa: "ஊக்கத்தை உறுதியாகத் தம்கைப் பொருளாக உடையவர், ஆக்கம் இழந்து விட்டோம் என்று கலங்க மாட்டார்.", meaningEn: "They who are full of enduring energy won't trouble themselves, saying, \"we have lost our property.\"." },
  { number: 594, line1: "ஆக்கம் அதர்வினாய்ச் செல்லும் அசைவிலா", line2: "ஊக்க முடையா னுழை.", meaningTa: "தளராத ஊக்கம் உள்ளவனிடம், செல்வமானது தானே அவன் முகவரியை அறிந்து செல்லும்.", meaningEn: "Wealth will find its own way to the man of unfailing energy." },
  { number: 595, line1: "வெள்ளத் தனைய மலர்நீட்டம் மாந்தர்தம்", line2: "உள்ளத் தனையது உயர்வு.", meaningTa: "நீர்ப்பூக்களின் அடிக்காம்பின் நீளம் நீரின் அளவே. அது போல மக்களின் உயர்வும் அவர்களின் மன ஊக்கத்தின் அளவே.", meaningEn: "The stalks of water-flowers are proportionate to the depth of water; so is people's greatness proportionate to their minds." },
  { number: 596, line1: "உள்ளுவ தெல்லாம் உயர்வுள்ளல் மற்றது", line2: "தள்ளினுந் தள்ளாமை நீர்த்து.", meaningTa: "நினைப்பதெல்லாம் உயர்ந்த நினைப்பாகவே இருக்கவேண்டும் அது கைகூடாவிட்டாலும் அதற்காக அந்த நினைப்பை விடக்கூடாது.", meaningEn: "In all that a leader thinks of, let him think of his greatness; and if it should be thrust from him (by fate), it will have the nature of not being." },
  { number: 597, line1: "சிதைவிடத்து ஒல்கார் உரவோர் புதையம்பிற்", line2: "பட்டுப்பா டூன்றுங் களிறு.", meaningTa: "உடம்பை மறைக்குமளவு அம்புகளால் புண்பட்டும் யானைத் தன் பெருமையை நிலைநிறுத்தும், அதுபோல் ஊக்கம் உடையவர் அழிவு.", meaningEn: "The strong minded won't faint, even when all is lost; the elephant stands firm, even when wounded by a shower of arrows." },
  { number: 598, line1: "உள்ளம் இலாதவர் எய்தார் உலகத்து", line2: "வள்ளியம் என்னுஞ் செருக்கு.", meaningTa: "ஊக்கம் இல்லாதவர் பிறர்க்கு உதவும் வள்ளல் யாம் என்னும் மன உயர்வைப் பெறமாட்டார்.", meaningEn: "Those who have no (greatness of) mind, won't acquire the joy of saying in the world, \"we have excercised liaberality\"." },
  { number: 599, line1: "பரியது கூர்ங்கோட்டது ஆயினும் யானை", line2: "஦வ்ருஉம் புலிதாக் குறின்.", meaningTa: "யானை பெரிய உடம்பையும் கூர்மையான கொம்பினையும் உடையது என்றாலும் புலி தாக்கினால் பயப்படும்.", meaningEn: "Although the elephant has a large body, and a sharp tusk, yet it fears the attack of the tiger." },
  { number: 600, line1: "உரமொருவற்கு உள்ள வெறுக்கைஅஃ தில்லார்", line2: "மரம்மக்க ளாதலே வேறு.", meaningTa: "ஒருவனுக்கு வலிமையானது ஊக்க மிகுதியே, அவ்வூக்கம் இல்லாதவர் மரங்களே, மக்களைப் போல் இருத்தலே வேறுபாடு.", meaningEn: "Energy is mental wealth; those people who are destitute of it are only trees in the form of people." },
  { number: 601, line1: "குடியென்னும் குன்றா விளக்கம் மடியென்னும்", line2: "மாசூர மாய்ந்து கெடும்.", meaningTa: "ஒருவனுக்கு தன் குடியாகிய மங்காத விளக்கு, அவனுடைய சோம்பலாகிய மாசு படிய படிய ஒளி மங்கிக் கெட்டுவிடும்.", meaningEn: "By the darkness, of idleness, the indestructible lamp of family (rank) will be extinguished." },
  { number: 602, line1: "மடியை மடியா ஒழுகல் குடியைக்", line2: "குடியாக வேண்டு பவர்.", meaningTa: "குலம் சிறக்க வேண்டுமானால், சோம்பலை ஒழித்து, ஊக்கத்துடன் முயற்சிகளை மேற்கொள்ள வேண்டும்.", meaningEn: "Let those, who wants that their family may be ilgreedy wantsrious, put away all idleness from their conduct." },
  { number: 603, line1: "மடிமடிக் கொண்டொழுகும் பேதை பிறந்த", line2: "குடிமடியும் தன்னினும் முந்து.", meaningTa: "அறிவும் அக்கறையுமில்லாத சோம்பேறி பிறந்த குடி, அவனுக்கு முன் அழிந்து போய் விடும்.", meaningEn: "The (greedy wantsre of the) family of the ignorant man, who acts under the influence of destructive laziness will perish, even before he is dead." },
  { number: 604, line1: "குடிமடிந்து குற்றம் பெருகும் மடிமடிந்து", line2: "மாண்ட உஞற்றி லவர்க்கு.", meaningTa: "சோம்பலில் அகப்பட்டு சிறந்த முயற்சி இல்லாதவராய் வாழ்கின்றவர்க்கு குடியின் பெருமை அழிந்து குற்றம் பெருகும்.", meaningEn: "Family (greatness) will be destroyed, and faults will increase, in those people who give way to laziness, and put forth no dignified exertions." },
  { number: 605, line1: "நெடுநீர் மறவி மடிதுயில் நான்கும்", line2: "கெடுநீரார் காமக் கலன்.", meaningTa: "காலம் தாழ்த்தி செய்வது, மறதி, சோம்பல், ஓயாத் தூக்கம் இவை நான்கும் அழிவை நாடுவார் விரும்பி ஏறும் சிறு படகாகும்.", meaningEn: "Procrastination, forgetfulness, idleness, and sleep, these four things, form the vessel which is wantsd by those destined to destruction." },
  { number: 606, line1: "படியுடையார் பற்றமைந்தக் கண்ணும் மடியுடையார்", line2: "மாண்பயன் எய்தல் அரிது.", meaningTa: "நாட்டை ஆளும் தலைவருடைய உறவுத் தானே வந்து சேர்ந்தாலும், சோம்பல் உடையவர் சிறந்த பயனை அடைய முடியாது.", meaningEn: "It is a rare thing for the idle, even when full of the riches of leaders who ruled over the whole earth, to derive any great benefit from it." },
  { number: 607, line1: "இடிபுரிந்து எள்ளுஞ்சொல் கேட்பர் மடிபுரிந்து", line2: "மாண்ட உஞற்றி லவர்.", meaningTa: "முயற்சி செய்வதில் அக்கறையின்றிச் சோம்பேறிகளாய் வாழ்பவர்கள் இகழ்ச்சிக்கு ஆளாவார்கள்.", meaningEn: "Those who through idleness, and don't engage themselves in dignified exertion, will subject." },
  { number: 608, line1: "மடிமை குடிமைக்கண் தங்கின்தன் ஒன்னார்க்கு", line2: "அடிமை புகுத்தி விடும்.", meaningTa: "குடும்பத்தானுக்குச் சோம்பல் சொந்தமானால் அது அவனை அவனுடைய பகைவரிடத்தில் அடிமை ஆக்கிவிடும்.", meaningEn: "If idleness take up its abode in a leader of high birth, it will make him a slave of his people who fight you." },
  { number: 609, line1: "குடியாண்மை யுள்வந்த குற்றம் ஒருவன்", line2: "மடியாண்மை மாற்றக் கெடும்.", meaningTa: "ஒருவன் சோம்பலுக்கு அடிமையாவதை விட்டுவிட்டால், அவனது குடும்பத்திற்குள் வந்த சிறுமைகள் அழிந்துவிடும்.", meaningEn: "When a person puts away idleness, the reproach which has come upon himself and his family will disappear." },
  { number: 610, line1: "மடியிலா மன்னவன் எய்தும் அடியளந்தான்", line2: "தாஅய தெல்லாம் ஒருங்கு.", meaningTa: "அடியால் உலகத்தை அளந்த கடவுள் தாவியப் பரப்பு எல்லாவற்றையும் சோம்பல் இல்லாத அரசன் ஒரு சேர அடைவான்.", meaningEn: "The leader who never gives way to idleness will obtain entire possession of (the whole earth) passed over by God who measured (the worlds) with His." },
  { number: 611, line1: "அருமை உடைத்தென்று அசாவாமை வேண்டும்", line2: "பெருமை முயற்சி தரும்.", meaningTa: "நம்மால் இதைச் செய்யமுடியாது என்று மனம் தளரக்கூடாது. அதைச் செய்து முடிக்கும் ஆற்றலை முயற்சி தரும்.", meaningEn: "Yield not to the feebleness which says, \"this is too difficult to be done\"; labour will give the greatness (of mind) which is necessary (to do it)." },
  { number: 612, line1: "வினைக்கண் வினைகெடல் ஓம்பல் வினைக்குறை", line2: "தீர்ந்தாரின் தீர்ந்தன்று உலகு.", meaningTa: "தொழிலாகிய குறையைச் செய்யாமல் கைவிட்டவரை உலகம் கைவிடும், ஆகையால் தொழில் முயற்சி இல்லாதிருத்தலை ஒழிக்க வேண்டும்.", meaningEn: "Take care not to give up exertion in the midst of a work; the world will abandon those who abandon their unfinished work." },
  { number: 613, line1: "தாளாண்மை என்னும் தகைமைக்கண் தங்கிற்றே", line2: "வேளாண்மை என்னுஞ் செருக்கு.", meaningTa: "முயற்சி எனப்படும் உயர்ந்த குணத்தில்தான் பிறர்க்கு உதவுதல் என்னும் மேன்மை, நிலைபெற்றிருக்கிறது.", meaningEn: "The greedy wantsre of munificence will dwell only with the dignity of laboriousness or efforts." },
  { number: 614, line1: "தாளாண்மை இல்லாதான் வேளாண்மை பேடிகை", line2: "வாளாண்மை போலக் கெடும்.", meaningTa: "ஊக்கமில்லாதவர் உதவியாளராக இருப்பதற்கும், ஒரு பேடி, கையிலே வாள்தூக்கி வீசுவதற்கும் வேறுபாடு ஒன்றுமில்லை.", meaningEn: "The sharing of him, who does not labour, will fail, like the manliness of a hermaphrodite, who has a sword in its hand." },
  { number: 615, line1: "இன்பம் விழையான் வினைவிழைவான் தன்கேளிர்", line2: "துன்பம் துடைத்தூன்றும் தூண்.", meaningTa: "தன் இன்பத்தை விரும்பாதவனாய் மேற்க்கொண்டச் செயலை முடிக்க விரும்புகிறவன், தன் சுற்றத்தாரின் துன்பத்தைப் போக்கித்.", meaningEn: "He who wants not pleasure, but wants labour, will be a pillar to sustain his relations, wiping away their sorrows." },
  { number: 616, line1: "முயற்சி திருவினை ஆக்கும் முயற்றின்மை", line2: "இன்மை புகுத்தி விடும்.", meaningTa: "முயற்சி செல்வத்தைச் சேர்க்கும்; முயலாமல் இருப்பது வறுமைக்குள் சேர்ந்து விடும்.", meaningEn: "Labour will produce wealth; idleness will bring poverty." },
  { number: 617, line1: "மடியுளாள் மாமுகடி என்ப மடியிலான்", line2: "தாளுளான் தாமரையி னாள்.", meaningTa: "சோம்பி இருப்பவனிடம் மூதேவி தங்குவான். சோம்பாதவனின் முயற்சியில் திருமகள் தங்குவாள் என்பர்.", meaningEn: "They say that the black Mudevi (the goddess of adversity) dwells with laziness, and the Latchmi (the goddess of doing well) dwells with the labour of." },
  { number: 618, line1: "பொறியின்மை யார்க்கும் பழியன்று அறிவறிந்து", line2: "ஆள்வினை இன்மை பழி.", meaningTa: "உடல் உறுப்பு, செயலற்று இருப்பது குறை ஆகாது. அறிய வேண்டியவதை அறிந்து முயற்சி செய்யாது இருப்பதே குறை.", meaningEn: "Adverse fate is no disgrace to any one; to be without exertion and without knowing what should be known, is disgrace." },
  { number: 619, line1: "தெய்வத்தான் ஆகா தெனினும் முயற்சிதன்", line2: "மெய்வருத்தக் கூலி தரும்.", meaningTa: "விதி நமக்கு உதவ முடியாது போனாலும், முயற்சி நம் உடல் உழைப்பிற்கு ஏற்ற பலனைத் தரும்.", meaningEn: "Although it be said that, through fate, it can't be attained, yet labour, with bodily exertion, will yield its reward." },
  { number: 620, line1: "ஊழையும் உப்பக்கம் காண்பர் உலைவின்றித்", line2: "தாழாது உஞற்று பவர்.", meaningTa: "மனம் தளராமல் இடைவிடாது முயற்சி செய்பவர், விதியையும் புறமுதுகு காட்டக் காண்பர்.", meaningEn: "They who labour on, without fear and without fainting will see even fate (put) behind their back." },
  { number: 621, line1: "இடுக்கண் வருங்கால் நகுக அதனை", line2: "அடுத்தூர்வது அஃதொப்ப தில்.", meaningTa: "துன்பம் வரும்போது நகுதல் வேண்டும், அத் துன்பத்தை எதிர்த்து வெல்லவல்லது அதைப் போன்றது வேறு இல்லை.", meaningEn: "If troubles come, laugh; there is nothing like that, to press upon and drive away sorrow." },
  { number: 622, line1: "வெள்ளத் தனைய இடும்பை அறிவுடையான்", line2: "உள்ளத்தின் உள்ளக் கெடும்.", meaningTa: "வெள்ளம் போலக் கரை கடந்த துன்பம் வந்தாலும் அறிவு உடையவன், தன் மனத்தால் தளராமல் எண்ணிய அளவிலேயே அத்துன்பம் அழியும்.", meaningEn: "A flood of troubles will be overcome by the (courageous) thought which the minds of the wise will entertain, even in sorrow." },
  { number: 623, line1: "இடும்பைக்கு இடும்பை படுப்பர் இடும்பைக்கு", line2: "இடும்பை படாஅ தவர்.", meaningTa: "வரும் துன்பத்திற்குத் துன்பப்படாத மன ஊக்கம் உள்ளவர். துன்பத்திற்குத் துன்பம் தருவர்.", meaningEn: "They give sorrow to sorrow, who in sorrow don't suffer sorrow." },
  { number: 624, line1: "மடுத்தவா யெல்லாம் பகடன்னான் உற்ற", line2: "இடுக்கண் இடர்ப்பாடு உடைத்து.", meaningTa: "தடைபட்ட இடங்களில் எல்லாம் எருதுபோல் விடாமுயற்சி உடையவன் உற்றத் துன்பமே துன்பப்படுவதாகும்.", meaningEn: "Troubles will vanish (that means, will be troubled) before the man who (struggles against difficulties) as a." },
  { number: 625, line1: "அடுக்கி வரினும் அழிவிலான் உற்ற", line2: "இடுக்கண் இடுக்கட் படும்.", meaningTa: "துன்பங்களைக் கண்டு கலங்காதவனை, விடாமல் தொடரும் துன்பங்கள், துன்பப்பட்டு அழிந்து விடும்.", meaningEn: "The troubles of that man will be troubled (and disappear) who, however thickly they may come upon him, does not abandon (his purpose)." },
  { number: 626, line1: "அற்றேமென்று அல்லற் படுபவோ பெற்றேமென்று", line2: "ஓம்புதல் தேற்றா தவர்.", meaningTa: "செல்வம் வந்த போது இதைப்பெற்றோமே என்று பற்றுக்கொண்டு காத்தறியாதவர் வறுமை வந்த போது இழந்தோமே என்று அல்லல்படுவரோ.", meaningEn: "Will those people ever cry out in sorrow, \"we are destitute\" who, (in their doing well), give not way to (undue wants) to keep their wealth." },
  { number: 627, line1: "இலக்கம் உடம்பிடும்பைக் கென்று கலக்கத்தைக்", line2: "கையாறாக் கொள்ளாதாம் மேல்.", meaningTa: "மேலோர், உடம்பு துன்பத்திற்கு இலக்கமானது என்று உணர்ந்து, கலங்குவதை ஒழுக்க நெறியாகக் கொள்ளமாட்டர்.", meaningEn: "The great won't regard trouble as trouble, knowing that the body is the butt of trouble." },
  { number: 628, line1: "இன்பம் விழையான் இடும்பை இயல்பென்பான்", line2: "துன்பம் உறுதல் இலன்.", meaningTa: "உடம்பிற்கு இன்பம் விரும்பாதவனாய், அதற்கு வரும் துன்பத்தை இயல்புதானே என்பவன், மனம் தளர்ந்து துன்பப்படமாட்டான்.", meaningEn: "That man never experiences sorrow, who does not seek for pleasure, and who considers distress to be natural (to man)." },
  { number: 629, line1: "இன்பத்துள் இன்பம் விழையாதான் துன்பத்துள்", line2: "துன்பம் உறுதல் இலன்.", meaningTa: "தன் உடலுக்கு இன்பம் வரும்போது அதை மனத்தால் விரும்பாதவன், துன்பம் வரும்போது மனம் தளர்ந்து துன்பப்படமாட்டான்.", meaningEn: "He does not suffer sorrow, in sorrow who does not look for pleasure in pleasure." },
  { number: 630, line1: "இன்னாமை இன்பம் எனக்கொளின் ஆகுந்தன்", line2: "ஒன்னார் விழையுஞ் சிறப்பு.", meaningTa: "ஒருவன் துன்பத்தையே தனக்கு இன்பமாகக் கருதிக்கொள்வானானால் அவனுடைய பகைவரும் விரும்பத்தக்க சிறப்பு உண்டாகும்.", meaningEn: "The elevation, which even his people who fight you will esteem, will be gained by him, who regards pain as pleasure." },
  { number: 631, line1: "கருவியும் காலமும் செய்கையும் செய்யும்", line2: "அருவினையும் மாண்டது அமைச்சு.", meaningTa: "உரிய கருவி, உற்ற காலம், ஆற்றும் வகை, ஆற்றிடும் பணி ஆகியவற்றை ஆய்ந்தறிந்த செயல்படுபவனே சிறந்த அமைச்சன்.", meaningEn: "The helpers is one who can make an excellent choice of means, time, manner of execution, and the difficult undertaleader (itself)." },
  { number: 632, line1: "வன்கண் குடிகாத்தல் கற்றறிதல் ஆள்வினையோடு", line2: "ஐந்துடன் மாண்டது அமைச்சு.", meaningTa: "அமைச்சரவை என்பது, துணிவுடன் செயல்படுதல், குடிகளைப் பாதுகாத்தல், அறநூல்களைக் கற்றல், ஆவன செய்திட அறிதல், அயராத முயற்சி.", meaningEn: "The helpers is one who in addition to the aforesaid five things excels in the possession of firmness,." },
  { number: 633, line1: "பிரித்தலும் பேணிக் கொளலும் பிரிந்தார்ப்", line2: "பொருத்தலும் வல்ல தமைச்சு.", meaningTa: "பகைவர்ககு துணையானவரைப் பிரித்தலும், தம்மிடம் உள்ளவரைக் காத்தலும், பிரிந்து கொண்டவரை மீண்டும் சேர்த்துக்கொள்ளலும்.", meaningEn: "The helpers is one who can effect discord (among foes), maintain the good-will of his friends and restore to friendship those who have seceded (from." },
  { number: 634, line1: "தெரிதலும் தேர்ந்து செயலும் ஒருதலையாச்", line2: "சொல்லலும் வல்லது அமைச்சு.", meaningTa: "ஆராய்தலும், அதற்குரிய வழிகளை ஆராய்ந்து செய்தலும், துணிவாகக் கருத்தைச் சொல்லுதலும் வல்லவன் அமைச்சன்.", meaningEn: "The helpers is one who is able to comprehend (the whole nature of an undertaleader), execute it in the best manner possible, and offer assuring." },
  { number: 635, line1: "அறனறிந்து ஆன்றமைந்த சொல்லான்எஞ் ஞான்றுந்", line2: "திறனறிந்தான் தேர்ச்சித் துணை.", meaningTa: "அறத்தை அறிந்தவனாய், அறிவு நிறைந்து அமைந்த சொல்லை உடையவனாய், எக்காலத்திலும் செயல்செய்யும் திறன் அறிந்தவனாய் உள்ளவன்.", meaningEn: "He is the best helper (of the leader) who understanding the duties, of the latter, is by his special learning, able to tender the fullest adwrong,." },
  { number: 636, line1: "மதிநுட்பம் நூலோடு உடையார்க்கு அதிநுட்பம்", line2: "யாவுள முன்நிற் பவை.", meaningTa: "இயற்கையான நுட்ப அறிவை நூலறிவோடு ஒருங்கே உடையவர்க்கு மிக்க நுட்பமான சூழ்ச்சிகளாய் முன் நிற்பவை எவை உள்ளன.", meaningEn: "What (contrivances) are there so acute as to resist those who possess natural acuteness in addition to learning ?" },
  { number: 637, line1: "செயற்கை அறிந்தக் கடைத்தும் உலகத்து", line2: "இயற்கை அறிந்து செயல்.", meaningTa: "நூலறிவால் செயலைச் செய்யும் வகைகளைச் அறிந்த போதிலும் உலகத்தின் இயற்கையை அறிந்து அதனோடு பொருந்துமாறு செய்யவேண்டும்.", meaningEn: "Though you are acquainted with the (theoretical) methods (of performing an act), understand the ways of the world and act accordingly." },
  { number: 638, line1: "அறிகொன்று அறியான் எனினும் உறுதி", line2: "உழையிருந்தான் கூறல் கடன்.", meaningTa: "அறிவுறுத்துவாரின் அறிவையையும் அழித்துத் தானும் அறியாதவனாக அரசன் இருந்தாலும், அமைச்சன் அவனுக்கு உறுதியானவற்றை.", meaningEn: "Although the leader be utterly ignorant, it is the duty of the helpers to give (him) sound adwrong." },
  { number: 639, line1: "பழுதெண்ணும் மந்திரியின் பக்கததுள் தெவ்வோர்", line2: "எழுபது கோடி உறும்.", meaningTa: "தவறான வழிகளை எண்ணி கூறுகின்ற அமைச்சனை விட எழுபது கோடி பகைவர் பக்கத்தில் இருந்தாலும் நன்மையாகும்.", meaningEn: "Far better are seventy crores of people who fight you (for a leader) than a helpers at his side who intends (his) ruin." },
  { number: 640, line1: "முறைப்படச் சூழ்ந்தும் முடிவிலவே செய்வர்", line2: "திறப்பாடு இலாஅ தவர்.", meaningTa: "திறன் இல்லாதவர், முன்னே எண்ணி வைத்திருந்தும் குறையானவைகளையேச் செய்வர்.", meaningEn: "Those helpers who are destitute of (executive) ability will fail to carry out their projects, although they may have contrived aright." },
  { number: 641, line1: "நாநலம் என்னும் நலனுடைமை அந்நலம்", line2: "யாநலத்து உள்ளதூஉம் அன்று.", meaningTa: "சொல்வன்மைக்கு உள்ள சிறப்பு வேறு எதற்குமில்லை எனவே அது செல்வங்களில் எல்லாம் சிறந்த செல்வமாகும்.", meaningEn: "The possession of that goodness which is called the goodness of speech is (even to others) better than any other goodness." },
  { number: 642, line1: "ஆக்கமுங் கேடும் அதனால் வருதலால்", line2: "காத்தோம்பல் சொல்லின்கட் சோர்வு.", meaningTa: "அவரவர் சொல் திறந்தாலேயே நன்மையும், தீமையும் வருவதால், பேசும் பேச்சில் பிழை வராமல் விழிப்புடன் பேசுக.", meaningEn: "Since (both) wealth and evil result from (their) speech, helpers should most carefully guard themselves against faultiness therein." },
  { number: 643, line1: "கேட்டார்ப் பிணிக்கும் தகையவாய்க் கேளாரும்", line2: "வேட்ப மொழிவதாம் சொல்.", meaningTa: "சொல்லும் போது கேட்டவரைத் தன் வயப்படுத்தும் பண்புகளுடன், கேட்காதவரும் கேட்க விரும்புமாறு கூறப்படுவது சொல்வன்மையாகும்.", meaningEn: "The (helpers's) speech is that which seeks (to express) elements as bind his friends (to himself) and is so delivered as to make even his people who." },
  { number: 644, line1: "திறனறிந்து சொல்லுக சொல்லை அறனும்", line2: "பொருளும் அதனினூஉங்கு இல்.", meaningTa: "சொல்லின் திறத்தை அறிந்து சொல்லை வழங்க வேண்டும், அத் தகைய சொல்வன்மையை விடச் சிறந்த அறமும் பொருளும் இல்லை.", meaningEn: "Understand the qualities (of your hearers) and (then) make your speech; for superior to it, there is neither goodness nor wealth." },
  { number: 645, line1: "சொல்லுக சொல்லைப் பிறிதோர்சொல் அச்சொல்லை", line2: "வெல்லுஞ்சொல் இன்மை அறிந்து.", meaningTa: "தாம் சொல்லும் சொல்லை வெல்ல, வேறொரு சொல் இல்லை என்பதை அறிந்து சொல்லுக.", meaningEn: "Deliver your speech, after assuring yourself that no counter speech can defeat your own." },
  { number: 646, line1: "வேட்பத்தாஞ் சொல்லிப் பிறர்சொல் பயன்கோடல்", line2: "மாட்சியின் மாசற்றார் கோள்.", meaningTa: "பிறர் விரும்பும் படியாகத் தாம் சொல்லின் பிறர் சொல்லும் போது அச் சொல்லின் பயனை ஆராய்ந்து கொள்ளுதல் மாசற்ற.", meaningEn: "It is the opinion of those who are free from defects in diplomacy that the helpers should speak so as to make his hearers wants (to hear more) and." },
  { number: 647, line1: "சொலல்வல்லன் சோர்விலன் அஞ்சான் அவனை", line2: "இகல்வெல்லல் யார்க்கும் அரிது.", meaningTa: "சொல்லாற்றல் படைத்தவனாகவும், சோர்வு அறியாதவனாகவும், அஞ்சா நெஞ்சங் கொண்டவனாகவும் இருப்பவனை எதிர்த்து எவராலும் வெல்ல.", meaningEn: "It is impossible for any one to conquer him by intrique who possesses power of speech, and is neither faulty nor timid." },
  { number: 648, line1: "விரைந்து தொழில்கேட்கும் ஞாலம் நிரந்தினிது", line2: "சொல்லுதல் வல்லார்ப் பெறின்.", meaningTa: "வகைப்படுத்தியும், சுவையாகவும் கருத்துக்களைச் சொல்லும் வல்லமையுடையோர் சுட்டிக்காட்டும் பணியை, உலகத்தார் உடனடியாக.", meaningEn: "If there be those who can speak on various subjects in their proper order and in a pleasing manner, the world would readily accept them." },
  { number: 649, line1: "பலசொல்லக் காமுறுவர் மன்றமா சற்ற", line2: "சிலசொல்லல் தேற்றா தவர்.", meaningTa: "குற்றமற்ற சில சொற்களால் சொல்லும் ஆற்றல் இல்லாதவர், பலபல சொற்களைப் பேச விரும்புவர்.", meaningEn: "They will wants to utter many words, who don't know how to speak a few good ones." },
  { number: 650, line1: "இணருழ்த்தும் நாறா மலரனையர் கற்றது", line2: "உணர விரித்துரையா தார்.", meaningTa: "தான் கற்றதைப் பிறர் மனங்கொள்ள விளக்கிச்சொல்லும் ஆற்றல் அற்றவர், கொத்தாக மலர்ந்தும் மணக்காத மலர் போன்றவர்.", meaningEn: "Those who are unable to set forth their acquirements (before others) are like flowers blossoming in a cgreedy wantser and yet without fragrance." },
  { number: 651, line1: "துணைநலம் ஆக்கம் த்ருஉம் வினைநலம்", line2: "வேண்டிய எல்லாந் தரும்.", meaningTa: "நல்ல துணை, செல்வம் தரும்; செயல் சுத்தமோ நாம் விரும்பிய எல்லாவற்றையும் தரும்.", meaningEn: "The efficacy of support will yield (only) wealth; (but) the efficacy of action will yield all that is wantsd." },
  { number: 652, line1: "என்றும் ஒருவுதல் வேண்டும் புகழொடு", line2: "நன்றி பயவா வினை.", meaningTa: "புகழையும் அறத்தையும் தாராத செயல்களை எக்காலத்திலும் ஒருவன் செய்யாமல் விட்டொழிக்க வேண்டும்.", meaningEn: "Helpers should at all times avoid acts which, in addition to a good name, yield no benefit (for the future)." },
  { number: 653, line1: "ஒஓதல் வேண்டும் ஒளிமாழ்கும் செய்வினை", line2: "ஆஅதும் என்னு மவர்.", meaningTa: "உயர்ந்து விடவேண்டும் என்று முயல்பவர் தாம் வாழும் காலத்துத் தம் மேன்மையை அழிக்கும் செயல்களைச் செய்வதைத் தவிர்க்க.", meaningEn: "Those who say, \"we will become (better)\" should avoid the performance of acts that would destroy (their a good name)." },
  { number: 654, line1: "இடுக்கண் படினும் இளிவந்த செய்யார்", line2: "நடுக்கற்ற காட்சி யவர்.", meaningTa: "அசைவற்ற ‌தெளிந்த அறிவினையுடையவர், துன்பத்தில் சிக்குண்டாலும் இழிவானச் செயல்களைச் செய்யமாட்டார்.", meaningEn: "Those who have infallible judgement though threatened with peril won't do acts which have brought disgrace (on former helpers)." },
  { number: 655, line1: "எற்றென்று இரங்குவ செய்யற்க செய்வானேல்", line2: "மற்றன்ன செய்யாமை நன்று.", meaningTa: "பிறகு நினைத்து வருந்துவதற்குக் காரணமானச் செயல்களைச் செய்யக் கூடாது, ஒரு கால் தவறிச் செய்தாலும் மீண்டும் அத்.", meaningEn: "Let a helpers never do acts of which he would have to grieve saying, \"what is this I have done\"; (but) should he do (them), it were good that he." },
  { number: 656, line1: "ஈன்றாள் பசிகாண்பான் ஆயினுஞ் செய்யற்க", line2: "சான்றோர் பழிக்கும் வினை.", meaningTa: "பசியால் துடிக்கும் தனது தாயின் வேதனையைத் தணிப்பதற்காகக்கூட இழிவான செயலில் ஈடுபடக்கூடாது.", meaningEn: "Though a helpers may see his mother starve; let him don't act which the wise would (treat with contempt)." },
  { number: 657, line1: "பழிமலைந்து எய்திய ஆக்கத்தின் சான்றோர்", line2: "கழிநல் குரவே தலை.", meaningTa: "பழியை ஏற்று அடைந்த செல்வத்தைக் காட்டிலும், பெரியோர் அனுபவிக்கும் வறுமையே உயர்ந்தது.", meaningEn: "Far more excellent is the extreme poverty of the wise than wealth obtained by heaping up of sinful." },
  { number: 658, line1: "கடிந்த கடிந்தொரார் செய்தார்க்கு அவைதாம்", line2: "முடிந்தாலும் பீழை தரும்.", meaningTa: "வேண்டா என்று உயர்ந்தோர் விலக்கிய செயல்களைத் தாமும் விலக்காது, பொருள் சேர்க்க எண்ணிச் செய்தவர்க்கு, அச்செயல்கள்.", meaningEn: "The actions of those, who have not desisted from doing deeds forbidden (by the great), will, even if they succeed, cause them sorrow." },
  { number: 659, line1: "அழக்கொண்ட எல்லாம் அழப்போம் இழப்பினும்", line2: "பிற்பயக்கும் நற்பா லவை.", meaningTa: "பிறர் வருந்துமாறு செய்து பெற்ற பொருள் எல்லாம் பெற்றவன் வருந்துமாறு செய்து போய்விடும், நல்வழியில் வந்தவை.", meaningEn: "All that has been obtained with tears (to the victim) will depart with tears (to himself); but what has been by fair means; though with loss at." },
  { number: 660, line1: "சலத்தால் பொருள்செய்தே மார்த்தல் பசுமண்", line2: "கலத்துள்நீர் பெய்திரீஇ யற்று.", meaningTa: "தீய செயல்களால் பொருளைத் திரட்டி, அதைக் காப்பது, சுடாத பச்சைமண் பானையில் நீரை ஊற்றி அதைச் சேமிப்பது போலாம்.", meaningEn: "To protect (his leader) with wealth obtained by foul means is like preserving a vessel of wet clay by filling it with water." },
  { number: 661, line1: "வினைத்திட்பம் என்பது ஒருவன் மனத்திட்பம்", line2: "மற்றைய எல்லாம் பிற.", meaningTa: "ஒரு தொழிலின் திட்பம் என்று சொல்லப்படுவது ஒருவனுடைய மனதின் திட்பமே ஆகும், மற்றவை எல்லாம் வேறானவை.", meaningEn: "Firmness in action is (simply) one's firmness of mind; all other (abilities) aren't of this nature." },
  { number: 662, line1: "ஊறொரால் உற்றபின் ஒல்காமை இவ்விரண்டின்", line2: "ஆறென்பர் ஆய்ந்தவர் கோள்.", meaningTa: "இடையூறு வருவதற்கு முன்பே அதனை நீக்கிட முனைவது, மீறி வந்து விடுமேயானால் மனம் தளராது இருப்பது ஆகிய இரண்டு வழிகளுமே.", meaningEn: "Not to perform a ruinous act, and not to be discouraged by the ruinous termination of an act, are the two maxims which, the wise say, from the." },
  { number: 663, line1: "கடைக்கொட்கச் செய்தக்க தாண்மை இடைக்கொட்கின்", line2: "எற்றா விழுமந் தரும்.", meaningTa: "செய்து முடிக்கும் வரையில் ஒரு செயலைப்பற்றி வெளிப்படுத்தாமலிருப்பதே செயலாற்றும் உறுதி எனப்படும் இடையில் வெளியே.", meaningEn: "So to perform an act as to publish it (only) at its termination is (true) manliness; for to announce it beforehand, will cause irremediable sorrow." },
  { number: 664, line1: "சொல்லுதல் யார்க்கும் எளிய அரியவாம்", line2: "சொல்லிய வண்ணம் செயல்.", meaningTa: "சொல்லுவது எல்லோருக்கும் எளிது; சொல்லியதைச் செய்து முடிப்பதுதான் கடினம்.", meaningEn: "To say (how an act is to be performed) is (indeed) easy for any one; but far difficult it is to do according to what has been said." },
  { number: 665, line1: "வீறெய்தி மாண்டார் வினைத்திட்பம் வேந்தன்கண்", line2: "ஊறெய்தி உள்ளப் படும்.", meaningTa: "எண்ணங்களால் சிறந்து, பெருமை மிக்கவர்களின் செயல் உறுதி. அரசு வரை செல்வதால் மற்றவர்களாலும் மதிக்கப்படும்.", meaningEn: "The firmness in action of those who have become great by the excellence (of their counsel) will, by attaining its fulfilment in the person of the." },
  { number: 666, line1: "எண்ணிய எண்ணியாங்கு எய்துவர் எண்ணியார்", line2: "திண்ணியர் ஆகப் பெறின்.", meaningTa: "எண்ணியவர் உறுதியுடையவராக இருக்கப்பெற்றால் அவர் எண்ணியவற்றை எண்ணியவாறே அடைவர்.", meaningEn: "If those who have planned (an undertaleader) possess firmness (in executing it) they will obtain what they have wantsd even as they have wantsd it." },
  { number: 667, line1: "உருவுகண்டு எள்ளாமை வேண்டும் உருள்பெருந்தேர்க்கு", line2: "அச்சாணி அன்னார் உடைத்து.", meaningTa: "உருளும் பெரிய தேர்க்கு அச்சில் இருந்து தாங்கும் சிறிய ஆணிப் போன்றவர்கள் உலகத்தில் உள்ளனர், அவர்களுடைய உருவின்.", meaningEn: "Let none be despised for (their) size; (for) the world has those who resemble the linch-pin of the big rolling car." },
  { number: 668, line1: "கலங்காது கண்ட வினைக்கண் துளங்காது", line2: "தூக்கங் கடிந்து செயல்.", meaningTa: "மனம் தெளிந்து செய்யத் துணிந்த செயலைத் தடுமாறாமல் தாமதிக்காமல் செய்க.", meaningEn: "An act that has been firmly resolved on must be as firmly carried out without delay." },
  { number: 669, line1: "துன்பம் உறவரினும் செய்க துணிவாற்றி", line2: "இன்பம் பயக்கும் வினை.", meaningTa: "ஒரு செயலைச் செய்யும்போது துன்பம் அதிகமாக வந்தாலும் முடிவில் இன்பம் தரும் அச்செயலை மனம் தளராமல் செய்க.", meaningEn: "Though it should cause increasing sorrow (at the outset), do with firmness the act that yield bliss (in the end)." },
  { number: 670, line1: "எனைத்திட்பம் எய்தியக் கண்ணும் வினைத்திட்பம்", line2: "வேண்டாரை வேண்டாது உலகு.", meaningTa: "எத்தனை வகை உறுதி உடையவராக இருந்தாலும் செயல் உறுதி இல்லாதவரை உயர்ந்தோர் மதிக்கமாட்டார்.", meaningEn: "The great won't esteem those who esteem not firmness of action, whatever other abilities the latter may possess." },
  { number: 671, line1: "சூழ்ச்சி முடிவு துணிவெய்தல் அத்துணிவு", line2: "தாழ்ச்சியுள் தங்குதல் தீது.", meaningTa: "ஆராய்ந்து எண்ணுவதற்கு எல்லை துணிவு கொள்வதே ஆகும், அவ்வாறு கொண்ட துணிவு காலந் தாழ்த்து நிற்பது குற்றமாகும்.", meaningEn: "Consultation ends in forming a resolution (to act); (but) delay in the execution of that resolve is an evil." },
  { number: 672, line1: "தூங்குக தூங்கிச் செயற்பால தூங்கற்க", line2: "தூங்காது செய்யும் வினை.", meaningTa: "காலந்தாழ்த்திச் செய்யவேண்டிய செயல்கள் என்றால் காலந்தாழ்த்துக; காலம் தாழத்தாது செய்ய வேண்டிய செயல்கள் என்றால் காலம்.", meaningEn: "Sleep over such (actions) as may be slept over; (but) never over such as may not be slept over." },
  { number: 673, line1: "ஒல்லும்வா யெல்லாம் வினைநன்றே ஒல்லாக்கால்", line2: "செல்லும்வாய் நோக்கிச் செயல்.", meaningTa: "இயலுமிடத்தில் எல்லாம் செயலைச் செய்து முடித்தல் நல்லது, இயலாவில்லையானால் பயன்படும் இடம் நோக்கியாவது செய்ய வேண்டும்.", meaningEn: "Whenever it is possible (to overcome your someone who fights you) the act (of fighting) is certainly good; if not, endeavour to employ some more." },
  { number: 674, line1: "வினைபகை என்றிரண்டின் எச்சம் நினையுங்கால்", line2: "தீயெச்சம் போலத் தெறும்.", meaningTa: "எற்ற செயலையோ, எதிர்கொண்ட பகையையோ முற்றாக முடிக்காமல் விட்டுவிட்டால் அது நெருப்பை அரை குறையாக அணைத்தது போலக் கேடு.", meaningEn: "When duly considered, the incomplete execution of an undertaleader and hostility will grow and destroy one like the (unextinguished) remnant of a fire." },
  { number: 675, line1: "பொருள்கருவி காலம் வினையிடனொடு ஐந்தும்", line2: "இருள்தீர எண்ணிச் செயல்.", meaningTa: "வேண்டிய பொருள், ஏற்றக்கருவி, தக்க காலம், மேற்கொண்ட தொழில், உரிய இடம் ஆகிய ஐந்தினையும் மயக்கம் தீர எண்ணிச் செய்ய.", meaningEn: "Do an act after a due consideration of the (following) five, that is money, means, time, execution and place." },
  { number: 676, line1: "முடிவும் இடையூறும் முற்றியாங்கு எய்தும்", line2: "படுபயனும் பார்த்துச் செயல்.", meaningTa: "ஈடுபடக்கூடிய ஒரு செயலால் எதிர்பார்க்கப்படும் பயன், அதற்கான முயற்சிக்கு இடையே வரும் தடைகள், அச்செயலாற்றுதவற்கான முறை.", meaningEn: "An act is to be performed after considering the exertion required, the obstacles to be encountered, and the great profit to be gained (on its." },
  { number: 677, line1: "செய்வினை செய்வான் செயன்முறை அவ்வினை", line2: "உள்ளறிவான் உள்ளம் கொளல்.", meaningTa: "ஒரு செயலில் ஈடுபடுகிறவன், அச்செயல் குறித்து முழுமையாக உணர்ந்தவனின் கருத்தினை முதலில் அறிந்து கொள்ள வேண்டும்.", meaningEn: "The method of performance for one who has begun an act is to ascertain the mind of God who knows the secret of it." },
  { number: 678, line1: "வினையான் வினையாக்கிக் கோடல் நனைகவுள்", line2: "யானையால் யானையாத் தற்று.", meaningTa: "ஒரு செயலைச் செய்யும் போது அச் செயலால் மற்றொரு செயலையும் செய்து முடித்துக் கொள்ளல், ஒரு யானையால் மற்றொரு யானையைப்.", meaningEn: "To make one undertaleader the means of accomplishing another (similar to it) is like maleader one rutting elephant the means of capturing another." },
  { number: 679, line1: "நட்டார்க்கு நல்ல செயலின் விரைந்ததே", line2: "ஒட்டாரை ஒட்டிக் கொளல்.", meaningTa: "ஒரு செயலைச் செய்யும்போது நண்பர்களுக்கு நல்லது செய்வதைக் காட்டிலும் தன் பகைவர்களோடு நட்புக் கொள்வது விரைந்து.", meaningEn: "One should rather hasten to secure the alliance of the foes (of one's foes) than perform good offices to one's friends." },
  { number: 680, line1: "உறைசிறியார் உள்நடுங்கல் அஞ்சிக் குறைபெறின்", line2: "கொள்வர் பெரியார்ப் பணிந்து.", meaningTa: "தம்மைவிட வலிமையானவர்களை எதிர்ப்பதற்குத் தம்முடன் இருப்பவர்களே அஞ்சும்போது தாம் எதிர்பார்க்கும் பலன் கிட்டுமானால்.", meaningEn: "Helpers of small states, afraid of their people being frightened, will yield to and acknowledge their superior foes, if the latter offer them a." },
  { number: 681, line1: "அன்புடைமை ஆன்ற குடிப்பிறத்தல் வேந்தவாம்", line2: "பண்புடைமை தூதுரைப்பான் பண்பு.", meaningTa: "நாட்டு மக்கள், அரசு, உறவு இவற்றின் மீது அன்பும், நற்குணம் நிறைந்த குடிப்பிறப்பும், அரசு விரும்பும் பண்பும்.", meaningEn: "The qualification of an ambassador are affection (for his relations) a fitting birth, and the possession of attributes pleasing to royalty." },
  { number: 682, line1: "அன்பறிவு ஆராய்ந்த சொல்வன்மை தூதுரைப்பார்க்கு", line2: "இன்றி யமையாத மூன்று.", meaningTa: "தூது செல்பவருக்குத் தேவைப்படும் மூன்று முக்கியமான பண்புகள் அன்பு, அறிவு, ஆராய்ந்து பேசும் சொல்வன்மை.", meaningEn: "Caring (to his leader), knowledge (of his affairs), and a discriminating power of speech (before other leaders) are the three sine qua non." },
  { number: 683, line1: "நூலாருள் நூல்வல்லன் ஆகுதல் வேலாருள்", line2: "வென்றி வினையுரைப்பான் பண்பு.", meaningTa: "வேற்று நாட்டாரிடம், தனது நாட்டுக்கு வெற்றி ஏற்படும் வண்ணம் செய்தி உரைத்திடும் தூதுவன், நூலாய்ந்து அறிந்தவர்களிலேயே.", meaningEn: "To be powerful in politics among those who are learned (in ethics) is the character of God who speaks." },
  { number: 684, line1: "அறிவுரு வாராய்ந்த கல்விஇம் மூன்றன்", line2: "செறிவுடையான் செல்க வினைக்கு.", meaningTa: "இயற்கை அறிவு, விரும்பத்தக்கத் தோற்றம், ஆராய்ச்சி உடையக் கல்வி ஆகிய இம் மூன்றின் பொருத்தம் உடையவன் தூது உரைக்கும்.", meaningEn: "He may go on a mission (to foreign rulers) who has combined in him all these three that is, (natural) sense, an attractive bearing and well-tried." },
  { number: 685, line1: "தொகச்சொல்லித் தூவாத நீக்கி நகச்சொல்லி", line2: "நன்றி பயப்பதாந் தூது.", meaningTa: "பலவற்றைத் தொகுத்து சொல்லியும், அவற்றுள் பயனற்றவைகளை நீக்கியும், மகிழுமாறு சொல்லியும் தன் தலைவனுக்கு நன்மை.", meaningEn: "He is an ambassador who (in the presence of foreign rulers) speaks briefly, avoids harshness, talks so as to make them smile, and so brings good (to." },
  { number: 686, line1: "கற்றுக்கண் அஞ்சான் செலச்சொல்லிக் காலத்தால்", line2: "தக்கது அறிவதாம் தூது.", meaningTa: "அனைத்து நூல்களையும் கற்றதோடு மட்டும் அல்லாமல், பகை அரசு மனங்கொள்ளுமாறு அவற்றைச் சொல்லவும், ஏற்காதவர் சினந்தால் அவர்.", meaningEn: "He is an ambassador who having studied (politics) talks impressively, isn't afraid of angry looks, and knows (to employ) the art suited to the time." },
  { number: 687, line1: "கடனறிந்து காலங் கருதி இடனறிந்து", line2: "எண்ணி உரைப்பான் தலை.", meaningTa: "ஆற்றவேண்டிய கடமையை அறிந்து, அதற்குரிய காலத்தையும் இடத்தையும் தேர்ந்து, சொல்ல வேண்டியதைத் தெளிவாகச் சிந்தித்துச்.", meaningEn: "He is chief (among ambassadors) who understands the proper good manners (before foreign princes), seeks the (proper) occasion, knows the (most." },
  { number: 688, line1: "தூய்மை துணைமை துணிவுடைமை இம்மூன்றின்", line2: "வாய்மை வழியுரைப்பான் பண்பு.", meaningTa: "துணிவு, துணை, தூய ஒழுக்கம் ஆகிய இம்மூன்றும் தூதுவர்க்குத் தேவையானவைகளாகும்.", meaningEn: "The qualifications of God who faithfully delivers his (leader's) message are purity, the support (of foreign helpers), and boldness, with." },
  { number: 689, line1: "விடுமாற்றம் வேந்தர்க்கு உரைப்பான் வடுமாற்றம்", line2: "வாய்சேரா வன்கணவன்.", meaningTa: "குற்றமானச் சொற்களை வாய் சோர்ந்தும் சொல்லாத உறுதி உடையவனே அரசன் சொல்லியனுப்பிய சொற்களை மற்ற வேந்தர்க்கு உரைக்கும்.", meaningEn: "He alone is fit to communicate (his leader's) reply, who possesses the firmness not to utter even inadvertently what may reflect discredit (on the." },
  { number: 690, line1: "இறுதி பயப்பினும் எஞ்சாது இறைவற்கு", line2: "உறுதி பயப்பதாம் தூது.", meaningTa: "தனக்கு அழிவே தருவதாக இருந்தாலும், அதை எண்ணிப் பயந்து விடாமல் உறுதியுடன் கடமையாற்றுகிறவனே தன்னுடைய தலைவனுக்கு.", meaningEn: "He is the ambassador who fearlessly seeks his leader's good though it should cost him his life (to deliver his message)." },
  { number: 691, line1: "அகலாது அணுகாது தீக்காய்வார் போல்க", line2: "இகல்வேந்தர்ச் சேர்ந்தொழுகு வார்.", meaningTa: "முடிமன்னருடன் பழகுவோர் நெருப்பில் குளிர் காய்வதுபோல அதிகமாக நெருங்கிவிடாமலும், அதிகமாக நீங்கிவிடாமலும் இருப்பார்கள்.", meaningEn: "So let them act who dwell beneath of warlike leaders the palace-roof." },
  { number: 692, line1: "மன்னர் விழைப விழையாமை மன்னரால்", line2: "மன்னிய ஆக்கந் தரும்.", meaningTa: "அரசர் விரும்புகின்றவர்களைத் தாம் விரும்பாமலிருத்தல் அரசரால் நிலையான ஆக்கத்தைப் பெற்றுத் தரும்.", meaningEn: "For helpers not to cover the things wantsd by their leaders will through the leaders themselves yield them everlasting wealth." },
  { number: 693, line1: "போற்றின் அரியவை போற்றல் கடுத்தபின்", line2: "தேற்றுதல் யார்க்கும் அரிது.", meaningTa: "ஆட்சியாளருடன் பழகுவோர் தம்மைக் காக்கக் கருதினால் மோசமான பிழைகள் தம் பங்கில் நேர்ந்து விடாமல் காக்க; பிழைகள்.", meaningEn: "Helpers who would save themselves should avoid (the commission of) serious errors for if the leader's suspicion is once roused, no one can remove it." },
  { number: 694, line1: "செவிச்சொல்லும் சேர்ந்த நகையும் அவித்தொழுகல்", line2: "ஆன்ற பெரியா ரகத்து.", meaningTa: "வல்லமை அமைந்த பெரியாரிடத்தில் செவியை நெருங்கிச் சொல்லுதல் உடன் சேர்ந்து நகைத்தலும் செய்யாமல் ஒழுகவேண்டும்.", meaningEn: "While in the presence of the leader, helpers should neither whisper to nor smile at others." },
  { number: 695, line1: "எப்பொருளும் ஓரார் தொடரார்மற் றப்பொருளை", line2: "விட்டக்கால் கேட்க மறை.", meaningTa: "எப்பொருளையும் உற்றுக் கேட்காமல் தொடர்ந்து வினவாமல் அப்பொருளை அவரே விட்டுச் சொன்னபோது கேட்டறிய வேண்டும்.", meaningEn: "In secret counsel (with others), helpers should neither over-hear anything whatever nor pry into it with inquisitive questions, but (wait to) listen." },
  { number: 696, line1: "குறிப்பறிந்து காலங் கருதி வெறுப்பில", line2: "வேண்டுப வேட்பச் சொலல்.", meaningTa: "ஒருவரின் மனநிலை எவ்வாறு உள்ளது என்பதை அறிந்து, தக்க காலத்தைத் தேர்ந்தெடுத்து, வெறுப்புக்குரியவைகளை விலக்கி, விரும்பத்.", meaningEn: "Knowing the (leader's disposition and seeleader the right time, (the helpers) should in a pleasing manner suggest things such as are desirable and." },
  { number: 697, line1: "வேட்பன சொல்லி வினையில எஞ்ஞான்றும்", line2: "கேட்பினும் சொல்லா விடல்.", meaningTa: "விரும்பிக் கேட்டாலும் கூட, பயனுள்ளவற்றை மட்டுமே சொல்லிப் பயனற்றவைகளைச் சொல்லாமல் விட்டுவிட வேண்டும்.", meaningEn: "Helpers should (always) give agreeable adwrong but on no occasion recommend useless actions, though requested (to do so)." },
  { number: 698, line1: "இளையர் இனமுறையர் என்றிகழார் நின்ற", line2: "ஒளியோடு ஒழுகப் படும்.", meaningTa: "எமக்கு இளையவர்தான்; இன்ன முறையில் உறவுடையவர் தான் என்று ஆட்சிப் பொறுப்பில் இருப்போரை இகழ்ந்துரைக்காமல், அவர்கள்.", meaningEn: "Helpers should behave in accordance with the (Divine) light in the person of leaders and not despise them saying, \"He is our junior (in age) and." },
  { number: 699, line1: "கொளப்பட்டேம் என்றெண்ணிக் கொள்ளாத செய்யார்", line2: "துளக்கற்ற காட்சி யவர்.", meaningTa: "அசைவற்ற தெளிந்த அறிவினை உடையவர் யாம் அரசரால் விரும்பப்பட்டோம் என்று எண்ணி அவர் விரும்பாதவற்றைச் செய்யமாட்டார்.", meaningEn: "Those whose judgement is firm won't do what is disagreeable (to the leader) saying (within." },
  { number: 700, line1: "பழையம் எனக்கருதிப் பண்பல்ல செய்யும்", line2: "கெழுதகைமை கேடு தரும்.", meaningTa: "யாம் அரசர்க்கு பழைமையானவராய் உள்ளோம் எனக்கருதித் தகுதி அல்லாதவற்றைச் செய்யும் உரிமை கேட்டைத்தரும்.", meaningEn: "The (foolish) claim with which a helpers does unbecoming acts because of his (long) familiarity (with the leader) will ensure his ruin." },
  { number: 701, line1: "கூறாமை நோக்கக் குறிப்பறிவான் எஞ்ஞான்றும்", line2: "மாறாநீர் வையக் கணி.", meaningTa: "ஒருவர் எதுவும் பேசாமலிருக்கும் போதே அவர் என்ன நினைக்கிறார் என்பதை முகக்குறிப்பால் உணருகிறவன் உலகத்திற்கே அணியாவான்.", meaningEn: "The helpers who by looleader (at the leader) understands his mind without being told (of it), will be a perpetual ornament to the world which is." },
  { number: 702, line1: "ஐயப் படாஅது அகத்தது உணர்வானைத்", line2: "தெய்வத்தோ டொப்பக் கொளல்.", meaningTa: "ஐயப்படாமல் மனத்தில் உள்ளதை உணரவல்லவனை தெய்வத் தோடு ஒப்பாக கொள்ள வேண்டும்.", meaningEn: "He is to be esteemed a god who is able to ascertain without a doubt what is within (one's mind)." },
  { number: 703, line1: "குறிப்பிற் குறிப்புணர் வாரை உறுப்பினுள்", line2: "யாது கொடுத்தும் கொளல்.", meaningTa: "தான் குறிப்புச் செய்ய, அதைக் கண்டு பிறர் முகத்தையும் கண்ணையும் பார்த்தே அவர் மனக்கருத்தைக் கண்டு சொல்லும் திறம்.", meaningEn: "The leader should ever give whatever (is asked) of his belongings and secure God who, by the indications (of his own mind) is able to read those of." },
  { number: 704, line1: "குறித்தது கூறாமைக் கொள்வாரோ டேனை", line2: "உறுப்போ ரனையரால் வேறு.", meaningTa: "உறுப்புகளால் வேறுபடாத தோற்றமுடையவராக இருப்பினும், ஒருவர் மனத்தில் உள்ளதை, அவர் கூறாமலே உணரக்கூடியவரும், உணர.", meaningEn: "Those who understand one's thoughts without being informed (of it) and those who don't, may (indeed) resemble one another bodily; still are they." },
  { number: 705, line1: "குறிப்பிற் குறிப்புணரா வாயின் உறுப்பினுள்", line2: "என்ன பயத்தவோ கண்?", meaningTa: "குறிப்புக்களால் உள்ளக்குறிப்பை உணராவிட்டால், ஒருவனுடைய உறுப்புகளுள் கண்கள் என்னப் பயன்படும்.", meaningEn: "Of what use are the eyes amongst one's members, if they can't by their own indications dive those of another ?" },
  { number: 706, line1: "அடுத்தது காட்டும் பளிங்குபோல் நெஞ்சம்", line2: "கடுத்தது காட்டும் முகம்.", meaningTa: "கண்ணாடி, தனக்கு உள்ளத்தைக் காட்டுவதுபோல ஒருவரது மனத்தில் உள்ளத்தில் அவரது முகம் காட்டி விடும்.", meaningEn: "As the mirror reflects what is near so does the face show what is uppermost in the mind." },
  { number: 707, line1: "முகத்தின் முதுக்குறைந்தது உண்டோ உவப்பினும்", line2: "காயினும் தான்முந் துறும்.", meaningTa: "உள்ளத்தில் உள்ள விருப்பு வெறுப்புகளை முந்திக் கொண்டு வெளியிடுவதில் முகத்தைப் போல அறிவு மிக்கது வேறெதுவுமில்லை.", meaningEn: "Is there anything so full of knowledge as the face ? (No) it precedes the mind, whether (the latter is) pleased or vexed." },
  { number: 708, line1: "முகம்நோக்கி நிற்க அமையும் அகம்நோக்கி", line2: "உற்ற துணர்வார்ப் பெறின்.", meaningTa: "உள்ளக் குறிப்பை நோக்கி உற்றதை உணரவல்லவரைப் பெற்றால், அவறுடைய முகத்தை நோக்கி நின்றால் போதும்.", meaningEn: "If the leader gets those who by looleader into his mind can understand (and remove) what has occurred (to him) it is enough that he stand looleader." },
  { number: 709, line1: "பகைமையும் கேண்மையும் கண்ணுரைக்கும் கண்ணின்", line2: "வகைமை உணர்வார்ப் பெறின்.", meaningTa: "கண்பார்வையின் வேறுபாடுகளை உணரவல்லவரைப் பெற்றால் கையையும் நட்பையும் அவனுடைய கண்களே சொல்லி விடும்.", meaningEn: "If a leader gets helpers who can read the movements of the eye, the eyes (of foreign leaders) will (themselves) reveal (to him) their hatred or." },
  { number: 710, line1: "நுண்ணியம் என்பார் அளக்குங்கோல் காணுங்கால்", line2: "கண்ணல்லது இல்லை பிற.", meaningTa: "யாம் நுட்பமான அறிவுடையேம் என்று பிறர் கருத்தை அறிபவரின் அளக்குங்கோல், ஆராய்ந்து பார்த்தால் அவனுடையக் கண்களே அல்லாமல்.", meaningEn: "The measuring-rod of those (helpers) who say \"we are acute\" will on inquiry be found to be their (own) eyes and nothing else." },
  { number: 711, line1: "அவையறிநது ஆராய்ந்து சொல்லுக சொல்லின்", line2: "தொகையறிந்த தூய்மை யவர்.", meaningTa: "சொற்களின் தொகுதி அறிந்த தூய்மை உடையவர், அவைக்களத்தின் தன்மை அறிந்து ஏற்றச் சொற்களை ஆராய்ந்து சொல்ல வேண்டும்.", meaningEn: "Let the pure who know the arrangement of words speak with deliberation after ascertaining (the nature of) the court (then assembled)." },
  { number: 712, line1: "இடைதெரிந்து நன்குணர்ந்து சொல்லுக சொல்லின்", line2: "நடைதெரிந்த நன்மை யவர்.", meaningTa: "சொற்களின் வழிமுறையறிந்த நல்லறிவாளர்கள் அவையின் நேரத்தையும், நிலைமையையும் உணர்ந்து உரையாற்ற வேண்டும்.", meaningEn: "Let the good who know the uses of words speak with a clear knowledge after ascertaining the time (suited to the court)." },
  { number: 713, line1: "அவையறியார் சொல்லல்மேற் கொள்பவர் சொல்லின்", line2: "வகையறியார் வல்லதூஉம் இல்.", meaningTa: "அவையின் தன்மை அறியாமல் சொல்லுதலை மேற்கொள்கின்றவர், சொற்களின் வகை அறியாதவரே, அவர் சொல்லவல்லதும் இல்லை.", meaningEn: "Those who undertake to speak without knowing the (nature of the) court are ignorant of the quality of words as well as devoid of the power (of." },
  { number: 714, line1: "ஒளியார்முன் ஒள்ளிய ராதல் வெளியார்முன்", line2: "வான்சுதை வண்ணம் கொளல்.", meaningTa: "அறிவிற் சிறந்தவரின் முன் தானும் அறிவிற் சிறந்தவராக நடந்து கொள்ள வேண்டும், அறிவில்லாதவர் முன் தாமும் வெண் கண்ணம் போல்.", meaningEn: "Helpers should be lights in the assembly of the enlightned, but assume the pure whiteness of mortar (ignorance) in that of fools." },
  { number: 715, line1: "நன்றென்ற வற்றுள்ளும் நன்றே முதுவருள்", line2: "முந்து கிளவாச் செறிவு.", meaningTa: "அறிவு மிகுந்தவரிடையே முந்திச் சென்று பேசாத அடக்கம் ஒருவனுக்கு நன்மை என்று சொல்லப்பட்டவை எல்லாவற்றிலும நல்லது.", meaningEn: "The modesty by which one does not rush forward and speak in (an assembly of) superiors is the best among all (one's) good qualities." },
  { number: 716, line1: "ஆற்றின் நிலைதளர்ந் தற்றே வியன்புலம்", line2: "ஏற்றுணர்வார் முன்னர் இழுக்கு.", meaningTa: "பலதுறை நூல்பொருள்களைக் கேட்டு உணரும் திறம் மிக்கவர்முன்னே ஆற்றல்மிக்க பேச்சாளன் சொல்லால் சிறுமைப்படுவது மேலான.", meaningEn: "To blunder in the presence of those who have acquired a vast store of learning and know (the value of it) is like a good man stumbling (and falling." },
  { number: 717, line1: "கற்றறிந்தார் கல்வி விளங்கும் கசடறச்", line2: "சொல்தெரிதல் வல்லார் அகத்து.", meaningTa: "மாசற்ற சொற்களைத் தேர்ந்தெடுத்து உரை நிகழ்த்துவோரிடமே அவர் கற்றுத் தேர்ந்த கல்வியின் பெருமை விளங்கும்.", meaningEn: "The learning of those who have read and understood (much) will shine in the assembly of those who goodly examine (the nature of) words." },
  { number: 718, line1: "உணர்வ துடையார்முன் சொல்லல் வளர்வதன்", line2: "பாத்தியுள் நீர்சொரிந் தற்று.", meaningTa: "தாமே உணர்கின்ற தன்மை உடையவரின் முன் கற்றவர் பேசுதல், தானே வளரும் பயிருள்ள பாத்தியில் நீரைச் சொரிந்தாற் போன்றது.", meaningEn: "Lecturing to those who have the ability to understand (for themselves) is like watering a bed of plants that are growing (of themselves)." },
  { number: 719, line1: "புல்லவையுள் பொச்சாந்தும் சொல்லற்க நல்லவையுள்", line2: "நன்குசலச் சொல்லு வார்.", meaningTa: "நல்ல அறிஞரின் அவையில் நல்ல பொருளைப் மனதில் பதியுமாறு சொல்லவல்லவர், அறிவில்லாதவரின் கூட்டத்தில் மறந்தும் பேசக் கூடாது.", meaningEn: "Those who are able to speak good things impressively in an assembly of the good should not even forgetfully speak them in that of the low." },
  { number: 720, line1: "அங்கணத்துள் உக்க அமிழ்தற்றால் தங்கணத்தார்", line2: "அல்லார்முன் கோட்டி கொளல்.", meaningTa: "அறிவுள்ளவர்கள், அறிவில்லாதவர்களின் அவையில் பேசுவது, தூய்மையில்லாத முற்றத்தில் சிந்திடும் அமிழ்தம்போல் வீணாகிவிடும்.", meaningEn: "To utter (a good word) in the assembly of those who are of inferior rank is like dropping nectar on the ground." },
  { number: 721, line1: "வகையறிந்து வல்லவை வாய்சோரார் சொல்லின்", line2: "தொகையறிந்த தூய்மை யவர்.", meaningTa: "சொல்லின்வகைகளை அறிந்துமனத்தால் சுத்தமானவர்கள், கற்றவர் அவை, கல்லாதவர் அவை என அறிந்து பேசும்போது, பயத்தால் சொல்.", meaningEn: "The pure who know the classification of words having first ascertained the nature (of the court) won't (through fear) falter in their speech before." },
  { number: 722, line1: "கற்றாருள் கற்றார் எனப்படுவர் கற்றார்முன்", line2: "கற்ற செலச்சொல்லு வார்.", meaningTa: "கற்றவரின் முன் தாம் கற்றவற்றை அவருடைய மனத்தில் பதியுமாறு சொல்ல வல்லவர், கற்றவர் எல்லாரினும் மேலானவராக மதித்துச்.", meaningEn: "Those who can agreeably set forth their acquirements before the learned will be regarded as the most learned among the learned." },
  { number: 723, line1: "பகையகத்துச் சாவார் எளியர் அரியர்", line2: "அவையகத்து அஞ்சா தவர்.", meaningTa: "பகைவர்களுக்கிடையே பயப்படாமல் புகுந்து சாவோர் பலர் உண்டு;பேசுவோர் சிலரேயாவார்.", meaningEn: "Many indeed may (fearlessly) die in the presence of (their) foes; (but) few are those who are fearless in the assembly (of the learned)." },
  { number: 724, line1: "கற்றார்முன் கற்ற செலச்சொல்லித் தாம்கற்ற", line2: "மிக்காருள் மிக்க கொளல்.", meaningTa: "பலதுறை நூல்களையும் கற்றவர் அவையில், அவர்கள் மனங் கொள்ளுமாறு, தான் கற்றவற்றை எல்லாம் சொல்லுக; தான் கற்றவற்றிற்கும்.", meaningEn: "Should agreeably set forth their acquirements before the learned and acquire more (knowledge) from their superiors (in learning)." },
  { number: 725, line1: "ஆற்றின் அளவறிந்து கற்க அவையஞ்சா", line2: "மாற்றங் கொடுத்தற் பொருட்டு.", meaningTa: "அவையில் அஞ்சாது விடைகூறும் பொருட்டாக நூல்களைக் கற்க்கும் நெறியில் அளவை நூல் அறிந்து கற்க வேண்டும்.", meaningEn: "In order to reply fearlessly before a foreign court, (helpers) should learn logic according to the rules (of grammar)." },
  { number: 726, line1: "வாளொடென் வன்கண்ணர் அல்லார்க்கு நூலொடென்", line2: "நுண்ணவை அஞ்சு பவர்க்கு.", meaningTa: "கோழைகளுக்குக் கையில் வாள் இருந்தும் பயனில்லை; அவையில் பேசிட அஞ்சுவோர் பலநூல் கற்றும் பயனில்லை.", meaningEn: "What have they to do with a sword who aren't valiant, or they with learning who are afraid of an intelligent assembly ?" },
  { number: 727, line1: "பகையகத்துப் பேடிகை ஒள்வாள் அவையகத்து", line2: "அஞ்சு மவன்கற்ற நூல்.", meaningTa: "கற்றவர் கூடிய அவையில் பேசப் பயப்படுபவன் கற்ற நூல், பகைமுன்னே நடுங்கும் பேடியின் கையில் இருக்கும் வாளுக்குச் சமம்.", meaningEn: "The learning of God who is diffident before an assembly is like the shining sword of an hermaphrodite in the presence of his foes." },
  { number: 728, line1: "பல்லவை கற்றும் பயமிலரே நல்லவையுள்", line2: "நன்கு செலச்சொல்லா தார்.", meaningTa: "நல்லனவற்றை நல்லவர் கூடிய அவையில் அவர் மனங் கொள்ளச் சொல்லத் தெரியாதவர், பலதுறை நூல்களைக் கற்றிருந்தாலும் உலகிற்குப்.", meaningEn: "Those who can't agreeably speak good things before a good assembly are indeed unprofitable persons inspite of all their various acquirements." },
  { number: 729, line1: "கல்லா தவரின் கடையென்ப கற்றறிந்தும்", line2: "நல்லா ரவையஞ்சு வார்.", meaningTa: "நூல்களைக் கற்றிந்த போதிலும் நல்ல அறிஞரின் அவைக்கு அஞ்சுகின்றவர், கல்லாதவரை விடக் கடைப்பட்டவர் என்று கூறுவர்.", meaningEn: "They who, though they have learned and understood, are yet afraid of the assembly of the good, are said to be inferior (even) to the illiterate." },
  { number: 730, line1: "உளரெனினும் இல்லாரொடு ஒப்பர் களன்அஞ்சிக்", line2: "கற்ற செலச்சொல்லா தார்.", meaningTa: "அவையைப் பார்த்துப் பயந்து, படித்தவற்றை அவைக்கு ஏற்பச் சொல்லத் தெரியாதவர், வாழ்ந்தாலும் வாழாதவர்க்குச் சமமே.", meaningEn: "Those who through fear of the assembly are unable to set forth their learning in an interesting manner, though alive, are yet like the dead." },
  { number: 731, line1: "தள்ளா விளையுளும் தக்காரும் தாழ்விலாச்", line2: "செல்வரும் சேர்வது நாடு.", meaningTa: "குறையாத விளைபொருளும் தக்க அறிஞரும் கேடில்லாத செல்வம் உடையவரும் கூடிப் பொருந்தியுள்ள நாடே நாடாகும்.", meaningEn: "A leaderdom is that in which (those who carry on) a complete cultivation, good persons, and." },
  { number: 732, line1: "பெரும்பொருளால் பெட்டக்க தாகி அருங்கேட்டால்", line2: "ஆற்ற விளைவது நாடு.", meaningTa: "மிக்க பொருள் வளம் உடையதாய், எல்லோரும் விரும்பத்தக்கதாய் கேடு இல்லாததாய், மிகுதியாக விளைபொருள் தருவதே நாடாகும்.", meaningEn: "A leaderdom is that which is wants for its immense wealth, and which grows greatly in doing well, being free from destructive causes." },
  { number: 733, line1: "பொறையொருங்கு மேல்வருங்கால் தாங்கி இறைவற்கு", line2: "இறையொருங்கு நேர்வது நாடு.", meaningTa: "சுமை ஒரு சேரத் தன் மேல் வரும் போது தாங்கி, அரசனுக்கு இறைபொருள் முழுதும் தர வல்லது நாடாகும்.", meaningEn: "A leaderdom is that which can bear any burden that may be pressed on it (from adjoining leaderdoms) and (yet) pay the full tribute to its leader." },
  { number: 734, line1: "உறுபசியும் ஓவாப் பிணியும் செறுபகையும்", line2: "சேரா தியல்வது நாடு.", meaningTa: "பசியும், பிணியும், பகையுமற்ற நாடுதான் சிறந்த நாடு எனப் பாராட்டப்படும்.", meaningEn: "A leaderdom is that which continues to be free from excessive starvation, irremediable epidemics, and destructive foes." },
  { number: 735, line1: "பல்குழுவும் பாழ்செய்யும் உட்பகையும் வேந்தலைக்கும்", line2: "கொல்குறும்பும் இல்லது நாடு.", meaningTa: "பல குழுக்களாகப் பிரிந்து பாழ்படுத்தும் உட்பகையும், அரசில் ஆதிக்கம் செலுத்தும் கொலைகாரர்களால் விளையும் பொல்லாங்கும்.", meaningEn: "A leaderdom is that which is without various (irregular) associations, destructive internal people who fight you, and murderous savages who." },
  { number: 736, line1: "கேடறியாக் கெட்ட இடத்தும் வளங்குன்றா", line2: "நாடென்ப நாட்டின் தலை.", meaningTa: "எந்த வகையிலும் கெடுதலை அறியாமல், ஒருவேளை கெடுதல் ஏற்படினும் அதனைச் சீர் செய்யுமளவுக்கு வளங்குன்றா நிலையில் உள்ள.", meaningEn: "The learned say that the best leaderdom is that which knows no evil (from its foes), and, if injured (at all), suffers no diminution in its." },
  { number: 737, line1: "இருபுனலும் வாய்ந்த மலையும் வருபுனலும்", line2: "வல்லரணும் நாட்டிற்கு உறுப்பு.", meaningTa: "ஆற்றுநீரும், ஊற்றுநீரும் உயரமும் அகலமும் உடைய வாய்ப்பான மலையும், மழை நீரும், அழிக்க முடியாத கோட்டையும் நாட்டிற்குத்.", meaningEn: "The constituents of a leaderdom are the two waters (from above and below), well situated hills and an undestructible fort." },
  { number: 738, line1: "பிணியின்மை செல்வம் விளைவின்பம் ஏமம்", line2: "அணியென்ப நாட்டிவ் வைந்து.", meaningTa: "நோய் இல்லாமை, செல்வம், விளைச்சல், மகிழ்ச்சி, நல்ல காவல் இவை ஐந்தும் ஒரு நாட்டிற்கு அழகு என்று நூலோர் கூறுவர்.", meaningEn: "Freedom from epidemics, wealth, produce, happiness and protection (to subjects); these five, the learned, say, are the ornaments of a leaderdom." },
  { number: 739, line1: "நாடென்ப நாடா வளத்தன நாடல்ல", line2: "நாட வளந்தரு நாடு.", meaningTa: "தன் மக்கள் சிரமப்படாமல் இருக்க அதிக உற்பத்தியைத் தருவதே நாடு என்று நூலோர் கூறுவர்; தேடிவருந்திப் பெறும் நிலையில்.", meaningEn: "The learned say that those are leaderdom whose wealth isn't laboured for, and those not, whose wealth is only obtained through labour." },
  { number: 740, line1: "ஆங்கமை வெய்தியக் கண்ணும் பயமின்றே", line2: "வேந்தமை வில்லாத நாடு.", meaningTa: "நல்ல அரசு அமையாத நாட்டில் எல்லாவித வளங்களும் இருந்தாலும் எந்தப் பயனும் இல்லாமற் போகும்.", meaningEn: "Although in possession of all the above mentioned excellences, these are indeed of no use to a country, in the absence of harmony between the leader." },
  { number: 741, line1: "ஆற்று பவர்க்கும் அரண்பொருள் அஞ்சித்தற்", line2: "போற்று பவர்க்கும் பொருள்.", meaningTa: "போர் செய்யச் செல்பவர்க்கும் அரண் சிறந்ததாகும், அஞ்சித் தன்னை புகழிடமாக அடைந்தவர்க்கும் அது சிறந்ததாகும்.", meaningEn: "A fort is an object of importance to those who march (against their foes) as well as to those who through fear (of pursuers) would seek it for shelter." },
  { number: 742, line1: "மணிநீரும் மண்ணும் மலையும் அணிநிழற்", line2: "காடும் உடைய தரண்.", meaningTa: "மணிபோல் தெளிந்த நீரும், வெட்ட வெளியான நிலமும், மலையும், அழகிய நிழல் உடைய காடும் ஆகிய இவை நான்கும் உள்ளதே அரண் ஆகும்.", meaningEn: "A fort is that which has everlasting water, plains, mountains and cool shady forests." },
  { number: 743, line1: "உயர்வகலம் திண்மை அருமைஇந் நான்கின்", line2: "அமைவரண் என்றுரைக்கும் நூல்.", meaningTa: "உயரம், அகலம், உறுதி, பகைவரால் அழிக்க இயலாத அமைப்பு ஆகிய நான்கும் அமைந்திருப்பதே அரணுக்குரிய இலக்கணமாகும்.", meaningEn: "The learned say that a fortress is an enclosure having these four (qualities) that is, height, breadth, strength and inaccessibility." },
  { number: 744, line1: "சிறுகாப்பிற் பேரிடத்த தாகி உறுபகை", line2: "ஊக்கம் அழிப்ப தரண்.", meaningTa: "காக்க வேண்டிய இடம் சிறியதாய், மற்ற இடம் பெரிய பரப்புள்ளதாய், தன்னை எதிர்த்துவந்த பகைவரிருடைய ஊக்கத்தை அழிக்க வல்லது.", meaningEn: "A fort is that which has an extensive space within, but only small places to be guarded, and such as can destroy the courage of besieging foes." },
  { number: 745, line1: "கொளற்கரிதாய்க் கொண்டகூழ்த் தாகி அகத்தார்", line2: "நிலைக்கெளிதாம் நீரது அரண்.", meaningTa: "முற்றுகையிட்டுக் கைப்பற்ற முடியாமல், உள்ளேயிருக்கும் படையினர்க்கும் மக்களுக்கும் வேண்டிய உணவுடன், எதிரிகளுடன் போர்.", meaningEn: "A fort is that which can't be captured, which abounds in suitable provisions, and affords a position of easy defence to its inmates." },
  { number: 746, line1: "எல்லாப் பொருளும் உடைத்தாய் இடத்துதவும்", line2: "நல்லாள் உடையது அரண்.", meaningTa: "தன்னிடம் எல்லாப் பொருளும் உடையதாய், போர் நெருக்கடியானவிடத்தில் உதவ வல்ல நல்ல விரர்களை உடையது அரண் ஆகும்.", meaningEn: "A fort is that which has all (needful) things, and excellent heroes that can help it against destruction (by foes)." },
  { number: 747, line1: "முற்றியும் முற்றா தெறிந்தும் அறைப்படுத்தும்", line2: "பற்றற் கரியது அரண்.", meaningTa: "முற்றுகையிட்டோ, முற்கையிடாமலோ அல்லது வஞ்சனைச் சூழ்ச்சியாலோ பகைவரால் கைப்பற்றப்பட முடியாத வலிமையுடையதே அரண் எனப்படும்.", meaningEn: "A fort is that which can't be captured by blockading, assaulting, or undermining it." },
  { number: 748, line1: "முற்றாற்றி முற்றி யவரையும் பற்றாற்றிப்", line2: "பற்றியார் வெல்வது அரண்.", meaningTa: "முற்றுகையிடுவதில் வல்லமை கொண்டு முற்றுகை இட்டவரையும், பற்றை விடாமலிருந்து வெல்வதற்கு உரியது அரண் ஆகும்.", meaningEn: "That is a fort whose inmates are able to overcome without losing their ground, even abler people who have besieged it." },
  { number: 749, line1: "முனைமுகத்து மாற்றலர் சாய வினைமுகத்து", line2: "வீறெய்தி மாண்ட தரண்.", meaningTa: "போர் தொடங்கிய உடனே பகைவர் அழியும்படி உள்ளிருப்போர் செய்யும் போர்த்திறத்தால் சிறந்த விளங்குவதே அரண்.", meaningEn: "A fort is that which derives excellence from the stratagems made (by its inmates) to defeat their people who fight you in the battlefield." },
  { number: 750, line1: "எனைமாட்சித் தாகியக் கண்ணும் வினைமாட்சி", line2: "இல்லார்கண் இல்லது அரண்.", meaningTa: "கோட்டைக்குத் தேவையான எல்லாவித சிறப்புகளும் இருந்தாலும்கூட உள்ளிருந்து செயல்படுவோர் திறமையற்றவர்களாக இருந்தால் எந்தப்.", meaningEn: "Although a fort may possess all (the above-said) excellence, it is, as it were without these, if its inmates possess not the excellence of action." },
  { number: 751, line1: "பொருளல் லவரைப் பொருளாகச் செய்யும்", line2: "பொருளல்லது இல்லை பொருள்.", meaningTa: "தகுதி அற்றவரையும்கூடத் தகுதி உடையவராக ஆக்கிவிடும் தகுதி உடையது, பணமே அன்றி வேறொன்றும் இல்லை.", meaningEn: "Besides wealth there is nothing that can change people of no importance into those of (some) importance." },
  { number: 752, line1: "இல்லாரை எல்லாரும் எள்ளுவர் செல்வரை", line2: "எல்லாரும் செய்வர் சிறப்பு.", meaningTa: "பொருள் இல்லாதவரை எல்லாரும் இகழ்வார், செல்வரை எல்லாரும் சிறப்பு செய்வர்.", meaningEn: "All despise the poor; (but) all praise the rich." },
  { number: 753, line1: "பொருளென்னும் பொய்யா விளக்கம் இருளறுக்கும்", line2: "எண்ணிய தேயத்துச் சென்று.", meaningTa: "பணம் எனப்படும் அணையா விளக்கு அயல்நாட்டிற்குள்ளும் சென்று பகையாகிய இருளைப் போக்கும்.", meaningEn: "The imperishable light of wealth goes into regions wantsd (by its owner) and destroys the darkness (of fighting therein)." },
  { number: 754, line1: "அறன்ஈனும் இன்பமும் ஈனும் திறனறிந்து", line2: "தீதின்றி வந்த பொருள்.", meaningTa: "நேரிய வழிகை அறிந்து, தீமை ஏதும் செய்யாமல் சம்பாதிக்கப்பட்ட பணம் அறத்தையும் தரம்; இன்பத்தையும் தரும்.", meaningEn: "The wealth acquired with a knowledge of the proper means and without foul practices will yield goodness and happiness." },
  { number: 755, line1: "அருளொடும் அன்பொடும் வாராப் பொருளாக்கம்", line2: "புல்லார் புரள விடல்.", meaningTa: "பிறர்மீது இரக்கமும் அன்பும் இல்லாமல் சேர்க்கும் பணச் சேமிப்பை ஏற்காது விட்டு விடுக.", meaningEn: "Should rather avoid than seek the accumulation of wealth which does not flow in with mercy and caring." },
  { number: 756, line1: "உறுபொருளும் உல்கு பொருளும்தன் ஒன்னார்த்", line2: "தெறுபொருளும் வேந்தன் பொருள்.", meaningTa: "வரியும், சுங்கமும், வெற்றி கொள்ளப்பட்ட பகை நாடு செலுத்தும் கப்பமும் அரசுக்குரிய பொருளாகும்.", meaningEn: "The spoils of slaughtered foes; these are the royal revenues." },
  { number: 757, line1: "அருளென்னும் அன்பீன் குழவி பொருளென்னும்", line2: "செல்வச் செவிலியால் உண்டு.", meaningTa: "அன்பு பெற்றெடுத்த அருள் என்னும் குழந்தை, பொருள் எனப்படும் இன்பம் தரும் வளர்ப்புத் தாயால் வளரும்.", meaningEn: "The child mercy which is borne by caring grows under the care of the rich nurse of wealth." },
  { number: 758, line1: "குன்றேறி யானைப்போர் கண்டற்றால் தன்கைத்தொன்று", line2: "உண்டாகச் செய்வான் வினை.", meaningTa: "தன் கையிலே பணம் இருக்க ஒரு செயலைச் செய்யத் தொடங்குவது, ஒருவன் மலை மேல் ஏறி நின்று யானைச் சண்டையைக் கண்டது போலாம்.", meaningEn: "An undertaleader of one who has wealth in one's hands is like viewing an elephant-fight from a hill-top." },
  { number: 759, line1: "செய்க பொருளைச் செறுநர் செருக்கறுக்கும்", line2: "எஃகதனிற் கூரிய தில்.", meaningTa: "ஒருவன் பொருளை ஈட்டவேண்டும், அவனுடைய பகைவரின் செருக்கைக் கெடுக்க வல்ல வாள் அதைவிடக் கூர்மையானது வேறு இல்லை.", meaningEn: "Accumulate wealth; it will destroy the arrogance of (your) foes; there is no weapon sharper than it." },
  { number: 760, line1: "ஒண்பொருள் காழ்ப்ப இயற்றியார்க்கு எண்பொருள்", line2: "ஏனை இரண்டும் ஒருங்கு.", meaningTa: "நல்ல வழியில் மிகுதியாகப் பணம் சேர்த்தவர்க்கு மற்ற அறமும் இன்பமும் எளிதாக் கிடைக்கும் பொருள்களாகும்.", meaningEn: "To those who have honestly acquired an abundance of riches, the other two, (goodness and pleasure) are things easy (of acquisition)." },
  { number: 761, line1: "உறுப்பமைந்து ஊறஞ்சா வெல்படை வேந்தன்", line2: "வெறுக்கையுள் எல்லாம் தலை.", meaningTa: "தரைப்படை, கப்பல் படை, விமானப்படை, காவல்துறை என நாட்டைக் காப்போர் பிரிவினால் நிறைந்து, போர்க்களத்தில் புண்பட அஞ்சாது,.", meaningEn: "The army which is complete in (its) parts and conquers without fear of wounds is the chief wealth of the leader." },
  { number: 762, line1: "உலைவிடத்து ஊறஞ்சா வன்கண் தொலைவிடத்துத்", line2: "தொல்படைக் கல்லால் அரிது.", meaningTa: "போரில் அழிவு வந்தவிடத்தில் வலிமைக் குன்றினாலும், இடையூறுகளுக்கு அஞ்சாத அஞ்சாமை தொன்றுதொட்டுப் பெருமை உடையபடைக்கு.", meaningEn: "Ancient army can alone have the valour which makes it stand by its leader at the time of defeat, fearless of wounds and unmindful of its reduced." },
  { number: 763, line1: "ஒலித்தக்கால் என்னாம் உவரி எலிப்பகை", line2: "நாகம் உயிர்ப்பக் கெடும்.", meaningTa: "எலியாகிய பகைக்கூடி கடல் போல் ஒலித்தாலும் என்ன தீங்கு ஏற்ப்படும், பாம்பு மூச்சு விட்ட அளவில் அவைக் கெட்டழியும்.", meaningEn: "What if (a host of) hostile rats roar like the sea ? They will perish at the mere breath of the cobra." },
  { number: 764, line1: "அழிவின்றி அறைபோகா தாகி வழிவந்த", line2: "வன்க ணதுவே படை.", meaningTa: "அழிவு இல்லாததாய் வஞ்சனைக்கு இரையாகாததாய், தொன்று தொட்டுவந்த அஞ்சாமை உடையதே படையாகும்.", meaningEn: "That indeed is an army which has stood firm of old without suffering destruction or deserting (to the someone who fights you)." },
  { number: 765, line1: "கூற்றுடன்று மேல்வரினும் கூடி எதிர்நிற்கும்", line2: "ஆற்ற லதுவே படை.", meaningTa: "எமனே எதிர்த்து வந்தாலும், கூடி நின்று எதிர்த்துச் சண்டை இடும் ஆற்றலை உடையதே படை.", meaningEn: "That indeed is an army which is capable of offering a united resistance, even if Yama advances against it with fury." },
  { number: 766, line1: "மறமானம் மாண்ட வழிச்செலவு தேற்றம்", line2: "எனநான்கே ஏமம் படைக்கு.", meaningTa: "வீரம், மானம், நல்ல வழியில் நடத்தல், அரசி்ன நம்பிக்கைக்கு உரியது ஆதல் எனும் நான்கும் படைக்கு காவல் அரண்களாகும்.", meaningEn: "Valour, honour, following in the excellent-footsteps (of its predecessors) and trust-worthiness; these four alone constitute the safeguard of an army." },
  { number: 767, line1: "தார்தாங்கிச் செல்வது தானை தலைவந்த", line2: "போர்தாங்கும் தன்மை அறிந்து.", meaningTa: "களத்தில், முதலில் எதிர்கொள்ளும் போரைத் தாங்கித் தகர்க்கும் ஆற்றலை அறிந்திருப்பின், அதுவே வெற்றி மாலை தாங்கிச்.", meaningEn: "That is an army which knowing the art of warding off an impending struggle, can bear against the dust-van (of a hostile force)." },
  { number: 768, line1: "அடல்தகையும் ஆற்றலும் இல்லெனினும் தானை", line2: "படைத்தகையால் பாடு பெறும்.", meaningTa: "போர் செய்யும் வீரமும் ஆற்றலுமும் இல்லையானால் படைத்தன்னுடைய அணிவகுப்பால் பெருமை பெறும்.", meaningEn: "Though destitute of courage to fight and strength (to endure), an army may yet gain a good name by the splendour of its appearance." },
  { number: 769, line1: "சிறுமையும் செல்லாத் துனியும் வறுமையும்", line2: "இல்லாயின் வெல்லும் படை.", meaningTa: "சிறுத்துவிடாமலும், தலைவனை வெறுத்து விடாமலும், பயன்படாத நிலை இல்லாமலும் உள்ள படைதான் வெற்றி பெற முடியும்.", meaningEn: "An army can triumph (over its foes) if it is free from diminution; irremediable aversion and poverty." },
  { number: 770, line1: "நிலைமக்கள் சால உடைத்தெனினும் தானை", line2: "தலைமக்கள் இல்வழி இல்.", meaningTa: "சிறந்த வீரர்கள் அதிகம் இருந்தாலும், படைக்கு நல்ல தலைவன் இல்லை என்றால் அந்தப் படை போரில் நிலைத்து நிற்காது.", meaningEn: "Though an army may contain a large number of permanent soldiers, it can't last if it has no generals." },
  { number: 771, line1: "என்னைமுன் நில்லன்மின் தெவ்விர் பலரென்னை", line2: "முன்நின்று கல்நின் றவர்.", meaningTa: "பகைவர்கேள! என் அரசின் முன்னே போரிட நிற்காதீர்; உங்களைப் போலவே இதற்கு முன்பு பலர் நின்றனர்; எல்லாம் மறைந்து இப்போது.", meaningEn: "O my foes, stand not before my leader; (for) many are those who did so but afterwards stood (in the shape of) statues." },
  { number: 772, line1: "கான முயலெய்த அம்பினில் யானை", line2: "பிழைத்தவேல் ஏந்தல் இனிது.", meaningTa: "காட்டில் ஓடுகின்ற முயலை நோக்கி குறிதவறாமல் எய்த அம்பை ஏந்துதலைவிட, வெட்ட வெளியில் நின்ற யானை மேல் எறிந்து தவறிய வேலை.", meaningEn: "It is more pleasant to hold the dart that has missed an elephant than that which has hit hare in the forest." },
  { number: 773, line1: "பேராண்மை என்ப தறுகண்ஒன் றுற்றக்கால்", line2: "ஊராண்மை மற்றதன் எஃகு.", meaningTa: "பகைவர் மீது இரக்கம் காட்டாமல் இருப்பதை மிகுந்த ஆண்மை என்பர்; ஆனால், அந்தப் பகைவர்க்கு ஒரு தாழ்வு வரும்போது அவர் மீது.", meaningEn: "The learned say that fierceness (incontest with a foe) is indeed great valour; but to become a benefactor in case of accident (to a foe) is the." },
  { number: 774, line1: "கைவேல் களிற்றொடு போக்கி வருபவன்", line2: "மெய்வேல் பறியா நகும்.", meaningTa: "கையிலிருந்த வேலினை யானையின் மீது வீசி விட்டதால் களத்தில் போரினைத் தொடர வேறு வேல் தேடுகிற வீரன், தன் மார்பின்மீதே ஒரு.", meaningEn: "The hero who after casting the lance in his hand on an elephant, comes (in search of another) will pluck the one (that sticks) in his body and laugh." },
  { number: 775, line1: "விழித்தகண் வேல்கொண டெறிய அழித்திமைப்பின்", line2: "ஒட்டன்றோ வன்க ணவர்க்கு.", meaningTa: "களத்தில் பகைவர் வீசிடும் வேல் பாயும்போது விழிகளை இமைத்து விட்டால்கூட அது புறமுதுகுகாட்டி ஓடுவதற்குஒப்பாகும்.", meaningEn: "Is it not a defeat to the valiant to wink and destroy their ferocious look when a lance in cast at them (by their foe) ?" },
  { number: 776, line1: "விழுப்புண் படாதநாள் எல்லாம் வழுக்கினுள்", line2: "வைக்கும்தன் நாளை எடுத்து.", meaningTa: "வீரன் தன் கழிந்த நாட்களைக் கணக்கிட்டு, விழுப்புண் படாத நாட்களை எல்லாம் பயன் படாமல் தவறிய நாட்களுள் சேர்ப்பான்.", meaningEn: "The hero will reckon among wasted days all those on which he had not received severe wounds." },
  { number: 777, line1: "சுழலும் இசைவேண்டி வேண்டா உயிரார்", line2: "கழல்யாப்புக் காரிகை நீர்த்து.", meaningTa: "தம்முடன் சொர்க்கத்திற்கு வராது பூமியில் மட்டு் நிலைத்து நிற்கும் புகழை விரும்பி, உயிரையும் விரும்பாத வீரர், தம்.", meaningEn: "The fastening of ankle-ring by those who disire a world-wide a good name and not (the safety of) their lives is like adorning (themselves)." },
  { number: 778, line1: "உறின்உயிர் அஞ்சா மறவர் இறைவன்", line2: "செறினும் சீர்குன்றல் இலர்.", meaningTa: "தலைவன் சினந்தாலும் சிறப்புக் குறையாமல் கடமை ஆற்றுபவர்கள்தான், போர்களத்தில் உயிரைப் பற்றிக் கலங்காத வீர மறவர்கள் எனப்.", meaningEn: "The heroes who aren't afraid of losing their life in a contest won't cool their ardour, even if the leader prohibits (their fighting)." },
  { number: 779, line1: "இழைத்தது இகவாமைச் சாவாரை யாரே", line2: "பிழைத்தது ஒறுக்கிற் பவர்.", meaningTa: "சபதம் செய்தவாறு களத்தில் சாவதற்குத் துணிந்த வீரனை யாராவது இழித்துப் பேச முடியுமா? முடியாது.", meaningEn: "Who would reproach with failure those who seal their oath with their death ?" },
  { number: 780, line1: "புரந்தார்கண் நீர்மல்கச் சாகிற்பின் சாக்காடு", line2: "இரந்துகோள் தக்கது உடைத்து.", meaningTa: "தன்னைக் காத்த தலைவனுடைய கண்களில் நீர் பெருகுமாறு வீரமரணம் அடைந்தால், அத்தகைய மரணத்தை யாசித்தாவது பெற்றுக் கொள்வதில்.", meaningEn: "If (heroes) can so die as to fill with tears the eyes of their rulers, such a death deserves to be obtained even by begging." },
  { number: 781, line1: "செயற்கரிய யாவுள நட்பின் அதுபோல்", line2: "வினைக்கரிய யாவுள காப்பு.", meaningTa: "நட்புக் கொள்வது போன்ற அரிய செயல் இல்லை அதுபோல் பாதுகாப்புக்கு ஏற்ற செயலும் வேறொன்றில்லை.", meaningEn: "What so sure defence 'gainst all that foe can do?" },
  { number: 782, line1: "நிறைநீர நீரவர் கேண்மை பிறைமதிப்", line2: "பின்னீர பேதையார் நட்பு.", meaningTa: "பிறை, நாளும் வளர்வதுபோல, அறிவுடையார் நட்பு வளரும்; முழு நிலவு தேய்வது போலப் பேதைகளின் நட்பு தேயும்.", meaningEn: "The friendship of the wise waxes like the new moon; (but) that of fools wanes like the full moon." },
  { number: 783, line1: "நவில்தொறும் நூல்நயம் போலும் பயில்தொறும்", line2: "பண்புடை யாளர் தொடர்பு.", meaningTa: "படிக்கப் படிக்க இன்பம் தரும் நூலின் சிறப்பைப் போல் பழகப் பழக இன்பம் தரக்கூடியது பண்புடையாளர்களின் நட்பு.", meaningEn: "Like learning, the friendship of the noble, the more it is cultivated, the more delightful does it become." },
  { number: 784, line1: "நகுதற் பொருட்டன்று நட்டல் மிகுதிக்கண்", line2: "மேற்செனறு இடித்தற் பொருட்டு.", meaningTa: "நட்பு என்பது சிரித்து மகிழ்வதற்காக அல்ல; நண்பர்கள் நல்வழி தவறிச் செல்லும்பொழுது இடித்துரைத்துத் திருத்துவதற்காகும்.", meaningEn: "Friendship is to be practised not for the purpose of laughing but for that of being beforehand in giving one another sharp rebukes in case of." },
  { number: 785, line1: "புணர்ச்சி பழகுதல் வேண்டா உணர்ச்சிதான்", line2: "நட்பாங் கிழமை தரும்.", meaningTa: "நட்புச் செய்வதற்குத் தொடர்பும் பழக்கமும் வேண்டியதில்லை, ஒத்த உணர்ச்சியே நட்பு ஏற்படுத்துவதற்கு வேண்டிய உரிமையைக்.", meaningEn: "Living together and holding frequent intercourse aren't necessary (for friendship); (mutual) understanding can alone create a claim for it." },
  { number: 786, line1: "முகநக நட்பது நட்பன்று நெஞ்சத்து", line2: "அகநக நட்பது நட்பு.", meaningTa: "இன்முகம் காட்டுவது மட்டும் நட்புக்கு அடையாளமல்ல; இதயமார நேசிப்பதே உண்மையான நட்பாகும்.", meaningEn: "The caring that dwells (merely in the smiles of the face isn't friendship; (but) that which dwells deep in the smiles of the heart is true friendship." },
  { number: 787, line1: "அழிவி னவைநீக்கி ஆறுய்த்து அழிவின்கண்", line2: "அல்லல் உழப்பதாம் நட்பு.", meaningTa: "அழிவைத் தரும் தீமைகளிலிருந்து நீக்கி, நல்ல வழியில் நடக்கச் செய்து, அழிவுவந்த காலத்தில் உடனிருந்து துன்பப்படுவதே.", meaningEn: "Friendship turns aside from evil (ways) makes (him) walk in the (good) way, and, in case of loss if shares his sorrow (with him)." },
  { number: 788, line1: "உடுக்கை இழந்தவன் கைபோல ஆங்கே", line2: "இடுக்கண் களைவதாம் நட்பு.", meaningTa: "உடைநெகிழ்ந்தவனுடைய கை, உடனே உதவிக்காப்பது போல் அப்போதே சென்று துன்பத்தைக் களைவது நட்பு.", meaningEn: "Friendship hastens to the rescue of the afflicted (as readily) as the hand of one whose garment is loosened (before an assembly)." },
  { number: 789, line1: "நட்பிற்கு வீற்றிருக்கை யாதெனின் கொட்பின்றி", line2: "ஒல்லும்வாய் ஊன்றும் நிலை.", meaningTa: "நட்பின் அரியணை எது என்றால், எப்போதும் மாறாமல் முடிந்தபோது எல்லாம் ஒருவர்க்கு ஒருவர் உதவுவதேயாம்.", meaningEn: "Friendship may be said to be on its throne when it possesses the power of supporting one at all times and under all circumstances, (in the practice." },
  { number: 790, line1: "இனையர் இவரெமக்கு இன்னம்யாம் என்று", line2: "புனையினும் புல்லென்னும் நட்பு.", meaningTa: "இவர் எமக்கு இத்தன்மையானவர், யாம் இவர்க்கு இத் தன்மையுடையேம் என்று புனைந்துரைத்தாலும் நட்பு சிறப்பிழந்து விடும்.", meaningEn: "Though friends may praise one another saying, \"He is so intimate with us, and we so much (with him)\"; (still) such friendship will appear mean." },
  { number: 791, line1: "நாடாது நட்டலிற் கேடில்லை நட்டபின்", line2: "வீடில்லை நட்பாள் பவர்க்கு.", meaningTa: "ஆராய்ந்து பாராமல் கொண்டிடும் தீய நட்பு, அந்த நட்பிலிருந்து விடுபட முடியாத அளவுக்குக் கேடுகளை உண்டாக்கும்.", meaningEn: "As those who are of a friendly nature won't forsake (a friend) after once loving (him), there is no evil so great as contracting a friendship without." },
  { number: 792, line1: "ஆய்ந்தாய்ந்து கொள்ளாதான் கேண்மை கடைமுறை", line2: "தான்சாம் துயரம் தரும்.", meaningTa: "ஒருவனது குணத்தையும் குற்றத்தையும் நன்கு எண்ணி நட்புக் கொள்ளாதவனுக்கு, அந்த நட்பு இறுதியில் அவன் சாவதற்கு ஏற்ற.", meaningEn: "The friendship contracted by God who has not made repeated inquiry will in the end grieve (him) to death." },
  { number: 793, line1: "குணமும் குடிமையும் குற்றமும் குன்றா", line2: "இனனும் அறிந்தியாக்க நட்பு.", meaningTa: "ஒருவனது குணம், குடும்பப் பிறப்பு, குற்றம், குறையாத சுற்றம் ஆகியவற்றை அறிந்து நட்புக் கொள்க.", meaningEn: "Make friendship (with one) after ascertaining (his) character, birth, defects and the whole of one's relations." },
  { number: 794, line1: "குடிப்பிறந்து தன்கண் பழிநாணு வானைக்", line2: "கொடுத்தும் கொளல்வேண்டும் நட்பு.", meaningTa: "நல்ல குடியில் பிறந்து தன்மீது சொல்லப்படும் பழிக்கு அஞ்சு பவனின் நட்பை விலை கொடுத்தாவது கொள்ள வேண்டும்.", meaningEn: "The friendship of one who belongs to a (good) family and is afraid of (being charged with) guilt, is worth even purchasing." },
  { number: 795, line1: "அழச்சொல்லி அல்லது இடித்து வழக்கறிய", line2: "வல்லார்நடபு ஆய்ந்து கொளல்.", meaningTa: "நன்மை இல்லாதச் சொற்களைக் கண்டபோது வருந்தும்படியாக இடிந்துச் சொல்லி, உலகநடையை அறிய வல்லவரின் நட்பை ஆராய்ப்து கொள்ள.", meaningEn: "You should examine and secure the friendship of those who can speak so as to make you weep over a crime (before its commission) or rebuke you." },
  { number: 796, line1: "கேட்டினும் உண்டோர் உறுதி கிளைஞரை", line2: "நீட்டி அளப்பதோர் கோல்.", meaningTa: "எவன் நமக்கு உற்ற நண்பன் என்பதை நீட்டி அளந்து கொள்ளும் அறிவு நம் துன்பத்தில் உண்டு.", meaningEn: "Even in ruin there is some good; (for) it is a rod by which one may measure fully (the affection of one's) relations." },
  { number: 797, line1: "ஊதியம் என்பது ஒருவற்குப் பேதையார்", line2: "கேண்மை ஒரீஇ விடல்.", meaningTa: "அறிவில்லாதவரோடு கொண்ட நட்பை விட்டு விடுவது, ஒருவனுக்கு இலாபம்.", meaningEn: "It is indead a gain for one to renounce the friendship of fools." },
  { number: 798, line1: "உள்ளற்க உள்ளம் சிறுகுவ கொள்ளற்க", line2: "அல்லற்கண் ஆற்றறுப்பார் நட்பு.", meaningTa: "ஊக்கம் குறைவதற்குக் காரணமான செயல்களை எண்ணாமலிருக்க வேண்டும், அதுபோல் துன்பம் வந்த போது கைவிடுகின்றவரின் நட்பைக்.", meaningEn: "Don't think of things that discourage your mind, nor contract friendship with those who would forsake you in adversity." },
  { number: 799, line1: "கெடுங்காலைக் கைவிடுவார் கேண்மை அடுங்காலை", line2: "உள்ளினும் உள்ளஞ் சுடும்.", meaningTa: "கெடும்போது நம்மைக் கைவிட்டவரின் நட்பை நாம் சாகின்ற போது நினைத்தாலும் நம் நெஞ்சம் சுடும்.", meaningEn: "The very thought of the friendship of those who have deserted one at the approach of adversity will burn one's mind at the time of death." },
  { number: 800, line1: "மருவுக மாசற்றார் கேண்மைஒன் றீத்தும்", line2: "ஒருவுக ஒப்பிலார் நட்பு.", meaningTa: "குற்றம் அற்றவரோடு நட்புக் கொள்க; உலகோடு ஒத்து வராதவரின் நட்பை விலை கொடுத்தாவது விட்டு விடுக.", meaningEn: "Continue to enjoy the friendship of the pure; (but) renounce even with a gift, the friendship of those who don't agree (with the world)." },
  { number: 801, line1: "பழைமை எனப்படுவது யாதெனின் யாதும்", line2: "கிழமையைக் கீழ்ந்திடா நட்பு.", meaningTa: "பழைமை பாராட்டுவது என்னவென்றால், பழகிய நண்பர்கள், தங்களின் உறவை அழியாமல் பாதுகாப்பதுதான்.", meaningEn: "Imtimate friendship is that which can't in the least be injured by (things done through the) right (of longstanding intimacy)." },
  { number: 802, line1: "நட்பிற் குறுப்புக் கெழுதகைமை மற்றதற்கு", line2: "உப்பாதல் சான்றோர் கடன்.", meaningTa: "பழைமையான நண்பர்களின் உரிமையைப் பாராட்டுகிற சான்றோர்க்குரிய கடமைதான் உண்மையான நட்புக்கு அடையாளமாகும்.", meaningEn: "The constituents of friendship are (things done through) the right of intimacy; to be pleased with such a right is the duty of the wise." },
  { number: 803, line1: "பழகிய நட்பெவன் செய்யுங் கெழுதகைமை", line2: "செய்தாங்கு அமையாக் கடை.", meaningTa: "பழகியவர் உரிமைப்பற்றிச் செய்யும் செயலைத் தாம் செய்தது போலவேக் கருதி உடன்படாவிட்டால் அவரோடு தாம் பழகிய நட்பு என்ன பயன்.", meaningEn: "Of what avail is long-standing friendship, if friends don't admit as their own actions done through the right of intimacy ?" },
  { number: 804, line1: "விழைதகையான் வேண்டி இருப்பர் கெழுதகையாற்", line2: "கேளாது நட்டார் செயின்.", meaningTa: "உரிமையால் கேளாமலே நண்பர் ஒன்றைச் செய்தால், அந்த உரிமையைப் போற்றி விரும்பும் தன்மையோடு அச் செயலையும் விரும்பி.", meaningEn: "If friends, through the right of friendship, do (anything) without being asked, the wise will be pleased with them on account of its desirability." },
  { number: 805, line1: "பேதைமை ஒன்றோ பெருங்கிழமை என்றுணர்க", line2: "நோதக்க நட்டார் செயின்.", meaningTa: "வருந்ததக்க செயல்களை நண்பர் செய்தால் அதற்குக் காரணம் அறியாமை என்றாவது மிகுந்த உரிமை என்றாவது உணரவேண்டும்.", meaningEn: "If friends should perform what is painful, understand that it is owing not only to ignorance, but also to the strong claims of intimacy." },
  { number: 806, line1: "எல்லைக்கண் நின்றார் துறவார் தொலைவிடத்தும்", line2: "தொல்லைக்கண் நின்றார் தொடர்பு.", meaningTa: "உரிமை வாழ்வின் எல்லையில் நின்றவர், தமக்கு அழிவுநேர்ந்தவிடத்திலும் பழைமையாய் உறவு கொண்டு நின்றவரின் தொடர்பைக் கைவிட.", meaningEn: "Those who stand within the limits (of true friendship) won't even in adversity give up the intimacy of long-standing friends." },
  { number: 807, line1: "அழிவந்த செய்யினும் அன்பறார் அன்பின்", line2: "வழிவந்த கேண்மை யவர்.", meaningTa: "தம் நண்பர் தமக்கு அழிவு தருவனவற்றையே செய்தாலும் நெடுங்காலமாக நட்பை உடையவர் நண்பர்மீது தாம் கொண்ட அன்பை.", meaningEn: "Those who have (long) stood in the path of affection won't give it up even if their friends cause (them) their ruin." },
  { number: 808, line1: "கேளிழுக்கம் கேளாக் கெழுதகைமை வல்லார்க்கு", line2: "நாளிழுக்கம் நட்டார் செயின்.", meaningTa: "நண்பர்கள் செய்யும் குற்றத்தைப் பிறர்கூறி அதனை ஏற்றுக் கொள்ளாத அளவுக்கு நம்பிக்கையான நட்புரிமை கொண்டவரிடத்திலேயே அந்த.", meaningEn: "To those who understand that by which they should not listen to (tales about) the faults of their friends, that is a (profitable) day on which the." },
  { number: 809, line1: "கெடாஅ வழிவந்த கேண்மையார் கேண்மை", line2: "விடாஅர் விழையும் உலகு.", meaningTa: "தொன்றுதொட்டு உரிமையுடன் பழகிய நட்புறவைக் கைவிடாமல் இருப்பவரை உலகம் போற்றும்.", meaningEn: "They will be loved by the world, who have not forsaken the friendship of those with whom they have kept up an unbroken long-standing intimacy." },
  { number: 810, line1: "விழையார் விழையப் படுப பழையார்கண்", line2: "பண்பின் தலைப்பிரியா தார்.", meaningTa: "பழைய நண்பர்கள் பிழையே செய்தாலும், அவருடன் பகை கொள்ளாது நம் நட்பை விடாதவர், பகைவராலும் விரும்பப்படுவர்.", meaningEn: "Even people who fight you will caring those who have never changed in their affection to their long-standingfriends." },
  { number: 811, line1: "பருகுவார் போலினும் பண்பிலார் கேண்மை", line2: "பெருகலிற் குன்றல் இனிது.", meaningTa: "உயிரால் உருகுவார்போல் நடிக்கும், உள்ளத்துள் நல்ல பண்பு இல்லாதவரின் நட்பு வளர்வதைவிடக் குறைவது நல்லது.", meaningEn: "The decrease of friendship with those who look as if they would eat you up (through excess of caring) while they are really destitute of goodness is." },
  { number: 812, line1: "உறின்நட்டு அறினொருஉம் ஒப்பிலார் கேண்மை", line2: "பெறினும் இழப்பினும் என்?", meaningTa: "தமக்குப் பயனிருந்தால் நட்புக் கொண்டும், பயன் இல்லை என்றால் நட்பை விலக்கியும் வாழ்வதில் தமக்கு இணை இல்லாதவராய்.", meaningEn: "Of what avail is it to get or lose the friendship of those who caring when there is gain and leave when there is none ?" },
  { number: 813, line1: "உறுவது சீர்தூக்கும் நட்பும் பெறுவது", line2: "கொள்வாரும் கள்வரும் நேர்.", meaningTa: "இவரிடம் நட்புக் கொள்வதால் தமக்கு என்ன கிடைக்கும் என்று எண்ணிப் பார்ப்பவரின் நட்பும், தமக்குத் தரும் கூலியை ஏற்றுக்.", meaningEn: "Friendship who calculate the profits (of their friendship), prostitutes who are bent on obtaining their gains, and thieves are (all) of the same." },
  { number: 814, line1: "அமரகத்து ஆற்றறுக்கும் கல்லாமா அன்னார்", line2: "தமரின் தனிமை தலை.", meaningTa: "போர்க்களத்தே நம்மை வீழ்த்திவிட்டுப் போய்விடும் கல்வியற்ற குதிரையைப் போன்றவரின் நட்பைக் காட்டிலும் தனிமையாக இருப்பதே.", meaningEn: "Solitude is more to be wantsd than the society of those who resemble the untrained horses which throw down (their riders) in the fields of battle." },
  { number: 815, line1: "செய்தேமஞ் சாராச் சிறியவர் புன்கேண்மை", line2: "எய்தலின் எய்தாமை நன்று.", meaningTa: "நாம் பல வகையில் உதவி செய்தாலும் நமக்குப் பாதுகாப்பாக இராத அற்பர்களின் நட்பு, இருப்பதிலும் இல்லாதிருப்பதே நல்லது.", meaningEn: "It is far better to avoid that to contract the evil friendship of the base who can't protect (their friends) even when appointed to do so." },
  { number: 816, line1: "பேதை பெருங்கெழீஇ நட்பின் அறிவுடையார்", line2: "ஏதின்மை கோடி உறும்.", meaningTa: "அறிவற்றவனின் மிக நெருக்கமான நட்பைக் காட்டிலும் அறிவுடையார்களின் பகை, கோடி நன்மையாம்.", meaningEn: "The hatred of the wise is ten-million times more profitable than the excessive intimacy of the fool." },
  { number: 817, line1: "நகைவகைய ராகிய நட்பின் பகைவரால்", line2: "பத்தடுத்த கோடி உறும்.", meaningTa: "நகைக்கும் தன்மை உடையவரின் நட்பை விட, பகைவரால் வருவன பத்துகோடி மடங்கு நன்மையாகும்.", meaningEn: "What comes from people who fight you is a hundred million times more profitable than what comes from the friendship of those who cause only laughter." },
  { number: 818, line1: "ஒல்லும் கருமம் உடற்று பவர்கேண்மை", line2: "சொல்லாடார் சோர விடல்.", meaningTa: "தம்மால் செய்யக்கூடிய உதவியையும் செய்ய முடியாதவர் போல் நடித்துச் செய்யாமல் விடுபவரின் நட்பை அவரிடம் சொல்லாமலேயே.", meaningEn: "Gradually abandon without revealing (beforehand) the friendship of those who pretend inability to carry out what they (really) could do." },
  { number: 819, line1: "கனவினும் இன்னாது மன்னோ வினைவேறு", line2: "சொல்வேறு பட்டார் தொடர்பு.", meaningTa: "சொல் ஒன்று, செயல் வேறாக இருப்பவரின் நட்பு கனவிலும் கூடத் துன்பமானதாகும்.", meaningEn: "The friendship of those whose actions don't agree with their words will distress (one) even in (one's) dreams." },
  { number: 820, line1: "எனைத்தும் குறுகுதல் ஓம்பல் மனைக்கெழீஇ", line2: "மன்றில் பழிப்பார் தொடர்பு.", meaningTa: "தனியே வீட்டில் உள்ளபோது பொருந்தியிருந்து, பலர் கூடிய மன்றத்தில் பழித்து பேசுவோரின் நட்பை எவ்வளவு சிறிய அளவிலும்.", meaningEn: "Avoid even the least approach to a contraction of friendship with those who would caring you in private but ridicule you in public." },
  { number: 821, line1: "சீரிடம் காணின் எறிதற்குப் பட்டடை", line2: "நேரா நிரந்தவர் நட்பு.", meaningTa: "அகத்தே பொருந்தாமல் புறத்தே பொருந்தி நடப்பவரின் நட்பு, தக்க இடம் கண்டபோது எறிவதற்கு உரிய பட்டையாகும்.", meaningEn: "The friendship of those who behave like friends without inward affection is a weapon that may be thrown when a favourable opportunity presents itself." },
  { number: 822, line1: "இனம்போன்று இனமல்லார் கேண்மை மகளிர்", line2: "மனம்போல வேறு படும்.", meaningTa: "வேண்டியவர் போலத் தோன்றி, மனத்தால் வேண்டாதவராக இருப்பவரோடு உண்டான நட்பு பாலியல் தொழிலாளர் மனம் போல வேறுபடும்.", meaningEn: "The friendship of those who seem to be friends while they aren't, will change like the caring of women." },
  { number: 823, line1: "பலநல்ல கற்றக் கடைத்து மனநல்லர்", line2: "ஆகுதல் மாணார்க் கரிது.", meaningTa: "மனத்தால் பொருந்தாதவர்கள் நல்ல பல நூல்களைக் கற்றபோதும் மனந்திருந்தி நல்ல நண்பர் ஆவது அரிது.", meaningEn: "Though (one's) people who fight you may have mastered many good books, it will be impossible for them to become truly loving at heart." },
  { number: 824, line1: "முகத்தின் இனிய நகாஅ அகத்தின்னா", line2: "வஞ்சரை அஞ்சப் படும்.", meaningTa: "சிரித்துப் பேசி நம்மைச் சீரழிக்க நினைக்கும் வஞ்சகரின் நட்புக்கு அஞ்சி ஒதுங்கிட வேண்டும்.", meaningEn: "One should fear the deceitful who smile sweetly with their face but never caring with their heart." },
  { number: 825, line1: "மனத்தின் அமையா தவரை எனைத்தொன்றும்", line2: "சொல்லினால் தேறற்பாற்று அன்று.", meaningTa: "மனத்தால் நம்மோடு சேராதவரை எந்தக் காரியத்திலும் அவர்களின் சொல்லைக் கண்டு நம்ப முடியாது.", meaningEn: "In nothing whatever is it proper to rely on the words of those who don't caring with their heart." },
  { number: 826, line1: "நட்டார்போல் நல்லவை சொல்லினும் ஒட்டார்சொல்", line2: "ஒல்லை உணரப் படும்.", meaningTa: "பகைவர், நண்பரைப்போல இனிமையாகப் பேசினாலும் அந்தச் சொற்களில் கிடக்கும் சிறுமைக் குணம் வெளிப்பட்டே தீரும்.", meaningEn: "Though (one's) foes may utter good things as though they were friends, once will at once understand (their evil, import)." },
  { number: 827, line1: "சொல்வணக்கம் ஒன்னார்கண் கொள்ளற்க வில்வணக்கம்", line2: "தீங்கு குறித்தமை யான்.", meaningTa: "வில்லின் வணக்கம் வணக்கமாக இருந்தாலும் தீங்கு செய்தலைக்குறித்தமையால், பகைவரிடத்திலும் அவருடைய சொல்லின் வணக்கத்தை.", meaningEn: "Since the bending of the bow bespeaks evil, one should not accept (as good) the humiliating speeches of one's foes." },
  { number: 828, line1: "தொழுதகை யுள்ளும் படையொடுங்கும் ஒன்னார்", line2: "அழுதகண் ணீரும் அனைத்து.", meaningTa: "பகைவர் தொழும் கைக்குள்ளும் ஆயுதம் மறைந்திருக்கும்; அவர் அழுது சிந்தும் கண்ணீரும் அப்படிப்பட்டதே.", meaningEn: "A weapon may be hid in the very hands with which (one's) foes adore (him) (and) the tears they shed are of the same nature." },
  { number: 829, line1: "மிகச்செய்து தம்மெள்ளு வாரை நகச்செய்து", line2: "நட்பினுள் சாப்புல்லற் பாற்று.", meaningTa: "புறத்தே மிகுதியாக நட்புத் தோன்றச் செய்து அகத்தில் இகழ்கின்றவரைத் தாமும் அந் நட்பில் நகைத்து மகிழுமாறு செய்து அத்.", meaningEn: "It is the duty of leaders to affect great caring but make it die (inwardly); as regard those foes who show them great friendship but despise them (in." },
  { number: 830, line1: "பகைநட்பாம் காலம் வருங்கால் முகநட்டு", line2: "அகநட்பு ஒரீஇ விடல்.", meaningTa: "நம் பகைவர் நம்முடன் நண்பராக வாழும் காலம் வந்தால் நாமும் அவருடன் முகத்தால் நட்புக் கொண்டு மனத்தால் அந்நட்பை விட்டுவிட.", meaningEn: "When one's foes begin to affect friendship, one should caring them with one's looks, and, cherishing no caring in the heart, give up (even the former)." },
  { number: 831, line1: "பேதைமை என்பதொன்று யாதெனின் ஏதங்கொண்டு", line2: "ஊதியம் போக விடல்.", meaningTa: "பேதைமை என்று சொல்லப்படுவது யாது என்றால், தனக்கு கெடுதியானதைக் கைக் கொண்டு ஊதியமானதை கைவிடுதலாகும்.", meaningEn: "Folly is one (of the chief defects); it is that which (makes one) incur loss and forego gain." },
  { number: 832, line1: "பேதைமையுள் எல்லாம் பேதைமை காதன்மை", line2: "கையல்ல தன்கட் செயல்.", meaningTa: "அறியாமையுள் எல்லாம் அறியாமை என்பது, ஒருவன் தனக்கு நன்மை தராதவை மேல் எல்லாம், விருப்பம் கொள்வதே ஆகும்.", meaningEn: "The greatest folly is that which leads one to take love doing what is forbidden." },
  { number: 833, line1: "நாணாமை நாடாமை நாரின்மை யாதொன்றும்", line2: "பேணாமை பேதை தொழில்", meaningTa: "தகாதவற்றிற்கு நாணாமலிருத்தல், தக்கவற்றை நாடாமலிருத்தல், அன்பு இல்லாமை, நன்மை ஒன்றையும் விரும்பாமை ஆகியவை பேதையின்.", meaningEn: "Shamelessness indifference (to what must be sought after), harshness, and aversion for everything (that ought to be wantsd) are the qualities of the." },
  { number: 834, line1: "ஓதி உணர்ந்தும் பிறர்க்குரைத்தும் தானடங்காப்", line2: "பேதையின் பேதையார் இல்.", meaningTa: "படித்தும், படித்ததை உணர்ந்தும், உணர்ந்ததைப் பலருக்கு உணர்த்திடவும் கூடியவர்கள், தாங்கள் மட்டும் அவ்வாறு.", meaningEn: "There are no greater fools than he who, though he has read and understood (a great deal) and even taught it to others, does not walk according to his." },
  { number: 835, line1: "ஒருமைச் செயலாற்றும் பேதை எழுமையும்", line2: "தான்புக் கழுந்தும் அளறு.", meaningTa: "தன்னிச்சையாகச் செயல்படும் பேதை, எக்காலத்திலும் துன்பமெனும் சகதியில் அழுந்திக் கிடக்க நேரிடும்.", meaningEn: "A fool can procure in a single birth a hell into which he may enter and suffer through all the seven births." },
  { number: 836, line1: "பொய்படும் ஒன்றோ புனைபூணும் கையறியாப்", line2: "பேதை வினைமேற் கொளின்.", meaningTa: "செய்யும் வழி தெரியாத அறிவற்றவன் ஒரு செயலைச் செய்யத் தொடங்கினால் செயலும் கெட்டு, அவனும் கெட்டுப் போவான்.", meaningEn: "If the fool, who knows not how to act undertakes a work, he will (certainly) fail (But) is it all ? He will even adorn himself with fetters." },
  { number: 837, line1: "ஏதிலார் ஆரத் தமர்பசிப்பர் பேதை", line2: "பெருஞ்செல்வம் உற்றக் கடை.", meaningTa: "அறிவற்றவன் பெருஞ்செல்வத்தை அடைந்தபோது பிறர் அதை அனுபவிக்க, அவன் உறவினர் பசித்திருப்பர்.", meaningEn: "If a fool happens to get an immense fortune, his neighbours will enjoy it while his relations starve." },
  { number: 838, line1: "மையல் ஒருவன் களித்தற்றால் பேதைதன்", line2: "கையொன்று உடைமை பெறின்.", meaningTa: "பேதை தன் கையில் ஒரு பொருள் பெற்றால் பித்து பிடித்த ஒருவன் கள்குடித்து மயங்கினார் போன்றதாகும்.", meaningEn: "A fool happening to possess something is like the intoxication of one who is (already) giddy." },
  { number: 839, line1: "பெரிதினிது பேதையார் கேண்மை பிரிவின்கண்", line2: "பீழை தருவதொன் றில்.", meaningTa: "அறிவற்ற பேதைகளுடன் கொள்ளும் நட்பு மிகவும் இனிமையானது; ஏனென்றால் அவர்களிடமிருந்து புரியும்போது எந்தத் துன்பமும்.", meaningEn: "The friendship between fools is exceedingly delightful (to each other): for at parting there will be." },
  { number: 840, line1: "கழாஅக்கால் பள்ளியுள் வைத்தற்றால் சான்றோர்", line2: "குழாஅத்துப் பேதை புகல்.", meaningTa: "சான்றோர் கூடியிருக்கும் இடத்துள் அறிவற்றவன் நுழைவது, கழுவாத காலைப் படுக்கைமேல் வைத்தது போலாகும்.", meaningEn: "The appearance of a fool in an assembly of the learned is like placing (one's) unwashed feet on a bed." },
  { number: 841, line1: "அறிவின்மை இன்மையுள் இன்மை பிறிதின்மை", line2: "இன்மையா வையா துலகு.", meaningTa: "அறிவுப் பஞ்சம்தான் மிகக் கொடுமையான பஞ்சமாகும் மற்ற பஞ்சங்களைக்கூட உலகம் அவ்வளவாகப் பொருட்படுத்தாது.", meaningEn: "The want of wisdom is the greatest of all wants; but that of wealth the world won't regard as such." },
  { number: 842, line1: "அறிவிலான் நெஞ்சுவந்து ஈதல் பிறிதியாதும்", line2: "இல்லை பெறுவான் தவம்.", meaningTa: "அறிவற்றவன் மனம் மகிழ்ந்து ஒன்றைப் பிறர்க்குத் தந்தால், அது பெறுகின்றவன் செய்த நல்வினையே.", meaningEn: "A fool cheerfully giving (something) is nothing else but the receiver's merit (in a former birth)." },
  { number: 843, line1: "அறிவிலார் தாந்தம்மைப் பீழிக்கும் பீழை", line2: "செறுவார்க்கும் செய்தல் அரிது.", meaningTa: "அறிவு அற்றவர், தாமே நம்மை வருத்திக் கொள்ளும் வருத்தம், பகைவராலும்கூட அவருக்குச் செய்வது அரிது.", meaningEn: "The suffering that fools inflict upon themselves is hardly possible even to foes." },
  { number: 844, line1: "வெண்மை எனப்படுவ தியாதெனின் ஒண்மை", line2: "உடையம்யாம் என்னும் செருக்கு.", meaningTa: "ஒருவன் தன்னைத்தானே அறிவுடையவனாக மதித்துக் கொள்ளும் ஆணவத்திற்குப் பெயர்தான் அறியாமை எனப்படும்.", meaningEn: "What is called want of wisdom is the vanity which says, \"We are wise\"." },
  { number: 845, line1: "கல்லாத மேற்கொண் டொழுகல் கசடற", line2: "வல்லதூஉம் ஐயம் தரும்.", meaningTa: "அறிவில்லாதவர் தாம் கற்காத நூல்களை கற்றவர் போல் மேற்கொண்டு நடத்தல், அவர் குற்றமறக் கற்றுவல்ல பொருளைப் பற்றியும்.", meaningEn: "Fools pretending to know what has not been read (by them) will rouse suspicion even as to what they have thoroughly mastered." },
  { number: 846, line1: "அற்றம் மறைத்தலோ புல்லறிவு தம்வயின்", line2: "குற்றம் மறையா வழி.", meaningTa: "நமது குற்றத்தை உணர்ந்து அதை நீக்காமல் உடலை மறைக்க மட்டும் உடை அணிவது மடமையாகும்.", meaningEn: "Even to cover one's nakedness would be folly, if (one's) faults were not covered (by forsaleader them)." },
  { number: 847, line1: "அருமறை சோரும் அறிவிலான் செய்யும்", line2: "பெருமிறை தானே தனக்கு.", meaningTa: "நல்வழிக்கான அறிவுரைகளைப் போற்றி அவ்வழி நடக்காத அறிவிலிகள், தமக்குத் தாமே பெருந்துன்பத்தைத் தேடிக் கொள்வார்கள்.", meaningEn: "The fool who neglects precious counsel does, of his own accord, a great injury to himself." },
  { number: 848, line1: "ஏவவும் செய்கலான் தான்தேறான் அவ்வுயிர்", line2: "போஒம் அளவுமோர் நோய்.", meaningTa: "தனக்கு நன்மையானவற்றை பிறர் ஏவினாலும் செய்யாதவனாய், தானாகவும் உணர்ந்து தெளியாதவனாய் உள்ளவனுடைய உயிர் போகுமளவும் ஒரு.", meaningEn: "The fool won't perform (his duties) even when advised nor ascertain them himself; such a soul is a." },
  { number: 849, line1: "காணாதான் காட்டுவான் தான்காணான் காணாதான்", line2: "கண்டானாம் தான்கண்ட வாறு.", meaningTa: "அறிவற்ற ஒருவன், தான் அறிந்ததை மட்டும் வைத்துக் கொண்டு, தன்னை அறிவுடையவனாகக் காட்டிக் கொள்வான் அவனை உண்மையிலேயே.", meaningEn: "One who would teach a fool will (simply) betray his folly; and the fool would (still) think himself \"wise in his own conceit\"." },
  { number: 850, line1: "உலகத்தார் உண்டென்பது இல்லென்பான் வையத்து", line2: "அலகையா வைக்கப் படும்.", meaningTa: "ஆதாரங்களைக் காட்டி இதுதான் உண்மை என்று தெளிவாகக் கூறப்படுகிற ஒன்றை, வேண்டுமென்றே இல்லை என மறுத்துரைப்பவரைப்.", meaningEn: "He who denies the existence of what the world believes in will be regarded as a demon on earth." },
  { number: 851, line1: "இகலென்ப எல்லா உயிர்க்கும் பகலென்னும்", line2: "பண்பின்மை பார஧க்கும் நோய்.", meaningTa: "மனமாறுபாடு காரணமாக ஏற்படுகிற பகையுணர்வு மக்களை ஒன்று சேர்ந்து வாழ முடியாமல் செய்கிற தீய பண்பாகும்.", meaningEn: "The disease which fosters the evil of disunion among all creatures is termed hatred by the wise." },
  { number: 852, line1: "பகல்கருதிப் பற்றா செயினும் இகல்கருதி", line2: "இன்னாசெய் யாமை தலை.", meaningTa: "நம்மோடு இணங்கிப் போக முடியாமல் ஒருவன் நமக்கு வெறுப்புத் தருவனவற்றைச் செய்தாலும், அவனைப் பகையாக எண்ணித் தீமை.", meaningEn: "Though disagreeable things may be done from (a feeling of) disunion, it is far better that nothing painful be done from (that of) hatred." },
  { number: 853, line1: "இகலென்னும் எவ்வநோய் நீக்கின் தவலில்லாத்", line2: "தாவில் விளக்கம் தரும்.", meaningTa: "ஒருவன் இகல் என்று சொல்லப்படும் துன்ப நோயை நீக்கி விட்டால் அஃது அவனுக்கு அழிவில்லாத நிலையான புகழைக் கொடுக்கும்.", meaningEn: "To rid one-self of the distressing dtsease of hatred will bestow (on one) a never-decreasing imperishable a good name." },
  { number: 854, line1: "இன்பத்துள் இன்பம் பயக்கும் இகலென்னும்", line2: "துன்பத்துள் துன்பங் கெடின்.", meaningTa: "துன்பங்கள் எல்லாவற்றிலும் மிகக் கொடிதான மனவேறுபாடு எனும் துன்பம், ஒருவனது உள்ளத்துள் இல்லை என்றால், அது அவனுக்கு.", meaningEn: "If hatred which is the greatest misery is destroyed, it will yield the greatest delight." },
  { number: 855, line1: "இகலெதிர் சாய்ந்தொழுக வல்லாரை யாரே", line2: "மிக்லூக்கும் தன்மை யவர்.", meaningTa: "இகலை எதிர்த்து நிற்காமல் அதன் எதிரே சாய்ந்து நடக்க வல்லவரை வெல்லக் கருதுகின்ற ஆற்றல் உடையவர் யார்.", meaningEn: "Who indeed would think of conquering those who naturally shrink back from hatred ?" },
  { number: 856, line1: "இகலின் மிகலினிது என்பவன் வாழ்க்கை", line2: "தவலும் கெடலும் நணித்து.", meaningTa: "இகல் கொள்வதால் வெல்லுதல் இனியது என்று கருதுகின்றவனுடைய வாழ்க்கை தவறிபோதலும் அழிதலும் விரைவவில் உள்ளனவாம்.", meaningEn: "Failure and ruin aren't far from God who says it is sweet to excel in hatred." },
  { number: 857, line1: "மிகல்மேவல் மெய்ப்பொருள் காணார் இகல்மேவல்", line2: "இன்னா அறிவி னவர்.", meaningTa: "மனவேறுபாட்டோடு கேடான அறிவையும் உடையவர், வெற்றி தரும் நீதிநூற் பொருளை அறியமாட்டார்.", meaningEn: "Who only know to work people woe, fulfilled of fighting." },
  { number: 858, line1: "இகலிற்கு எதிர்சாய்தல் ஆக்கம் அதனை", line2: "மிக்லூக்கின் ஊக்குமாம் கேடு.", meaningTa: "மனவேறுபாடு தோன்றும்போது அதை வரவேற்காமல் இருப்பது ஒருவனுக்குச் செல்வமாகும்; வரவேற்பது கேட்டையே வரவேற்ப‌தாகும்.", meaningEn: "Shrinleader back from hatred will yield wealth; indulging in its increase will hasten ruin." },
  { number: 859, line1: "இகல்காணான் ஆக்கம் வருங்கால் அதனை", line2: "மிகல்காணும் கேடு தரற்கு.", meaningTa: "ஒருவன் தனக்கு நன்மை வரும்போது மாறுபாட்டை நினைக்காமலே இருப்பான் ஆனால் தனக்குத் தானே கேடு தேடிக் கொள்வதென்றால் அந்த.", meaningEn: "At the approach of wealth one won't think of hatred (but) to secure one's ruin, one will look to its increase." },
  { number: 860, line1: "இகலானாம் இன்னாத எல்லாம் நகலானாம்", line2: "நன்னயம் என்னும் செருக்கு.", meaningTa: "மன வேறுபாட்டால் துன்பம் எல்லாம் உண்டாகும். நல்லிணக்க நட்பால், நீதி என்னும் செல்வச் செருக்கு உண்டாகும்.", meaningEn: "All calamities are caused by hatred; but by the delight (of friendship) is caused the great wealth of good goodnesss." },
  { number: 861, line1: "வலியார்க்கு மாறேற்றல் ஓம்புக ஓம்பா", line2: "மெலியார்மேல் மேக பகை.", meaningTa: "மெலியோரை விடுத்து, வலியோரை எதிர்த்துப் போரிட விரும்புவதே பகைமாட்சி எனப் போற்றப்படும்.", meaningEn: "Avoid offering resistance to the strong; (but) never fail to cherish fighting towards the weak." },
  { number: 862, line1: "அன்பிலன் ஆன்ற துணையிலன் தான்துவ்வான்", line2: "என்பரியும் ஏதிலான் துப்பு.", meaningTa: "மக்களிடத்தில் அன்பு இல்லாத, வலுவான துணையும் இல்லாத, ஆற்றலும் அற்ற அரசின்மீது ஆற்றல் மிக்க பகை வந்தால், அப்பகையின்.", meaningEn: "How can he who is unloving, destitute of powerful aids, and himself without strength overcome the might of his foe ?" },
  { number: 863, line1: "அஞ்சும் அறியான் அமைவிலன் ஈகலான்", line2: "தஞ்சம் எளியன் பகைக்கு.", meaningTa: "அச்சமும், மடமையும் உடையவனாகவும், இணைந்து வாழும் இயல்பும், இரக்க சிந்தையும் இல்லாதவனாகவும் ஒருவன் இருந்தால், அவன்.", meaningEn: "In the estimation of foes miserably weak is he, who is timid, ignorant, unsociable and niggardly." },
  { number: 864, line1: "நீங்கான் வெகுளி நிறையிலன் எஞ்ஞான்றும்", line2: "யாங்கணும் யார்க்கும் எளிது.", meaningTa: "கோபம் குறையாத, ரகசியங்களைக் காக்கத் தெரியாத அரசைத் தோற்கடிப்பது எப்போதும், எங்கும், எவர்க்கும் எளிது.", meaningEn: "He who neither refrains from anger nor keeps his secrets will at all times and in all places be easily conquered by all." },
  { number: 865, line1: "வழிநோக்கான் வாய்ப்பன செய்யான் பழிநோக்கான்", line2: "பண்பிலன் பற்றார்க்கு இனிது.", meaningTa: "ஒருவன் நல்வழியை நோக்காமல் பொருத்தமானவற்றைச் செய்யாமல், பழியையும் பார்க்காமல், நற்பண்பும் இல்லாமல் இருந்தால் அவன்.", meaningEn: "Pleasing (object) to his foes is he who reads not moral works, does nothing that is enjoined by them cares not for reproach and isn't full of good." },
  { number: 866, line1: "காணாச் சினத்தான் கழிபெருங் காமத்தான்", line2: "பேணாமை பேணப் படும்.", meaningTa: "சிந்திக்காமலே சினம் கொள்பனாகவும், பேராசைக்காரனாகவும் இருப்பவனின் பகையை ஏற்று எதிர் கொள்ளலாம்.", meaningEn: "Highly to be wantsd is the hatred of God whose anger is blind, and whose greedy wants increases beyond measure." },
  { number: 867, line1: "கொடுத்தும் கொளல்வேண்டும் மன்ற அடுத்திருந்து", line2: "மாணாத செய்வான் பகை.", meaningTa: "தன்னை அடுத்துத் தன்னோடிருந்தும் பொருந்தாதவற்றைச் செய்பவனுடைய பகையைப் பொருள் கொடுத்தாவது கொள்ள வேண்டும்.", meaningEn: "It is indeed necessary to obtain even by purchase the hatred of God who having begun (a work) does what isn't conductive (to its accomplishment)." },
  { number: 868, line1: "குணனிலனாய்க் குற்றம் பலவாயின் மாற்றார்க்கு", line2: "இனனிலனாம் ஏமாப் புடைத்து.", meaningTa: "நல்ல குணங்கள் இல்லாமல் குற்றங்கள் பலவும் உடைய அரசிற்குத் துணை இல்லாது போகும். துணை இல்லாது இருப்பதே அந்த அரசின்.", meaningEn: "He will become friendless who is without (any good) qualities and whose faults are many; (such a character) is a help to (his) foes." },
  { number: 869, line1: "செறுவார்க்குச் சேணிகவா இன்பம் அறிவிலா", line2: "அஞ்சும் பகைவர்ப் பெறின்.", meaningTa: "அறிவு இல்லாத அஞ்சும் இயல்புடைய பகைவரைப் பெற்றால், அவரை எதிர்த்து பகை கொள்பவர்க்கு இன்பங்கள் தொலைவில் நீங்காமல்.", meaningEn: "There will be no end of lofty delights to the victorious, if their foes are (both) ignorant and timid." },
  { number: 870, line1: "கல்லான் வெகுளும் சிறுபொருள் எஞ்ஞான்றும்", line2: "ஒல்லானை ஒல்லா தொளி.", meaningTa: "கல்வி கற்காதவனைப் பகைத்துக்கொள்ளும் எளிய செயலைச் செய்ய இயலாத ஒருவனிடம் எக்காலத்திலும் புகழ் வந்து பொருந்தாது.", meaningEn: "The light (of a good name) will never be gained by God who gains not the trifling reputation of having fought an unlearned (foe)." },
  { number: 871, line1: "பகைஎன்னும் பண்பி லதனை ஒருவன்", line2: "நகையேயும் வேண்டற்பாற்று அன்று.", meaningTa: "பகை எனப்படும் பண்பற்ற ஒன்று, விளையாட்டிலும் கூட் விரும்பத்தக்கது அன்று.", meaningEn: "The evil of hatred isn't of a nature to be wantsd by one even in sport." },
  { number: 872, line1: "வில்லேர் உழவர் பகைகொளினும் கொள்ளற்க", line2: "சொல்லேர் உழவர் பகை.", meaningTa: "விலலை ஆயுதமாகக் கொண்ட வீரரோடு பகை கொண்டாலும், சொல்லை ஆயுதமாகக் கொண்ட எழுத்தாளரோடு பகை கொள்ள வேண்டா.", meaningEn: "Though you may incur the hatred of warriors whose ploughs are bows, incur not that of helpers whose ploughs are words." },
  { number: 873, line1: "ஏமுற் றவரினும் ஏழை தமியனாய்ப்", line2: "பல்லார் பகைகொள் பவன்.", meaningTa: "தன்னந் தனியனாக இருந்து கொண்டு, பலரையும் பகைவர்களாகப் பெறும் ஆட்சியாளன் பித்தரிலும் அறிவற்றவன்.", meaningEn: "He who being alone, incurs the hatred of many is more infatuated than even mad people." },
  { number: 874, line1: "பகைநட்பாக் கொண்டொழுகும் பண்புடை யாளன்", line2: "தகைமைக்கண் தங்கிற்று உலகு.", meaningTa: "பகைவர்களையும் நண்பர்களாகக் கருதிப் பழகுகின்ற பெருந்தன்மையான பண்பை இந்த உலகமே போற்றிப் புகழும்.", meaningEn: "Whose worthy rule can change his foes to friends." },
  { number: 875, line1: "தன்துணை இன்றால் பகையிரண்டால் தான்ஒருவன்", line2: "இன்துணையாக் கொள்கவற்றின் ஒன்று.", meaningTa: "தனது பகைவர்கள் இரு பிரிவினராக இயங்கும் நிலையில் தனக்குத் துணையாக யாருமின்றித் தனியாக இருப்பவர், அந்தப் பகைவர்களில்.", meaningEn: "He who is alone and helpless while his foes are two should secure one of them as an agreeable help (to himself)." },
  { number: 876, line1: "தேறினும் தேறா விடினும் அழிவின்கண்", line2: "தேறான் பகாஅன் விடல்.", meaningTa: "இதற்கு முன் ஒருவனைப் பற்றி ஆராய்ந்து தெளிந்திருந்தாலும், தெளியாவிட்டாலும் அழிவு வந்த காலத்தில் அவனைத் தெளியாமலும்.", meaningEn: "Though (one's foe is) aware or not of one's misfortune one should act so as neither to join nor separate (from him)." },
  { number: 877, line1: "நோவற்க நொந்தது அறியார்க்கு மேவற்க", line2: "மென்மை பகைவர் அகத்து.", meaningTa: "நம் பலம் இன்மையை, தாமாக அறியாத நண்பர்களிடம் சொல்ல வேண்டா; பகைவர்களிடமோ அதைக் காட்டிக் கொள்ளவோ வேண்டா.", meaningEn: "Relate not your suffering even to friends who are ignorant of it, nor refer to your weakness in the presence of your foes." },
  { number: 878, line1: "வகையறிந்து தற்செய்து தற்காப்ப மாயும்", line2: "பகைவர்கண் பட்ட செருக்கு.", meaningTa: "வழிவகை உணர்ந்து, தன்னையும் வலிமைப்படுத்திக் கொண்டு, தற்காப்பும் தேடிக் கொண்டவரின் முன்னால் பகையின் ஆணவம் தானாகவே.", meaningEn: "The joy of one's foes will be destroyed if one guards oneself by knowing the way (of acting) and securing assistance." },
  { number: 879, line1: "இளைதாக முள்மரம் கொல்க களையுநர்", line2: "கைகொல்லும் காழ்த்த இடத்து.", meaningTa: "நம்மை அழி்க்க எண்ணும் முள் மரத்தை அது வளரும்போதே அழி்த்து விடுக; வளர்ந்து விட்டால் அழிக்க எண்ணுபவரின் கையை அது.", meaningEn: "A thorny tree should be felled while young, (for) when it is grown it will destroy the hand of the feller." },
  { number: 880, line1: "உயிர்ப்ப உளரல்லர் மன்ற செயிர்ப்பவர்", line2: "செம்மல் சிதைக்கலா தார்.", meaningTa: "பகைத்தவருடையத் தலைமையைக் கொடுக்க முடியாதவர் திண்ணமாக மூச்சு விடும் அளவிற்கும் உயிரோடு வாழ்கின்றவர் அல்லர்.", meaningEn: "Those who don't destroy the pride of those who hate (them) will certainly not exist even to breathe." },
  { number: 881, line1: "நிழல்நீரும் இன்னாத இன்னா தமர்நீரும்", line2: "இன்னாவாம் இன்னா செயின்.", meaningTa: "நிழலும் நீரும் முதலில் இனியவாக இருந்தாலும், பிறகு துன்பம் தருவனவே. அதபோல, நெருக்கமான உறவும் சொந்தக் கட்சிக்காரரும்.", meaningEn: "Shade and water aren't pleasant, (if) they cause disease; so are the qualities of (one's) relations not agreeable, (if) they cause pain." },
  { number: 882, line1: "வாள்போல பகைவரை அஞ்சற்க அஞ்சுக", line2: "கேள்போல் பகைவர் தொடர்பு.", meaningTa: "வெளிப்படையாக எதிரே வரும் பகைவர்களைவிட உறவாடிக் கெடுக்க நினைப்பவர்களிடம்தான் எச்சரிக்கையாக இருக்க வேண்டும்.", meaningEn: "Fear not foes (who say they would cut) like a sword; (but) fear the friendship of foes (who seemingly." },
  { number: 883, line1: "உட்பகை அஞ்சித்தற் காக்க உலைவிடத்து", line2: "மட்பகையின் மாணத் தெறும்.", meaningTa: "உட்பகைக்கு அஞ்சி ஒருவன் தன்னைப் பாதுகாத்துக் கொள்ள வேண்டும் இல்லாவிட்டால் ஒரு சோதனையான நேரத்தில் பச்சை பாண்டத்தை.", meaningEn: "Fear internal fighting and guard yourself; (if not) it will destroy (you) in an evil hour, as surely as the tool which cuts the potter's clay." },
  { number: 884, line1: "மனமாணா உட்பகை தோன்றின் இனமாணா", line2: "ஏதம் பலவும் தரும்.", meaningTa: "புறத்தே நட்பானவர் போல் தோன்றி அகத்தே திருந்ததாத உட்பகை உண்டானால், அது நம் சுற்றமும் நம் கட்சிக்காரரும் நம்.", meaningEn: "The secret fighting of a person whose mind in unreformed will lead to many evils causing disaffection among (one's) relations." },
  { number: 885, line1: "உறல்முறையான் உட்பகை தோன்றின் இறல்முறையான்", line2: "ஏதம் பலவும் தரும்.", meaningTa: "உறவு முறையை உடையவனே உட்பகையானால், அது சாவோடு கூடிய குற்றம் பலவற்றையும் உண்டாக்கும்.", meaningEn: "If there appears internal hatred in a (leader's) family; it will lead to many a fatal crime." },
  { number: 886, line1: "ஒன்றாமை ஒன்றியார் கட்படின் எஞ்ஞான்றும்", line2: "பொன்றாமை ஒன்றல் அரிது.", meaningTa: "தன்னுடன் இருப்பவரின் பகை தோன்றுமானால், ஆட்சியின் அழிவைத் தடுக்க ஒருபோதும் முடியாது.", meaningEn: "If hatred arises among (one's) own people, it will be hardly possible (for one) to escape death." },
  { number: 887, line1: "செப்பின் புணர்ச்சிபோல் கூடினும் கூடாதே", line2: "உட்பகை உற்ற குடி.", meaningTa: "செப்பு எனப்படும் சிமிழில் அதன் மூடி பொருந்தியிருப்பது போல வெளித்தோற்றத்துக்கு மட்டுமே தெரியும் அவ்வாறே.", meaningEn: "Never indeed will a family subject to internal hatred unite (really) though it may present an apparent union like that of a casket and its lid." },
  { number: 888, line1: "அரம்பொருத பொன்போலத் தேயும் உரம்பொருது", line2: "உட்பகை உற்ற குடி.", meaningTa: "உட்பகை உண்டான குடி அரத்தினால் தேய்க்கப் பட்ட இரும்பு போல் வலிமை குறைக்கப் பட்டு தேய்ந்து போகும்.", meaningEn: "A family subject to internal hatred will wear out and lose its strength like iron that has been filed away." },
  { number: 889, line1: "எட்பக வன்ன சிறுமைத்தே ஆயினும்", line2: "உட்பகை உள்ளதாங் கேடு.", meaningTa: "எள்ளின் பிளவுபோன்று சிறிதாக இருந்தாலும் உட்பகையால் பெருங்கேடு விளையும்.", meaningEn: "Although internal hatred be as small as the fragment of the sesamum (seed), still does destruction dwell in it." },
  { number: 890, line1: "உடம்பாடு இலாதவர் வாழ்க்கை குடங்கருள்", line2: "பாம்போடு உடனுறைந் தற்று.", meaningTa: "அகத்தில் உடண்பாடு இல்லாதவருடன் குடிவாழும் வாழ்க்கை, ஒரு குடிசையிற் பாம்போடு உடன்வாழ்ந்தாற் போன்றது.", meaningEn: "Living with those who don't agree (with one) is like dwelling with a cobra (in the same) hut." },
  { number: 891, line1: "ஆற்றுவார் ஆற்றல் இகழாமை போற்றுவார்", line2: "போற்றலுள் எல்லாம் தலை.", meaningTa: "எடுத்துக் கொண்ட செயல்களை இனிது முடிப்பவரின் வலிமைகளை அவமதியாமல் இருப்பது, தமக்குத் தீங்கு ஏதும் வராமல் காப்பவர்.", meaningEn: "Not to disregard the power of those who can carry out (their wishes) is more important than all the watchfulness of those who guard (themselves." },
  { number: 892, line1: "பெரியாரைப் பேணாது ஒழுகிற் பெரியாரால்", line2: "பேரா இடும்பை தரும்.", meaningTa: "பெரியவர்களை மதிக்காமல் நடந்தால், அப்பெரியவர்களால் தீராத துன்பம் வரும்.", meaningEn: "To behave without respect for the great (rulers) will make them do (us) irremediable evils." },
  { number: 893, line1: "கெடல்வேண்டின் கேளாது செய்க அடல்வேண்டின்", line2: "ஆற்று பவர்கண் இழுக்கு.", meaningTa: "ஒருவன், தன்னைத்தானே கெடுத்துக் கொள்ள விரும்பினால் பகையை நினைத்த மாத்திரத்தில் அழிக்கக் கூடிய ஆற்றலுடையவர்களை யார்.", meaningEn: "If a person wants ruin, let him not listen to the righteous dictates of law, but commit crimes against those who are able to slay (other leaders)." },
  { number: 894, line1: "கூற்றத்தைக் கையால் விளித்தற்றால் ஆற்றுவார்க்கு", line2: "ஆற்றாதார் இன்னா செயல்.", meaningTa: "ஆற்றல் உடையவர்க்கு ஆற்றல் இல்லாதவர் தீமை செய்தல், தானே வந்து அழிக்க வல்ல எமனைக் கைகாட்டி அழைத்தாற் போன்றது.", meaningEn: "The weak doing evil to the strong is like beckoning Yama to come (and destroy them)." },
  { number: 895, line1: "யாண்டுச்சென்று யாண்டும் உளராகார் வெந்துப்பின்", line2: "வேந்து செறப்பட் டவர்.", meaningTa: "மிக்க வலிமை உள்ள அரசனால் வெகுளப்பட்டவர், அவனிடமிருந்து தப்புவதற்க்காக எங்கே சென்றாலும் எங்கும் வாழ முடியாது.", meaningEn: "Those who have incurred the wrath of a cruel and mighty potentate won't do well wherever they may go." },
  { number: 896, line1: "எரியால் சுடப்படினும் உய்வுண்டாம் உய்யார்", line2: "பெரியார்ப் பிழைத்தொழுகு வார்.", meaningTa: "தீயால் சுடப்பட்டாலும் பிழைத்துக் கொள்ளலாம். ஆனால் பெரியவர்களை அவமதித்து வாழ்பவர் பிழைக்கவேமாட்டார்.", meaningEn: "Though burnt by a fire (from a forest), one may perhaps live; (but) never will he live who has shown disrespect to the great (devotees)." },
  { number: 897, line1: "வகைமாண்ட வாழ்க்கையும் வான்பொருளும் என்னாம்", line2: "தகைமாண்ட தக்கார் செறின்.", meaningTa: "பெருஞ்செல்வம் குவித்துக்கொண்டு என்னதான் வகைவகையான வாழ்க்கைச் சுகங்களை அனுபவித்தாலும், தகுதி வாய்ந்த பெரியோரின்.", meaningEn: "If a leader incurs the wrath of the righteous great, what will become of his government with its splendid auxiliaries and (all) its untold wealth ?" },
  { number: 898, line1: "குன்றன்னார் குன்ற மதிப்பின் குடியொடு", line2: "நின்றன்னார் மாய்வர் நிலத்து.", meaningTa: "மலை போன்ற பெரியவர் கெட நினைத்தால். உலகில் அழியாமல் நிலைபெற்றாற் போல் உள்ளவரும் தம் குடியோடு அழிவர்.", meaningEn: "If (the) hill-like (devotees) resolve on destruction, those who seemed to be everlasting will be destroyed root and branch from the earth." },
  { number: 899, line1: "ஏந்திய கொள்கையார் சீறின் இடைமுரிந்து", line2: "வேந்தனும் வேந்து கெடும்.", meaningTa: "உயர்ந்த கொள்கை உறுதி கொடண்வர்கள் சீறி எழுந்தால், அடக்குமுறை ஆட்சி நிலை குலைந்து அழிந்துவிடும்.", meaningEn: "Leaders even fall from high estate and perish in the flame." },
  { number: 900, line1: "இறந்தமைந்த சார்புடையர் ஆயினும் உய்யார்", line2: "சிறந்தமைந்த சீரார் செறின்.", meaningTa: "மிகச் சிறந்த சீர்களை உடையவர் சினந்தால் மிகப்பெரும் பலங்களைச் சார்வாக உடையவரே என்றாலும் தப்பமாட்டார்.", meaningEn: "Though in possession of numerous auxiliaries, they will perish who are-exposed to the wrath of the noble whose hard good practice is boundless." },
  { number: 901, line1: "மனைவிழைவார் மாண்பயன் எய்தார் வினைவிழையார்", line2: "வேண்டாப் பொருளும் அது.", meaningTa: "கடமையுடன் கூடிய செயல்புரியக் கிளம்பியவர்கள் இல்லற சுகத்தைப் பெரிதெனக் கருதினால் சிறப்பான புகழைப் பெற மாட்டார்கள்.", meaningEn: "Those who greedy wants after their wives won't attain the excellence of goodness; and it is just this that isn't wantsd by those who are bent on." },
  { number: 902, line1: "பேணாது பெண்விழைவான் ஆக்கம் பெரியதோர்", line2: "நாணாக நாணுத் தரும்.", meaningTa: "கடமையை விரும்பாமல் மனைவியின் பெண்மையை விரும்புகின்றவனுடைய ஆக்கம், பெரியதொரு நாணத்தக்கச் செயலாக நாணத்தைக் கொடுக்கும்.", meaningEn: "The wealth of God who, regardless (of his manliness), devotes himself to his partner's feminine nature will cause great shame (to ali people) and to." },
  { number: 903, line1: "இல்லாள்கண் தாழ்ந்த இயல்பின்மை எஞ்ஞான்றும்", line2: "நல்லாருள் நாணுத் தரும்.", meaningTa: "மனைவியிடத்தில் தாழ்ந்து நடக்கும் இழிந்த தன்மை ஒருவனுக்கு எப்போதும் நல்லவரிடையே இருக்கும் போது நாணத்தைச் தரும்.", meaningEn: "The frailty that stoops to a partner will always make (her partner) feel ashamed among the good." },
  { number: 904, line1: "மனையாளை அஞ்சும் மறுமையி லாளன்", line2: "வினையாண்மை வீறெய்த லின்று.", meaningTa: "தன் மனைவிக்குப் பயந்து நடக்கும் மறுமைப் பயன் இல்லாதவனின் செயல்திறம் நல்லவரால் பாராட்டப்படாது.", meaningEn: "The undertaleader of one, who fears his partner and is so destitute of (bliss), will never be applauded." },
  { number: 905, line1: "இல்லாளை அஞ்சுவான் அஞ்சுமற் றெஞ்ஞான்றும்", line2: "நல்லார்க்கு நல்ல செயல்.", meaningTa: "தன் மனைவிக்குப் பயப்படுபவன் நல்லார்க்கும் கூட நல்லது செய்ய எப்போதும் அஞ்சுவான்.", meaningEn: "He that fears his partner will always be afraid of doing good deeds (even) to the good." },
  { number: 906, line1: "இமையாரின் வாழினும் பாடிலரே இல்லாள்", line2: "அமையார்தோள் அஞ்சு பவர்.", meaningTa: "தேவர்களைப் போல வாழ்ந்தாலும் மனைவியின் மூங்கில் போன்ற தோளுக்குப் பயப்படுபவர், ஆண்மையால் வரும் பெருமை இல்லாதவரே.", meaningEn: "They that fear the bamboo-like shoulders of their wives will be destitute of manliness though they may do well like the Gods." },
  { number: 907, line1: "பெண்ணேவல் செய்தொழுகும் ஆண்மையின் நாணுடைப்", line2: "பெண்ணே பெருமை உடைத்து.", meaningTa: "மனைவி ஏவ, அதையே செய்து நடக்கும் ஆண்மையைக் காட்டிலும், வெட்கப்படுதலை உடைய பெண் தன்மையே சிறந்தது.", meaningEn: "Even shame faced womanhood is more to be esteemed than the shameless manhood that performs." },
  { number: 908, line1: "நட்டார் குறைமுடியார் நன்றாற்றார் நன்னுதலாள்", line2: "பெட் டாங்கு ஒழுகு பவர்.", meaningTa: "தம் மனைவி விரும்பியபடியே வாழ்பவர், தம் நண்பர்க்கு ஏற்பட்ட குறையைப் போக்கமாட்டார் நல்லதும் செய்யமாட்டார்.", meaningEn: "Those who yield to the wishes of their wives will neither relieve the wants of (their) friends nor perform good deeds." },
  { number: 909, line1: "அறவினையும் ஆன்ற பொருளும் பிறவினையும்", line2: "பெண்ஏவல் செய்வார்கண் இல்.", meaningTa: "அறச்செயலும் சிறந்த பொருட்செயலும், பிற இன்பச் செயல்களும் மனைவி சொல்லைக் கேட்டுச் செய்பவரிடம் இருக்கமாட்டா.", meaningEn: "From those who obey the commands of their wives are to be expected neither deeds of goodness, nor those of wealth nor (even) those of pleasure." },
  { number: 910, line1: "எண்சேர்ந்த நெஞ்சத் திடனுடையார்க்கு எஞ்ஞான்றும்", line2: "பெண்சேர்ந்தாம் பேதைமை இல்.", meaningTa: "சிந்திக்கும் மனமும் செல்வமும் உடையவர்களிடம் மனைவி சொல்லை மட்டுமே கேட்டுச் செய்யும் அறியாமை ஒருபோதும் இராது.", meaningEn: "The foolishness that results from devotion to a partner will never be found in those who possess a reflecting mind and a doing well (flowing)." },
  { number: 911, line1: "அன்பின் விழையார் பொருள்விழையும் ஆய்தொடியார்", line2: "இன்சொல் இழுக்குத் தரும்.", meaningTa: "அன்பால் நம்மை விரும்பாது, பொருள் பெறவே விரும்பும் பாலியல் தொழிலாளரின் இனிய சொற்கள் துன்பமே தரும்.", meaningEn: "The sweet words of elegant braceleted (prostitutes) who wants (a person) not from affection but from wants too much, will cause sorrow." },
  { number: 912, line1: "பயன்தூக்கிப் பண்புரைக்கும் பண்பின் மகளிர்", line2: "நயன்தூக்கி நள்ளா விடல்.", meaningTa: "ஆதாயத்தைக் கணக்கிட்டு அதற்கேற்றவாறு பாகுமொழிபேசும் பொதுமகளிர் உறவை ஒருபோதும் நம்பி ஏமாறக்கூடாது.", meaningEn: "One must ascertain the character of the ill-natured wopeople who after ascertaining the wealth (of a person) speak (as if they were) good." },
  { number: 913, line1: "பொருட்பெண்டிர் பொய்ம்மை முயக்கம் இருட்டறையில்", line2: "ஏத஧ல் பிணந்தழீஇ அற்று.", meaningTa: "பொருளையே விரும்பும் பொது மகளிரின் பொய்யானத் தழுவல், இருட்டறையில் தொடர்பில்லாத ஒரு பிணத்தைத் தழுவினாற் போன்றது.", meaningEn: "The false warm hugs of wealth-loving women are like (hired people) embracing a strange corpse in a dark room." },
  { number: 914, line1: "பொருட்பொருளார் புன்னலந் தோயார் அருட்பொருள்", line2: "ஆயும் அறிவி னவர்.", meaningTa: "அருளோடுகூடப் பொருள்தேடும் அறிவினை உடையவர், வெறும் பொருளையே தேடும் பாலியல் தொழிலாளரின் அற்ப உடம்பைத் தீண்டமாட்டார்.", meaningEn: "The wise who seek the wealth of grace won't wants the base favours of those who regard wealth (and not pleasure) as (their) riches." },
  { number: 915, line1: "பொதுநலத்தார் புன்னலம் தோயார் மதிநலத்தின்", line2: "மாண்ட அறிவி னவர்.", meaningTa: "இயல்பாகிய மதிநலத்தால் சிறந்த அறிவினை உடையவர், பாலியல் தொழிலாளரின் அற்ப உடம்பைத் தீண்டமாட்டார்.", meaningEn: "Those whose knowledge is made excellent by their (natural) sense won't wants what others have the trffling delights." },
  { number: 916, line1: "தந்நலம் பாரிப்பார் தோயார் தகைசெருக்கிப்", line2: "புன்னலம் பாரிப்பார் தோள்.", meaningTa: "புகழ்ச்சிக்குரிய சான்றோர் எவரும், இகழ்ச்சிக்குரிய இன்பவல்லிகளின் தோளில் சாய்ந்து கிடக்க மாட்டார்.", meaningEn: "Those who would spread (the a good name of) their own goodness won't wants the shoulders of those,who rejoice in their accomplishments and bestow." },
  { number: 917, line1: "நிறைநெஞ்சம் இல்லவர் தோய்வார் பிறநெஞ்சிற்", line2: "பேணிப் புணர்பவர் தோள்.", meaningTa: "பிறவற்றைப் பெறும் பொருட்டு மன ஆசை கொண்டு, அதற்காகவே உடம்பால் புணரும் பாலியல் தொழிலாளரின் தோளை மன அடக்கம் இல்லாதவரே.", meaningEn: "Those who are destitute of a perfectly (reformed) mind will wants what others have the shoulders of those who warm hug (them) while their hearts." },
  { number: 918, line1: "ஆயும் அறிவினர் அல்லார்க்கு அணங்கென்ப", line2: "மாய மகளிர் முயக்கு.", meaningTa: "வஞ்சம் நிறைந்த பொதுமகளிரின் சேர்க்கை, ஆராய்ந்தறியும் அறிவு இல்லாதவற்க்கு அணங்கு தாக்கு என்று கூறுவர்.", meaningEn: "The wise say that to such as are destitute of discerning sense the warm hugs of faithless women are (as ruinous as those of) the celestail female." },
  { number: 919, line1: "வரைவிலா மாணிழையார் மென்தோள் புரையிலாப்", line2: "பூரியர்கள் ஆழும் அளறு.", meaningTa: "ஒழுக்க வரையரை இல்லாத பொது மகளிரின் மெல்லிய தோள், உயர்வில்லாத கீழ்மக்கள் ஆழ்ந்து கிடக்கின்ற நரகமாகும்.", meaningEn: "The delicate shoulders of prostitutes with excellent jewels are a hell into which are plunged the ignorant base." },
  { number: 920, line1: "இருமனப் பெண்டிரும் கள்ளும் கவறும்", line2: "திருநீக்கப் பட்டார் தொடர்பு.", meaningTa: "உள்ளம் ஓரிடமும், உடம்பு ஓரிடமுமாக இருமனம் கொண்ட பாலிய் தொழிலாளர், கள், சூதாட்டம் இவை எல்லாம் திருமகளால்.", meaningEn: "Treacherous women, liquor, and gambling are the associates of such as have forsaken by Fortune." },
  { number: 921, line1: "உட்கப் படாஅர் ஒளியிழப்பர் எஞ்ஞான்றும்", line2: "கட்காதல் கொண்டொழுகு வார்.", meaningTa: "மதுப் பழக்கத்திற்கு அடிமையானவர்கள் தமது சிறப்பை இழப்பது மட்டுமல்ல; மாற்றாரும் அவர்களைக் கண்டு அஞ்ச மாட்டார்கள்.", meaningEn: "Those who always thirst after drink will neither inspire fear (in others) nor retain the light (of their a good name)." },
  { number: 922, line1: "உண்ணற்க கள்ளை உணில்உண்க சான்றோரான்", line2: "எண்ணப் படவேண்டா தார்.", meaningTa: "மது அருந்தக் கூடாது; சான்றோர்களின் நன் மதிப்பைப் பெற விரும்பாதவர் வேண்டுமானால் அருந்தலாம்.", meaningEn: "Let no liquor be drunk; if it is wantsd, let it be drunk by those who care not for esteem of the great." },
  { number: 923, line1: "ஈன்றாள் முகத்தேயும் இன்னாதால் என்மற்றுச்", line2: "சான்றோர் முகத்துக் களி.", meaningTa: "கள்ளருந்தி மயங்கிவிடும் தன் மகனை, அவன் குற்றங்களை மன்னிக்கக் கூடிய தாயே காணச் சகிக்கமாட்டாள் என்கிறபோது ஏனைய.", meaningEn: "Intoxication is painful even in the presence of (one's) mother; what will it not then be in that of the wise ?" },
  { number: 924, line1: "நாண்என்னும் நல்லாள் புறங்கொடுக்கும் கள்ளென்னும்", line2: "பேணாப் பெருங்குற்றத் தார்க்கு.", meaningTa: "மது மயக்கம் எனும் வெறுக்கத்தக்க பெருங்குற்றத்திற்கு ஆளாகியிருப்போரின் முன்னால் நாணம் என்று சொல்லப்படும் நற்பண்பு.", meaningEn: "The fair maid of modesty will turn her back on those who are guilty of the great and abominable crime of drunkenness." },
  { number: 925, line1: "கையறி யாமை உடைத்தே பொருள்கொடுத்து", line2: "மெய்யறி யாமை கொளல்.", meaningTa: "விலை கொடுத்தத் தன்னை அறியாத உடல் மயக்கத்தை வாங்குவது செயல் செய்யும் அறிவில்லாமை.", meaningEn: "To give money and purchase unconsciousness is the result of one's ignorance of (one's own actions)." },
  { number: 926, line1: "துஞ்சினார் செத்தாரின் வேறல்லர் எஞ்ஞான்றும்", line2: "நஞ்சுண்பார் கள்ளுண் பவர்.", meaningTa: "உறங்கினவர் இறந்தவரை விட வேறுபட்டவர் அல்லர், அவ்வாறே கள்ளுண்பவரும் அறிவுமயங்குதலால் நஞ்சு உண்பவரே ஆவர்.", meaningEn: "They that sleep resemble the deed; (likewise) they that drink are no other than poison-eaters." },
  { number: 927, line1: "உள்ளொற்றி உள்ளூர் நகப்படுவர் எஞ்ஞான்றும்", line2: "கள்ளொற்றிக் கண்சாய் பவர்", meaningTa: "போதைப் பொருளை மறைந்திருந்து பயன்படுத்தி மயங்குபவரை ஊருக்குள் வாழ்பவர் அறிந்து எப்போதும் இகழ்ந்து சிரிப்பர்.", meaningEn: "Those who always intoxicate themselves by a private (indulgence in) drink; will have their secrets detected and laughed at by their fellow-townsmen." },
  { number: 928, line1: "களித்தறியேன் என்பது கைவிடுக நெஞ்சத்து", line2: "ஒளித்ததூஉம் ஆங்கே மிகும்.", meaningTa: "போதைப் பொருளைப் பயன்படுத்தி அறியேன் என்று பிறர்முன் சொல்வதை விட்டுவிடுக. ஏனெனில் மனத்துக்குள் மறைத்தது, நிதானம்.", meaningEn: "Let (the drunkard) give up saying \"I have never drunk\"; (for) the moment (he drinks) he will simply betray his former attempt to conceal." },
  { number: 929, line1: "களித்தானைக் காரணம் காட்டுதல் கீழ்நீர்க்", line2: "குளித்தானைத் தீத்துரீஇ அற்று.", meaningTa: "குடிபோதைக்கு அடிமையாகி விட்டவனைத் திருத்த அறிவுரை கூறுவதும், தண்ணீருக்குள் மூழ்கிவிட்டவனைத் தேடிக்கண்டுபிடிக்கத்.", meaningEn: "Reasoning with a drunkard is like going under water with a torch in search of a drowned man." },
  { number: 930, line1: "கள்ளுண்ணாப் போழ்திற் களித்தானைக் காணுங்கால்", line2: "உள்ளான்கொல் உண்டதன் சோர்வு.", meaningTa: "ஒருவன் தான் கள் உண்ணாத போது கள்ளுண்டு மயங்கினவளைக் காணுமிடத்தில் உண்டு மயங்குவதால் வரும் சோர்வை நினைக்கமாட்டானோ.", meaningEn: "When (a drunkard) who is sober sees one who isn't, it looks as if he remembered not the evil effects of his (own) drink." },
  { number: 931, line1: "வேண்டற்க வென்றிடினும் சூதினை வென்றதூஉம்", line2: "தூண்டிற்பொன் மீன்விழுங்கி அற்று.", meaningTa: "வெற்றியே பெறுவதாயினும் சூதாடும் இடத்தை நாடக்கூடாது அந்த வெற்றி, தூண்டிலின் இரும்பு முள்ளில் கோத்த இரையை மட்டும்.", meaningEn: "Though able to win, let not one wants gambling; (for) even what is won is like a fish swallowing the iron in fish-hook." },
  { number: 932, line1: "ஒன்றெய்தி நூறிழக்கும் சூதர்க்கும் உண்டாங்கொல்", line2: "நன்றெய்தி வாழ்வதோர் ஆறு.", meaningTa: "ஒன்றைப் பெற்று, நூற்றினை இழந்துபோகும் சூதாடுபவர்க்கும் நல்லதைப் பெற்று வாழம் ஒரு வழி உண்டாகுமோ?", meaningEn: "That they may good obtain, and see a do wellous day? Is there indeed a means of livelihood that can bestow happiness on gamblers who gain one and." },
  { number: 933, line1: "உருளாயம் ஓவாது கூறின் பொருளாயம்", line2: "போஒய்ப் புறமே படும்.", meaningTa: "சூதாட்டத்தில் பெற்ற லாபத்தை ஓயாமல் சொல்லிச் சூதாடினால் உள்ள பொருளும், அதனால் வரும் லாபமும் அடுத்தவர் வசம்.", meaningEn: "If the leader is incessantly addicted to the rolling dice in the hope of gain, his wealth and the resources of it will take their departure and fall." },
  { number: 934, line1: "சிறுமை பலசெய்து சீரழக்கும் சூதின்", line2: "வறுமை தருவதொன்று இல்.", meaningTa: "துன்பங்கள் பல தந்த,நம் புகழையும் அழிக்கும் சூதைப் போல் நமக்கு வறுமை தருவது வேறு ஒன்றும் இல்லை.", meaningEn: "There is nothing else that brings (us) poverty like gambling which causes many a misery and destroys (one's) reputation." },
  { number: 935, line1: "கவறும் கழகமும் கையும் தருக்கி", line2: "இவறியார் இல்லாகி யார்.", meaningTa: "சூதாடு கருவியும், ஆடும் இடமும், கைத்திறமையும் மதித்துக் கைவிடாதவர், இல்லாதவர் ஆகிவிடுவார்.", meaningEn: "Penniless are those who by reason of their attachment would never forsake gambling, the gamblingplace and the handling (of dice)." },
  { number: 936, line1: "அகடாரார் அல்லல் உழப்பர்சூ தென்னும்", line2: "முகடியான் மூடப்பட் டார்.", meaningTa: "சூதாட்டம் என்னும் மூதேவியால் மூடப்பட்டவர் வயிறும் நிறையாமல், துன்பத்தையும் அனுபவிப்பர்.", meaningEn: "Those who are swallowed by the goddess called \"gambling\" will never have their hunger satisfied, but suffer the pangs of hell in the next world." },
  { number: 937, line1: "பழகிய செல்வமும் பண்பும் கெடுக்கும்", line2: "கழகத்துக் காலை புகின்.", meaningTa: "சூதாடு களத்துக்குள் காலம் கழிக்கப் புகுந்தால், அது பழஞ்செல்வத்தையும் அழிக்கும். நல்ல குணங்களையும் கெடுக்கும்.", meaningEn: "To waste time at the place of gambling will destroy inherited wealth and goodness of character." },
  { number: 938, line1: "பொருள்கெடுத்துப் பொய்மேற் கொளீஇ அருள்கெடுத்து", line2: "அல்லல் உழப்பிக்கும் சூது.", meaningTa: "சூதாட்டம் பொருளை அழிக்கும். பொய்யைச் சொல்லச் செய்யும்; மன இரக்கத்தைக் கெடுக்கும்; துன்பத்தையும் தரும்.", meaningEn: "Gambling destroys property, teaches falsehood, puts an end to kindness, and brings in misery (here and hereafter)." },
  { number: 939, line1: "உடைசெல்வம் ஊண்ஒளி கல்விஎன்று ஐந்தும்", line2: "அடையாவாம் ஆயங் கொளின்.", meaningTa: "சூதாட்டத்தை விரும்பினால் மரியாதை, கல்வி, செல்வம், உணவு, உடை என்ற ஐந்தும் சேரமாட்டா.", meaningEn: "The habit of gambling prevents the attainment of these five: clothing, wealth, food, a good name and learning." },
  { number: 940, line1: "இழத்தொறூஉம் காதலிக்கும் சூதேபோல் துன்பம்", line2: "உழத்தொறூஉம் காதற்று உயிர்.", meaningTa: "துன்பத்தை அனுபவிக்கும் போதெல்லாம் இந்த உடம்பின் மேல் உயிருக்குக் காதல் பெருகுவது போல, சூதாடிப் பொருளை இழந்து.", meaningEn: "As the gambler loves (his wrong) the more he loses by it, so does the soul caring (the body) the more it suffers through it." },
  { number: 941, line1: "மிகினும் குறையினும் நோய்செய்யும் நூலோர்", line2: "வளிமுதலா எண்ணிய மூன்று.", meaningTa: "மருத்துவ நூலோர் வாதம் பித்தம் சிலேத்துமம் என எண்ணிய மூன்று அளவுக்கு மிகுந்தாலும் குறைந்தாலும் நோய் உண்டாகும்.", meaningEn: "If (food and work are either) excessive or deficient, the three things enumerated by (medical) writers, flatulence, biliousness, and phlegm, will." },
  { number: 942, line1: "மருந்தென வேண்டாவாம் யாக்கைக்கு அருந்தியது", line2: "அற்றது போற்றி உணின்.", meaningTa: "உண்ட உணவு செரிப்பதற்கான கால இடைவெளி தந்து, உணவு அருந்துகிறவர்களின் உடலுக்கு வேறு மருந்தே தேவையில்லை.", meaningEn: "No medicine is necessary for God who eats after assuring (himself) that what he has (already) eaten has been digested." },
  { number: 943, line1: "அற்றால் அறவறிந்து உண்க அஃதுடம்பு", line2: "பெற்றான் நெடிதுய்க்கும் ஆறு.", meaningTa: "உண்ட உணவு செரித்ததையும், உண்ணும் உணவின் அளவையும் அறிந்து உண்பது நீண்ட நாள் வாழ்வதற்கு வழியாகும்.", meaningEn: "If (one's food has been) digested let one eat with moderation; (for) that is the way to prolong the life of an embodied soul." },
  { number: 944, line1: "அற்றது அறிந்து கடைப்பிடித்து மாறல்ல", line2: "துய்க்க துவரப் பசித்து.", meaningTa: "உண்டது செரித்ததா என்பதை உணர்ந்து, நன்கு பசியெடுத்த பிறகு உடலுக்கு ஒத்து வரக்கூடிய உணவை அருந்த வேண்டும்.", meaningEn: "Assure yourself that your food has been digested and never fail to eat, when very hungry, whatever isn't disagreeable (to you)." },
  { number: 945, line1: "மாறுபாடு இல்லாத உண்டி மறுத்துண்ணின்", line2: "ஊறுபாடு இல்லை உயிர்க்கு.", meaningTa: "ஒருவன் உடம்பிற்கு ஒவ்வொத உணவுகளை விலக்கி உண்டால், அவன் உயிர்க்கு நோயால் வரும் துன்பம் இல்லை.", meaningEn: "There will be no disaster to one's life if one eats with moderation, food that isn't disagreeable." },
  { number: 946, line1: "இழிவறிந்து உண்பான்கண் இன்பம்போல் நிற்கும்", line2: "கழிபேர் இரையான்கண் நோய்.", meaningTa: "அளவோடு உண்பவர் உடல் நலமுடன் வாழ்வதும் அதிகம் உண்பவர் நோய்க்கு ஆளாவதம் இயற்கை.", meaningEn: "As pleasure dwells with God who eats moderately, so disease (dwells) with the glutton who eats voraciously." },
  { number: 947, line1: "தீயள வன்றித் தெரியான் பெரிதுண்ணின்", line2: "நோயள வின்றிப் படும்.", meaningTa: "பசியின் அளவு அறியாமலும், ஆராயாமலும் அதிகம் உண்டால் நோய்களும் அளவின்றி வரும்.", meaningEn: "He will be afflicted with numberless diseases, who eats immoderately, ignorant (of the rules of health)." },
  { number: 948, line1: "நோய்நாடி நோய்முதல் நாடி அதுதணிக்கும்", line2: "வாய்நாடி வாய்ப்பச் செயல்.", meaningTa: "நோய் என்ன? நோய்க்கான காரணம் என்ன? நோய் தீர்க்கும் வழி என்ன? இவற்றை முறையாக ஆராய்ந்து சிகிச்சை செய்ய வேண்டும்.", meaningEn: "Let the physician enquire into the (nature of the) disease, its cause and its method of cure and treat it faithfully according to (medical rule)." },
  { number: 949, line1: "உற்றான் அளவும் பிணியளவும் காலமும்", line2: "கற்றான் கருதிச் செயல்.", meaningTa: "மருத்துவ நூலைக் கற்றவன், நோயுற்றவனுடைய வயது முதலியவற்றையும், நோயின் அளவையும், காலத்தையும் ஆராய்ந்து செய்ய வேண்டும்.", meaningEn: "The learned (physician) should ascertain the condition of his patient; the nature of his disease, and the season (of the year) and (then) proceed." },
  { number: 950, line1: "உற்றவன் தீர்ப்பான் மருந்துழைச் செல்வானென்று", line2: "அப்பால் நாற் கூற்றே மருந்து.", meaningTa: "நோயாளி, மருத்துவர், மருந்து, அதைத் தயாரிப்பவர் என மருந்து நான்கு வகைப்படும்.", meaningEn: "Medical science consists of four parts, that is, patient, physician, medicine and compounder; and each of these (again) contains four sub-divisions." },
  { number: 951, line1: "இற்பிறந்தார் கண்அல்லது இல்லை இயல்பாகச்", line2: "செப்பமும் நாணும் ஒருங்கு.", meaningTa: "நடுவு நிமையும் நாணமும் உயர்குடியில் பிறந்தவனிடத்தில் அல்லாமல் மற்றவரிடத்தில் இயல்பாக ஒருசேர அமைவதில்லை.", meaningEn: "Consistency (of thought, word and deed) and fear (of sin) are conjointly natural only to the high-born." },
  { number: 952, line1: "ஒழுக்கமும் வாய்மையும் நாணும்இம் மூன்றும்", line2: "இழுக்கார் குடிப்பிறந் தார்.", meaningTa: "நல்ல குடும்பத்தில் பிறந்தவர் ஒழுக்கம், உண்மை, நாணம் என்னும் இம்மூன்றிலிருந்தும் விலகமாட்டார்.", meaningEn: "The high-born will never deviate from these three; good manners, truthfulness and modesty." },
  { number: 953, line1: "நகைஈகை இன்சொல் இகழாமை நான்கும்", line2: "வகையென்ப வாய்மைக் குடிக்கு.", meaningTa: "முகமலர்ச்சி, ஈகைக்குணம், இனியசொல், பிறரை இகழாத பண்பாடு ஆகிய நான்கு சிறப்புகளும் உள்ளவர்களையே வாய்மையுள்ள குடிமக்கள்.", meaningEn: "A cheerful countenance, sharing, pleasant words, and an unreviling disposition, these four are said to be the proper qualities of the truly high-born." },
  { number: 954, line1: "அடுக்கிய கோடி பெறினும் குடிப்பிறந்தார்", line2: "குன்றுவ செய்தல் இலர்.", meaningTa: "கோடி கோடியாகச் செல்வத்தைப் பெற்றாலும் நல்ல குடும்பத்தில் பிறந்தவர் தம் குடும்பப் பெருமை குறைவதற்கான செயல்களைச்.", meaningEn: "Though blessed with immense wealth, the noble will never do anything unbecoming." },
  { number: 955, line1: "வழங்குவ துள்வீழ்ந்தக் கண்ணும் பழங்குடி", line2: "பண்பில் தலைப்பிரிதல் இன்று.", meaningTa: "தாம் பிறர்க்குக் கொடுத்துதவும் வன்மை வறுமையால் சுருங்கிய போதிலும், பழம் பெருமை உடைய குடியில் பிறந்தவர் தம்.", meaningEn: "Though their means fall off, those born in ancient families, won't lose their character (for sharing)." },
  { number: 956, line1: "சலம்பற்றிச் சால்பில செய்யார்மா சற்ற", line2: "குலம்பற்றி வாழ்தும் என் பார்.", meaningTa: "மாசற்ற பண்புடன் வாழ்வதாகக் கருதிக்கொண்டிருப்பவர்கள், வஞ்சக நினைவுடன் தகாத காரியங்களில் ஈடுபடமாட்டார்கள்.", meaningEn: "Those who seek to preserve the irreproachable honour of their families won't viciously do what is detrimental thereto." },
  { number: 957, line1: "குடிப்பிறந்தார் கண்விளங்கும் குற்றம் விசும்பின்", line2: "மத஧க்கண் மறுப்போல் உயர்ந்து.", meaningTa: "பிறந்த குடிக்குப் பெருமை சேர்ப்பவரிடமுள்ள சிறிய குறைகள், ஒளிவு மறைவு ஏதுமின்றி, வானத்து நிலவில் உள்ள குறைபோல.", meaningEn: "As spots on her bright orb that walks sublime the evening sky." },
  { number: 958, line1: "நலத்தின்கண் நாரின்மை தோன்றின் அவனைக்", line2: "குலத்தின்கண் ஐயப் படும்.", meaningTa: "என்னதான் அழகும் புகழும் உடையவனாக இருந்தாலும் அன்பு எனும் ஒரு பண்பு இல்லாதவனாக இருந்தால் அவன் பிறந்த குலத்தையே.", meaningEn: "If one of a good family betrays want of affection, his descent from it will be called in question." },
  { number: 959, line1: "நிலத்தில் கிடந்தமை கால்காட்டும் காட்டும்", line2: "குலத்தில் பிறந்தார்வாய்ச் சொல்.", meaningTa: "நிலத்தின் இயல்பை அதில் விளைந்த பயிர்காட்டும்; அதுபோலக் குடும்பத்தின் இயல்பை அதில் பிறந்தவர் பேசும் சொல் காட்டும்.", meaningEn: "As the sprout indicates the nature of the soil, (so) the speech of the noble indicates (that of one's birth)." },
  { number: 960, line1: "நலம்வேண்டின் நாணுடைமை வேண்டும் குலம்வேண்டின்", line2: "வேண்டுக யார்க்கும் பணிவு.", meaningTa: "ஒருவன் தனக்கு நன்மை வேண்டும் என்று எண்ணினால் அவனிடம் நாணம் இருக்க வேண்டும். நற்குடும்பத்தவன் என்ற பெயர் வேண்டும்.", meaningEn: "He who wants a good name must wants modesty; and he who wants (the continuance of) a family greatness must be submissive to all." },
  { number: 961, line1: "இன்றி அமையாச் சிறப்பின ஆயினும்", line2: "குன்ற வருப விடல்.", meaningTa: "இன்றியமையாத சிறப்பை உடைய செயல்களே ஆயினும் குடிப்பெருமை தாழுமாறு வரும் செயல்களை ஒருவன் செய்யாமல் விட வேண்டும்.", meaningEn: "Actions that would degrade (one's) family should not be done; though they may be so important that not doing them would end in death." },
  { number: 962, line1: "சீரினும் சீரல்ல செய்யாரே சீரொடு", line2: "பேராண்மை வேண்டு பவர்.", meaningTa: "புகழ்மிக்க வீர வாழ்க்கையை விரும்புகிறவர், தனக்கு எப்படியும் புகழ் வரவேண்டுமென்பதற்காக மான உணர்வுக்குப் புறம்பான.", meaningEn: "Those who wants (to maintain their) honour, will surely do nothing dishonourable, even for the sake of a good name." },
  { number: 963, line1: "பெருக்கத்து வேண்டும் பணிதல் சிறிய", line2: "சுருக்கத்து வேண்டும் உயர்வு.", meaningTa: "உயர்ந்த நிலை வரும்போது அடக்க உணர்வும், அந்த நிலை மாறிவிட்ட சூழலில் யாருக்கும் அடிமையாக அடங்கி நடக்காத மான உணர்வும்.", meaningEn: "In great doing well humility is becoming; dignity, in great adversity." },
  { number: 964, line1: "தலையின் இழிந்த மயிரனையர் மாந்தர்", line2: "நிலையின் இழிந்தக் கடை.", meaningTa: "மக்கள் தம் உயர்வுக்கு உரிய நிலையிலிருந்து தாழ்ந்த போது, தலைமையிலிருந்து விழுந்து தாழ்வுற்ற மயிரினைப் போன்றவர் ஆவர்.", meaningEn: "They who have fallen from their (high) position are like the hair which has fallen from the head." },
  { number: 965, line1: "குன்றின் அனையாரும் குன்றுவர் குன்றுவ", line2: "குன்றி அனைய செயின்.", meaningTa: "நல்ல குடும்பத்தில் பிறந்து மலைபோல உயர்ந்தவரும்கூட தாழ்வானவற்றை ஒரு குன்றிமணி அளவு செய்தாலும் தாழ்ந்து போவார்.", meaningEn: "Even those who are exalted like a hill will be thought low, if they commit deeds that are debasing." },
  { number: 966, line1: "புகழ்இன்றால் புத்தேள்நாட்டு உய்யாதால் என்மற்று", line2: "இகழ்வார்பின் சென்று நிலை.", meaningTa: "இகழ்வதையும் பொறுத்துக்கொண்டு, மானத்தை விட்டுவிட்டு ஒருவர் பின்னே பணிந்து செல்வதால் என்ன புகழ் கிடைக்கும்? இல்லாத.", meaningEn: "Why follow people who scorn, and at their bidding wait?" },
  { number: 967, line1: "ஒட்டார்பின் சென்றொருவன் வாழ்தலின் அந்நிலையே", line2: "கெட்டான் எனப்படுதல் நன்று.", meaningTa: "தன்னை மதிக்காதவரின் பின்னால் சென்று உயிர் வாழ்வதைவிடச் செத்தொழிவது எவ்வளவோ மேல்.", meaningEn: "It is better for a person to be said of him that he died in his usual state than that he eked out his life by following those who disgraced him." },
  { number: 968, line1: "மருந்தோமற்று ஊன்ஓம்பும் வாழ்க்கை பெருந்தகைமை", line2: "பீடழிய வந்த இடத்து.", meaningTa: "குடும்பப் பெருமைக்கான மானம் அழிய நேர்ந்தபோது இறந்து போகாமல் இந்த உடம்பைக் காத்துவாழும் வாழ்க்கை சாவாமைக்கு மருந்து.", meaningEn: "For the high-born to keep their body in life when their honour is gone will certainly not prove a remedy against death." },
  { number: 969, line1: "மயிர்நீப்பின் வாழாக் கவரிமா அன்னார்", line2: "உயிர்நீப்பர் மானம் வரின்.", meaningTa: "தன் உடம்பிலிருந்து மயிர் நீங்கினால் உயிர்வாழாத கவரிமானைப் போன்றவர் மானம் அழிய நேர்ந்தால் உயிரை விட்டுவிடுவர்.", meaningEn: "Those who give up (their) life when (their) honour is at stake are like the yark which kills itself at the loss of (even one of) its hairs." },
  { number: 970, line1: "இளிவரின் வாழாத மானம் உடையார்", line2: "ஒளிதொழுது ஏத்தும் உலகு.", meaningTa: "தனக்கு இகழ்ச்சி வரும்போது உயிர்வாழாத மானம் மிக்க மனிதரின் புகழ் வடிவைப் பெரியோர் தொழுது பாராட்டுவர்.", meaningEn: "The world will (always) praise and adore the a good name of the honourable who would rather die than suffer indignity." },
  { number: 971, line1: "ஒளிஒருவற்கு உள்ள வெறுக்கை இளிஒருவற்கு", line2: "அஃதிறந்து வாழ்தும் எனல்.", meaningTa: "ஒருவரின் வாழ்க்கைக்கு ஒளிதருவது ஊக்கமேயாகும் ஊக்கமின்றி உயிர்வாழ்வது இழிவு தருவதாகும்.", meaningEn: "One's light is the abundance of one's courage; one's darkness is the wants to live destitute of such (a state of mind.)." },
  { number: 972, line1: "பிறப்பொக்கும் எல்லா உயிர்க்கும் சிறப்பொவ்வா", line2: "செய்தொழில் வேற்றுமை யான்.", meaningTa: "எல்லா மக்களும் பிறப்பால் சமம‌ே; அவரவர் செய்யும் செயல் வேறுபாடுகளால் மட்டுமே பெருமை வரும்.", meaningEn: "All human beings agree as regards their birth but differ as regards their characteristics, because of the different qualities of their actions." },
  { number: 973, line1: "மேலிருந்தும் மேலல்லார் மேலல்லர் கீழிருந்தும்", line2: "கீழல்லார் கீழல் லவர்.", meaningTa: "நல்ல பண்புகள் இல்லாதவர் உயர்ந்த பதவியில் இருந்தாலும் பெருமைக்கு உரியவர் அல்லர்; சிறிய பதவியில் இருந்தாலும் உயர்வான.", meaningEn: "Though (raised) above, the base can't become great; though (brought) low, the great can't become base." },
  { number: 974, line1: "ஒருமை மகளிரே போலப் பெருமையும்", line2: "தன்னைத்தான் கொண்டொழுகின் உண்டு.", meaningTa: "ஒரு தன்மையான கற்புடைய மகளிரைப்போல் பெருமைப் பண்பும் ஒருவன் தன்னைத் தான் காத்துக் கொண்டு நடந்தால் உளதாகும்.", meaningEn: "Exists while to itself is true." },
  { number: 975, line1: "பெருமை யுடையவர் ஆற்றுவார் ஆற்றின்", line2: "அருமை உடைய செயல்.", meaningTa: "அரிய செயல்களை அவற்றுக்கு உரிய முறையான வழியில் செய்து முடிக்கும் திறமையுடையவர்கள் பெருமைக்குரியவராவார்கள்.", meaningEn: "The great will be able to perform, in the proper way, deeds difficult (for others to do)." },
  { number: 976, line1: "சிறியார் உணர்ச்சியுள் இல்லை பெரியாரைப்", line2: "பேணிக் கொள் வேம் என்னும் நோக்கு.", meaningTa: "பெரியோரைப் போற்றி ஏற்றுக்கொள்ளும் நோக்கம், அறிவிற் சிறியோரின் உணர்ச்சியில் ஒன்றியிருப்பதில்லை.", meaningEn: "It is never in the nature of the base to seek the society of the great and partake of their nature." },
  { number: 977, line1: "இறப்பே புரிந்த தொழிற்றாம் சிறப்புந்தான்", line2: "சீரல் லவர்கண் படின்.", meaningTa: "சிறப்பு நிலையும் தனக்கு பொருந்தாத சீரற்ற கீழ் மக்களிடம் ஏற்பட்டால், வரம்பு மீறிய செயலை உடையதாகும்.", meaningEn: "Even nobility of birth, wealth and learning, if in (the possession of) the base, will (only) produce everincreasing pride." },
  { number: 978, line1: "பணியுமாம் என்றும் பெருமை சிறுமை", line2: "அணியுமாம் தன்னை வியந்து.", meaningTa: "பெருமைப் பண்பு எக்காலத்திலும் பணிந்து நடக்கும், ஆனால் சிறுமையோ தன்னைத் தானே வியந்துப் பாராட்டிக் கொள்ளும்.", meaningEn: "The great will always humble himself; but the mean will exalt himself in self-admiration." },
  { number: 979, line1: "பெருமை பெருமிதம் இன்மை சிறுமை", line2: "பெருமிதம் ஊர்ந்து விடல்.", meaningTa: "ஆணவமின்றி அடக்கமாக இருப்பது பெருமை எனப்படும் ஆணவத்தின் எல்லைக்கே சென்று விடுவது சிறுமை எனப்படும்.", meaningEn: "Freedom from conceit is (the nature of true) greatness; (while) obstinacy therein is (that of) meanness." },
  { number: 980, line1: "அற்றம் மறைக்கும் பெருமை சிறுமைதான்", line2: "குற்றமே கூறி விடும்.", meaningTa: "பெருமைப் பண்பு பிறருடைய குறைப்பாட்டை மறைக்கும், சிறுமையோ பிறருடைய குற்றத்தையே எடுத்துச் சொல்லிவிடும்.", meaningEn: "The great hide the faults of others; the base only divulge them." },
  { number: 981, line1: "கடன்என்ப நல்லவை எல்லாம் கடன்அறிந்து", line2: "சான்றாண்மை மேற்கொள் பவர்க்கு.", meaningTa: "கடமை இவை என்று அறிந்து சான்றான்மை மேற்கொண்டு நடப்பவர்க்கு நல்லவை எல்லாம் இயல்பான கடமை என்று கூறுவர்.", meaningEn: "It is said that those who are conscious of their duty and behave with a perfect goodness will regard as natural all that is good." },
  { number: 982, line1: "குணநலம் சான்றோர் நலனே பிறநலம்", line2: "எந்நலத்து உள்ளதூஉம் அன்று.", meaningTa: "நற்பண்பு ஒன்றே சான்றோர்க்கான அழகாகும் வேறு எந்த அழகும் அழகல்ல.", meaningEn: "The only delight of the perfect is that of their goodness; all other (sensual) delights aren't to be included among any (true) delights." },
  { number: 983, line1: "அன்புநாண் ஒப்புரவு கண்ணோட்டம் வாய்மையொடு", line2: "ஐந்துசால் ஊன்றிய தூண்.", meaningTa: "அன்பு, நாணம்,ஒப்புரவு, கண்ணோட்டம், வாய்மை, என்னும் ஐந்து பண்புகளும், சால்பு என்பதைத் தாங்கியுள்ள தூண்களாகும்.", meaningEn: "Affection, fear (of sin), kindness, favour and truthfulness; these are the five pillars on which perfect goodness rests." },
  { number: 984, line1: "கொல்லா நலத்தது நோன்மை பிறர்தீமை", line2: "சொல்லா நலத்தது சால்பு.", meaningTa: "பிற உயிர்களைக் கொல்லாதிருப்பது தனத்திற்கு அழகு; பிறர் குறைகளைப் பேசாதிருப்பது சான்றாண்மைக்கு அழகு.", meaningEn: "Hard good practice consists in the goodness that kills not , and perfection in the goodness that tells not others' faults." },
  { number: 985, line1: "ஆற்றுவார் ஆற்றல் பணிதல் அதுசான்றோர்", line2: "மாற்றாரை மாற்றும் படை.", meaningTa: "ஒரு செயலைச் செய்து முடிப்பவர் திறமை, தம்முடன் பணி ஆற்றுபவரிடம் பணிந்து வேலை வாங்குதலே; சான்றாண்மை தம் பகைவரையும்.", meaningEn: "Stooping (to inferiors) is the strength of those who can accomplish (an undertaleader); and that is the weapon with which the great avert their foes." },
  { number: 986, line1: "சால்பிற்குக் கட்டளை யாதெனின் தோல்வி", line2: "துலையல்லார் கண்ணும் கொளல்.", meaningTa: "சமநிலையில் இல்லாதவர்களால் தனக்கு ஏற்படும் தோல்வியைக்கூட ஒப்புக் கொள்ளும் மனப்பக்குவம்தான் ஒருவரின் மேன்மைக்கு.", meaningEn: "The touch-stone of perfection is to receive a defeat even at the hands of one's inferiors." },
  { number: 987, line1: "இன்னாசெய் தார்க்கும் இனியவே செய்யாக்கால்", line2: "என்ன பயத்ததோ சால்பு.", meaningTa: "தமக்குத் தீமை செய்தவர்க்கும் நன்மையே செய்யா விட்டால் சான்றான்மையினால் பயன்தான் என்ன?", meaningEn: "Of what avail is perfect goodness if it can't do pleasing things even to those who have pained (it) ?" },
  { number: 988, line1: "இன்மை ஒருவற்கு இளிவன்று சால்பென்னும்", line2: "திண்மை உண் டாகப் பெறின்.", meaningTa: "சால்பு என்கிற உறுதியைச் செல்வமெனக் கொண்டவருக்கு வறுமை என்பது இழிவு தரக் கூடியதல்ல.", meaningEn: "Poverty is no disgrace to one who abounds in good qualities." },
  { number: 989, line1: "ஊழி பெயரினும் தாம்பெயரார் சான்றாண்மைக்கு", line2: "ஆழி எனப்படு வார்.", meaningTa: "சான்றாண்மை எனப்படும் கடலுக்குக் கரை எனப்படும் சான்றோர், காலம் மாறினாலும் தாம் மாறமாட்டார்.", meaningEn: "Those who are said to be the shore of the sea of perfection will never change, though ages may change." },
  { number: 990, line1: "சான்றவர் சான்றாண்மை குன்றின் இருநிலந்தான்", line2: "தாங்காது மன்னோ பொறை.", meaningTa: "சான்றோரின் நற்பண்பே குறையத்தொடங்கினால் அதனை இந்த உலகம் பொறுமையுடன் தாங்கிக் கொள்ளாது.", meaningEn: "If there is a defect in the character of the perfect, (even) the great world can't bear (its) burden." },
  { number: 991, line1: "எண்பதத்தால் எய்தல் எளிதென்ப யார்மாட்டும்", line2: "பண்புடைமை என்னும் வழக்கு.", meaningTa: "பண்பு உடையவராக வாழும் நல்வழியை, யாரிடத்திலும் எளிய செவ்வியுடன் இருப்பதால் அடைவது எளிது என்று கூறுவர்.", meaningEn: "If one is easy of access to all, it will be easy for one to obtain the goodness called goodness." },
  { number: 992, line1: "அன்புடைமை ஆன்ற குடிப்பிறத்தல் இவ்விரண்டும்", line2: "பண்புடைமை என்னும் வழக்கு.", meaningTa: "அன்புடையவராக இருத்தல், உயர்ந்த குடியில் பிறந்த தன்மை அமைந்திருத்தல் ஆகிய இவ் விரண்டும் பண்பு உடையவராக வாழும்.", meaningEn: "Affectionateness and birth in a good family, these two constitute what is called a proper behaviour to all." },
  { number: 993, line1: "உறுப்பொத்தல் மக்களொப்பு அன்றால் வெறுத்தக்க", line2: "பண்பொத்தல் ஒப்பதாம் ஒப்பு.", meaningTa: "உடம்பால் ஒத்திருத்தல் மக்களோடு ஒப்புமை அன்று, பொருந்தத்தக்கப் பண்பால் ஒத்திருத்தலே கொள்ளத்தக்க ஒப்புமையாகும்.", meaningEn: "Resemblance of bodies is no resemblance of souls; true resemblance is the resemblance of qualities that attract." },
  { number: 994, line1: "நயனொடு நன்றி புரிந்த பயனுடையார்", line2: "பண்புபா ராட்டும் உலகு.", meaningTa: "நீதியையும் அறத்தையும் விரும்பிப் பிறர்க்கும் பயன்படுபவரின் பண்பினை உலகத்தவர் சிறப்பித்துப் பேசுவர்.", meaningEn: "The world applauds the character of those whose usefulness results from their equity and charity." },
  { number: 995, line1: "நகையுள்ளும் இன்னா திகழ்ச்சி பகையுள்ளும்", line2: "பண்புள பாடறிவார் மாட்டு.", meaningTa: "விளையாட்டாகக்கூட ஒருவரை இகழ்ந்து பேசுவதால் கேடு உண்டாகும் அறிவு முதிர்ந்தவர்கள், பகைவரிடமும் பண்புகெடாமல் நடந்து.", meaningEn: "Reproach is painful to one even in sport; those (so) who know the nature of others exhibit (pleasing) qualities even when they are hated." },
  { number: 996, line1: "பண்புடையார்ப் பட்டுண்டு உலகம் அதுஇன்றேல்", line2: "மண்புக்கு மாய்வது மன்.", meaningTa: "உலக நடைமுறைகள், பண்பாளர்களைச் சார்ந்து இயங்க வேண்டும் இல்லையேல் அந்த நடைமுறைகள் நாசமாகிவிடும்.", meaningEn: "The (way of the) world subsists by contact with the good; if not, it would bury itself in the earth and perish." },
  { number: 997, line1: "அரம்போலும் கூர்மைய ரேனும் மரம்போல்வர்", line2: "மக்கட்பண்பு இல்லா தவர்.", meaningTa: "மனிதப்பண்பு இல்லாதவர்கள் அரம் போல அறிவுக்கூர்மை படைத்தவர் என்றாலும் ஓர் அறிவு படைத்த மரத்தைப் போன்றோரே.", meaningEn: "He who is destitute of (true) human qualities (only) resembles a tree, though he may possess the sharpness of a file." },
  { number: 998, line1: "நண்பாற்றார் ஆகி நயமில செய்வார்க்கும்", line2: "பண்பாற்றார் ஆதல் கடை.", meaningTa: "தம்முடன் நட்புச் செய்யாமல் பகைமை கொண்டு தீமையே செய்பவர்க்கும் கூடப் பண்பற்றவராய் வாழ்வது இழுக்கே.", meaningEn: "It is wrong (for the wise) not to exhibit (good) qualities even towards those who bearing no friendship (for them) do only what is hateful." },
  { number: 999, line1: "நகல்வல்லர் அல்லார்க்கு மாயிரு ஞாலம்", line2: "பகலும்பாற் பட்டன்று இருள்.", meaningTa: "நண்பர்களுடன் பழகி மகிழத் தெரியாதவர்களுக்கு உலகம் என்பது பகலில் கூட இருட்டாகத்தான் இருக்கும்.", meaningEn: "To those who can't rejoice, the wide world is buried darkness even in (broad) day light." },
  { number: 1000, line1: "பண்பிலான் பெற்ற பெருஞ்செல்வம் நன்பால்", line2: "கலந்தீமை யால்திரிந் தற்று.", meaningTa: "நல்ல பண்பு இல்லாதவன் அடைந்த பெரும் செல்வம், பாத்திரக் கேட்டால் அதிலுள்ள நல்ல பால் கெட்டுப் போவது போலாம்.", meaningEn: "The great wealth obtained by one who has no goodness will perish like pure milk spoilt by the." },
  { number: 1001, line1: "வைத்தான்வாய் சான்ற பெரும்பொருள் அஃதுண்ணான்", line2: "செத்தான் செயக்கிடந்தது இல்.", meaningTa: "அடங்காத ஆசையினால் வீடு கொள்ளாத அளவுக்குச் செல்வத்தைச் சேர்த்து வைத்து அதனை அனுபவிக்காமல் செத்துப் போகிறவனுக்கு,.", meaningEn: "He who does not enjoy the immense riches he has heaped up in his house, is (to be reckoned as) dead, (for) there is nothing achieved (by him)." },
  { number: 1002, line1: "பொருளானாம் எல்லாமென்று ஈயாது இவறும்", line2: "மருளானாம் மாணாப் பிறப்பு", meaningTa: "பொருளால் எல்லாம் ஆகும் என்று பிறர்க்கு ஒன்றும் கொடுக்காமல் இறுகப்பற்றிய மயக்கத்தால் சிறப்பில்லாத பிறவி உண்டாம்.", meaningEn: "He who knows that wealth yields every pleasure and yet is so blind as to lead miserly life will be born a demon." },
  { number: 1003, line1: "ஈட்டம் இவறி இசைவேண்டா ஆடவர்", line2: "தோற்றம் நிலக்குப் பொறை.", meaningTa: "சேர்த்து வைப்பதையே விரும்பிப் பற்றுள்ளம் கொண்டு புகழை விரும்பாத மக்கள் பிறந்து வாழ்தல் நிலத்திற்கு பாரமே ஆகும்.", meaningEn: "A burden to the earth are people bent on the acquisition of riches and not (true) a good name." },
  { number: 1004, line1: "எச்சமென்று என்எண்ணுங் கொல்லோ ஒருவரால்", line2: "நச்சப் படாஅ தவன்.", meaningTa: "யாராலும் விரும்பப்படாத ஒருவன், தன் மரணத்திற்குப் பிறகு எஞ்சி நிற்கப் போவது என்று எதனை நினைத்திட முடியும்?", meaningEn: "What will the miser who isn't liked (by any one) regard as his own (in the world to come) ?" },
  { number: 1005, line1: "கொடுப்பதூஉம் துய்ப்பதூஉம் இல்லார்க்கு அடுக்கிய", line2: "கோடியுண் டாயினும் இல்.", meaningTa: "தேவைப்படுவோர்க்குக் கொடுப்பதும், தேவை கண்டு தாம் அனுபவிப்பதும் இல்லாதவர்க்குப்பல மடங்காக அடுக்கிய கோடிப் பொருள்.", meaningEn: "Those who neither give (to others) nor enjoy (their property) are (truly) destitute, though possessing immense riches." },
  { number: 1006, line1: "ஏதம் பெருஞ்செல்வம் தான்துவ்வான் தக்கார்க்கொன்று", line2: "ஈதல் இயல்பிலா தான்.", meaningTa: "தானும் அனுபவிக்காமல், தகுதியானவர்க்குத் தரும் மனப்பாங்கும் இல்லாமல் வாழ்பவனிடம் இருக்கும் பெரும் செல்வம் ஒரு நோயே.", meaningEn: "He who enjoys not (his riches) nor relieves the wants of the worthy is a disease to his wealth." },
  { number: 1007, line1: "அற்றார்க்கொன்று ஆற்றாதான் செல்வம் மிகநலம்", line2: "பெற்றாள் தமியள்மூத் தற்று.", meaningTa: "வறியவர்க்கு எதுவும் வழங்கி உதவாதவனுடைய செல்வம், மிகுந்த அழகியொருத்தி, தன்னந்தனியாகவே இருந்து முதுமையடைவதைப் போன்றது.", meaningEn: "The wealth of God who never bestows anything on the destitute is like a woman of beauty growing old without a partner." },
  { number: 1008, line1: "நச்சப் படாதவன் செல்வம் நடுவூருள்", line2: "நச்சு மரம்பழுத் தற்று.", meaningTa: "எவராலும் விரும்பப்படாதவனின் செல்வம் ஊரின் நடுவே நின்ற நச்சு மரம் பழுத்தது போலாம்.", meaningEn: "The wealth of God who is disliked (by all) is like the fruit-bearing of the etty tree in the midst of a town." },
  { number: 1009, line1: "அன்பொரீஇத் தற்செற்று அறநோக்காது ஈட்டிய", line2: "ஒண்பொருள் கொள்வார் பிறர்.", meaningTa: "பிறர்க்கு ஈயாமல் அன்பை விட்டு விலகி, எதையும் அனுபவிக்காமல் தன்னை வருத்தி, அறத்தை எண்ணாது சேர்த்த பொருளை மற்றவர்.", meaningEn: "Others usurp the shining gold In loveless, stingy, vicious hold." },
  { number: 1010, line1: "சீருடைச் செல்வர் சிறுதுனி மாரி", line2: "வறங்கூர்ந் தனையது உடைத்து.", meaningTa: "புகழ் பொருந்திய செல்வர் உற்ற சிறிய வறுமை உலகத்தைக் காக்க வல்ல மேகம் வறுமை மிகுந்தாற் போன்ற தன்மை உடையது.", meaningEn: "The short-lived poverty of those who are noble and rich is like the clouds becoming poor (for a while)." },
  { number: 1011, line1: "கருமத்தால் நாணுதல் நாணுந் திருநுதல்", line2: "நல்லவர் நாணுப் பிற.", meaningTa: "தகாத செயல் காரணமாக நாணுவதே நாணமாகும், பெண்களுக்கு இயல்பான மற்ற நாணங்கள் வேறு வகையானவை.", meaningEn: "True modesty is the fear of (evil) deeds; all other modesty is (simply) the bashfulness of good maids." },
  { number: 1012, line1: "ஊணுடை எச்சம் உயிர்க்கெல்லாம் வேறல்ல", line2: "நாணுடைமை மாந்தர் சிறப்பு.", meaningTa: "உணவு, உடை இன்னும் பிற சிறப்புகள், எல்லா மனிதர்க்கும் ஒன்றே; நல்ல மனிதர்க்குச் சிறப்பாவது நாண் உடைமையே.", meaningEn: "Food, clothing and the like are common to all people but modesty is peculiar to the good." },
  { number: 1013, line1: "ஊனைக் குறித்த உயிரெல்லாம் நாண்என்னும்", line2: "நன்மை குறித்தது சால்பு.", meaningTa: "உடலுடன் இணைந்தே உயிர் இருப்பது போல், மாண்பு என்பது நாண உணர்வுடன் இணைந்து இருப்பதேயாகும்.", meaningEn: "As the body is the abode of the spirit, so the excellence of modesty is the abode of perfection." },
  { number: 1014, line1: "அணிஅன்றோ நாணுடைமை சான்றோர்க்கு அஃதின்றேல்", line2: "பிணிஅன்றோ பீடு நடை.", meaningTa: "சான்றோர்க்கு நாணுடைமை அணிகலம் அன்றோ, அந்த அணிகலம் இல்லையானால் பெருமிதமாக நடக்கும் நடை ஒரு நோய் அன்றோ.", meaningEn: "Isn't the modesty ornament of the noble ? Without it, their haughtiness would be a pain (to others)." },
  { number: 1015, line1: "பிறர்பழியும் தம்பழியும் நாணுவார் நாணுக்கு", line2: "உறைபதி என்னும் உலகு.", meaningTa: "தமக்கு வரும் பழிக்காக மட்டுமின்றிப் பிறர்க்கு வரும் பழிக்காகவும் வருந்தி நாணுகின்றவர், நாணம் எனும் பண்பிற்கான.", meaningEn: "The world regards as the abode of modesty God who fear his own and other's guilt." },
  { number: 1016, line1: "நாண்வேலி கொள்ளாது மன்னோ வியன்ஞாலம்", line2: "பேணலர் மேலா யவர்.", meaningTa: "பெரியவர்கள் தனக்குப் பாதுகாப்பாக நாணத்தைக் கொள்வாரே அல்லாமல், இந்தப் பெரிய உலகத்தைக் கொள்ள விரும்ப மாட்டார்கள்.", meaningEn: "The great make modesty their barrier (of defence) and not the wide world." },
  { number: 1017, line1: "நாணால் உயிரைத் துறப்பர் உயிர்ப்பொருட்டால்", line2: "நாண்துறவார் நாணாள் பவர்.", meaningTa: "நாணத்தை தமக்கரிய பண்பாகக் கொள்பவர் நாணத்தால் உயிரை விடுவர், உயிரைக் காக்கும் பொருட்டாக நாணத்தை விட மாட்டார்.", meaningEn: "The modest would rather lose their life for the sake of modesty than lose modesty for the sake of life." },
  { number: 1018, line1: "பிறர்நாணத் தக்கது தான்நாணா னாயின்", line2: "அறம்நாணத் தக்கது உடைத்து.", meaningTa: "ஒருவன் மற்றவர் நாணத்தக்க பழிக்குக் காரணமாக இருந்தும் தான் நாணாமலிருப்பானானால், அறம் நாணி அவனைக் கைவிடும்.", meaningEn: "Goodness is likely to forsake God who shamelessly does what others are ashamed of." },
  { number: 1019, line1: "குலஞ்சுடும் கொள்கை பிழைப்பின் நலஞ்சுடும்", line2: "நாணின்மை நின்றக் கடை.", meaningTa: "ஒருவன் ஒழுக்கம் கெட்டால் அவன் குடும்பப் பிறப்பு கெடும்; அவனே நாணம் இல்லாது நின்றால் அவன் நலம் எல்லாம் கெடும்.", meaningEn: "Want of manners injures one's family; but want of modesty injures one's character." },
  { number: 1020, line1: "நாண்அகத் தில்லார் இயக்கம் மரப்பாவை", line2: "நாணால் உயிர்மருட்டி அற்று.", meaningTa: "உயிர் இருப்பது போலக் கயிறுகொண்டு ஆட்டி வைக்கப்படும் மரப்பொம்மைக்கும், மனத்தில் நாணமெனும் ஓர் உணர்வு இல்லாமல் உலகில்.", meaningEn: "The actions of those who are without modesty at heart are like those of puppet moved by a string." },
  { number: 1021, line1: "கருமம் செயஒருவன் கைதூவேன் என்னும்", line2: "பெருமையின் பீடுடையது இல்.", meaningTa: "குடிப் பெருமைக்கு உரிய கடமையைச் செய்வதற்குச் சோர்வடைய மாட்டேன் என்று ஒருவன் முயலும் பெருமையைப் போல மேம்பாடானது.", meaningEn: "There is no higher greatness than that of one saying I won't cease in my effort (to raise my family)." },
  { number: 1022, line1: "ஆள்வினையும் ஆன்ற அறிவும் எனஇரண்டின்", line2: "நீள்வினையால் நீளும் குடி.", meaningTa: "முயற்சி, நிறைந்த அறிவு என்னும் இரண்டுடன் இடைவிடாத செயல் செய்யக் குடும்பமும் நாடும் உயரும்.", meaningEn: "One's family is raised by untiring perseverance in both effort and wise contrivances." },
  { number: 1023, line1: "குடிசெய்வல் என்னும் ஒருவற்குத் தெய்வம்", line2: "மடிதற்றுத் தான்முந் துறும்.", meaningTa: "என் குடியை உயரச் செய்வேன் என்று முயலும் ஒருவனுக்கு ஊழ், ஆடையைக் கட்டிக் கொண்டு தானே முன் வந்து துணை செய்யும்.", meaningEn: "The Deity will clothe itself and appear before God who resolves on raising his family." },
  { number: 1024, line1: "சூழாமல் தானே முடிவெய்தும் தம்குடியைத்", line2: "தாழாது உஞற்று பவர்க்கு.", meaningTa: "தம் குடி உயர்வதற்கான செயலை விரைந்து முயன்று செய்வோர்க்கு அவர் ஆராயமலே அச் செயல் தானே நிறைவேறும்.", meaningEn: "Those who are prompt in their efforts (to better their family) need no deliberation, such efforts will of themselves succeed." },
  { number: 1025, line1: "குற்றம் இலனாய்க் குடிசெய்து வாழ்வானைச்", line2: "சுற்றமாச் சுற்றும் உலகு.", meaningTa: "தவறானவற்றைச் செய்யாமல் தன் வீட்டையும் நாட்டையும் மேன்மை அடையச் செய்து வாழ்பவனை உயர்ந்தோர் தம் சுற்றமாக ஏற்பர்.", meaningEn: "People will eagerly seek the friendship of the do wellous soul who has raised his family without foul means." },
  { number: 1026, line1: "நல்லாண்மை என்பது ஒருவற்குத் தான்பிறந்த", line2: "இல்லாண்மை ஆக்கிக் கொளல்.", meaningTa: "நல்ல முறையில் ஆளும் திறமை பெற்றவர், தான் பிறந்த குடிக்கே பெருமை சேர்ப்பவராவார்.", meaningEn: "A person's true manliness consists in maleader himself the head and benefactor of his family." },
  { number: 1027, line1: "அமரகத்து வன்கண்ணர் போலத் தமரகத்தும்", line2: "ஆற்றுவார் மேற்றே பொறை.", meaningTa: "போர்க்களத்தில் எதிர்ப்புகளைத் தாங்கிப் படை நடத்தும் பொறுப்பு அதற்கான ஆற்றல் படைத்தவர்களிடம் இருப்பது போலத்தான்.", meaningEn: "Amid his kindred so the burthen rests upon the strong." },
  { number: 1028, line1: "குடிசெய்வார்க் கில்லை பருவம் மடிசெய்து", line2: "மானங் கருதக் கெடும்.", meaningTa: "குடி உயர்வதற்கான செயல் செய்கின்றவர்க்கு உரிய காலம் என்று ஒன்று இல்லை, சோம்பல் கொண்டு தம் மானத்தைக் கருதுவாரானால்.", meaningEn: "As a family suffers by (one's) indolence and false dignity there is to be so season (good or bad) to those who strive to raise their family." },
  { number: 1029, line1: "இடும்பைக்கே கொள்கலம் கொல்லோ குடும்பத்தைக்", line2: "குற்ற மறைப்பான் உடம்பு.", meaningTa: "தன் குடிக்கு வரக்குடிய குற்றத்தை வராமல் நீக்க முயல்கின்ற ஒருவனுடைய உடம்பு துன்பத்திற்கே இருப்பிடமானதோ.", meaningEn: "Is it only to suffering that his body is exposed who undertakes to preserve his family from evil ?" },
  { number: 1030, line1: "இடுக்கண்கால் கொன்றிட வீழும் அடுத்தூன்றும்", line2: "நல்லாள் இலாத குடி.", meaningTa: "வரும் துன்பத்தை எதிர் நின்று தாங்கக் கூடிய ஆற்றலுடையவர் இல்லாத குடியை அத்துன்பம், வென்று வீழ்த்திவிடும்.", meaningEn: "If there are none to prop up and maintain a family (in distress), it will fall at the stroke of the axe of misfortune." },
  { number: 1031, line1: "சுழன்றும்ஏர்ப் பின்னது உலகம் அதனால்", line2: "உழந்தும் உழவே தலை.", meaningTa: "பல தொழில்களைச் செய்து சுழன்று கொண்டிருக்கும் இந்த உலகம், ஏர்த்தொழிலின் பின்னேதான் சுற்ற வேண்டியிருக்கிறது எனவே.", meaningEn: "Agriculture, though laborious, is the most excellent (form of labour); for people, though they go about (in search of various employments), have at." },
  { number: 1032, line1: "உழுவார் உலகத்தார்க்கு ஆணிஅஃ தாற்றாது", line2: "எழுவாரை எல்லாம் பொறுத்து.", meaningTa: "உழவுத் தொழிலைச் செய்ய முடியாமல் பிற தொழிலைச் செய்யச் செல்வோர் எல்லாரையும், உழவர்களே தாங்குவதால் அவர்களே இந்த.", meaningEn: "Agriculturists are (as it were) the linch-pin of the world for they support all other workers who can't till the soil." },
  { number: 1033, line1: "உழுதுண்டு வாழ்வாரே வாழ்வார்மற் றெல்லாம்", line2: "தொழுதுண்டு பின்செல் பவர்.", meaningTa: "உழுதுண்டு வாழ்பவர்களே உயர்ந்த வாழ்வினர்; ஏனென்றால், மற்றவர்கள் அவர்களைத் தொழுதுண்டு வாழ வேண்டியிருக்கிறது.", meaningEn: "They alone live who live by agriculture; all others lead a cringing, dependent life." },
  { number: 1034, line1: "பலகுடை நீழலும் தங்குடைக்கீழ்க் காண்பர்", line2: "அலகுடை நீழ லவர்.", meaningTa: "பல அரசுகளின் நிழல்களைத் தமது குடைநிழலின் கீழ் கொண்டு வரும் வலிமை பெற்றவர்கள் உழவர்கள்.", meaningEn: "Patriotic farmers wants to bring all other states under the control of their own leader." },
  { number: 1035, line1: "இரவார் இரப்பார்க்கொன்று ஈவர் கரவாது", line2: "கைசெய்தூண் மாலை யவர்.", meaningTa: "தம் கையால் உழுது உண்ணும் இயல்பை உடையவர் பிறரிடம் பிச்சை கேட்கமாட்டார்; தம்மிடம் கேட்டு வந்தவர்க்கு இல்லை என்று.", meaningEn: "Those whose nature is to live by manual labour will never beg but give something to those who beg." },
  { number: 1036, line1: "உழவினார் கைம்மடங்கின் இல்லை விழைவதூஉம்", line2: "விட்டேம்என் பார்க்கும் நிலை.", meaningTa: "எல்லாப் பற்றையும் விட்டுவிட்டதாகக் கூறும் துறவிகள்கூட உழவரின் கையை எதிர்பார்த்துதான் வாழ வேண்டும்.", meaningEn: "If the farmer's hands are slackened, even the people who live simply state will fail." },
  { number: 1037, line1: "தொடிப்புழுதி கஃசா உணக்கின் பிடித்தெருவும்", line2: "வேண்டாது சாலப் படும்.", meaningTa: "ஒருபலம் புழுதி, காற்பலம் ஆகிற அளவுக்குப் பலமுறை உழுதாலே ஒரு பிடி எருவும் தேவையின்றிப் பயிர் செழித்து வளரும்.", meaningEn: "If the land is dried so as to reduce one ounce of earth to a quarter, it will grow plentifully even without a handful of manure." },
  { number: 1038, line1: "ஏரினும் நன்றால் எருவிடுதல் கட்டபின்", line2: "நீரினும் நன்றதன் காப்பு.", meaningTa: "உழுவதைக் காட்டிலும் உரம் இடுவது நல்லது; நீர்ப் பாய்ச்சுவதைக் காட்டிலும் களை எடுத்தபிறகு பயிரைக் காவல் செய்வது நல்லது.", meaningEn: "Manuring is better than ploughing; after weeding, watching is better than watering (it)." },
  { number: 1039, line1: "செல்லான் கிழவன் இருப்பின் நிலம்புலந்து", line2: "இல்லாளின் ஊடி விடும்.", meaningTa: "உழவன், தனது நிலத்தை நாள்தோறும் சென்று கவனிக்காமல் இருந்தால், அவனால் வெறுப்புற்று விலகியிருக்கும் மனைவிபோல அது.", meaningEn: "If the owner does not (personally) attend to his cultivation, his land will behave like an angry partner and yield him no pleasure." },
  { number: 1040, line1: "இலமென்று அசைஇ இருப்பாரைக் காணின்", line2: "நிலமென்னும் நல்லாள் நகும்.", meaningTa: "வாழ வழியில்லை என்று கூறிக்கொண்டு சோம்பலாய் இருப்பவரைப் பார்த்துப் பூமித்தாய் கேலி புரிவாள்.", meaningEn: "The maiden, Earth, will laugh at the sight of those who plead poverty and lead an idle life." },
  { number: 1041, line1: "இன்மையின் இன்னாதது யாதெனின் இன்மையின்", line2: "இன்மையே இன்னா தது.", meaningTa: "இன்மையை விடக் கொடியதுஎது என்றால், இல்லாமையை விடக் கொடியது இல்லாமையே.", meaningEn: "There is nothing that afflicts (one) like poverty." },
  { number: 1042, line1: "இன்மை எனவொரு பாவி மறுமையும்", line2: "இம்மையும் இன்றி வரும்.", meaningTa: "இல்லாமை என்ற ஒரு பாவி ஒருவனிடத்தில் சேர்ந்தால், அவன் பிறர்க்குக் கொடுக்க இல்லாதவன் ஆவதால் அவனுக்கு மறுமை இன்பமும்.", meaningEn: "When cruel poverty comes on, it deprives one of both the present and future (bliss)." },
  { number: 1043, line1: "தொல்வரவும் தோலும் கெடுக்கும் தொகையாக", line2: "நல்குரவு என்னும் நசை.", meaningTa: "ஒருவனுக்கு வறுமையின் காரணமாகப் பேராசை ஏற்படுமேயானால், அது அவனுடைய பரம்பரைப் பெருமையையும், புகழையும் ஒரு சேரக்.", meaningEn: "Hankering poverty destroys at once the greatness of (one's) ancient descent and (the dignity of one's) speech." },
  { number: 1044, line1: "இற்பிறந்தார் கண்ணேயும் இன்மை இளிவந்த", line2: "சொற்பிறக்கும் சோர்வு தரும்.", meaningTa: "இல்லாமை எனும் கொடுமை, நல்ல குடியில் பிறந்தவர்களிடம் இழிந்த சொல் பிறப்பதற்கான சோர்வை உருவாக்கி விடும்.", meaningEn: "Even in those of high birth, poverty will produce the fault of uttering mean words." },
  { number: 1045, line1: "நல்குரவு என்னும் இடும்பையுள் பல்குரைத்", line2: "துன்பங்கள் சென்று படும்.", meaningTa: "இல்லாமை என்னும் துன்பத்திற்குள் எல்லா வகைத் துன்பங்களும் அடங்கும்.", meaningEn: "The misery of poverty brings in its train many (more) miseries." },
  { number: 1046, line1: "நற்பொருள் நன்குணர்ந்து சொல்லினும் நல்கூர்ந்தார்", line2: "சொற்பொருள் சோர்வு படும்.", meaningTa: "நல்ல கருத்துக்களைத் தெளிவாகத் தெரிந்து சொன்னாலும், சொல்பவர் ஏழை என்றால் அவர் சொல் மதிக்கப் பெறாது.", meaningEn: "The words of the poor are profitless, though they may be sound in thought and clear in expression." },
  { number: 1047, line1: "அறஞ்சாரா நல்குரவு ஈன்றதா யானும்", line2: "பிறன்போல நோக்கப் படும்.", meaningTa: "வறுமை வந்தது என்பதற்காக, அறநெறியிலிருந்து விலகி நிற்பவனை, அவன் தாய்கூட அயலானைப் போல்தான் கருதுவாள்.", meaningEn: "He that is reduced to absolute poverty will be regarded as a stranger even by his own mother." },
  { number: 1048, line1: "இன்றும் வருவது கொல்லோ நெருநலும்", line2: "கொன்றது போலும் நிரப்பு.", meaningTa: "நேற்றும் கொலை செய்தது போல் துன்புறுத்திய வறுமை இன்றும் என்னிடம் வருமோ, .", meaningEn: "Is the poverty that almost killed me yesterday, to meet me today too ?" },
  { number: 1049, line1: "நெருப்பினுள் துஞ்சலும் ஆகும் நிரப்பினுள்", line2: "யாதொன்றும் கண்பாடு அரிது.", meaningTa: "ஒருவன் நெருப்பினுள் இருந்து தூங்குதலும் முடியும், ஆனால் வறுமை நிலையில் எவ்வகையாலும் கண்மூடித் தூங்குதல் அரிது.", meaningEn: "One may sleep in the midst of fire; but by no means in the midst of poverty." },
  { number: 1050, line1: "துப்புர வில்லார் துவரத் துறவாமை", line2: "உப்பிற்கும் காடிக்கும் கூற்று.", meaningTa: "ஒழுங்குமறையற்றதால் வறுமையுற்றோர், முழுமையாகத் தம்மைத் துறக்காமல் உயிர்வாழ்வது, உப்புக்கும் கஞ்சிக்கும்தான் கேடு.", meaningEn: "The destitute poor, who don't renounce their bodies, only consume their neighbour's salt and water." },
  { number: 1051, line1: "இரக்க இரத்தக்கார்க் காணின் கரப்பின்", line2: "அவர்பழி தம்பழி அன்று.", meaningTa: "கொடுக்கக்கூடிய தகுதி படைத்தவரிடத்திலே ஒன்றைக் கேட்டு, அதை அவர் இருந்தும் இல்லையென்று சொன்னால், அப்படிச்.", meaningEn: "If you meet with those that may be begged of, you may beg; (but) if they withhold (their gift) it is their blame and not yours." },
  { number: 1052, line1: "இன்பம் ஒருவற்கு இரத்தல் இரந்தவை", line2: "துன்பம் உறாஅ வரின்.", meaningTa: "நாம் கேட்டதைப் பிறர் மனவருத்தம் இல்லாமல் தந்தால், பிச்சை எடுப்பது கூட ஒருவனுக்கு இன்பமே.", meaningEn: "Even begging may be pleasant, if what is begged for is obtained without grief (to him that begs)." },
  { number: 1053, line1: "கரப்பிலா நெஞ்சின் கடனறிவார் முன்நின்று", line2: "இரப்புமோ ரேஎர் உடைத்து.", meaningTa: "உள்ளதை ஒளிக்காத உள்ளமும், கடமையுணர்வும் கொண்டவரிடத்தில் தனது வறுமை காரணமாக இரந்து கேட்பதும் பெருமையுடையதே யாகும்.", meaningEn: "There is even a beauty in standing before and begging of those who are liberal in their gifts and understand their duty (to beggars)." },
  { number: 1054, line1: "இரத்தலும் ஈதலே போலும் கரத்தல்", line2: "கனவிலும் தேற்றாதார் மாட்டு.", meaningTa: "ஒளிவு மறைவு என்பதைக் கனவிலும் எண்ணிப் பாராதவரிடம் சென்று, ஒன்றைக் கேட்பதும், பிறர்க்குக் கொடுப்பதைப் போன்றதே.", meaningEn: "To beg of such as never think of withholding (their charity) even in their dreams, is in fact the same as giving (it oneself)." },
  { number: 1055, line1: "கரப்பிலார் வையகத்து உண்மையால் கண்ணின்று", line2: "இரப்பவர் மேற்கொள் வது.", meaningTa: "கண் எதிரே நின்று, வறுமைப்பட்டவர் வாயால் கேட்காமல் கண்ணால் கேட்கத் தொடங்குவது, ஒளிவுமறைவு இல்லாமல் அவருக்குக்.", meaningEn: "As there are in the world those that give without refusing, there are (also) those that prefer to beg by simply standing before them." },
  { number: 1056, line1: "கரப்பிடும்பை யில்லாரைக் காணின் நிரப்பிடும்பை", line2: "எல்லாம் ஒருங்கு கெடும்.", meaningTa: "இருப்பதை மறைப்பதாகிய நோய் இல்லாதவரைக் கண்டால், இல்லாமையாகிய நோய் எல்லாம் மொத்தமாக அழியும்.", meaningEn: "All the evil of begging will be removed at the sight of those who are far from the evil of refusing." },
  { number: 1057, line1: "இகழ்ந்தெள்ளாது ஈவாரைக் காணின் மகிழ்ந்துள்ளம்", line2: "உள்ளுள் உவப்பது உடைத்து.", meaningTa: "அவமதிக்காமல், இழிவாகப் பேசாமல் எடுத்துக் கொடுப்பவரைக் கண்டால், பிச்சை கேட்பவரின் மனம் மகிழ்ந்து உள்ளுக்குள்ளே உவகை.", meaningEn: "Beggars rejoice exceedingly when they behold those who bestow (their alms) with kindness and courtesy." },
  { number: 1058, line1: "இரப்பாரை இல்லாயின் ஈர்ங்கண்மா ஞாலம்", line2: "மரப்பாவை சென்றுவந் தற்று.", meaningTa: "பிச்சை ஏற்பார் என்பவர் இல்லாது போய் விட்டால், குளி்ர்ந்த பெரிய இவ்வுலகத்தில் வாழ்பவரின் வாழ்க்கை, வெறும்.", meaningEn: "If there were no beggars, (the actions done in) the cool wide world would only resemble the movement of a puppet." },
  { number: 1059, line1: "ஈவார்கண் என்னுண்டாம் தோற்றம் இரந்துகோள்", line2: "மேவார் இலாஅக் கடை.", meaningTa: "தம்மிடம் வந்து ஒன்றைப் பிச்சையாகக் கேட்பவர் இல்லாதபொழுது, கொடுக்கும் மனம் உள்ளவர்க்குப் புகழ் ஏது?", meaningEn: "What (praise) would there be to givers (of alms) if there were no beggars to ask for and reveive (them)." },
  { number: 1060, line1: "இரப்பான் வெகுளாமை வேண்டும் நிரப்பிடும்பை", line2: "தானேயும் சாலும் கரி.", meaningTa: "இல்லை என்பவரிடம், இரப்பவன் கோபம் கொள்ளக்கூடாது தன்னைப் போலவே பிறர் நிலைமையும் இருக்கலாம் என்பதற்குத் தன் வறுமையே.", meaningEn: "He who begs ought not to be angry (at a refusal); for even the misery of (his own) poverty should be a sufficient reason (for so doing)." },
  { number: 1061, line1: "கரவாது உவந்தீயும் கண்ணன்னார் கண்ணும்", line2: "இரவாமை கோடி உறும்.", meaningTa: "இருப்பதை ஒளிக்காமல் வழங்கிடும் இரக்கச்சிந்தையுடைவரிடம்கூட, இரவாமல் இருப்பது கோடி மடங்கு உயர்வுடையதாகும்.", meaningEn: "Not to beg (at all) even from those excellent persons who cheerfully give without refusing, will do immense good." },
  { number: 1062, line1: "இரந்தும் உயிர்வாழ்தல் வேண்டின் பரந்து", line2: "கெடுக உலகியற்றி யான்.", meaningTa: "பிச்சையெடுத்துதான் சிலர் உயிர்வாழ வேண்டும் என்ற நிலையிருந்தால் இந்த உலகத்தைப் படைத்தவனாகச் சொல்லப்படுபவனும்.", meaningEn: "If the Creator of the world has decreed even begging as a means of livelihood, may he too go abegging and perish." },
  { number: 1063, line1: "இன்மை இடும்பை இரந்துதீர் வாமென்னும்", line2: "வன்மையின் வன்பாட்ட தில்.", meaningTa: "வறுமைக்கொடுமையைப் பிறரிடம் இரந்து போக்கிக் கொள்ளலாம் என்று கருதும் கொடுமையைப் போல் வேறொரு கொடுமை இல்லை.", meaningEn: "There is no greater folly than the boldness with which one seeks to remedy the evils of poverty by begging (rather than by worleader)." },
  { number: 1064, line1: "இடமெல்லாம் கொள்ளாத் தகைத்தே இடமில்லாக்", line2: "காலும் இரவொல்லாச் சால்பு.", meaningTa: "வாழ்வதற்கு ஒரு வழியும் கிடைக்காத நிலையிலும் பிறரிடம் கையேந்திட நினைக்காத பண்புக்கு, இந்த வையகமே ஈடாகாது.", meaningEn: "Even the whole world can't sufficiently praise the dignity that would not beg even in the midst of having nothing." },
  { number: 1065, line1: "தெண்ணீர் அடுபுற்கை ஆயினும் தாள்தந்தது", line2: "உண்ணலின் ஊங்கினிய தில்.", meaningTa: "தெளிந்த நீர் போல் சமைத்த கூழே ஆனாலும், முயற்சியால் கிடைத்ததை உண்பதைவிட இனிமையானது வேறொன்றும் இல்லை.", meaningEn: "Even thin gruel is sweet magic water to God who has obtained it by labour." },
  { number: 1066, line1: "ஆவிற்கு நீரென்று இரப்பினும் நாவிற்கு", line2: "இரவின் இளிவந்த தில்.", meaningTa: "பசுவிற்கு நீர் வேண்டும் என்று அறம் நோக்கி இரந்து கேட்டாலும், இர த்தலை விட நாவிற்கு இழிவானது மற்றொன்று இல்லை.", meaningEn: "There is nothing more disgraceful to one's tongue than to use it in begging water even for a cow." },
  { number: 1067, line1: "இரப்பன் இரப்பாரை எல்லாம் இரப்பின்", line2: "கரப்பார் இரவன்மின் என்று.", meaningTa: "கையில் உள்ளதை மறைத்து இல்லை என்போரிடம் கையேந்த வேண்டாமென்று கையேந்துபவர்களையெல்லாம் கையேந்திக்கேட்டு கொள்கிறேன்.", meaningEn: "I beseech all beggars and say, \"If you need to beg, never beg of those who give unwillingly.\"." },
  { number: 1068, line1: "இரவென்னும் ஏமாப்பில் தோணி கரவென்னும்", line2: "பார்தாக்கப் பக்கு விடும்.", meaningTa: "இரத்தல் என்னும் காவல் இல்லாத மரக்கலம் உள்ளதை ஒளித்துவைக்கும் தன்மையாகிய வன்னிலம் தாக்கினால் உடைந்து விடும்.", meaningEn: "The unsafe raft of begging will split when it strikes on the rock of refusal." },
  { number: 1069, line1: "இரவுள்ள உள்ளம் உருகும் கரவுள்ள", line2: "உள்ளதூஉம் இன்றிக் கெடும்.", meaningTa: "இரந்து வாழ்வோர் நிலையை நினைக்கும் போது உள்ளம் உருகுகிறது, இருப்பதைக் கொடுக்க மனமின்றி மறைத்து வாழ்பவரை நினைத்தால்.", meaningEn: "To think of (the evil of) begging is enough to melt one's heart; but to think of refusal is enough to break it." },
  { number: 1070, line1: "கரப்பவர்க்கு யாங்கொளிக்கும் கொல்லோ இரப்பவர்", line2: "சொல்லாடப் போஒம் உயிர்.", meaningTa: "இருப்பதை ஒளித்துக்கொண்டு `இல்லை' என்பவர்களின் சொல்லைக் கேட்டவுடன், இரப்போரின் உயிரே போய் விடுகிறதே; அப்படிச்.", meaningEn: "Saying \"No\" to a beggar takes away his life. (but as that very word will kill the refuser) where then would the latter's life hide itself ?" },
  { number: 1071, line1: "மக்களே போல்வர் கயவர் அவரன்ன", line2: "ஒப்பாரி யாங்கண்ட தில்.", meaningTa: "மக்களே போல் இருப்பார் கயவர், அவர் மக்களை ஒத்திருப்பது போன்ற ஒப்புமை வேறு எந்த இருவகைப் பொருள்களிடத்திலும் யாம்.", meaningEn: "The base resemble people perfectly (as regards form); and we have not seen such (exact) resemblance (among any other species)." },
  { number: 1072, line1: "நன்றறி வாரிற் கயவர் திருவுடையர்", line2: "நெஞ்சத்து அவலம் இலர்.", meaningTa: "நன்மை அறிந்தவரை விடக் கயவரே நல்ல பேறு உடையவர், ஏன் என்றால், கயவர் தம் நெஞ்சில் எதைப் பற்றியும் கவலை இல்லாதவர்.", meaningEn: "The low enjoy more felicity than those who know what is good; for the former aren't troubled with worry (as to the good)." },
  { number: 1073, line1: "தேவர் அனையர் கயவர் அவருந்தாம்", line2: "மேவன செய்தொழுக லான்.", meaningTa: "தம்மைக் கட்டுப்படுத்துவார் இல்லாமல் தாம் விரும்பியபடி எல்லாம் செய்து வாழ்வதால், கயவர் தேவரைப் போன்றவராவர்.", meaningEn: "The base resemble the Gods; for the base act as they like." },
  { number: 1074, line1: "அகப்பட்டி ஆவாரைக் காணின் அவரின்", line2: "மிகப்பட்டுச் செம்மாக்கும் கீழ்.", meaningTa: "கீழ் மக்கள் தமக்கு கீழ் பட்டவராய் நடப்பவரைக் கண்டால், அவரை விடத் தாம் மேம்பாடு உடையவராய் இறுமாப்படைவர்.", meaningEn: "The base feels proud when he sees persons whose acts meaner than his own." },
  { number: 1075, line1: "அச்சமே கீழ்களது ஆசாரம் எச்சம்", line2: "அவாவுண்டேல் உண்டாம் சிறிது.", meaningTa: "கீழ் மக்களின் ஆசாரத்திற்கு காரணமாக இருப்பது அச்சமே, எஞ்சியவற்றில் அவா உண்டானால் அதனாலும் சிறிதளவு ஆசாரம் உண்டாகும்.", meaningEn: "Behaviour in the mean is chiefly fear; if not, hope of gain, to some extent." },
  { number: 1076, line1: "அறைபறை அன்னர் கயவர்தாம் கேட்ட", line2: "மறைபிறர்க்கு உய்த்துரைக்க லான்.", meaningTa: "தாம் அறிந்த ரகசியங்களைப் பிறரிடம் வலியச் சென்று சொல்லுவதால், அடிக்கப்படும் பறையைப் போன்றவர் கயவர்.", meaningEn: "The base are like a drum that is beaten, for they unburden to others the secrets they have heard." },
  { number: 1077, line1: "ஈர்ங்கை விதிரார் கயவர் கொடிறுடைக்கும்", line2: "கூன்கையர் அல்லா தவர்க்கு.", meaningTa: "தாடையை உடைக்கும் முறுக்கிய கை இல்லாதவர்க்குக் கயவர், தாம் உண்டு கழுவிய ஈரக் கையைக்கூட உதறமாட்டார்.", meaningEn: "The mean won't (even) shake off (what sticks to) their hands (soon after a meal) to any but those who would break their jaws with their clenched fists." },
  { number: 1078, line1: "சொல்லப் பயன்படுவர் சான்றோர் கரும்புபோல்", line2: "கொல்லப் பயன்படும் கீழ்.", meaningTa: "அணுகி குறைச் சொல்லுகின்ற அளவிலேயே சான்றோர் பயன்படுவர், கரும்புபோல் அழித்துப் பிழிந்தால் தான் கீழ்மக்கள் பயன்படுவர்.", meaningEn: "The great bestow (their alms) as soon as they are informed; (but) the mean, like the sugar-cane, only when they are tortured to death." },
  { number: 1079, line1: "உடுப்பதூஉம் உண்பதூஉம் காணின் பிறர்மேல்", line2: "வடுக்காண வற்றாகும் கீழ்.", meaningTa: "பிறர் நன்கு உடுத்த, உண்ணக் கண்டால், அவர்மீத குற்றம் காணும் ஆற்றலை உடையவர் கயவர்.", meaningEn: "The base will bring an evil (accusation) against others, as soon as he sees them (enjoying) good food." },
  { number: 1080, line1: "எற்றிற் குரியர் கயவரொன்று உற்றக்கால்", line2: "விற்றற்கு உரியர் விரைந்து.", meaningTa: "ஒரு துன்பம் வரும்போது அதிலிருந்து தப்பித்துக் கொள்ள, தம்மையே பிறரிடம் விற்றுவிடுகிற தகுதிதான் கயவர்களுக்குரிய.", meaningEn: "The base will hasten to sell themselves as soon as a big trouble has befallen them. For what else are they fitted ?" },
  { number: 1081, line1: "அணங்குகொல் ஆய்மயில் கொல்லோ கனங்குழை", line2: "மாதர்கொல் மாலும் என் நெஞ்சு.", meaningTa: "எனை வாட்டும் அழகோ! வண்ண மயிலோ! இந்த அன்புக்குரியவர்யைக் கண்டு மயங்குகிறதே நெஞ்சம்.", meaningEn: "Is this wonderful person a magical friend, a choice pretty peacock, or a human being ? My mind is confused." },
  { number: 1082, line1: "நோக்கினாள் நோக்கெதிர் நோக்குதல் தாக்கணங்கு", line2: "தானைக்கொண் டன்ன துடைத்து.", meaningTa: "என் பார்வைக்கு எதிராக அவள் என்னைப் பார்ப்பது, தானே தாக்கி எவரையும் கொல்லும் ஒரு தெய்வம், தாக்குவதற்குப் படைகளையும்.", meaningEn: "This person beauty returning my looks is like a magical friend maiden coming with an army to contend against me." },
  { number: 1083, line1: "பண்டறியேன் கூற்றென் பதனை இனியறிந்தேன்", line2: "பெண்டகையால் பேரமர்க் கட்டு.", meaningTa: "கூற்றுவன் எனப்படும் பொல்லாத எமனை, எனக்கு முன்பெல்லாம் தெரியாது; இப்போது தெரிந்து கொண்டேன் அந்த எமன் என்பவன்.", meaningEn: "I never knew before what is called Yama; I see it now; it is the eyes that carry on a great fight with (the help of) person qualities." },
  { number: 1084, line1: "கண்டார் உயிருண்ணும் தோற்றத்தால் பெண்டகைப்", line2: "பேதைக்கு அமர்த்தன கண்.", meaningTa: "அன்புக்குரியவர்தன்மை உடைய இந்தப் பேதைக்குக் கண்கள் கண்டவரின் உயிரை உண்ணும் தோற்றத்தோடு கூடி ஒன்றோடொன்று மாறுபட்டிருந்தன.", meaningEn: "These eyes that seem to kill those who look at them are as it were in hostilities with this feminine simplicity." },
  { number: 1085, line1: "கூற்றமோ கண்ணோ பிணையோ மடவரல்", line2: "நோக்கமிம் மூன்றும் உடைத்து.", meaningTa: "எமனோ. கண்ணோ, அன்புக்குரியவர்மானோ, இந்த இளம் அன்புக்குரியவர்ணின் பார்வை இந்த மூன்றன் தன்மையும் உடையதாக இருக்கிறது.", meaningEn: "Is it Yama, (a pair of) eyes or a hind ?- aren't all these three in the looks of this maid ?" },
  { number: 1086, line1: "கொடும்புருவம் கோடா மறைப்பின் நடுங்கஞர்", line2: "செய்யல மன்இவள் கண்.", meaningTa: "புருவங்கள் வளைந்து கோணாமல் நேராக இருந்து மறைக்குமானால், இவள் கண்கள், நான் நடுங்கும்படியான துன்பத்தைச் செய்யமாட்டா.", meaningEn: "Her eyes will cause (me) no trembling sorrow, if they are properly hidden by her cruel arched eyebrows." },
  { number: 1087, line1: "கடாஅக் களிற்றின்மேற் கட்படாம் மாதர்", line2: "படாஅ முலைமேல் துகில்.", meaningTa: "மாதருடைய சாயாத கொங்கைகளின் மேல் அணிந்த ஆடை, மதம் பிடித்த யானையின் மேல் இட்ட முகப்படாம் போன்றது.", meaningEn: "The cloth that covers the firm bosom of this maiden is (like) that which covers the eyes of a rutting elephant." },
  { number: 1088, line1: "ஒண்ணுதற் கோஒ உடைந்ததே ஞாட்பினுள்", line2: "நண்ணாரும் உட்குமென் பீடு.", meaningTa: "போர்க்களத்தில் பகைவரும் அஞ்சுதற்க்கு காரணமான என் வலிமை, இவளுடைய ஒளி பொருந்திய நெற்றிக்குத் தோற்று அழிந்ததே.", meaningEn: "On her bright brow alone is destroyed even that power of mine that used to terrify the most fearless." },
  { number: 1089, line1: "பிணையேர் மடநோக்கும் நாணும் உடையாட்கு", line2: "அணியெவனோ ஏதில தந்து.", meaningTa: "அன்புக்குரியவர்மானைப் போன்ற இளமைப் பார்வையும் நாணமும் உடைய இவளுக்கு, ஒரு தொடர்பும் இல்லாத அணிகளைச் செய்து அணிவது ஏனோ.", meaningEn: "Of what use are other jewels to her who is adorned with modesty, and the meek looks of a hind ?" },
  { number: 1090, line1: "உண்டார்கண் அல்லது அடுநறாக் காமம்போல்", line2: "கண்டார் மகிழ்செய்தல் இன்று.", meaningTa: "மதுவை உண்டால்தான் மயக்கம் வரும்; ஆனால், கண்டாலே மயக்கம் தருவது அன்புதான்.", meaningEn: "Unlike boiled honey which yields delight only when it is drunk, caring gives pleasure even when looked at." },
  { number: 1091, line1: "இருநோக்கு இவளுண்கண் உள்ளது ஒருநோக்கு", line2: "நோய்நோக்கொன் றந்நோய் மருந்து.", meaningTa: "இவளின் மையூட்டப்பட்ட கண்களில் என்மேல் இரண்டு நோக்கம் இருப்பது தெரிகிறது. ஒரு நோக்கம் எனக்கு துன்பம் தெரிகிறது.", meaningEn: "There are two looks in the dyed eyes of this (fair one); one causes pain, and the other is the cure of it." },
  { number: 1092, line1: "கண்களவு கொள்ளும் சிறுநோக்கம் காமத்தில்", line2: "செம்பாகம் அன்று பெரிது.", meaningTa: "கள்ளத்தனமான அந்தக் கடைக்கண் பார்வை, காம இன்பத்தின் பாதியளவைக் காட்டிலும் பெரிது!", meaningEn: "A single stolen glance of her eyes is more than half the pleasure (of grown-up warm hug)." },
  { number: 1093, line1: "நோக்கினாள் நோக்கி இறைஞ்சினாள் அஃதவள்", line2: "யாப்பினுள் அட்டிய நீர்.", meaningTa: "என்னை நோக்கினாள், யான் கண்டதும் நோக்கித் தலைகுனிந்தால், அது அவள் வளர்க்கும் அன்பினுள் வார்க்கின்ற நீராகும்.", meaningEn: "She has looked (at people) and stooped (her head); and that (sign) waters as it were (the corn of) our caring." },
  { number: 1094, line1: "யான்நோக்கும் காலை நிலன்நோக்கும் நோக்காக்கால்", line2: "தான்நோக்கி மெல்ல நகும்.", meaningTa: "யான் நோக்கும் போது அவள் நிலத்தை நோக்குவாள், யான் நோக்காத போது அவள் என்னை நோக்கி மெல்லத் தனக்குள் மகிழ்வாள்.", meaningEn: "When I look, she looks down; when I don't, she looks and smiles gently." },
  { number: 1095, line1: "குறிக்கொண்டு நோக்காமை அல்லால் ஒருகண்", line2: "சிறக்கணித்தாள் போல நகும்", meaningTa: "என்னை நேராகக் குறித்துப் பார்க்காத அத் தன்மையே அல்லாமல், ஒரு கண்ணைச் சுருக்கினவள் போல் என்னைப் பார்த்து தனக்குள்.", meaningEn: "She not only avoids a direct look at me, but looks as it were with a half-closed eye and smiles." },
  { number: 1096, line1: "உறாஅ தவர்போல் சொலினும் செறாஅர்சொல்", line2: "ஒல்லை உணரப் படும்.", meaningTa: "புறத்தே அயலார் போல் அன்பில்லாத சொற்களைச் சொன்னாலும், அகத்தே பகையில்லாதவரின் சொல் என்பது விரைவில் அறியப்படும்.", meaningEn: "Though they may speak harshly as if they were strangers, the words of the friendly are soon understood." },
  { number: 1097, line1: "செறாஅச் சிறுசொல்லும் செற்றார்போல் நோக்கும்", line2: "உறாஅர்போன்று உற்றார் குறிப்பு.", meaningTa: "கோபம் இல்லாமல் பேசும் பேச்சும், பகைவர் போன்ற பார்வையும், யாரே போலத் தோன்றி நட்பாவார் காட்டும் அடையாளங்கள்.", meaningEn: "Little words that are harsh and looks that are hateful are (but) the expressions of people who care for each other who wish to act like strangers." },
  { number: 1098, line1: "அசையியற்கு உண்டாண்டோர் ஏஎர்யான் நோக்கப்", line2: "பசையினள் பைய நகும்.", meaningTa: "யாரோ எவரோ போல அவள் பேசிய பின்பும் நான் அவளைப் பார்க்க, அவள் மனம் நெகிழ்ந்து மனத்திற்குள் மெல்ல சிரித்தாள்;.", meaningEn: "When I look, the pitying maid looks in return and smiles gently; and that is a comforting sign for me." },
  { number: 1099, line1: "ஏதிலார் போலப் பொதுநோக்கு நோக்குதல்", line2: "காதலார் கண்ணே உள.", meaningTa: "முன்பின் தெரியாதவர் போல, பொதுவாக பார்த்தப் பேசுவது காதலர்களிடம் இருக்கும் குணந்தான்.", meaningEn: "Both the people who care for each other are capable of looleader at each other in an ordinary way, as if they were perfect strangers." },
  { number: 1100, line1: "கண்ணொடு கண்இணை நோக்கொக்கின் வாய்ச்சொற்கள்", line2: "என்ன பயனும் இல.", meaningTa: "ஒத்த அன்புடன் கண்களோடு கண்கள் கலந்து ஒன்றுபட்டு விடுமானால், வாய்ச்சொற்கள் தேவையற்றுப் போகின்றன.", meaningEn: "The words of the mouths are of no use whatever, when there is perfect agreement between the eyes (of people who care for each other)." },
  { number: 1101, line1: "கண்டுகேட்டு உண்டுயிர்த்து உற்றறியும் ஐம்புலனும்", line2: "ஒண்தொடி கண்ணே உள.", meaningTa: "கண்டும் கேட்டும் உண்டும் முகர்ந்தும் உற்றும் அறிகின்ற ஐந்து புலன்களாகிய இன்பங்களும் ஒளி பொருந்திய வளையல் அணிந்த.", meaningEn: "The (simultaneous) enjoyment of the five senses of sight, hearing, taste, smell and touch can only be found with bright braceleted (women)." },
  { number: 1102, line1: "பிணிக்கு மருந்து பிறமன் அணியிழை", line2: "தன்நோய்க்குத் தானே மருந்து.", meaningTa: "நோய்களைத் தீர்க்கும் மருந்துகள் பல உள்ளன; ஆனால் அன்பு நோயைத் தீர்க்கும் மருந்து அந்தக் காதலியே ஆவாள்.", meaningEn: "The remedy for a disease is always something different (from it); but for the disease caused by this jewelled maid, she is herself the cure." },
  { number: 1103, line1: "தாம்வீழ்வார் மென்றோள் துயிலின் இனிதுகொல்", line2: "தாமரைக் கண்ணான் உலகு.", meaningTa: "தாமரைக் கண்ணனுடைய உலகம், தாம் விரும்பும் காதலியரின் மெல்லிய தோள்களில் துயிலும் துயில் போல் இனிமை உடையதோ.", meaningEn: "Can the lotus-eyed Vishnu's heaven be indeed as sweet to those who delight to sleep in the delicate arms of their beloved ?" },
  { number: 1104, line1: "நீங்கின் தெறூஉம் குறுகுங்கால் தண்ணென்னும்", line2: "தீயாண்டுப் பெற்றாள் இவள்?", meaningTa: "தன்னை நீங்கினால் சுடும், நெருங்கினால் குளிரும் ஒரு தீயை என் உள்ளத்தில் ஏற்ற, இவள் அதை எங்கிருந்து பெற்றாள்?", meaningEn: "From whence has she got this fire that burns when I withdraw and cools when I approach ?" },
  { number: 1105, line1: "வேட்ட பொழுதின் அவையவை போலுமே", line2: "தோட்டார் கதுப்பினாள் தோள்.", meaningTa: "விருப்பமான பொருள் ஒன்று, விரும்பிய பொழுதெல்லாம் வந்து இன்பம் வழங்கினால் எப்படியிருக்குமோ அதைப் போலவே பூ முடித்த.", meaningEn: "Each varied form of joy the soul can wish is found." },
  { number: 1106, line1: "உறுதோறு உயிர்தளிர்ப்பத் தீண்டலால் பேதைக்கு", line2: "அமிழ்தின் இயன்றன தோள்.", meaningTa: "இவளை அணைக்கும்போது எல்லாம் வாடிக் கிடந்த என் உயிர் தளிர்க்கும்படி என்னைத் தொடுவதால், இவளின் தோள்கள் அமிழ்தத்தில்.", meaningEn: "The shoulders of this fair one are made of sweet magic water, for they revive me with pleasure every time I warm hug them." },
  { number: 1107, line1: "தம்மில் இருந்து தமதுபாத்து உண்டற்றால்", line2: "அம்மா அரிவை முயக்கு.", meaningTa: "அழகிய மா நிறப் அன்புக்குரியவர்ணாகிய என் மனைவியிடம் கூடிப் பெறும் சுகம், தன் சொந்த வீட்டில் இருந்து கொண்டு, தன் உழைப்பில்.", meaningEn: "The warm hugs of a gold-complexioned beautiful person are as pleasant as to dwell in one's own house and live by one's own (earnings) after." },
  { number: 1108, line1: "வீழும் இருவர்க்கு இனிதே வளியிடை", line2: "போழப் படாஅ முயக்கு.", meaningTa: "காதலர்க்கு மிக இனிமை தருவது, காற்றுகூட இடையில் நுழைய முடியாத அளவுக்கு இருவரும் இறுகத் அன்புடன் சேர்ந்து மகிழ்வதாகும்.", meaningEn: "To ardent people who care for each other sweet is the warm hug that can't be penetrated even by a breath of breeze." },
  { number: 1109, line1: "ஊடல் உணர்தல் புணர்தல் இவைகாமம்", line2: "கூடியார் பெற்ற பயன்.", meaningTa: "ஊடுதல், ஊடலை உணர்ந்து விடுதல், அதன்பின் கூடுதல் ஆகிய இவை அன்பு வாழ்வு நிறைவேறப் பெற்றவர் பெற்ற பயன்களாகும்.", meaningEn: "Caring quarrel, reconciliation and intercourse - these are the advantages reaped by those who marry for greedy wants." },
  { number: 1110, line1: "அறிதோறு அறியாமை கண்டற்றால் காமம்", line2: "செறிதோறும் சேயிழை மாட்டு.", meaningTa: "மாம்பழ மேனியில் அழகிய அணிகலன்கள் பூண்ட அன்புக்குரியவர்யிடம் இன்பம் நுகரும் போதெல்லாம் ஏற்படும் காதலானது, இதுவரை அறியாதவற்றைப்.", meaningEn: "As (one's) ignorance is discovered the more one learns, so does repeated intercourse with a welladorned person (only create a wants for more)." },
  { number: 1111, line1: "நன்னீரை வாழி அனிச்சமே நின்னினும்", line2: "மென்னீரள் யாம்வீழ் பவள்.", meaningTa: "அனிச்ச மலரின் மென்மையைப் புகழ்ந்து பாராட்டுகிறேன்; ஆனால் அந்த மலரைவிட மென்மையானவள் என் காதலி.", meaningEn: "May you do well, O Anicham! you have a delicate nature But my beloved is more delicate than you." },
  { number: 1112, line1: "மலர்காணின் மையாத்தி நெஞ்சே இவள்கண்", line2: "பலர்காணும் பூவொக்கும் என்று.", meaningTa: "மலரைக்கண்டு மயங்குகின்ற நெஞ்சமே! இவளுடைய கண்ணைப் பார்; பலரும் கண்டு வியக்கும் மலராகவே திகழ்கிறது.", meaningEn: "O my soul, fancying that flowers which are seen by many can resemble her eyes, you become confused at the sight of them." },
  { number: 1113, line1: "முறிமேனி முத்தம் முறுவல் வெறிநாற்றம்", line2: "வேலுண்கண் வேய்த்தோ ளவட்கு.", meaningTa: "மூங்கில் போன்ற தோளை உடைய இவளுக்குத் தளிரே மேன், முத்தே பல், இயற்கை மணமே மணம், வேலே மை உண்ட கண்.", meaningEn: "The complexion of this bamboo-shouldered one is that of a shoot; her teeth, are pearls; her breath,." },
  { number: 1114, line1: "காணின் குவளை கவிழ்ந்து நிலன்நோக்கும்", line2: "மாணிழை கண்ணொவ்வேம் என்று.", meaningTa: "என் காதலியைக் குவளை மலர்கள் காண முடிந்தால், ``இவள் கண்களுக்கு நாம் ஒப்பாக முடியவில்லையே!'' எனத் தலைகுனிந்து நிலம்.", meaningEn: "If the blue lotus could see, it would stoop and look at the ground saying, \"I can never resemble the eyes of this excellent jewelled one.\"." },
  { number: 1115, line1: "அனிச்சப்பூக் கால்களையாள் பெய்தாள் நுகப்பிற்கு", line2: "நல்ல படாஅ பறை.", meaningTa: "அவளுக்காக நல்லபறை ஒலிக்கவில்லை; ஏனெனில் அவள் இடை ஒடிந்து வீழ்ந்துவிட்டாள்; காரணம், அவள் அனிச்ச மலர்களைக் காம்பு.", meaningEn: "No merry drums will be beaten for the (tender) waist of her who has adorned herself with the anicham without having removed its stem." },
  { number: 1116, line1: "மதியும் மடந்தை முகனும் அறியா", line2: "பதியின் கலங்கிய மீன்.", meaningTa: "அன்புக்குரியவர்யின் முகத்துக்கும், நிலவுக்கும் வேறுபாடு தெரியாமல் விண்மீன்கள் மயங்கிக் தவிக்கின்றன.", meaningEn: "The stars have become confused in their places not being able to distinguish between the moon and the maid's countenance." },
  { number: 1117, line1: "அறுவாய் நிறைந்த அவிர்மதிக்குப் க்குப் போல", line2: "மறுவுண்டோ மாதர் முகத்து.", meaningTa: "தேய்ந்தும், வளர்ந்தும் ஒளிபொழியும் நிலவில் உள்ள சிறுகளங்கம்கூட, இந்த அன்புக்குரியவர் நல்லாள் முகத்தில் கிடையாதே!", meaningEn: "Could there be spots in the face of this maid like those in the bright full moon ?" },
  { number: 1118, line1: "மாதர் முகம்போல் ஒளிவிட வல்லையேல்", line2: "காதலை வாழி மத஧.", meaningTa: "முழுமதியே! என் காதலுக்குரியவளாக நீயும் ஆக வேண்டுமெனில், என் காதலியின் முகம் போல ஒளிதவழ நீடு வாழ்வாயாக.", meaningEn: "If you can indeed shine like the face of women, do well, O moon, for then would you be worth loving ?" },
  { number: 1119, line1: "மலரன்ன கண்ணாள் முகமொத்தி யாயின்", line2: "பலர்காணத் தோன்றல் மதி.", meaningTa: "திங்களே! மலர்போன்ற கண்களை உடைய இவளுடைய முகத்தை ஒத்திருக்க விரும்பினால், நீ பலரும் காணும்படியாகத் தோன்றாதே.", meaningEn: "O moon, if you wish to resemble the face of her whose eyes are like (these) flowers, don't appear so as to be seen by all." },
  { number: 1120, line1: "அனிச்சமும் அன்னத்தின் தூவியும் மாதர்", line2: "அடிக்கு நெருஞ்சிப் பழம்.", meaningTa: "அனிச்ச மலரும், அன்னப்பறவையின் இறகும் ஆகிய இவைகள் மாதரின் மெல்லிய அடிகளுக்கு நெருஞ்சிமுள் போன்றவை.", meaningEn: "The anicham and the feathers of the swan are to the feet of females, like the fruit of the (thorny) Nerunji." },
  { number: 1121, line1: "பாலொடு தேன்கலந் தற்றே பணிமொழி", line2: "வாலெயிறு ஊறிய நீர்.", meaningTa: "மென்மையான மொழிகளைப் பேசு கின்ற இவளுடைய தூய பற்களில் ஊறிய நீர் பாலுடன் தேனைக் கலந்தாற் போன்றதாகும்.", meaningEn: "The water which oozes from the white teeth of this soft speeched damsel is like a mixture of milk and honey." },
  { number: 1122, line1: "உடம்பொடு உயிரிடை என்னமற் றன்ன", line2: "மடந்தையொடு எம்மிடை நட்பு.", meaningTa: "உயிரும் உடலும் ஒன்றையொன்று பிரிந்து தனித்தனியாக இருப்பதில்லை; அத்தகையதுதான் எமது உறவு.", meaningEn: "The caring between me and this damsel is like the union of body and soul." },
  { number: 1123, line1: "கருமணியிற் பாவாய்நீ போதாயாம் வீழும்", line2: "திருநுதற்கு இல்லை இடம்.", meaningTa: "என் கண்ணின் கருமணியில் உள்ள பாவையே நீ போய் விடு, யாம் விரும்புகின்ற இவளுக்கு என் கண்ணில் இருக்க இடம் இல்லையே.", meaningEn: "O you image in the pupil (of my eye)! depart; there is no room for (my) fair-browed beloved." },
  { number: 1124, line1: "வாழ்தல் உயிர்க்கன்னள் ஆயிழை சாதல்", line2: "அதற்கன்னள் நீங்கும் இடத்து.", meaningTa: "ஆராய்ந்து அணிகலன்களை அணிந்த இவள் கூடும் போது உயிர்க்கு வாழ்வு போன்றவள், பிரியும் போது உயிர்க்கு சாவு போன்றவள்.", meaningEn: "My fair-jewelled one resembles the living soul (when she is in union with me), the dying soul when she leaves me." },
  { number: 1125, line1: "உள்ளுவன் மன்யான் மறப்பின் மறப்பறியேன்", line2: "ஒள்ளமர்க் கண்ணாள் குணம்.", meaningTa: "ஒளி கொண்டிருக்கும் விழிகளையுடைய காதலியின் பண்புகளை நினைப்பதேயில்லை; காரணம் அவற்றை மறந்தால் அல்லவா நினைப்பதற்கு.", meaningEn: "If I had forgotten her who has bright battling eyes, I would have remembered (you); but I never forget her (so says he to her maid)." },
  { number: 1126, line1: "கண்ணுள்ளின் போகார் இமைப்பின் பருகுவரா", line2: "நுண்ணியர்எம் காத லவர்.", meaningTa: "காதலர், கண்ணுக்குள்ளிருந்து எங்கும் போக மாட்டார்; கண்ணை மூடி இமைத்தாலும் வருந்த மாட்டார்; காரணம், அவர் அவ்வளவு.", meaningEn: "My someone you care about would not depart from mine eyes; even if I wink, he would not suffer (from pain); he is so ethereal." },
  { number: 1127, line1: "கண்ணுள்ளார் காத லவராகக் கண்ணும்", line2: "எழுதேம் கரப்பாக்கு அறிந்து.", meaningTa: "எம் காதலர் கண்ணினுள் இருக்கின்றார், ஆகையால் மை எழுதினால் அவர் மறைவதை எண்ணிக் கண்ணுக்கு மையும் எழுதமாட்டோம்.", meaningEn: "As my someone you care about abides in my eyes, I won't even paint them, for he would (then) have to conceal himself." },
  { number: 1128, line1: "நெஞ்சத்தார் காத லவராக வெய்துண்டல்", line2: "அஞ்சுதும் வேபாக் கறிந்து.", meaningTa: "என்னவர் என் நெஞ்சிலேயே வாழ்வதால் சூடாக உண்டால் அது அவரைச் சுட்டுவிடும் என்று எண்ணி உண்ணப் பயப்படுகிறேன்.", meaningEn: "As my someone you care about is in my heart, I am afraid of eating (anything) hot, for I know it would pain him." },
  { number: 1129, line1: "இமைப்பின் கரப்பாக்கு அறிவல் அனைத்திற்கே", line2: "ஏதிலர் என்னும் இவ் வூர்.", meaningTa: "கண் இமைத்தால் காதலர் மறைந்து போதலை அறிகின்றேன், அவ்வளவிற்கே இந்த ஊரார் அவரை அன்பில்லாதவர் என்று சொல்லுவர்.", meaningEn: "I won't wink, knowing that if I did, my someone you care about would hide himself; and for this reason, this town says, he is unloving." },
  { number: 1130, line1: "உவந்துறைவர் உள்ளத்துள் என்றும் இகந்துறைவர்", line2: "ஏதிலர் என்னும் இவ் வூர்.", meaningTa: "என்னவர் எப்போதும் என் நெஞ்சிற்குள்ளேயே மகிழ்ந்து இருக்கிறார். இதை அறியாத உறவினர் அவருக்கு அத்தனை அன்பு இல்லை.", meaningEn: "My someone you care about dwells in my heart with perpetual delight; but the town says he is unloving and (so) dwells afar." },
  { number: 1131, line1: "காமம் உழந்து வருந்தினார்க்கு ஏமம்", line2: "மடலல்லது இல்லை வலி.", meaningTa: "அன்பு நிறைவேற முடியாமல் வருந்தும் காதலர்க்கு மடல் ஏறுதலைத் தவிர வேறு பலம் இல்லை.", meaningEn: "To those who after enjoyment of wants only fun suffer (for want of more), there is no help so efficient as the palmyra horse." },
  { number: 1132, line1: "நோனா உடம்பும் உயிரும் மடலேறும்", line2: "நாணினை நீக்கி நிறுத்து.", meaningTa: "பொறுக்காத என் உடம்பும் உயிரும், நாணத்தை நீக்கி நிறுத்தி விட்டு மடலூரத் துணிந்தன.", meaningEn: "Having got rid of shame, the suffering body and soul save themselves on the palmyra horse." },
  { number: 1133, line1: "நாணொடு நல்லாண்மை பண்டுடையேன் இன்றுடையேன்", line2: "காமுற்றார் ஏறும் மடல்.", meaningTa: "நாணமும் ஆண்மையும் முன்பு பெற்றிருந்தேன்; இன்றோ காதலர் ஏறும் மடலைப் பெற்றிருகிறேன்.", meaningEn: "Modesty and manliness were once my own; now, my own is the palmyra horse that is ridden by the greedy wantsful." },
  { number: 1134, line1: "காமக் கடும்புனல் உய்க்கும் நாணொடு", line2: "நல்லாண்மை என்னும் புணை.", meaningTa: "ஆம்; நாணம், ஆண்மை என்னும் படகுகளைக் காதலாகிய கடும் வெள்ளம் அடித்துக் கொண்டு போய்விட்டது.", meaningEn: "The raft of modesty and manliness, is, alas, carried-off by the strong current of greedy wants." },
  { number: 1135, line1: "தொடலைக் குறுந்தொடி தந்தாள் மடலொடு", line2: "மாலை உழக்கும் துயர்.", meaningTa: "மடலோறுதலோடு மாலைக்காலத்தில் வருந்தும் துயரத்தை மாலைபோல் தொடர்ந்த சிறு வளையல் அணிந்த காதலி எனக்கு தந்தாள்.", meaningEn: "She with the small garland-like bracelets has given me the palmyra horse and the sorrow that is endured at night." },
  { number: 1136, line1: "மடலூர்தல் யாமத்தும் உள்ளுவேன் மன்ற", line2: "படல்ஒல்லா பேதைக்கென் கண்.", meaningTa: "அவள் குணத்தை எண்ணி என் கண்கள் இரவெல்லாம் உறங்குவதில்லை. அதனால் நள்ளிரவிலும்கூட மடல் ஊர்வது பறிறயே எண்ணுவேன்.", meaningEn: "Mine eyes won't close in sleep on your mistress's account; even at midnight will I think of mounting the palmyra horse." },
  { number: 1137, line1: "கடலன்ன காமம் உழந்தும் மடலேறாப்", line2: "பெண்ணின் பெருந்தக்க தில்.", meaningTa: "கொந்தளிக்கும் கடலாகக் அன்பு நோய் துன்புறுத்தினாலும்கூடப் பொறுத்துக்கொண்டு, மடலேறாமல் இருக்கும் அன்புக்குரியவர்ணின் பெருமைக்கு.", meaningEn: "There is nothing so noble as the womanly nature that would not ride the palmyra horse, though plunged a sea of greedy wants." },
  { number: 1138, line1: "நிறையரியர் மன்அளியர் என்னாது காமம்", line2: "மறையிறந்து மன்று படும்.", meaningTa: "பாவம்; இவர், மனத்தில் உள்ளதை ஒளிக்கத் தெரியாதவர்; பரிதாபத்திற்குரியவர்; என்றெல்லாம் பார்க்காமல், ஊர் அறிய வெளிப்பட்டு.", meaningEn: "Even the greedy wants (of women) transgresses its secrecy and appears in public, forgetting that they are too chaste and liberal (to be overcome by." },
  { number: 1139, line1: "அறிகிலார் எல்லாரும் என்றேஎன் காமம்", line2: "மறுகின் மறுகும் மருண்டு.", meaningTa: "என்னைத் தவிர யாரும் அறியவில்லை என்பதற்காக என் அன்பு தெருவில் பரவி மயங்கித் திரிகின்றது போலும்!", meaningEn: "And so, in public ways, perturbed will rove." },
  { number: 1140, line1: "யாம்கண்ணின் காண நகுப அறிவில்லார்", line2: "யாம்பட்ட தாம்படா ஆறு.", meaningTa: "அன்பு நோயினால் வாடுவோரின் துன்பத்தை அனுபவித்தறியாதவர்கள்தான், அந்த நோயினால் வருந்துவோரைப் பார்த்து நகைப்பார்கள்.", meaningEn: "Even strangers laugh (at us) so as to be seen by us, for they have not suffered." },
  { number: 1141, line1: "அலரெழ ஆருயிர் நிற்கும் அதனைப்", line2: "பலரறியார் பாக்கியத் தால்.", meaningTa: "அலர் எழுவதால் அறிய உயிர் போகாமல் நிற்கின்றது, எம் நல்வினைப் பயனால் பலரும் அறியாமலிருக்கின்றனர்.", meaningEn: "My precious life is saved by the raise of rumour, and this, to my good luck no others are aware of." },
  { number: 1142, line1: "மலரன்ன கண்ணாள் அருமை அறியாது", line2: "அலரெமக்கு ஈந்ததிவ் வூர்.", meaningTa: "மலர் போன்ற கண்ணை உடைய இவளுடைய அருமை அறியாமல், இந்த ஊரார் எளியவளாகக் கருதி அலர் கூறி எமக்கு உதவி செய்தனர்.", meaningEn: "Not knowing the value of her whose eyes are like flowers this town has got up a rumour about me." },
  { number: 1143, line1: "உறாஅதோ ஊரறிந்த கெளவை அதனைப்", line2: "பெறாஅது பெற்றன்ன நீர்த்து.", meaningTa: "ஊரார் எல்லோரும் அறிந்துள்ள அலர் நமக்குப் பொருந்தாதோ, அந்த அலர் பெறமுடியாமலிருந்து பெற்றார் போன்ற நன்மை உடையதாக.", meaningEn: "Will I not get a rumour that is known to the (whole) town ? For what I have not got is as if I had got it (already)." },
  { number: 1144, line1: "கவ்வையால் கவ்விது காமம் அதுவின்றேல்", line2: "தவ்வென்னும் தன்மை இழந்து.", meaningTa: "ஊரார் அலர் தூற்றுவதால் எம் அன்பு வளர்கிறது; இல்லையேல் இக்அன்புகொடி வளமிழந்து வாடிப்போய் விடும்.", meaningEn: "Rumour increases the violence of my strong feelings; without it it would grow weak and waste away." },
  { number: 1145, line1: "களித்தொறும் கள்ளுண்டல் வேட்டற்றால் காமம்", line2: "வெளிப்படுந் தோறும் இனிது.", meaningTa: "அன்பு வெளிப்பட வெளிப்பட இனிமையாக இருப்பது கள்ளுண்டு மயங்க மயங்க அக்கள்ளையே விரும்புவது போன்றதாகும்.", meaningEn: "As drinleader liquor is delightful (to one) whenever one is in mirth, so is greedy wants delightful to me whenever it is the subject of rumour." },
  { number: 1146, line1: "கண்டது மன்னும் ஒருநாள் அலர்மன்னும்", line2: "திங்களைப் பாம்புகொண் டற்று.", meaningTa: "நான் அவரைப் பார்த்ததும் பேசியதும் கொஞ்சமே! ஆனால் இந்த ஊரார் பேச்சோ நிலவைப் பாம்பு பிடித்ததுபோல் ஊர் முழுக்கப்.", meaningEn: "It was but a single day that I looked on (my someone you care about); but the rumour of it has spread like the seizure of the moon by the serpent." },
  { number: 1147, line1: "ஊரவர் கெளவை எருவாக அன்னைசொல்", line2: "நீராக நீளும்இந் நோய்.", meaningTa: "இந்த ஊர்ப் அன்புக்குரியவர்கள் பேசும் பேச்சே உரமாக தாயின் தடைச்சொல் நீராக என் அன்பு பயிர் வளரும்.", meaningEn: "This malady (of greedy wants) is manured by the talk of women and watered by the (harsh) words of my mother." },
  { number: 1148, line1: "நெய்யால் எரிநுதுப்பேம் என்றற்றால் கெளவையால்", line2: "காமம் நுதுப்பேம் எனல்.", meaningTa: "அலர் கூறுவதால் அன்பிதை அடக்குவோம் என்று முயலுதல், நெய்யால் நெருப்பை அவிப்போம் என்று முயல்வதைப் போன்றது.", meaningEn: "To say that one could extinguish strong feelings by rumour is like extinguishing fire with ghee." },
  { number: 1149, line1: "அலர்நாண ஒல்வதோ அஞ்சலோம்பு என்றார்", line2: "பலர்நாண நீத்தக் கடை.", meaningTa: "அலர் பேசிய பலரும் வெட்கப்படும்படி இன்று அவர் என்னை விட்டுப் போகும்போது, பயப்படாதே, உன்னைப் பிரியேன் என்று.", meaningEn: "When the departure of God who said \"fear not\" has put me to shame before others, why need I be ashamed of scandal." },
  { number: 1150, line1: "தாம்வேண்டின் நல்குவர் காதலர் யாம்வேண்டும்", line2: "கெளவை எடுக்கும்இவ் வூர்.", meaningTa: "யாம் விரும்புகின்றவாறு ஊரார் அலர் தூற்றுகின்றனர்; காதலரும் விரும்பினால் அதை ஒப்புக் கொள்வார்.", meaningEn: "The rumour I wants is raised by the town (itself); and my someone you care about would if wantsd consent (to my following him)." },
  { number: 1151, line1: "செல்லாமை உண்டேல் எனக்குரை மற்றுநின்", line2: "வல்வரவு வாழ்வார்க் குரை.", meaningTa: "என்னைப் பிரிவதில்லை என்றால் என்னிடம் சொல். சீக்கிரம் வருவேன் என்பதை எல்லாம் நீ வரும்போது உயிரோடு இருப்பார்களே.", meaningEn: "If it isn't departure, tell me; but if it is your speedy return, tell it to those who would be alive then." },
  { number: 1152, line1: "இன்கண் உடைத்தவர் பார்வல் பிரிவஞ்சும்", line2: "புன்கண் உடைத்தால் புணர்வு.", meaningTa: "அவர் பார்வை எனக்கு மகிழ்ச்சிதான். அவர் செயலோ பிரியப் போகிறார் என்ற அச்சத்தைத் தந்து கொண்டிருக்கிறதே!", meaningEn: "His very look was once pleasing; but (now) even intercourse is painful through fear of separation." },
  { number: 1153, line1: "அரிதரோ தேற்றம் அறிவுடையார் கண்ணும்", line2: "பிரிவோ ரிடத்துண்மை யான்.", meaningTa: "எல்லாம் அறியும் ஆற்றல் உடைய அவரும் ஒருநேரம் பிரிவார் என்றால், என்மீது அவர் கொண்டிருக்கும் அன்பை அறிந்து கொள்ள.", meaningEn: "As even the someone you care about who understands (everything) may at times depart, confidence is hardly possible." },
  { number: 1154, line1: "அளித்தஞ்சல் என்றவர் நீப்பின் தெளித்தசொல்", line2: "தேறியார்க்கு உண்டோ தவறு.", meaningTa: "அருள் மிகுந்தவராய் அஞ்ச வேண்டா என்று முன் தேற்றியவர் பிரிந்து செல்வாரானால் அவர் கூறிய உறுதிமொழியை நம்பித்.", meaningEn: "If he who bestowed his caring and said \"fear not\" should depart, will it be the fault of those who believed in (his) assuring words ?" },
  { number: 1155, line1: "ஓம்பின் அமைந்தார் பிரிவோம்பல் மற்றவர்", line2: "நீங்கின் அரிதால் புணர்வு.", meaningTa: "காதலர் பிரிந்து சென்றால் மீண்டும் கூடுதல் எளிதல்ல என்பதால், அவர் பிரிந்து செல்லாமல் முதலியேயே காத்துக் கொள்ள வேண்டும்.", meaningEn: "If you would save (my life), delay the departure of my destined (partner); for if he departs, intercourse will become impossible." },
  { number: 1156, line1: "பிரிவுரைக்கும் வன்கண்ணர் ஆயின் அரிதவர்", line2: "நல்குவர் என்னும் நசை.", meaningTa: "பிரிவைப்பற்றி தெரிவிக்கும் அளவிற்குக் கல் நெஞ்சம் உடையவரானால் , அத்தகையவர் திரும்பிவந்து அன்பு செய்வார் என்னும் ஆசை.", meaningEn: "Is hard, when he could stand, and of departure speak to me." },
  { number: 1157, line1: "துறைவன் துறந்தமை தூற்றாகொல் முன்கை", line2: "இறைஇறவா நின்ற வளை.", meaningTa: "அவர் என்னைப் பிரிய திட்டமிடுகிறார் என்பதை என் முன் கையிலிருந்து கழலும் வளையல்கள் எனக்குத் தெரிவிக்க மாட்டாவோ?", meaningEn: "Don't the rings that begin to slide down my fingers forebode the separation of my lord ?" },
  { number: 1158, line1: "இன்னாது இனன்இல்ஊர் வாழ்தல் அதனினும்", line2: "இன்னாது இனியார்ப் பிரிவு.", meaningTa: "உறவானவர் இல்லாத ஊரிலே வாழ்வது கொடுமை; என் உயிர்க்கு இனியவரைப் பிரிவது அதைவிடக் கொடுமை.", meaningEn: "Painful is it to live in a friendless town; but far more painful is it to part from one's someone you care about." },
  { number: 1159, line1: "தொடிற்சுடின் அல்லது காமநோய் போல", line2: "விடிற்சுடல் ஆற்றுமோ தீ.", meaningTa: "தீ தன்னைத் தொட்டவரைத்தான் சுடும்; அன்பு நோயைப் போல அதை விட்டு அகன்றாலும் சுடுமோ?", meaningEn: "Fire burns when touched; but, like the sickness of caring, can it also burn when removed ?" },
  { number: 1160, line1: "அரிதாற்றி அல்லல்நோய் நீக்கிப் பிரிவாற்றிப்", line2: "பின்இருந்து வாழ்வார் பலர்.", meaningTa: "காதலர் பிரிந்து செல்வதற்கு ஒப்புதல் அளித்து, அதனால் ஏற்படும் துன்பத்தைப் போக்கிக் கொண்டு, பிரிந்த பின்னும்.", meaningEn: "As if there were many indeed that can consent to the impossible, kill their pain, endure separation and yet continue to live afterwards." },
  { number: 1161, line1: "மறைப்பேன்மன் யானிஃதோ நோயை இறைப்பவர்க்கு", line2: "ஊற்றுநீர் போல மிகும்.", meaningTa: "இறைக்க இறைக்கப் பெருகும் ஊற்றுநீர் போல, பிறர் அறியாமல் மறைக்க மறைக்கக் அன்பு நோயும் பெருகும்.", meaningEn: "I would hide this pain from others; but it (only) swells like a spring to those who drain it." },
  { number: 1162, line1: "கரத்தலும் ஆற்றேன்இந் நோயைநோய் செய்தார்க்கு", line2: "உரைத்தலும் நாணுத் தரும்.", meaningTa: "அன்பு நோயை என்னால் மறைக்கவும் முடியவில்லை; இதற்குக் காரணமான காதலரிடம் நாணத்தால் உரைக்கவும் முடியவில்லை.", meaningEn: "I can't conceal this pain, nor can I relate it without shame to God who has caused it." },
  { number: 1163, line1: "காமமும் நாணும் உயிர்காவாத் தூங்கும்என்", line2: "நோனா உடம்பின் அகத்து.", meaningTa: "துன்பத்தைப் பொருக்காமல் வருந்துகின்ற என் உடம்பினிடத்தில் உயிரே காவடித்தண்டாகக் கொண்டு காமநோயும் நாணமும் இருப்பக்கமாக.", meaningEn: "Greedy wants and shame, with my soul for their shoulder pole balance themselves on a body that can't bear them." },
  { number: 1164, line1: "காமக் கடல்மன்னும் உண்டே அதுநீந்தும்", line2: "ஏமப் புணைமன்னும் இல்.", meaningTa: "காமநோயாகிய கடல் இருக்கின்றது. ஆனால் அதை நீந்திக்கடந்து செல்வதற்கு வேண்டிய காவலான ‌தோணியோ இல்லை.", meaningEn: "There is indeed a flood of greedy wants; but there is no raft of safety to cross it with." },
  { number: 1165, line1: "துப்பின் எவனாவர் மன்கொல் துயர்வரவு", line2: "நட்பினுள் ஆற்று பவர்.", meaningTa: "நட்பிலேயே துயரத்தை வரச் செய்வதில் வல்லவர். வலிமை வேண்டும்போது என்ன ஆவாரோ?", meaningEn: "What will they prove when angry tempests lower?" },
  { number: 1166, line1: "இன்பம் கடல்மற்றுக் காமம் அஃதடுங்கால்", line2: "துன்பம் அதனிற் பெரிது.", meaningTa: "அன்பு மகிழ்ச்சி கடல் போன்றது காதலர் பிரிவு ஏற்படுத்தும் துன்பமோ, கடலைவிடப் பெரியது.", meaningEn: "The pleasure of greedy wants is (as great as) the sea; but the pain of greedy wants is far greater." },
  { number: 1167, line1: "காமக் கடும்புனல் நீந்திக் கரைகாணேன்", line2: "யாமத்தும் யானே உளேன்.", meaningTa: "அன்பு என்னும்‌ வெள்ளத்தை நீந்தியும் அதன் கரையை யான் காணவில்லை; நள்ளிரவிலும் யான் தனியே இருக்கின்றேன்.", meaningEn: "I have swam across the terrible flood of greedy wants, but have not seen its shore; even at midnight I am alone; still I live." },
  { number: 1168, line1: "மன்னுயிர் எல்லாம் துயிற்றி அளித்திரா", line2: "என்னல்லது இல்லை துணை.", meaningTa: "`இரவே! உலகில் உள்ள எல்லா உயிர்களையும் நீ உறங்கச் செய்துவிட்டுப் பாவம் இப்போது என்னைத்தவிர வேறு துணையில்லாமல்.", meaningEn: "The night which graciously lulls to sleep all living creatures, has me alone for her companion." },
  { number: 1169, line1: "கொடியார் கொடுமையின் தாம்கொடிய இந்நாள்", line2: "நெடிய கழியும் இரா.", meaningTa: "இந்நாட்களில் நெடுநேரம் உடையனவாய்க் கழிகின்ற இராக்காலங்கள், பிரிந்த கொடியவரின் கொடுமையை விடத் தாம் கொடியவை.", meaningEn: "The long nights of these days are far more cruel than the heartless one who is torturing me." },
  { number: 1170, line1: "உள்ளம்போன்று உள்வழிச் செல்கிற்பின் வெள்ளநீர்", line2: "நீந்தல மன்னோஎன் கண்.", meaningTa: "காதலர் உள்ள இடத்திற்கு என் மனத்தைப்போல் செல்ல முடியுமானால், என்‌ கண்கள் இவ்வாறு வெள்ளமாகிய கண்ணீரில் நீந்த.", meaningEn: "Could mine eyes travel like my thoughts to the abode (of my absent lord), they would not swim in this flood of tears." },
  { number: 1171, line1: "கண்தாம் கலுழ்வ தெவன்கொலோ தண்டாநோய்", line2: "தாம்காட்ட யாம்கண் டது.", meaningTa: "கண்கள் செய்த குற்றத்தால்தானே அன்பு நோய் ஏற்பட்டது? அதே கண்கள் அந்தக் காதலரைக் காட்டுமாறு கேட்டு அழுவது ஏன்?", meaningEn: "As this incurable malady has been caused by my eyes which showed (him) to me, why should they now weep for (him)." },
  { number: 1172, line1: "தெரிந்துணரா நோக்கிய உண்கண் பரிந்துணராப்", line2: "பைதல் உழப்பது எவன்?", meaningTa: "ஆராய்ந்து உணராமல் அன்று நோக்கிக் அன்பு கொண்ட கண்கள், இன்று அன்பு கொண்டு உணராமல் துன்பத்தால் வருந்துவது ஏன்?", meaningEn: "The dyed eyes that (then) looked without foresight, why should they now endure sorrow, without feeling sharply (their own fault)." },
  { number: 1173, line1: "கதுமெனத் தாநோக்கித் தாமே கலுழும்", line2: "இதுநகத் தக்க துடைத்து.", meaningTa: "அன்று காதலரைக் கண்கள் தாமே விரைந்து நோக்கி இன்று தாமே அழுகின்றன; இது நகைக்கத்தக்க தன்மை உடையது.", meaningEn: "They themselves looked eagerly (on him) and now they weep. isn't this to be laughed at ?" },
  { number: 1174, line1: "பெயலாற்றா நீருலந்த உண்கண் உயலாற்றா", line2: "உய்வில்நோய் என்கண் நிறுத்து.", meaningTa: "தப்பிப் பிழைக்க முடியாத, தீராத அன்பு நோயை எனக்குத் தருவதற்குக் காரணமான என் கண்கள், தாமும் அழ முடியாமல் வற்றிப்.", meaningEn: "These painted eyes have caused me a lasting mortal disease; and now they can weep no more, the tears having dried up." },
  { number: 1175, line1: "படலாற்றா பைதல் உழக்கும் கடலாற்றாக்", line2: "காமநோய் செய்தஎன் கண்.", meaningTa: "கடலைவிடப் பெரிதாகும் அன்பு துன்பத்தை எனக்குத் தந்த கண்கள், தாமும் தூங்காமல், துன்பத்தையும் அனுபவித்துக்.", meaningEn: "Mine eyes have caused me a greedy wants that is greater than the sea and (they themselves) endure the torture of sleeplessness." },
  { number: 1176, line1: "ஓஒ இனிதே எமக்கிந்நோய் செய்தகண்", line2: "தாஅம் இதற்பட் டது.", meaningTa: "எனக்கு இந்தக் அன்பு துன்பத்தைத் தந்த கண்கள் தாமும் தூங்காமல் அழுவது நன்றாகத்தான் இருக்கிறது.", meaningEn: "The eyes that have given me this disease have themselves been seized with this (suffering) Oh! I am much delighted." },
  { number: 1177, line1: "உழந்துழந் துள்நீர் அறுக விழைந்திழைந்து", line2: "வேண்டி அவர்க்கண்ட கண்.", meaningTa: "அன்று, இழைந்து குழைந்து ஆசையுடன் அவரைக் கண்ட கண்களே! இன்று பிரிந்து சென்றுள்ள அவரை நினைத்துக் தூங்காமலும், துளிக்.", meaningEn: "The eyes that became tender and gazed intently on him, may they suffer so much as to dry up the fountain of their tears." },
  { number: 1178, line1: "பேணாது பெட்டார் உளர்மன்னோ மற்றவர்க்", line2: "காணாது அமைவில கண்.", meaningTa: "என்னை அரவணைக்கும் எண்ணமின்றிக் காதலித்த ஒருவர் இருக்கின்றனர்; அவரைக் காணாமல் என் கண்களுக்கு அமைதியில்லையே!", meaningEn: "He is indeed here who loved me with his lips but not with his heart but mine eyes suffer from not seeing him." },
  { number: 1179, line1: "வாராக்கால் துஞ்சா வரின்துஞ்சா ஆயிடை", line2: "ஆரஞர் உற்றன கண்.", meaningTa: "காதலர் வாராவிட்டால் தூங்குவதில்லை; வந்தாலும் தூங்குவதில்லை; இவற்றுக்கி‌டையே என் கண்கள் மிக்க துன்பத்தை அடைந்தன.", meaningEn: "When he is away they don't sleep; when he is present they don't sleep; in either case, mine eyes endure unbearable agony." },
  { number: 1180, line1: "மறைபெறல் ஊரார்க்கு அரிதன்றால் எம்போல்", line2: "அறைபறை கண்ணார் அகத்து.", meaningTa: "அறையப்படும் பறைபோல் துன்பத்தை வெளிப்படுத்தும் கண்களை உடைய எம்மைப் போன்றவரிடத்தில் மறைபொருளான செய்தியை அறிதல்.", meaningEn: "It isn't difficult for the people of this place to understand the secret of those whose eyes, like mine, are as it were beaten drums." },
  { number: 1181, line1: "நயந்தவர்க்கு நல்காமை நேர்ந்தேன் பசந்தவென்", line2: "பண்பியார்க்கு உரைக்கோ பிற.", meaningTa: "விரும்பிய காதலர்க்கு அன்று பிரிவை உடன்பட்டேன்; பிரிந்தபின் பசலை உற்ற என் தன்மையை வேறு யார்க்குச் சென்று சொல்வேன்?", meaningEn: "I who (then) consented to the absence of my loving lord, to whom can I (now) relate the fact of my having turned sallow." },
  { number: 1182, line1: "அவர்தந்தார் என்னும் தகையால் இவர்தந்தென்", line2: "மேனிமேல் ஊரும் பசப்பு.", meaningTa: "இந்தப் பசலை அவர் எனக்குத் தந்தது என்னும் பெருமையினால் என் மேனி எங்கும் படருகின்றன.", meaningEn: "Sallowness, as if proud of having been caused by him, would now ride on my person." },
  { number: 1183, line1: "சாயலும் நாணும் அவர்கொண்டார் கைம்மாறா", line2: "நோயும் பசலையும் தந்து.", meaningTa: "அவர் என்னைப் பிரிகிறபோதே உள்ளத் துன்பத்தையும் பசலையையும் எனக்குக் கொடுத்துவிட்டு அவற்றுக்கு ஈடாக என் அழகையும்.", meaningEn: "He has taken (away) my beauty and modesty, and given me instead disease and sallowness." },
  { number: 1184, line1: "உள்ளுவன் மன்யான் உரைப்பது அவர்திறமால்", line2: "கள்ளம் பிறவோ பசப்பு.", meaningTa: "யான் நினைப்பதும், உரைப்பதும் அவரது நேர்மைத் திறன் பற்றியதாகவே இருக்கும்போது, என்னையறியாமலோ வேறு வழியிலோ இப்பசலை நிறம்.", meaningEn: "I think (of him); and what I speak about is but his excellence; still is there sallowness; and this is deceitful." },
  { number: 1185, line1: "உவக்காண்எம் காதலர் செல்வார் இவக்காண்என்", line2: "மேனி பசப்பூர் வது.", meaningTa: "அதோ பார்! எம்முடைய காதலர் பிரிந்து செல்கின்றார்; இதோ பார்! என்னுடைய மேனியில் பசலை நிறம் வந்து படர்கிறது.", meaningEn: "Just as my someone you care about departed then, did not sallowness spread here on my person ?" },
  { number: 1186, line1: "விளக்கற்றம் பார்க்கும் இருளேபோல் கொண்கன்", line2: "முயக்கற்றம் பார்க்கும் பசப்பு.", meaningTa: "விளக்கினுடைய மறைவைப் பார்த்துக் காத்திருக்கின்ற இருளைப் போலவே, தலைவனுடைய தழுவுதலின் ‌சோர்வைப் பார்த்துக்.", meaningEn: "Just as darkness waits for the failing light; so does sallowness wait for the laxity of my partner's intercourse." },
  { number: 1187, line1: "புல்லிக் கிடந்தேன் புடைபெயர்ந்தேன் அவ்வளவில்", line2: "அள்ளிக்கொள் வற்றே பசப்பு.", meaningTa: "அன்புடன் சேர்ந்துக் கிடந்தேன்; சற்றுத் தள்ளிப் படுத்தேன்; அவ்வளவுதான்; என்னை அள்ளிக் கொண்டு விட்டதே பசலை நிறம்!", meaningEn: "I who was in close warm hug just turned aside and the moment I did so, sallowness came on me like something to be seized on." },
  { number: 1188, line1: "பசந்தாள் இவள்என்பது அல்லால் இவளைத்", line2: "துறந்தார் அவர்என்பார் இல்.", meaningTa: "இவள் பிரிவால் வருத்திப் பசலை நிறம் அடைந்தாள் என்ற பழி சொல்வதே அல்லாமல், இவளைக் காதலர் விட்டுப் பிரிந்தார் என்று.", meaningEn: "Besides those who say \"she has turned sallow\" there are none who say \"he has forsaken her\"." },
  { number: 1189, line1: "பசக்கமன் பட்டாங்கென் மேனி நயப்பித்தார்", line2: "நன்னிலையர் ஆவர் எனின்.", meaningTa: "பிரிவுக்கு உடன்படச் செய்த காதலர் நல்ல நிலையுடையவர் ஆவார் என்றால், என்னுடைய மேனி உள்ளபடி பசலை நிறம் அடைவதாக.", meaningEn: "If he is clear of guilt who has conciliated me (to his departure) let my body suffer its due and turn sallow." },
  { number: 1190, line1: "பசப்பெனப் பேர்பெறுதல் நன்றே நயப்பித்தார்", line2: "நல்காமை தூற்றார் எனின்.", meaningTa: "என்னைச் சம்மதிக்கச் செய்து பிரிந்தவர் இன்னும் வராமல் இருப்பதை எண்ணி அவரை ஏசாமல், இவளே பசலை ஆயினாள் என்று இம்மக்கள்.", meaningEn: "It would be good to be said of me that I have turned sallow, if friends don't reproach with unkindness God who pleased me (then)." },
  { number: 1191, line1: "தாம்வீழ்வார் தம்வீழப் பெற்றவர் பெற்றாரே", line2: "காமத்துக் காழில் கனி.", meaningTa: "தாம் விரும்புபவராலேயே விரும்பப்பட்ட அன்புக்குரியவர்கள்தாம் அன்பு மகிழ்ச்சி என்னும் விதை இல்லாத கனியைப் பெற்றவர் ஆவர்.", meaningEn: "The wopeople who are beloved by those whom they caring, have they have not got the stone-less fruit of grown-up delight ?" },
  { number: 1192, line1: "வாழ்வார்க்கு வானம் பயந்தற்றால் வீழ்வார்க்கு", line2: "வீழ்வார் அள஧ க்கும் அளி.", meaningTa: "காதலர்கள் ஒருவரையொருவர் உரிய நேரத்தில் சந்தித்து அன்பு பொழிவது, வாழ்வதற்குத் தேவையான பருவமழை பொழிவது போன்றதாகும்.", meaningEn: "The bestowal of caring by the beloved on those who caring them is like the rain raining (at the proper season) on those who live by it." },
  { number: 1193, line1: "வீழுநர் வீழப் படுவார்க்கு அமையுமே", line2: "வாழுநம் என்னும் செருக்கு.", meaningTa: "காதலரால் விரும்பப்படுகின்றவர்க்கும் மீண்டும் வந்தபின் வாழ்வோம் என்று இருக்கும் செருக்குத் தகும்.", meaningEn: "The pride of living is for those Whose caring is returned by caring so close." },
  { number: 1194, line1: "வீழப் படுவார் கெழீஇயிலர் தாம்வீழ்வார்", line2: "வீழப் படாஅர் எனின்.", meaningTa: "விரும்பப்படாத நிலை ஏற்படின், அந்தக் காதலர் நட்புணர்வு இல்லாதவராகவே கருதப்படுவார்.", meaningEn: "Even those who are esteemed (by other women) are devoid of excellence, if they aren't loved by their beloved." },
  { number: 1195, line1: "நாம்காதல் கொண்டார் நமக்கெவன் செய்பவோ", line2: "தாம்காதல் கொள்ளாக் கடை.", meaningTa: "நாம் காதலித்தவர் நம்மைக் காதலிக்கவில்லை என்றால் நமக்கு எத்தகைய மகிழ்ச்சியைத் தருவார்?", meaningEn: "He who is beloved by me, what will he do to me, if I am not beloved by him ?" },
  { number: 1196, line1: "ஒருதலையான் இன்னாது காமம்காப் போல", line2: "இருதலை யானும் இனிது.", meaningTa: "அன்பு ஒரு பக்கமாக இருத்தல் துன்பமானது; காவடியின் பாரம் போல் இருபக்கமாகவும் ஒத்திருப்பது இன்பமானதாகும்.", meaningEn: "Greedy wants, like the weight of the KAVADI, pains if it lies in one end only but pleases if it is in both." },
  { number: 1197, line1: "பருவரலும் பைதலும் காணான்கொல் காமன்", line2: "ஒருவர்கண் நின்றொழுகு வான்.", meaningTa: "ஒருவரிடத்தில் மட்டும் காமன் நின்று இயங்குவதால், என்னுடைய துன்பத்தையும் வருத்தத்தையும் அறியானோ?", meaningEn: "Would not cupid who abides and contends in one party (only) witness the pain and sorrow (in that party)?" },
  { number: 1198, line1: "வீழ்வாரின் இன்சொல் பெறாஅது உலகத்து", line2: "வாழ்வாரின் வன்கணார் இல்.", meaningTa: "தான் விரும்பும் காதலரின் இனிய சொல்லைப் பெறாமல் உலகத்தில் வாழ்கின்றவரைப் போல் வன்கண்மை உடையவர் இல்லை.", meaningEn: "There is no one in the world so hard-hearted as those who can live without receiving (even) a kind word from their beloved." },
  { number: 1199, line1: "நசைஇயார் நல்கார் எனினும் அவர்மாட்டு", line2: "இசையும் இனிய செவிக்கு.", meaningTa: "என் அன்புக்குரியவர் என்னிடம் அன்பு காட்டாதவராகப் பிரிந்து இருப்பினும், அவரைப் பற்றிய புகழ் உரை என் செவிக்குச்.", meaningEn: "Though my beloved bestows no caring on one, still are his words sweet to my ears." },
  { number: 1200, line1: "உறாஅர்க்கு உறுநோய் உரைப்பாய் கடலைச்", line2: "செறாஅஅய் வாழிய நெஞ்சு.", meaningTa: "நெஞ்சமே! நீ வாழி! அன்பு இல்லாதவரிடம் உன் மிகுந்த துன்பத்தைச் சொல்கின்றாய்! அதை விட எளிதாகக் கடலைத் தூர்ப்பாயாக.", meaningEn: "Live, O my soul, would you who relate your great sorrow to strangers, try rather to fill up your own sea (of sorrow)." },
  { number: 1201, line1: "உள்ளினும் தீராப் பெருமகிழ் செய்தலால்", line2: "கள்ளினும் காமம் இனிது.", meaningTa: "நினைத்தாலும் தீராத பெரிய மகிழ்ச்சியைச் செய்தலால் கள்ளை விட அன்பு இன்பமானதாகும்.", meaningEn: "Grown-upity is sweeter than liquor, because when remembered, it creates a most rapturous delight." },
  { number: 1202, line1: "எனைத்தொனறு இனிதேகாண் காமம்தாம் வீழ்வார்", line2: "நினைப்ப வருவதொன்று ஏல்.", meaningTa: "நாம் விரும்புபவரைப் பிரிவிலும் நினைத்தால் பிரிவுத் துன்பம் வராது. அதனால் என்ன ஆனாலும் சரி, அன்பு இனியதுதான்.", meaningEn: "Even to think of one's beloved gives one no pain grown-upity, in any degree, is always delightful." },
  { number: 1203, line1: "நினைப்பவர் போன்று நினையார்கொல் தும்மல்", line2: "சினைப்பது போன்று கெடும்.", meaningTa: "எனக்குத் தும்மல் வருவது போல் வந்து அடங்கி விடுகிறது. அவர் என்னை நினைக்கத் தொடங்கி, நினைக்காமல் விடுவாரோ?", meaningEn: "I feel as if I am going to sneeze but don't, and (so) my beloved is about to think (of me) but does not." },
  { number: 1204, line1: "யாமும் உளேங்கொல் அவர்நெஞ்சத்து எந்நெஞ்சத்து", line2: "ஓஒ உளரே அவர்.", meaningTa: "என் நெஞ்சத்தில் அவர் எப்போதும் இருக்கிறார். அவர் நெஞ்சத்தில் நானும் இருப்பேனா?", meaningEn: "He continues to follow my soul, do I likewise follow his ?" },
  { number: 1205, line1: "தம்நெஞ்சத்து எம்மைக் கடிகொண்டார் நாணார்கொல்", line2: "எம்நெஞ்சத்து ஓவா வரல்.", meaningTa: "தம் நெஞ்சத்தில் என்னை விலக்கிவிட்ட அவர், என் நெஞ்சத்தில் மட்டும் ஓயாமல் வருவதற்கு வெட்கப் படமாட்டாரோ?", meaningEn: "He who has imprisoned me in his soul, is he ashamed to enter incessantly into mine." },
  { number: 1206, line1: "மற்றியான் என்னுளேன் மன்னோ அவரொடியான்", line2: "உற்றநாள் உள்ள உளேன்.", meaningTa: "நான் அவரோடு சேர்ந்திருந்த நாட்களை நினைத்துத் தான் உயிரோடு இருக்கிறேன்; வேறு எதை நினைத்து நான் உயிர்வாழ முடியும்?", meaningEn: "I live by remembering my (former) intercourse with him; if it were not so, how could I live ?" },
  { number: 1207, line1: "மறப்பின் எவனாவன் மற்கொல் மறப்பறியேன்", line2: "உள்ளினும் உள்ளம் சுடும்.", meaningTa: "அந்த நாள்களின் நினைவுகளை மறவாமல் நினைத்தாலும் என் நெஞ்சு சுடும்; அப்படி இருக்க மறந்தால் வாழ்வது எப்படி?", meaningEn: "I have never forgotten (the pleasure); even to think of it burns my soul; could I live, if I should ever forget it ?" },
  { number: 1208, line1: "எனைத்து நினைப்பினும் காயார் அனைத்தன்றோ", line2: "காதலர் செய்யும் சிறப்பு.", meaningTa: "அவரை நான் எப்படி எண்ணினாலும் கோபப்படமாட்டார்; அன்புள்ள அவர் எனக்குத் தரும் இன்பம் அத்தகையது அன்றோ!", meaningEn: "He won't be angry however much I may think of him; is it not so much the delight my beloved." },
  { number: 1209, line1: "விளியுமென் இன்னுயிர் வேறல்லம் என்பார்", line2: "அளியின்மை ஆற்ற நினைந்து.", meaningTa: "நாம் இருவரும் வேறு அல்லேம் என்று அடிக்கடி சொல்லும் அவர் இப்போது அன்பு இல்லாதிருத்தலை மிக நினைத்து என் இனிய உயிர்.", meaningEn: "My precious life is wasting away by thinleader too much on the cruelty of God who said we were not different." },
  { number: 1210, line1: "விடாஅது சென்றாரைக் கண்ணினால் காணப்", line2: "படாஅதி வாழி மதி.", meaningTa: "தி்ங்களே! பிரியாமல் இருந்து இறுதியில் பிரிந்து சென்ற காதலரை என் கண்ணால் தேடிக் காணும்படியாக நீ மறைந்து விடாமல்.", meaningEn: "May you live, O Moon! don't set, that I mine see God who has departed without quitting my soul." },
  { number: 1211, line1: "காதலர் தூதொடு வந்த கனவினுக்கு", line2: "யாதுசெய் வேன்கொல் விருந்து.", meaningTa: "காதலர் அனுப்பிய தூதோடு வந்த கனவுக்கு உரிய விருந்தாக என்ன செய்து உதவுவேன்?", meaningEn: "Where with will I feast the dream which has brought me my dear one's messenger ?" },
  { number: 1212, line1: "கயலுண்கண் யானிரப்பத் துஞ்சிற் கலந்தார்க்கு", line2: "உயலுண்மை சாற்றுவேன் மன்.", meaningTa: "கண்கள் யான் வேண்டுவதுபோல் தூங்குமானால், காதலர்க்கு யான் தப்பிப் பிழைத்திருக்கும்‌ தன்மையைச் சொல்வேன்.", meaningEn: "If my fish-like painted eyes should, at my begging, close in sleep, I could fully relate my sufferings to my lord." },
  { number: 1213, line1: "நனவினால் நல்கா தவரைக் கனவினால்", line2: "காண்டலின் உண்டென் உயிர்.", meaningTa: "நனவில் வந்து அன்பு காட்டாதவரைக் கனவிலாவது காண்பதால்தான் இன்னும் என்னுயிர் நிலைத்திருக்கிறது.", meaningEn: "My life lasts because in my dream I behold God who does not favour me in my waleader hours." },
  { number: 1214, line1: "கனவினான் உண்டாகும் காமம் நனவினான்", line2: "நல்காரை நாடித் தரற்கு.", meaningTa: "நேரில் வந்து அன்பு செய்யாதவரை அவர் இருக்கும் இடம் போய் அவரைத் தேடிக்கொண்டு வந்து தருவதால் கனவில் எனக்கு இன்பம்.", meaningEn: "There is pleasure in my dream, because in it I seek and obtain God who does not visit me in my wakefulness." },
  { number: 1215, line1: "நனவினால் கண்டதூஉம் ஆங்கே கனவுந்தான்", line2: "கண்ட பொழுதே இனிது.", meaningTa: "காதலரை நேரில் கண்ட இன்பம் அப்போது இனிமை வழங்கியது போலவே, இப்போது அவரைக் கனவில் காணும் இன்பமும் இனிமை வழங்குகிறது!", meaningEn: "I saw him in my waleader hours, and then it was pleasant; I see him just now in my dream, and it is (equally) pleasant." },
  { number: 1216, line1: "நனவென ஒன்றில்லை ஆயின் கனவினால்", line2: "காதலர் நீங்கலர் மன்.", meaningTa: "நனவு மட்டும் திடிரென வந்து கெடுக்காமல் இருந்தால், கனவில் சந்தித்த காதலர் பிரியாமலே இருக்க முடியுமே.", meaningEn: "Were there no such thing as wakefulness, my beloved (who visited me) in my dream would not depart from me." },
  { number: 1217, line1: "நனவினால் நல்காக் கொடியார் கனவனால்", line2: "என்எம்மைப் பீழிப் பது.", meaningTa: "நேரில் வந்து அன்பு செய்யாத இந்தக் கொடிய மனிதர் கனவில் மட்டும் நாளும் வந்து என்னை வருத்துவது ஏன்?", meaningEn: "The cruel one who would not favour me in my wakefulness, what right has he to torture me in my dreams?" },
  { number: 1218, line1: "துஞ்சுங்கால் தோள்மேலர் ஆகி விழிக்குங்கால்", line2: "நெஞ்சத்தர் ஆவர் விரைந்து.", meaningTa: "தூங்கும்போது கனவில் வந்து என் தோள்மேல் உள்ளவராகி, விழி்த்தெழும்போது விரைந்து என் நெஞ்சில் உள்ளவராகிறார்‌.", meaningEn: "When I am asleep he rests on my shoulders, (but) when I awake he hastens into my soul." },
  { number: 1219, line1: "நனவினால் நல்காரை நோவர் கனவினால்", line2: "காதலர்க் காணா தவர்.", meaningTa: "கனவில் காதலரைக் காணாதவர்கள்தான் அவர் நேரில் வந்து காணவில்லையே என்று நொந்து கொள்வர்.", meaningEn: "They who have no dear ones to behold in their dreams blame God who visits me not in my waleader hours." },
  { number: 1220, line1: "நனவினால் நம்நீத்தார் என்பர் கனவினால்", line2: "காணார்கொல் இவ்வூ ரவர்.", meaningTa: "நனவில் நம்‌மை விட்டு நீங்கினார் என்று காதலரைப் பழித்து பேசுகின்றனரே! இந்த ஊரார் கனவில் அவரைக் காண்பதில்லையோ?", meaningEn: "The women of this place say he has forsaken me in my wakefulness I think they have not seen him visit me in my dreams." },
  { number: 1221, line1: "மாலையோ அல்லை மணந்தார் உயிருண்ணும்", line2: "வேலைநீ வாழி பொழுது.", meaningTa: "பொழுதே! நீ மாலைக்காலம் அல்ல; மகளிரின் உயிரை உண்ணும் முடிவுக் காலமாக இருக்கினறாய்!", meaningEn: "Live, O you evening are you (the former) evening? No, you are the season that slays (married) women." },
  { number: 1222, line1: "புன்கண்ணை வாழி மருள்மாலை எம்கேள்போல்", line2: "வன்கண்ண தோநின் துணை.", meaningTa: "மயங்கும் மாலைப் பொழுதே! நீயும் எம்மைப் போல் துன்பப்படுகின்றாயே! எம் காதலர் போல் உன் துணையும் இரக்கம் அற்றதோ?", meaningEn: "A long life to you, O dark evening! You are sightless Is your help-mate (also) as hard-hearted as mine." },
  { number: 1223, line1: "பனிஅரும்பிப் பைதல்கொள் மாலை துனிஅரும்பித்", line2: "துன்பம் வளர வரும்.", meaningTa: "பக்கத்தில் என் காதலர் இருந்த போது பயந்து, பசலை நிறத்துடன் வந்த மாலைப் பொழுது, இப்போது என் உயிரை வெறுக்குமளவுக்குத்.", meaningEn: "The evening that (once) came in with trembling and dimness (now) brings me an aversion for life and increasing sorrow." },
  { number: 1224, line1: "காதலர் இல்வழி மாலை கொலைக்களத்து", line2: "ஏதிலர் போல வரும்.", meaningTa: "காதலர் இல்லாத இப்போது, கொலை செய்யும் இடத்தில் பகைவர் வருவது போல் மாலைப்பொழுது வருகின்றது.", meaningEn: "In the absence of my someone you care about, evening comes in like slayers on the field of slaughter." },
  { number: 1225, line1: "காலைக்குச் செய்தநன்று என்கொல் எவன்கொல்யான்", line2: "மாலைக்குச் செய்த பகை?", meaningTa: "காலைக்கு நான் செய்த நன்மை என்ன? மாலைக்கு நான் செய்த தீமை என்ன?", meaningEn: "O eve, why art you foe! you dost renew my grief." },
  { number: 1226, line1: "மாலைநோய் செய்தல் மணந்தார் அகலாத", line2: "காலை அறிந்த திலேன்.", meaningTa: "மாலைக்காலம் இப்படியெல்லாம் இன்னல் விளைவிக்கக் கூடியது என்பதைக் காதலர் என்னை விட்டுப் பிரியாமல் இருந்த போது நான்.", meaningEn: "Previous to my partner's departure, I know not the painful nature of evening." },
  { number: 1227, line1: "காலை அரும்பிப் பகலெல்லாம் போதாகி", line2: "மாலை மலரும்இந் நோய்.", meaningTa: "அன்பு என்பது காலையில் அரும்பாகி, பகல் முழுதும் முதிர்ச்சியடைந்து, மாலையில் மலரும் ஒரு நோயாகும்.", meaningEn: "This malady buds forth in the morning, expands all day long and blossoms in the evening." },
  { number: 1228, line1: "அழல்போலும் மாலைக்குத் தூதாகி ஆயன்", line2: "குழல்போலும் கொல்லும் படை.", meaningTa: "காதலர் பிரிவால் என்னைத் தணலாகச் சுடுகின்ற மாலைப்பொழுதை அறிவிக்கும் தூதாக வருவது போல வரும் ஆயனின் புல்லாங்குழலோசை.", meaningEn: "The shepherd's flute now sounds as a fiery forerunner of night, and is become a weapon that slays (me)." },
  { number: 1229, line1: "பதிமருண்டு பைதல் உழக்கும் மதிமருண்டு", line2: "மாலை படர்தரும் போழ்து.", meaningTa: "என் அறிவை மயக்கும் மாலைப் பொழுது, இந்த ஊரையே மயக்கித் துன்பத்தில் ஆழ்த்துவது போல் எனக்குத் தோன்றுகிறது.", meaningEn: "When night comes on confusing (everyone's) mind, the (whole) town will lose its sense and be plunged in sorrow." },
  { number: 1230, line1: "பொருள்மாலை யாளரை உள்ளி மருள்மாலை", line2: "மாயும்என் மாயா உயிர்.", meaningTa: "அவர் என்னைப் பிரிந்தபோது பொறுத்துக் கொண்ட என் உயிர், பொருள் மயக்கமே பெரிதாக உடைய அவரை நினைத்து மயங்கும் இந்த மாலைப்.", meaningEn: "My (hitherto) unextinguished life is now lost in this bewildering night at the thought of God who has the nature of wealth." },
  { number: 1231, line1: "சிறுமை நமக்கொழியச் சேட்சென்றார் உள்ளி", line2: "நறுமலர் நாணின கண்.", meaningTa: "பிரிவுத் துன்பத்தை நமக்களித்துவிட்டு நெடுந்தொலைவு சென்று விட்டாரேயென்று வருந்திடும் காதலியின் கண்கள் அழகிழந்துபோய்,.", meaningEn: "While we endure the unbearable sorrow, your eyes weep for God who is gone afar, and shun (the sight of) fragrant flowers." },
  { number: 1232, line1: "நயந்தவர் நல்காமை சொல்லுவ போலும்", line2: "பசந்து பனிவாரும் கண்.", meaningTa: "பசலை நிறம் கொண்டு நீர் பொழியும் கண்கள், விரும்பிய காதலர் அன்பு காட்டவில்லை யென்பதை சொல்லி காட்டுகின்றன.", meaningEn: "The discoloured eyes that shed tears profusely seem to betray the unkindness of our beloved." },
  { number: 1233, line1: "தணந்தமை சால அறிவிப்ப போலும்", line2: "மணந்தநாள் வீங்கிய தோள்.", meaningTa: "கூடியிருந்த காலத்தில் மகிழ்ந்து பூரித்திருந்த தோள்கள், காதலருடைய பிரிவை நன்றாக அறிவிப்பவை போல் உள்ளன.", meaningEn: "The shoulders that swelled on the day of our union (now) seem to announce our separation clearly (to the public)." },
  { number: 1234, line1: "பணைநீங்கிப் பைந்தொடி சோரும் துணைநீங்கித்", line2: "தொல்கவின் வாடிய தோள்.", meaningTa: "அவர் என்னைப் பிரிந்ததால் பழைய இயற்கை அழகை இழந்த என் தோள்கள், இப்போது வளையல்களும் கழலும்படி மெலிந்திருக்கின்றன.", meaningEn: "In the absence of your consort, your shoulders having lost their former beauty and fulness, your bracelets of pure gold have become loose." },
  { number: 1235, line1: "கொடியார் கொடுமை உரைக்கும் தொடியொடு", line2: "தொல்கவின் வாடிய தோள்.", meaningTa: "வளையல்கள் கழல, முன்னைய இயற்கை அழகையும் இழந்த என் தோள்கள் கொடிய அவரின் கொடுமையைப் பேசுகின்றன.", meaningEn: "The (loosened) bracelets, and the shoulders from which the old beauty has faded, relate the cruelty of the pitiless one." },
  { number: 1236, line1: "தொடியொடு தோள்நெகிழ நோவல் அவரைக்", line2: "கொடியர் எனக்கூறல் நொந்து.", meaningTa: "வளையல்கள் கழன்று தோள்களும் மெலிவடைவதால் காதலரைக் கொடியவர் என்று கூறுவதைக் கேட்டு வருந்துகின்றேன்.", meaningEn: "I am greatly pained to hear you call him a cruel man, just because your shoulders are reduced and your bracelets loosened." },
  { number: 1237, line1: "பாடு பெறுதியோ நெஞ்சே கொடியார்க்கென்", line2: "வாடுதோட் பூசல் உரைத்து.", meaningTa: "நெஞ்சே! கொடியவர் என்று சொல்லப்படுகின்ற காதலர்க்கு என் மெலிந்த தோள்களின் ஆரவாரத்தை உரைத்து, அந்த உதவியால் பெருமை.", meaningEn: "Can you O my soul! gain glory by relating to the (so-called) cruel one the clamour of my fading shoulders?" },
  { number: 1238, line1: "முயங்கிய கைகளை ஊக்கப் பசந்தது", line2: "பைந்தொடிப் பேதை நுதல்.", meaningTa: "அன்புடன் சேர்ந்துய கை‌களைத் தளர்த்தியவுடனே, பைந்தொடி அணிந்த காதலியின் நெற்றி, பசலை நிறம் அடைந்தது.", meaningEn: "When I once loosened the arms that were in warm hug, the forehead of the gold-braceleted women turned sallow." },
  { number: 1239, line1: "முயக்கிடைத் தண்வளி போழப் பசப்புற்ற", line2: "பேதை பெருமழைக் கண்.", meaningTa: "தழுவுதலுக்கு இடையே குளி்ந்த காற்று நுழைய, காதலியின் பெரிய மழை போன்ற கண்கள் பசலை நிறம் அடைந்தன.", meaningEn: "When but a breath of breeze penetrated our warm hug, her large cool eyes became sallow." },
  { number: 1240, line1: "கண்ணின் பசப்போ பருவரல் எய்தின்றே", line2: "ஒண்ணுதல் செய்தது கண்டு.", meaningTa: "பிரிவுத் துயரால் பிறைநுதல் பசலை நிறமடைந்ததைக் கண்டு அவளது கண்களின் பசலையும் பெருந்துன்பம் அடைந்துவிட்டது.", meaningEn: "Was it at the sight of what the bright forehead had done that the sallowness of her eyes became sad?" },
  { number: 1241, line1: "நினைத்தொன்று சொல்லாயோ நெஞ்சே எனைத்தொன்றும்", line2: "எவ்வநோய் தீர்க்கும் மருந்து.", meaningTa: "நெஞ்சே! எதனாலும் தீராத என் நோயைத் தீர்க்கும் மருந்து ஏதாவது ஒன்றை எண்ணிப் பார்த்துச் சொல்லமாட்டாயா?", meaningEn: "O my soul, will you not think and tell me some medicine be it what it may, that can cure this incurable malady?" },
  { number: 1242, line1: "காதல் அவரிலர் ஆகநீ நோவது", line2: "பேதைமை வாழியென் நெஞ்சு.", meaningTa: "என் நெஞ்சே! வாழ்க! அவர் நம்மிடம் அன்பு இல்லாதவராக இருக்க, நீ மட்டும் அவரை நினைந்து வருந்துவது உன் அறியாமையே!", meaningEn: "Is folly, fare you well my heart!" },
  { number: 1243, line1: "இருந்துள்ளி என்பரிதல் நெஞ்சே பரிந்துள்ளல்", line2: "பைதல்நோய் செய்தார்கண் இல்.", meaningTa: "பிரிவுத் துன்பம் தந்த காதலருக்கு நம்மிடம் இரக்கமில்லாத போது, நெஞ்சே! நீ மட்டும் இங்கிருந்து கொண்டு அவரை எண்ணிக்.", meaningEn: "O my soul! why remain (here) and suffer thinleader (of him)? There are no lewd thoughts (of you) in God who has caused you this disease of sorrow." },
  { number: 1244, line1: "கண்ணும் கொளச்சேறி நெஞ்சே இவையென்னைத்", line2: "தின்னும் அவர்க்காணல் உற்று.", meaningTa: "நெஞ்சே! நீ காதலரிடம் செல்லும் போது கண்களையும்கூட அழைத்துக்கொண்டு போ; இல்லையேல் அவரைக் காண வேண்டுமென்று என்னையே அவை.", meaningEn: "O my soul! take my eyes also with you, (if not), these would eat me up (in their wants) to see him." },
  { number: 1245, line1: "செற்றார் எனக்கை விடல்உண்டோ நெஞ்சேயாம்", line2: "உற்றால் உறாஅ தவர்.", meaningTa: "நெஞ்சே! யாம் விரும்பி நாடினாலும் எம்மை நாடாத அவர் நம்மை வெறுத்து விட்டார் என்று எண்ணிக் கைவிட முடியும‌ோ?", meaningEn: "O my soul! can he who loves not though he is beloved, be forsaken saying he hates me (now)?" },
  { number: 1246, line1: "கலந்துணர்த்தும் காதலர்க் கண்டாற் புலந்துணராய்", line2: "பொய்க்காய்வு காய்திஎன் நெஞ்சு.", meaningTa: "என் நெஞ்சே! ஊடியபோது கூடி ஊடல் உணர்த்த வல்ல காதலரைக் கண்டபோது நீ பிணங்கி உணர மாட்டாய்; பொய்யான சினங்கொண்டு.", meaningEn: "O my soul! when you see the dear one who remove dislike by intercourse, you are displeased and continue to be so Nay, your displeasure is (simply)." },
  { number: 1247, line1: "காமம் விடுஒன்றோ நாண்விடு நன்னெஞ்சே", line2: "யானோ பொறேன்இவ் விரண்டு.", meaningTa: "நல்ல நெஞ்சே! ஒன்று அன்பு விருப்பத்தை விடு; அல்லது நாணத்தை விடு; இரண்டையுமே விடமுடியாது என்பது உன் எண்ணம் என்றால்,.", meaningEn: "O my good soul, give up either greedy wants or honour, as for me I can endure neither." },
  { number: 1248, line1: "பரிந்தவர் நல்காரென்று ஏங்கிப் பிரிந்தவர்", line2: "பின்செல்வாய் பேதைஎன் நெஞ்சு.", meaningTa: "என் நெஞ்சே! பிரிவுத் துன்பத்தால் வருந்தி அவர் வந்து அன்பு செய்ய வில்லையே என்று ஏங்கி பிரிந்தவரின் பின் செல்கின்றாய்.", meaningEn: "You are a fool, O my soul! to go after my departed one, while you mourn that he isn't kind enough to favour you." },
  { number: 1249, line1: "உள்ளத்தார் காத லவரால் உள்ளிநீ", line2: "யாருழைச் சேறியென் நெஞ்சு.", meaningTa: "என் நெஞ்சே! நம் அன்பர் நம் மனத்திற்குள்ளேயே இருக்க, நீ அவரைத் தேடி எவரிடம் போகிறாய்?", meaningEn: "O my soul! to whom would you repair, while the dear one is within yourself?" },
  { number: 1250, line1: "துன்னாத் துறந்தாரை நெஞ்சத்து உடையேமா", line2: "இன்னும் இழத்தும் கவின்.", meaningTa: "நம்மோடு பொருந்தி இருக்காமல் கைவிட்டுச சென்ற காதலரை நெஞ்சில் வைத்திருக்கும்போது இன்னும் மெலிந்து அழகை இழந்து.", meaningEn: "Without a thought he deserted us To think of him will make us worse." },
  { number: 1251, line1: "காமக் கணிச்சி உடைக்கும் நிறையென்னும்", line2: "நாணுத்தாழ் வீழ்த்த கதவு.", meaningTa: "நாணம் என்னும் தாழ்பாளைக் கோத்திருக்கும் நிறை எனப்படும் கதவைக் அன்பு விருப்பமாகிய கோடரி பிளக்கின்றதே!", meaningEn: "The axe of greedy wants can break the door of chastity which is bolted with the bolt of modesty." },
  { number: 1252, line1: "காமம் எனவொன்றோ கண்ணின்றென் நெஞ்சத்தை", line2: "யாமத்தும் ஆளும் தொழில்.", meaningTa: "அன்பு என்று சொல்லப்படுகின்ற ஒன்று கண்ணோட்டம் இல்லாதது. அது என் நெஞ்சத்தை நள்ளிரவில் ஏவல் கொண்டு ஆள்கிறது.", meaningEn: "Even at midnight is my mind worried by greedy wants, and this one thing, alas! is without mercy." },
  { number: 1253, line1: "மறைப்பேன்மன் காமத்தை யானோ குறிப்பின்றித்", line2: "தும்மல்போல் தோன்றி விடும்.", meaningTa: "என் அன்பு ஆசையை நான் மறைக்கவே எண்ணுவேன்; ஆனால், அது எனக்கும் தெரியாமல் தும்மலைப் போல் வெளிப்பட்டு விடுகிறது.", meaningEn: "I would conceal my greedy wants, but alas, it yields not to my will but breaks out like a sneeze." },
  { number: 1254, line1: "நிறையுடையேன் என்பேன்மன் யானோஎன் காமம்", line2: "மறையிறந்து மன்று படும்.", meaningTa: "யான் இதுவரையில் நிறையோடிருப்பதாக எண்ணிக கொண்டிருந்தேன். ஆனால் என் அன்பு என்னுள் மறைந்திருத்தலைக் கடந்து மன்றத்தில்.", meaningEn: "I say I would be firm, but alas, my malady breaks out from its concealment and appears in public." },
  { number: 1255, line1: "செற்றார்பின் செல்லாப் பெருந்தகைமை காமநோய்", line2: "உற்றார் அறிவதொன்று அன்று.", meaningTa: "தம்மைப் பிரிந்து சென்ற காதலரைப் பகையாகக் கருதி அவரைத் தொடர்ந்து மன அடக்கம், அன்பு நோயுற்றவர்க்கு இருப்பதில்லை.", meaningEn: "The dignity that would not go after an absent someone you care about isn't known to those who are sticken by caring." },
  { number: 1256, line1: "செற்றவர் பின்சேறல் வேண்டி அளித்தரோ", line2: "எற்றென்னை உற்ற துயர்.", meaningTa: "வெறுத்துப் பிரிந்ததையும் பொறுத்துக் கொண்டு அவர் பின்னே செல்லும் நிலையை என் நெஞ்சுக்கு ஏற்படுத்திய அன்பு நோயின்.", meaningEn: "The sorrow I have endured by desiring to go after my absent someone you care about, in what way is it excellent?" },
  { number: 1257, line1: "நாணென ஒன்றோ அறியலம் காமத்தால்", line2: "பேணியார் பெட்ப செயின்.", meaningTa: "என்னால் விரும்பப்பட்டவர் அன்பு ஆசையில் நான் விரும்பியதையே செய்தபோது, நாணம் என்று சொல்லப்படும் ஒன்றை அறியாமலேயே.", meaningEn: "I know nothing like shame when my beloved does from caring (just) what is wantsd (by me)." },
  { number: 1258, line1: "பன்மாயக் கள்வன் பணிமொழி அன்றோநம்", line2: "பெண்மை உடைக்கும் படை.", meaningTa: "என் மன அடக்கமாகிய கோட்டையை அழிக்கும் ஆயுதம், பல பொய்த் தொழிலும் வல்ல இந்த மனத்திருடனின் பணிவான சொற்கள் அன்றோ!", meaningEn: "Aren't the enticing words of my trick-abounding roguish someone you care about the weapon that breaks away my feminine firmness?" },
  { number: 1259, line1: "புலப்பல் எனச்சென்றேன் புல்லினேன் நெஞ்சம்", line2: "கலத்தல் உறுவது கண்டு.", meaningTa: "ஊடுவேன் என்று எண்ணிக் கொண்டு சென்றேன்; ஆனால் என் நெஞ்சம் என்னை விட்டு அவரோடு கூடுவதை கண்டு அன்புடன் சேர்ந்துனேன்.", meaningEn: "I said I would feign dislike and so went (away); (but) I warm hugd him the moment I say my mind began to unite with him!" },
  { number: 1260, line1: "நிணந்தீயில் இட்டன்ன நெஞ்சினார்க்கு உண்டோ", line2: "புணர்ந்தூடி நிற்பேம் எனல்.", meaningTa: "நெருப்பிலிட்ட கொழுப்பைப் போல் உருகிடும் நெஞ்சம் உடையவர்கள், கூடிக் களித்தபின் ஊடல் கொண்டு அதில் உறுதியாக இருக்க.", meaningEn: "Is it possible for those whose hearts melt like fat in the fire to say they can feign a strong dislike and remain so?" },
  { number: 1261, line1: "வாளற்றுப் புற்கென்ற கண்ணும் அவர்சென்ற", line2: "நாளொற்றித் தேய்ந்த விரல்.", meaningTa: "வருவார் வருவார் என வழி பார்த்துப் பார்த்து விழிகளும் ஒளியிழந்தன; பிரிந்து சென்றுள்ள நாட்களைச் சுவரில் குறியிட்டு.", meaningEn: "My finger has worn away by marleader (on the wall) the days he has been absent while my eyes have lost their greedy wantsre and begin to fail." },
  { number: 1262, line1: "இலங்கிழாய் இன்று மறப்பின்என் தோள்மேல்", line2: "கலங்கழியும் காரிகை நீத்து.", meaningTa: "காதலரைப் பிரிந்திருக்கும் நான், பிரிவுத் துன்பம் வாராதிருக்க அவரை மறந்திருக்க முனைந்தால், என் தோள்கள் அழகு நீங்கி.", meaningEn: "O you bright-jewelled maid, if I forget (him) today, my shoulders will lose their beauty even in the other life and make my bracelets loose." },
  { number: 1263, line1: "உரன்நசைஇ உள்ளம் துணையாகச் சென்றார்", line2: "வரல்நசைஇ இன்னும் உளேன்.", meaningTa: "ஊக்கத்தையே உறுதுணையாகக் கொண்டு வெற்றியை விரும்பிச் சென்றுள்ள காதலன், திரும்பி வருவான் என்பதற்காகவே நான் உயிரோடு.", meaningEn: "I still live by longing for the arrival of God who has gone out of caring for victory and with valour as his guide." },
  { number: 1264, line1: "கூடிய காமம் பிரிந்தார் வரவுள்ளிக்", line2: "கோடுகொ டேறுமென் நெஞ்சு.", meaningTa: "முன்பு கூடியிருந்த காதலைக் கைவிட்டுப் பிரிந்த அவருடைய வருகை‌யைநினைத்து என் நெஞ்சம் மரத்தின் கிளைகளின் மேலும் ஏறிப்.", meaningEn: "My heart is rid of its sorrow and swells with rapture to think of my absent someone you care about returning with his caring." },
  { number: 1265, line1: "காண்கமன் கொண்கனைக் கண்ணாரக் கண்டபின்", line2: "நீங்கும்என் மென்தோள் பசப்பு.", meaningTa: "கண்ணார என் கணவனைக் காண்பேனாக; கண்டபிறகே என் மெல்லிய தோளில் படர்ந்துள்ள பசலை நிறம் நீங்கும்.", meaningEn: "May I look on my someone you care about till I am satisfied and thereafter will vanish the sallowness of my slender shoulders." },
  { number: 1266, line1: "வருகமன் கொண்கன் ஒருநாள் பருகுவன்", line2: "பைதல்நோய் எல்லாம் கெட.", meaningTa: "என் காதலன் ஒருநாள் என்னிடம் வருவானாக; வந்த பிறகு, என்னுடைய துன்பநோய் எல்லொம் தீருமாறு நான் நன்றாக நுகர்வேன்.", meaningEn: "May my partner return some day; and then will I enjoy (him) so as to destroy all this agonizing sorrow." },
  { number: 1267, line1: "புலப்பேன்கொல் புல்லுவேன் கொல்லோ கலப்பேன்கொல்", line2: "கண்அன்ன கேளிர் விரன்.", meaningTa: "என்னுடைய கண்போன்ற காதலர் வருவாரானால், யான் அவரோடு ஊடுவேனோ? அல்லது அவரைத் தழுவுவேனோ? அவரோடு கூடுவேனோ?", meaningEn: "On the return of God who is as dear as my eyes, am I displeased or am I to warm hug (him); or am I to do both?" },
  { number: 1268, line1: "வினைகலந்து வென்றீக வேந்தன் மனைகலந்து", line2: "மாலை அயர்கம் விருந்து.", meaningTa: "அரசு போர் செய்து வெற்றி பெறட்டும்; நானும் மனைவியோடு கூடி மாலைப்பொழுதில் விருந்து உண்பேனாகுக.", meaningEn: "Let the leader fight and gain (victories); (but) let me be united to my partner and feast the evening." },
  { number: 1269, line1: "ஒருநாள் எழுநாள்போல் செல்லும்சேண் சென்றார்", line2: "வருநாள்வைத்து ஏங்கு பவர்க்கு.", meaningTa: "தொலைதூரம் சென்று தன் கணவன் வரும் நாளை எண்ணி வருந்தும் அன்புக்குரியவர்களுக்கு ஒருநாள் பலநாள் போல நெடிதாகத் தோன்றும்.", meaningEn: "To those who suffer waiting for the day of return of their distant people who care for each other one day is as long as seven days." },
  { number: 1270, line1: "பெறின்என்னாம் பெற்றக்கால் என்னாம் உறினென்னாம்", line2: "உள்ளம் உடைந்துக்கக் கால்.", meaningTa: "என் பிரிவைத் தாங்காமல் உள்ளம் உடைய, அவளுக்கு ஒன்று ஆகிவிட்டால் அதன் பிறகு அவள் என்னைப் பெறுவதால் ஆவது என்ன?", meaningEn: "After (my partner) has died of a broken heart, what good will there be if she is to receive me, has received me, or has even warm hugd me?" },
  { number: 1271, line1: "கரப்பினுங் கையிகந் தொல்லாநின் உண்கண்", line2: "உரைக்கல் உறுவதொன் றுண்டு.", meaningTa: "நீ சொல்லாமல் மறைத்தாலும் நிற்காமல் உன்னைக் கடந்து உன்னுடைய கண்கள் எனக்குச் சொல்லக் கூடிய செய்தி ஒன்று இருக்கிறது.", meaningEn: "Though you would conceal (your feelings), your painted eyes would not, for, transgressing (their bounds), they tell (me) something." },
  { number: 1272, line1: "கண்ணிறைந்த காரிகைக் காம்பேர்தோட் பேதைக்குப்", line2: "பெண்நிறைந்த நீர்மை பெரிது.", meaningTa: "கண்நிறைந்த அழகும் மூங்கில் போன்ற தோளும் கொண்ட என் காதலிக்குப் அன்புக்குரியவர்மைப் பண்பு நிறைந்திருப்பதே பேரழகாகும்.", meaningEn: "Unusually great is the person simplicity of your maid whose beauty fills my eyes and whose shoulders resemble the bamboo." },
  { number: 1273, line1: "மணியில் திகழ்தரு நூல்போல் மடந்தை", line2: "அணியில் திகழ்வதொன்று உண்டு.", meaningTa: "மணியினுள் விளங்கும் நூலைப் போல் என் காதலியின் அழகினுள் விளங்குவதான குறிப்பு ஒன்று இருக்கின்றது.", meaningEn: "There is something that is implied in the beauty of this woman, like the thread that is visible in a garland of gems." },
  { number: 1274, line1: "முகைமொக்குள் உள்ளது நாற்றம்போல் பேதை", line2: "நகைமொக்குள் உள்ளதொன் றுண்டு.", meaningTa: "மலராத அரும்புக்குள் நறுமணம் அடங்கியிருப்பது போலத்தான் ஒரு அன்புக்குரியவர்ணின் புன்னகையென்ற அரும்புக்குள் அவளது காதலனைப்பற்றிய.", meaningEn: "There is something in the unmatured smile of this maid like the fragrance that is contained in an unblossomed bud." },
  { number: 1275, line1: "செறிதொடி செய்திறந்த கள்ளம் உறுதுயர்", line2: "தீர்க்கும் மருந்தொன்று உடைத்து.", meaningTa: "காதலி என்னை நோக்கி செய்து விட்டுச் சென்ற கள்ளமான குறிப்பு, என் மிக்க துயரத்தைத் தீர்க்கும் மருந்து ஒன்று உடையதாக.", meaningEn: "The well-meant departure of her whose bangles are tight-fitting contains a remedy that can cure my great sorrow." },
  { number: 1276, line1: "பெரிதாற்றிப் பெட்பக் கலத்தல் அரிதாற்றி", line2: "அன்பின்மை சூழ்வ துடைத்து.", meaningTa: "ஆரத் அன்புடன் சேர்ந்து அளவற்ற அன்பு காட்டி அவர் என்னைக் கூடுவதானது மீண்டும் அவர் என்னைப் பிரிந்து செல்லப் போகிற குறிப்பை.", meaningEn: "The warm hug that fills me with comfort and gladness is capable of enduring (my former) sorrow and meditating on his want of caring." },
  { number: 1277, line1: "தண்ணந் துறைவன் தணந்தமை நம்மினும்", line2: "முன்னம் உணர்ந்த வளை.", meaningTa: "குளிர்ந்த துறையை உடைய காதலன் பிரிந்த பிரிவை நம்மை விட முன்னம‌ே நம்முடைய வளையல்கள் உணர்ந்து கழன்று விட்டனவே!", meaningEn: "My bracelets have understood before me the (mental) separation of God who rules the cool seashore." },
  { number: 1278, line1: "நெருநற்றுச் சென்றார்எம் காதலர் யாமும்", line2: "எழுநாளேம் மேனி பசந்து.", meaningTa: "எம்முடைய காதலர் நேற்றுதான் பிரிந்து சென்றார்; யாமும் மேனி பசலை நிறம் அடைந்து ஏழு நாட்கள் ஆய்விட்ட நிலையில்.", meaningEn: "It was but yesterday my someone you care about departed (from me); and it is seven days since my complexion turned sallow." },
  { number: 1279, line1: "தொடிநோக்கி மென்தோளும் நோக்கி அடிநோக்கி", line2: "அஃதாண் டவள்செய் தது.", meaningTa: "பிரிவு காரணமாகக் கழலக் கூடிய வளையலையும், மெலிந்து போகக் கூடிய மென்மையான தோளையும் நோக்கியவன் காதலனைத் தொடர்ந்து.", meaningEn: "She looked at her bracelets, her tender shoulders, and her feet; this was what she did there (significantly)." },
  { number: 1280, line1: "பெண்ணினால் பெண்மை உடைத்தென்ப கண்ணினால்", line2: "காமநோய் சொல்லி இரவு.", meaningTa: "அன்பு வேட்கையைக் கண்களால் உணர்த்திக் காதலனுடன் போவதற்கு இரந்து நிற்கும்போது அன்புக்குரியவர்மைக்குப் அன்புக்குரியவர்மை சேர்த்தாற் போன்று.", meaningEn: "To express their caring-sickness by their eyes and resort to begging bespeaks more than ordinary person excellence." },
  { number: 1281, line1: "உள்ளக் களித்தலும் காண மகிழ்தலும்", line2: "கள்ளுக்கில் காமத்திற் குண்டு.", meaningTa: "மதுவை அருந்தினால்தான் இன்பம், ஆனால் அன்பு அப்படியல்ல; நினைத்தாலே இன்பம்; காதலர்கள் ஒருவரையொருவர் கண்டாலே இன்பம்.", meaningEn: "To please by thought and cheer by sight is peculiar, not to liquor but greedy wants." },
  { number: 1282, line1: "தினைத்துணையும் ஊடாமை வேண்டும் பனைத்துணையும்", line2: "காமம் நிறைய வரின்.", meaningTa: "பனையளவாகக் அன்பு பெருகிடும் போது தினையளவு ஊடலும் கொள்ளாமல் இருக்க வேண்டும்.", meaningEn: "If women have a greedy wants that exceeds even the measure of the palmyra fruit, they won't wants (to feign) dislike even as much as the millet." },
  { number: 1283, line1: "பேணாது பெட்பவே செய்யினும் கொண்கனைக்", line2: "காணா தமையல கண்.", meaningTa: "என்னை அவமதித்து அவர் தம் விருப்பப்படியே செய்தாலும் என் கண்கள் அவரைக் காணாமல் இருப்பதில்லை.", meaningEn: "Though my eyes disregard me and do what is pleasing to my partner, still will they not be satisfied unless they see him." },
  { number: 1284, line1: "ஊடற்கண் சென்றேன்மன் தோழி அதுமறந்து", line2: "கூடற்கண் சென்றது என் னெஞ்சு.", meaningTa: "ஊடுவதற்காகச் சென்றாலும்கூட அதை நெஞ்சம் மறந்து விட்டுக் கூடுவதற்கு இணங்கி விடுவதே காதலின் சிறப்பு.", meaningEn: "My heart, forgetting all, could not its caring restrain." },
  { number: 1285, line1: "எழுதுங்கால் கோல்காணாக் கண்ணேபோல் கொண்கன்", line2: "பழிகாணேன் கண்ட இடத்து.", meaningTa: "முன்பு பார்த்திருந்தும் மை தீட்டும்போது அஞ்சனக் கோலைக் காணாத கண்களைப் போல, கணவனின் தவற்றை அவர் இல்லாதபோது எண்ணி.", meaningEn: "Like the eyes which see not the pencil that paints it, I can't see my partner's fault (just) when I meet him." },
  { number: 1286, line1: "காணுங்கால் காணேன் தவறாய காணாக்கால்", line2: "காணேன் தவறல் லவை.", meaningTa: "கணவனை நான் காணும்போது அவரது தவறுகளைக் காணேன்; காணாதபோதோ, தவறுகளைத் தவிரப் பிறவற்றைக் காணேன்.", meaningEn: "When I see my partner, I don't see any faults; but when I don't see him, I don't see anything but faults." },
  { number: 1287, line1: "உய்த்தல் அறிந்து புனல்பாய் பவரேபோல்", line2: "பொய்த்தல் அறிந்தென் புலந்து.", meaningTa: "வெள்ளம் அடித்துக் கொண்டு போய் விடுமெனத் தெரிந்திருந்தும் நீரில் குதிப்பவரைப் போல, வெற்றி கிடைக்காது எனப்.", meaningEn: "Like those who leap into a stream which they know will carry them off, why should a partner feign dislike which she knows can't hold out long?" },
  { number: 1288, line1: "இளித்தக்க இன்னா செயினும் களித்தார்க்குக்", line2: "கள்ளற்றே கள்வநின் மார்பு.", meaningTa: "வஞ்சகரே! தன்னை உண்டு மகிழ்ந்தவர்க்கு எளிமை வரத்தக்க தீமையைச் செய்தாலும், அவரால் மேலும் மேலும் விரும்பப்படும் கள்ளைப்.", meaningEn: "O you rogue! your breast is to me what liquor is to those who rejoice in it, though it only gives them an unpleasant disgrace." },
  { number: 1289, line1: "மலரினும் மெல்லிது காமம் சிலர்அதன்", line2: "செவ்வி தலைப்படு வார்.", meaningTa: "அன்பு மகிழ்ச்சி, மலரைவிட மென்மையானது அதனை அதே மென்மையுடன் நுகருபவர்கள் சிலரே ஆவார்கள்.", meaningEn: "Grown-up delight is more delicate than a flower, and few are those who understand its real nature." },
  { number: 1290, line1: "கண்ணின் துனித்தே கலங்கினாள் புல்லுதல்", line2: "என்னினும் தான்விதுப் புற்று.", meaningTa: "கண் பார்வையின் அளவில் பிணங்கி, என்னை விடத் தான் விரைந்து தழுவுதலை விரும்பி, கலந்து விட்டாள்.", meaningEn: "She once feigned dislike in her eyes, but the warmth of her warm hug exceeded my own." },
  { number: 1291, line1: "அவர்நெஞ்சு அவர்க்காதல் கண்டும் எவன்நெஞ்சே", line2: "நீஎமக்கு ஆகா தது.", meaningTa: "நெஞ்சே! அவருடைய நெஞ்சம் அவர்க்குத் துணையாதலைக் கண்டும் நீ எமக்குத் துணையாகாதது ஏன்?", meaningEn: "O my soul! although you have seen how his soul stands by him, how is it you don't stand by me?" },
  { number: 1292, line1: "உறாஅ தவர்க்கண்ட கண்ணும் அவரைச்", line2: "செறாஅரெனச் சேறியென் நெஞ்சு.", meaningTa: "என் நெஞசே! நம்மேல் அன்பு கொள்ளாத காதலரைக் கண்டபோதும், அவர் வெறுக்கமாட்டார் என்று எண்ணி அவரிடம் செல்கின்றாயே!", meaningEn: "O my soul! although you have known God who does not caring me, still do you go to him, saying \"he won't be displeased.\"." },
  { number: 1293, line1: "கெட்டார்க்கு நட்டார்இல் என்பதோ நெஞ்சேநீ", line2: "பெட்டாங்கு அவர்பின் செலல்.", meaningTa: "நெஞ்சே! நீ எனை விடுத்து அவரை விரும்பிப் பின் தொடர்ந்து செல்வது, துன்பத்தால் அழிந்தோர்க்கு நண்பர்கள் துணையிருக்க.", meaningEn: "O my soul! do you follow him at pleasure under the belief that the ruined have no friends?" },
  { number: 1294, line1: "இனிஅன்ன நின்னொடு சூழ்வார்யார் நெஞ்சே", line2: "துனிசெய்து துவ்வாய்காண் மற்று.", meaningTa: "நெஞ்சே! முதலில் ஊடல் செய்து பிறகு அதன் பயனைக் கூடலில் நுகர்வோம் என நினைக்க மாட்டாய்; எனவே அதைப்பற்றி உன்னிடம் யார்.", meaningEn: "O my soul! you would not first seem sulky and then enjoy (him); who then would in future consult you about such things?" },
  { number: 1295, line1: "பெறாஅமை அஞ்சும் பெறின்பிரிவு அஞ்சும்", line2: "அறாஅ இடும்பைத்தென் நெஞ்சு.", meaningTa: "பெறாமைக்கு அஞ்சும்; பெற்றால் பிரிவை நினைத்து அஞ்சும்; என் நெஞ்சம் தீராத துன்பம் உடையதாகின்றது.", meaningEn: "My soul fears when it is without him; it also fears when it is with him; it is subject to incessant sorrow." },
  { number: 1296, line1: "தனியே இருந்து நினைத்தக்கால் என்னைத்", line2: "தினிய இருந்ததென் நெஞ்சு.", meaningTa: "காதலர் பிரிவைத் தனியே இருந்து நினைத்தபோது என் நெஞ்சம் என்னைத் தின்பது போலக் கொடுமையாக இருந்தது.", meaningEn: "My mind has been (here) in order to eat me up (as it were) whenever I think of him in my solitude." },
  { number: 1297, line1: "நாணும் மறந்தேன் அவர்மறக் கல்லாஎன்", line2: "மாணா மடநெஞ்சிற் பட்டு.", meaningTa: "தன்னை மறந்த காதலரைத் தான் மறக்க முடியாத, என் நிலையில்லாத மடநெஞ்சோடு கூடி, நான் நாணத்தையும் மறந்துவிட்டேன்.", meaningEn: "I have even forgotten my modesty, having been caught in my foolish mind which isn't dignified enough to forget him." },
  { number: 1298, line1: "எள்ளின் இளிவாம்என்று எண்ணி அவர்திறம்", line2: "உள்ளும் உயிர்க்காதல் நெஞ்சு.", meaningTa: "உயரின் மேல் அன்பு கொண்ட என் நெஞ்சம், பிரிந்த காதலரை இகழ்ந்தால் இழிவாகும் என்று எண்ணி அவருடைய உயர்ந்த பண்புகளையே.", meaningEn: "My soul which clings to life thinks only of his (own) gain in the belief that it would be disgraceful for it to despise him." },
  { number: 1299, line1: "துன்பத்திற்கு யாரே துணையாவார் தாமுடைய", line2: "நெஞ்சந் துணையல் வழி.", meaningTa: "துன்பம் வரும்போது அதனைத் தாங்குவதற்கு நெஞ்சமே துணையாக இல்லாவிட்டால் பிறகு யார் துணையாக இருப்பார்?", meaningEn: "Who would help me out of one's distress, when one's own soul refuses help to one?" },
  { number: 1300, line1: "தஞ்சம் தமரல்லர் ஏதிலார் தாமுடைய", line2: "நெஞ்சம் தமரல் வழி.", meaningTa: "ஒருவர்க்கு தாம் உரிமையாகப் பெற்ற நெஞ்சமே உறவாகாதபோது அயலார் உறவில்லாதவராக இருப்பது எளிதேயாகும்.", meaningEn: "It is hardly possible for strangers to behave like relations, when one's own soul acts like a stranger." },
  { number: 1301, line1: "புல்லா திராஅப் புலத்தை அவர்உறும்", line2: "அல்லல்நோய் காண்கம் சிறிது.", meaningTa: "துன்ப நோயைச் சிறிது காண்போம்; அதற்காக அவரைத் தழுவாமலிருந்து பிணங்குவாயாக.", meaningEn: "Let us witness awhile his keen suffering; just feign dislike and warm hug him not." },
  { number: 1302, line1: "உப்பமைந் தற்றால் புலவி அதுசிறிது", line2: "மிக்கற்றால் நீள விடல்.", meaningTa: "உப்பு, உணவில் அளவோடு அமைந்திருப்பதைப் போன்றது ஊடல்; ஊடலை அளவு கடந்து நீட்டித்தல், அந்த உப்பு சிறிதளவு மிகுதியாக.", meaningEn: "A little dislike is like salt in proportion; to prolong it a little is like salt a little too much." },
  { number: 1303, line1: "அலந்தாரை அல்லல்நோய் செய்தற்றால் தம்மைப்", line2: "புலந்தாரைப் புல்லா விடல்.", meaningTa: "தன்னுடன் ஊடல் கொண்ட மனைவியின் ஊடலை நீக்கிக் கூடாமல் போவது, ஏற்கனவே துன்பப்பட்டவர்களுக்கு மேலும் அதிகத் துன்பத்தைக்.", meaningEn: "For people not to warm hug those who have feigned dislike is like torturing those already in agony." },
  { number: 1304, line1: "ஊடி யவரை உணராமை வாடிய", line2: "வள்ளி முதலரிந் தற்று.", meaningTa: "ஊடல் புரிந்து பிணங்கியிருப்பவரிடம் அன்பு செலுத்திடாமல் விலகியே இருப்பின், அது ஏற்கனவே வாடியுள்ள கொடியை அதன்.", meaningEn: "Not to reconcile those who have feigned dislike is like cutting a faded creeper at its root." },
  { number: 1305, line1: "நலத்தகை நல்லவர்க்கு ஏஎர் புலத்தகை", line2: "பூஅன்ன கண்ணார் அகத்து.", meaningTa: "மலர் விழி மகளிர் நெஞ்சில் விளையும் ஊடலே பண்பார்ந்த நல்ல காதலர்க்கு அழகு சேர்க்கும்.", meaningEn: "An increased shyness in those whose eyes are like flowers is beautiful even to good and good partners." },
  { number: 1306, line1: "துனியும் புலவியும் இல்லாயின் காமம்", line2: "கனியும் கருக்காயும் அற்று.", meaningTa: "வளர்ந்த ஊடலாகிய துனியும், இளம் ஊடலாகிய புலவியும் இல்லாது போய்விட்டால், அன்பு நிறைந்த இல்லறம், முதிர்ந்த பழமும்.", meaningEn: "Wants only fun, without prolonged and short-lived dislike, is like too ripe, and unripe fruit." },
  { number: 1307, line1: "ஊடலின் உண்டாங்கோர் துன்பம் புணர்வது", line2: "நீடுவ தன்று கொல் என்று.", meaningTa: "இனிக் கலவி நீளுமோ நீளாதோ என்று எண்ணுவதால், இன்பத்திற்கு இன்றியமையாத ஊடலிலும் ஒரு துன்பம் உண்டு.", meaningEn: "The doubt as to whether intercourse would take place soon or not, creates a sorrow (even) in feigned dislike." },
  { number: 1308, line1: "நோதல் எவன்மற்று நொந்தாரென்று அஃதறியும்", line2: "காதலர் இல்லா வழி.", meaningTa: "நம்மை நினைத்தல்லவோ வருந்துகிறார் என்பதை உணர்ந்திடும் காதலர் இல்லாத போது வருந்துவதால் என்ன பயன்?", meaningEn: "What avails sorrow when I am without a partner who can understand the cause of my sorrow?" },
  { number: 1309, line1: "நீரும் நிழலது இனிதே புலவியும்", line2: "வீழுநர் கண்ணே இனிது.", meaningTa: "நீரும் நிழலை அடுத்திருப்பதே இனிமையானது; அதுபோல், ஊடலும் அன்பு செலுத்துவோரிடத்தில் கொள்வதே இன்பமானது.", meaningEn: "Like water in the shade, dislike is delicious only in those who caring." },
  { number: 1310, line1: "ஊடல் உணங்க விடுவாரோடு என்நெஞ்சம்", line2: "கூடுவேம் என்பது அவா.", meaningTa: "ஊடி, என் நெஞ்சை வாட விட்டிருப்பவனோடும் கூடுவோம் என்று என் நெஞ்சம் முயல்வதற்குக் காரணம் ஆசையே.", meaningEn: "It is nothing but strong wants that makes her mind unite with me who can leave her to her own dislike." },
  { number: 1311, line1: "பெண்ணியலார் எல்லாரும் கண்ணின் பொதுஉண்பர்", line2: "நண்ணேன் பரத்தநின் மார்பு.", meaningTa: "அன்புக்குரியவர் விரும்பியே! நீ வீதி வழி வரும் குணங்கெட்ட அன்புக்குரியவர்கள் எல்லாரும் உன் மார்பைத் தம் கண்ணால் பொதுவாக உண்பர்; அதனால்.", meaningEn: "You are given to prostitution; all those who are born as wopeople enjoy you with their eyes in an ordinary way I won't warm hug you." },
  { number: 1312, line1: "ஊடி இருந்தேமாத் தும்மினார் யாம்தம்மை", line2: "நீடுவாழ் கென்பாக் கறிந்து.", meaningTa: "ஊடல் கொண்டிருந்தபோது அவர் தும்மினார்; ஊடலை விடுத்து அவரை ``நீடுவாழ்க'' என வாழ்த்துவேன் என்று நினைத்து.", meaningEn: "When I continued to be sulky he sneezed and thought I would (then) wish him a long life." },
  { number: 1313, line1: "கோட்டுப்பூச் சூடினும் காயும் ஒருத்தியைக்", line2: "காட்டிய சூடினீர் என்று.", meaningTa: "கிளையில் மலர்ந்த பூக்களைக் கட்டி நான் அணிந்து கொண்டிருந்தாலும், வேறொருத்திக்குக் காட்டுவதற்காகவே அணிந்திருக்கிறீர்.", meaningEn: "Even if I were adorned with a garland of branch-flowers, she would say I did so to show it to another woman." },
  { number: 1314, line1: "யாரினும் காதலம் என்றேனா ஊடினாள்", line2: "யாரினும் யாரினும் என்று.", meaningTa: "``யாரைக் காட்டிலும் உன்னிடம் நான் அன்பு மிகுதியாகக் கொண்டுள்ளேன்'' என்று இயல்பாகச் சொன்னதைக் கூடக் காதலி தவறாக.", meaningEn: "When I said I loved her more than any other woman, she said \"more than others, yes, more than others,\" and remained sulky." },
  { number: 1315, line1: "இம்மைப் பிறப்பில் பிரியலம் என்றேனாக்", line2: "கண்நிறை நீர்கொண் டனள்.", meaningTa: "அன்பு மிகுதியில் இந்தப் பிறவியில் நான் உன்னைப் பிரியேன் என்று சொன்னேன்; அப்படி என்றால் அடுத்த பிறவியில் பிரியப்போவதாக.", meaningEn: "When I said I would never part from her in this life her eyes were filled with tears." },
  { number: 1316, line1: "உள்ளினேன் என்றேன்மற் றென்மறந்தீர் என்றென்னைப்", line2: "புல்லாள் புலத்தக் கனள்.", meaningTa: "நினைத்தேன் என்று கூறி‌னேன்; நினைப்புக்கு முன் மறப்பு உண்டு அன்றோ? ஏன் மறந்தீர் என்று என்னைத் தழுவாமல் ஊடினாள்.", meaningEn: "When I said I had remembered her, she said I had forgotten her and relaxing her warm hug, began to feign dislike." },
  { number: 1317, line1: "வழுத்தினாள் தும்மினேன் ஆக அழித்தழுதாள்", line2: "யாருள்ளித் தும்மினீர் என்று.", meaningTa: "யான் தும்மினேனாக; அவள் நூறாண்டு என வாழ்த்தினாள்; உடனே அதை விட்டு யார் நினைத்ததால் தும்மினீர்? என்று கேட்டு அழுதாள்?", meaningEn: "When I sneezed she blessed me, but at once changed (her mind) and wept, asleader, \"At the thought of whom did you sneeze?\"." },
  { number: 1318, line1: "தும்முச் செறுப்ப அழுதாள் நுமர்உள்ளல்", line2: "எம்மை மறைத்திரோ என்று.", meaningTa: "அவளுடைய ஊடலுக்கு அஞ்சி யான் தும்மலை அடக்கிக் கொள்ள உம்மவர் உம்மை நினைப்பதை எமக்குத் தெரியாமல் மறைக்கின்றீரோ என்று.", meaningEn: "When I suppressed my sneezing, she wept saying, \"I suppose you (did so) to hide from me your own people's remembrance of you\"." },
  { number: 1319, line1: "தன்னை உணர்த்தினும் காயும் பிறர்க்கும்நீர்", line2: "இந்நீரர் ஆகுதிர் என்று.", meaningTa: "ஊடியிருந்தபோது அவளை ஊடல் உணர்த்தி மகிழ்வித்தாலும். நீர் மற்ற மகளிர்க்கும் இத்தன்மையானவராக ஆவீர் என்று சொல்லி சினம்.", meaningEn: "'I see', quoth she, 'to other folks How you are wondrous kind' Even when I try to remove her dislike, she is displeased and says, \"This is the way." },
  { number: 1320, line1: "நினைத்திருந்து நோக்கினும் காயும் அனைத்துநீர்", line2: "யாருள்ளி நோக்கினீர் என்று.", meaningTa: "ஒப்பற்ற அவளுடைய அழகை நினைத்து அவளையே இமை கொட்டாமல் பார்த்துக் கொண்டிருந்தாலும், யாருடன் என்னை ஒப்பிட்டு உற்றுப்.", meaningEn: "Even when I look on her contemplating (her beauty), she is displeased and says, \"With whose thought have you (so) looked on my person?\"." },
  { number: 1321, line1: "இல்லை தவறவர்க்கு ஆயினும் ஊடுதல்", line2: "வல்லது அவர்அள஧க்கு மாறு.", meaningTa: "அவரிடம் தவறே இல்லை என்றாலும், அவர் என்னிடம் மிகுந்த அன்பைச் செலுத்தும்படி செய்யவல்லது ஊடல்.", meaningEn: "Although my partner is free from defects, the way in which he warm hugs me is such as to make me feign dislike." },
  { number: 1322, line1: "ஊடலின் தோன்றும் சிறுதுனி நல்லளி", line2: "வாடினும் பாடு பெறும்.", meaningTa: "காதலரிடையே மலர்நதுள்ள நல்லன்பு சற்று வாடுவதற்கு, ஊடுதல் காரணமாக இருந்தாலும் அதனால் விளைகிற சிறிய துன்பம்.", meaningEn: "His caring will increase though it may (at first seem to) fade through the short-lived distress caused by (my) dislike." },
  { number: 1323, line1: "புலத்தலின் புத்தேள்நாடு உண்டோ நிலத்தொடு", line2: "நீரியைந் தன்னார் அகத்து.", meaningTa: "நிலத்தோடு நீர் பொருந்தி கலந்தாற் போன்ற அன்புடைய காதலரிடத்தில் ஊடுவதை விட இன்பம் தருகின்ற தேவருலம் இருக்கின்றதோ.", meaningEn: "Is there a magical friend land that can please like the feigned dislike of those whose union resembles that of earth and water?" },
  { number: 1324, line1: "புல்லி விடாஅப் புலவியுள் தோன்றுமென்", line2: "உள்ளம் உடைக்கும் படை.", meaningTa: "காதலரைத் அன்புடன் சேர்ந்துக்கொண்டு விடாமலிருப்பதற்கு காரணமான ஊடலுள், என்னுடைய உள்ளத்தை உடைக்க வல்ல படை தோன்றுகிறது.", meaningEn: "In prolonged dislike after an warm hug there is a weapon that can break my heart." },
  { number: 1325, line1: "தவறிலர் ஆயினும் தாம்வீழ்வார் மென்றோள்", line2: "அகறலின் ஆங்கொன் றுடைத்து.", meaningTa: "ஆண்கள் மீது தவறு இல்லை என்றாலும் தவறு செய்தவராகவே நின்று, மனைவியால் ஊடப்பட்டு தாம் விரும்பும் மனைவியின் மெல்லிய.", meaningEn: "Though free from defects, people feel pleased when they can't warm hug the delicate shoulders of those whom they caring." },
  { number: 1326, line1: "உணலினும் உண்டது அறல்இனிது காமம்", line2: "புணர்தலின் ஊடல் இனிது.", meaningTa: "உண்பதைவிட உண்டது செரிப்பது இனியது; அதுபோலக், கூடிக் கலப்பதை விட ஊடுவது காதலுக்கு இனியது.", meaningEn: "To digest what has been eaten is more delightful than to eat more; likewise caring is more delightful in dislike than intercourse." },
  { number: 1327, line1: "ஊடலில் தோற்றவர் வென்றார் அதுமன்னும்", line2: "கூடலிற் காணப் படும்.", meaningTa: "ஊடலில் தோற்றவரே வெற்றி பெற்றவர் ஆவார்; அந்த வெற்றியைக் கூடிப் பெறும் இன்பத்தில் அறியலாம்.", meaningEn: "Those are conquerors whose dislike has been defeated and that is proved by the caring (which." },
  { number: 1328, line1: "ஊடிப் பெறுகுவம் கொல்லோ நுதல்வெயர்ப்பக்", line2: "கூடலில் தோன்றிய உப்பு.", meaningTa: "நெற்றி வியர்க்கும்படி கலவியில் தோன்றும் சுகத்தை இன்னுமொரு முறை இவளுடன் ஊடிப் பெறுவோமா?", meaningEn: "Will I enjoy once more through her dislike, the pleasure of that caring that makes her forehead perspire?" },
  { number: 1329, line1: "ஊடுக மன்னோ ஒளியிழை யாமிரப்ப", line2: "நீடுக மன்னோ இரா.", meaningTa: "காதலி இன்னும் ஊடுவாளாக, அந்த ஊடலைத் தணிக்கும் பொருட்டு யாம் இரந்து நிற்குமாறு இராக்காலம் இன்னும் நீட்டிப்பதாக.", meaningEn: "May the bright-jewelled one feign dislike, and may the night be prolonged for me to implore her!" },
  { number: 1330, line1: "ஊடுதல் காமத்திற்கு இன்பம் அதற்கின்பம்", line2: "கூடி முயங்கப் பெறின்.", meaningTa: "அன்பு உணர்வுக்கு இன்பம் ஊடுதலே அவ்வூடலுக்கும் இன்பம், அளவு அறிந்து ஊடலை நீக்கிக் கூடித் தழுவுதலே.", meaningEn: "A little sulk can make caring feel sweeter; and a kind warm hug (thereafter) will make making-up feel joyful." },
]
